    case StockMoveRepository.TYPE_INCOMING:
      newStockMove.setTypeSelect(StockMoveRepository.TYPE_OUTGOING);
      break;
    case StockMoveRepository.TYPE_OUTGOING:
      newStockMove.setTypeSelect(StockMoveRepository.TYPE_INCOMING);
      break;
    default:
      newStockMove.setTypeSelect(StockMoveRepository.TYPE_INTERNAL);
      break;
  }
}

protected StockMoveLine copyStockMoveLine(StockMoveLine stockMoveLine, boolean split) {
  StockMoveLine newStockMoveLine = stockMoveLineRepo.copy(stockMoveLine, false);

  if (split) {
    newStockMoveLine.setQty(stockMoveLine.getRealQty().subtract(stockMoveLine.getQty()));
    newStockMoveLine.setRealQty(newStockMoveLine.getQty());
  } else {
    newStockMoveLine.setQty(stockMoveLine.getRealQty());
    newStockMoveLine.setRealQty(stockMoveLine.getRealQty());
  }
  return newStockMoveLine;
}

protected void setPlannedStatus(StockMove stockMove) {
  stockMove.setStatusSelect(StockMoveRepository.STATUS_PLANNED);
  stockMoveRepo.save(stockMove);
}

@Transactional(rollbackOn = {Exception.class})
protected String realizeStockMove(StockMove stockMove, boolean checkOngoingInventoryFlag)
    throws AxelorException {
  if (stockMove.getStatusSelect() == null
      || stockMove.getStatusSelect() != StockMoveRepository.STATUS_PLANNED) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_REALIZATION_WRONG_STATUS));
  }

  LOG.debug("Stock realization : {} ", stockMove.getStockMoveSeq());

  if (stockMove.getTypeSelect() == StockMoveRepository.TYPE_INCOMING
      && !stockMove.getIsReversion()
      && appStockService.getAppStock().getIsRequiredShipmentSupplierDetails()
      && (stockMove.getSupplierShipmentDate() == null
          || Strings.isNullOrEmpty(stockMove.getSupplierShipmentRef()))) {
    throw new AxelorException(
        stockMove,
        TraceBackRepository.CATEGORY_MISSING_FIELD,
        I18n.get(StockExceptionMessage.STOCK_MOVE_MISSING_SUPPLIER_SHIPMENT_DETAILS));
  }

  if (checkOngoingInventoryFlag) {
    checkOngoingInventory(stockMove);
  }

  int initialStatus = stockMove.getStatusSelect();

  String newStockSeq = null;
  stockMoveLineService.checkTrackingNumber(stockMove);
  stockMoveLineService.checkConformitySelection(stockMove);
  fillRealizeWapPriceForStockMove(stockMove);

  stockMoveLineService.checkExpirationDates(stockMove);

  BigDecimal exTaxTotal = stockMoveToolService.compute(stockMove);
  stockMove = JpaModelHelper.ensureManaged(stockMove);
  setRealizedStatus(stockMove);
  stockMove.setRealDate(appBaseService.getTodayDate(stockMove.getCompany()));
  stockMove.setExTaxTotal(exTaxTotal);

  stockMove = stockMoveRepo.save(stockMove);

  stockMoveLineService.updateLocations(
      initialStatus,
      StockMoveRepository.STATUS_CANCELED,
      getPlannedStockMoveLineIds(stockMove, true),
      stockMove.getEstimatedDate(),
      false,
      false,
      true);

  stockMoveLineService.updateLocations(
      StockMoveRepository.STATUS_DRAFT,
      StockMoveRepository.STATUS_REALIZED,
      getStockMoveLineIds(stockMove),
      stockMove.getEstimatedDate(),
      true,
      true,
      true);

  stockMove = JpaModelHelper.ensureManaged(stockMove);
  clearPlannedStockMoveLine(stockMove, true);
  storeCustomsCodesForStockMove(stockMove);
  resetMasses(stockMove);

  boolean mustBeSplit = mustBeSplit(stockMove);
  if (stockMove.getIsWithBackorder() && mustBeSplit) {
    Optional<StockMove> newStockMove =
        copyAndSplitStockMove(JpaModelHelper.ensureManaged(stockMove));
    if (newStockMove.isPresent()) {
      newStockSeq = newStockMove.get().getStockMoveSeq();
    }
  }

  if (stockMove.getIsWithReturnSurplus() && mustBeSplit) {
    Optional<StockMove> newStockMove =
        copyAndSplitStockMoveReverse(JpaModelHelper.ensureManaged(stockMove), true);
    if (newStockMove.isPresent()) {
      if (newStockSeq != null) {
        newStockSeq = newStockSeq + " " + newStockMove.get().getStockMoveSeq();
      } else {
        newStockSeq = newStockMove.get().getStockMoveSeq();
      }
    }
  }
  computeMasses(stockMove);

  stockMove = stockMoveRepo.find(stockMove.getId());
  if (stockMove.getTypeSelect() == StockMoveRepository.TYPE_INCOMING
      && !stockMove.getIsReversion()) {
    partnerProductQualityRatingService.calculate(stockMove);
  }

  return newStockSeq;
}

protected Set<Long> getStockMoveLineIds(StockMove stockMove) {
  final Set<Long> lineIds = new LinkedHashSet<>();
  final long stockMoveId = stockMove.getId();
  BatchProcessorHelper.builder()
      .flushAfterBatch(false)
      .build()
      .<StockMoveLine>forEachByQuery(
          getStockMoveLineQuery(stockMoveId), line -> lineIds.add(line.getId()));
  return lineIds;
}

protected void storeCustomsCodesForStockMove(StockMove stockMove) throws AxelorException {

  Long stockMoveId = stockMove.getId();
  Query<StockMoveLine> query = getStockMoveLineQuery(stockMoveId);

  BatchProcessorHelper.of()
      .<StockMoveLine, AxelorException>forEachByQuery(
          query, stockMoveLineService::storeCustomsCodes);
}

protected void computeMasses(StockMove stockMove) throws AxelorException {
  Company company = Beans.get(CompanyRepository.class).find(stockMove.getCompany().getId());
  StockConfig stockConfig = company.getStockConfig();
  Unit endUnit = stockConfig != null ? stockConfig.getCustomsMassUnit() : null;
  UnitConversionService unitConversionService = Beans.get(UnitConversionService.class);

  final long stockMoveId = stockMove.getId();
  final StockMove[] stockMoveHolder = {stockMoveRepo.find(stockMoveId)};

  Query<StockMoveLine> query =
      stockMoveLineRepo
          .all()
          .filter(
              "self.stockMove.id = :stockMoveId "
                  + "AND self.product IS NOT NULL "
                  + "AND self.product.productTypeSelect = :storable "
                  + "AND self.id > :lastSeenId")
          .bind("stockMoveId", stockMove.getId())
          .bind("storable", ProductRepository.PRODUCT_TYPE_STORABLE)
          .order("id");

  BatchProcessorHelper.of()
      .<StockMoveLine, AxelorException>forEachByQuery(
          query,
          stockMoveLine -> {
            Product product = stockMoveLine.getProduct();
            if (product == null
                || !ProductRepository.PRODUCT_TYPE_STORABLE.equals(
                    product.getProductTypeSelect())) {
              return;
            }

            boolean massesRequiredForStockMoveLine =
                stockMoveLineService.checkMassesRequired(stockMoveHolder[0], stockMoveLine);

            if (massesRequiredForStockMoveLine && endUnit == null) {
              throw new AxelorException(
                  stockMoveHolder[0],
                  TraceBackRepository.CATEGORY_NO_VALUE,
                  I18n.get(StockExceptionMessage.STOCK_MOVE_17));
            }

            computeNetMass(stockMoveLine, endUnit, unitConversionService);
            computeTotalNetMass(stockMoveLine, massesRequiredForStockMoveLine);
          },
          () -> stockMoveHolder[0] = stockMoveRepo.find(stockMoveId));
}

protected void resetMasses(StockMove stockMove) {

  Long stockMoveId = stockMove.getId();
  Query<StockMoveLine> query = getStockMoveLineQuery(stockMoveId);

  BatchProcessorHelper.of()
      .<StockMoveLine>forEachByQuery(query, (StockMoveLine sml) -> sml.setTotalNetMass(null));
}

protected void checkOngoingInventory(StockMove stockMove) throws AxelorException {

  BatchProcessorHelper batchHelper =
      BatchProcessorHelper.builder().flushAfterBatch(false).build();

  Set<Long> stockLocationIds = new HashSet<>();
  Set<Long> productIds = new HashSet<>();
  Long stockMoveId = stockMove.getId();
  Query<StockMoveLine> smlQuery = getStockMoveLineQuery(stockMoveId);

  batchHelper.<StockMoveLine>forEachByQuery(
      smlQuery,
      sml -> {
        StockLocation from = sml.getFromStockLocation();
        StockLocation to = sml.getToStockLocation();
        if (from != null && from.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
          stockLocationIds.add(from.getId());
          Set<Long> locationIds =
              stockLocationService
                  .getLocationAndAllParentLocationsIdsOrderedFromTheClosestToTheFurthest(from);
          if (locationIds != null) {
            stockLocationIds.addAll(locationIds);
          }
        }
        if (to != null && to.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
          stockLocationIds.add(to.getId());
          Set<Long> locationIds =
              stockLocationService
                  .getLocationAndAllParentLocationsIdsOrderedFromTheClosestToTheFurthest(to);
          if (locationIds != null) {
            stockLocationIds.addAll(locationIds);
          }
        }

        if (sml.getProduct() != null) {
          productIds.add(sml.getProduct().getId());
        }
      });

  if (stockLocationIds.isEmpty() || productIds.isEmpty()) {
    return;
  }

  InventoryLineRepository inventoryLineRepo = Beans.get(InventoryLineRepository.class);

  InventoryLine inventoryLine =
      inventoryLineRepo
          .all()
          .filter(
              "self.inventory.isStockMoveBlocked = true\n"
                  + "AND self.inventory.stockLocation.id IN (:stockLocationIds)\n"
                  + "AND self.product.id IN (:productList)")
          .bind("stockLocationIds", stockLocationIds)
          .bind("productList", productIds)
          .fetchOne();

  if (inventoryLine != null) {
    throw new AxelorException(
        inventoryLine,
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_19),
        inventoryLine.getInventory().getInventorySeq());
  }
}

protected void setRealizedStatus(StockMove stockMove) {
  stockMove.setStatusSelect(StockMoveRepository.STATUS_REALIZED);
}

protected void computeTotalNetMass(
    StockMoveLine stockMoveLine, boolean massesRequiredForStockMoveLine) throws AxelorException {
  BigDecimal netMass = stockMoveLine.getNetMass();
  if (netMass.signum() != 0) {
    BigDecimal totalNetMass = netMass.multiply(stockMoveLine.getRealQty());
    stockMoveLine.setTotalNetMass(totalNetMass);
  } else if (massesRequiredForStockMoveLine) {
    throw new AxelorException(
        stockMoveLine.getStockMove(),
        TraceBackRepository.CATEGORY_NO_VALUE,
        I18n.get(StockExceptionMessage.STOCK_MOVE_18));
  }
}

protected void computeNetMass(
    StockMoveLine stockMoveLine, Unit endUnit, UnitConversionService unitConversionService)
    throws AxelorException {
  BigDecimal netMass = stockMoveLine.getNetMass();
  Product product = stockMoveLine.getProduct();
  if (netMass.signum() == 0) {
    Unit startUnit = product.getMassUnit();
    if (startUnit != null && endUnit != null) {
      netMass =
          unitConversionService.convert(
              startUnit, endUnit, product.getNetMass(), product.getNetMass().scale(), null);
      stockMoveLine.setNetMass(netMass);
    }
  }
}

def before_validate(self):
	self.set_has_unit_price_items()
	self.flags.allow_zero_qty = self.has_unit_price_items

def validate_fg_item_for_subcontracting(self):
	if self.is_subcontracted:
		for item in self.items:
			if not item.fg_item:
				frappe.throw(
					_("Row #{0}: Finished Good Item is not specified for service item {1}").format(
						item.idx, item.item_code
					)
				)
			else:
				if not frappe.get_value("Item", item.fg_item, "is_sub_contracted_item"):
					frappe.throw(
						_("Row #{0}: Finished Good Item {1} must be a sub-contracted item").format(
							item.idx, item.fg_item
						)
					)
				if not frappe.db.get_value(
					"Subcontracting BOM",
					{"finished_good": item.fg_item, "is_active": 1},
					"finished_good_bom",
				) and not frappe.get_value("Item", item.fg_item, "default_bom"):
					frappe.throw(
						_("Row #{0}: BOM not found for FG Item {1}").format(item.idx, item.fg_item)
					)
			if not item.fg_item_qty:
				frappe.throw(_("Row #{0}: Finished Good Item Qty can not be zero").format(item.idx))
	else:
		for item in self.items:
			item.set("fg_item", None)
			item.set("fg_item_qty", 0)

def validate_po(self):
	# validate p.o date v/s delivery date
	if self.po_date and not self.skip_delivery_note:
		for d in self.get("items"):
			if d.delivery_date and getdate(self.po_date) > getdate(d.delivery_date):
				frappe.throw(
					_("Row #{0}: Expected Delivery Date cannot be before Purchase Order Date").format(
						d.idx
					)
				)

	if self.po_no and self.customer and not self.skip_delivery_note:
		so = frappe.db.sql(
			"select name from `tabSales Order` \
			where ifnull(po_no, '') = %s and name != %s and docstatus < 2\
			and customer = %s",
			(self.po_no, self.name, self.customer),
		)
		if so and so[0][0]:
			if cint(
				frappe.get_single_value("Selling Settings", "allow_against_multiple_purchase_orders")
			):
				frappe.msgprint(
					_(
						"Warning: Sales Order {0} already exists against Customer's Purchase Order {1}"
					).format(frappe.bold(so[0][0]), frappe.bold(self.po_no)),
					alert=True,
				)
			else:
				frappe.throw(
					_(
						"Sales Order {0} already exists against Customer's Purchase Order {1}. To allow multiple Sales Orders, Enable {2} in {3}"
					).format(
						frappe.bold(so[0][0]),
						frappe.bold(self.po_no),
						frappe.bold(
							_("'Allow Multiple Sales Orders Against a Customer's Purchase Order'")
						),
						get_link_to_form("Selling Settings", "Selling Settings"),
					)
				)

def validate_for_items(self):
	for d in self.get("items"):
		# used for production plan
		d.transaction_date = self.transaction_date

		tot_avail_qty = frappe.db.sql(
			"select projected_qty from `tabBin` \
			where item_code = %s and warehouse = %s",
			(d.item_code, d.warehouse),
		)
		d.projected_qty = tot_avail_qty and flt(tot_avail_qty[0][0]) or 0

def validate_sales_mntc_quotation(self):
	for d in self.get("items"):
		if d.prevdoc_docname:
			res = frappe.db.sql(
				"select name from `tabQuotation` where name=%s and order_type = %s",
				(d.prevdoc_docname, self.order_type),
			)
			if not res:
				frappe.msgprint(
					_("Quotation {0} not of type {1}").format(d.prevdoc_docname, self.order_type)
				)

def validate_delivery_date(self):
	if self.order_type == "Sales" and not self.skip_delivery_note:
		delivery_date_list = [d.delivery_date for d in self.get("items") if d.delivery_date]
		max_delivery_date = max(delivery_date_list) if delivery_date_list else None
		if (max_delivery_date and not self.delivery_date) or (
			max_delivery_date and getdate(self.delivery_date) != getdate(max_delivery_date)
		):
			self.delivery_date = max_delivery_date
		if self.delivery_date:
			for d in self.get("items"):
				if not d.delivery_date:
					d.delivery_date = self.delivery_date
				if getdate(self.transaction_date) > getdate(d.delivery_date):
					frappe.msgprint(
						_("Expected Delivery Date should be after Sales Order Date"),
						indicator="orange",
						title=_("Invalid Delivery Date"),
						raise_exception=True,
					)
		else:
			frappe.throw(_("Please enter Delivery Date"))

	self.validate_sales_mntc_quotation()

def validate_proj_cust(self):
	if self.project and self.customer_name:
		res = frappe.db.sql(
			"""select name from `tabProject` where name = %s
			and (customer = %s or ifnull(customer,'')='')""",
			(self.project, self.customer),
		)
		if not res:
			frappe.throw(
				_("Customer {0} does not belong to project {1}").format(self.customer, self.project)
			)

def validate_warehouse(self):
	super().validate_warehouse()

	for d in self.get("items"):
		if (
			(
				frappe.get_cached_value("Item", d.item_code, "is_stock_item") == 1
				or (
					self.has_product_bundle(d.item_code)
					and self.product_bundle_has_stock_item(d.item_code)
				)
			)
			and not d.warehouse
			and not cint(d.delivered_by_supplier)
		):
			frappe.throw(
				_("Source warehouse required for stock item {0}").format(d.item_code), WarehouseRequired
			)

def validate_with_previous_doc(self):
	super().validate_with_previous_doc(
		{
			"Quotation": {"ref_dn_field": "prevdoc_docname", "compare_fields": [["company", "="]]},
			"Quotation Item": {
				"ref_dn_field": "quotation_item",
				"compare_fields": [["item_code", "="], ["uom", "="], ["conversion_factor", "="]],
				"is_child_table": True,
				"allow_duplicate_prev_row_id": True,
			},
		}
	)

	if cint(frappe.get_single_value("Selling Settings", "maintain_same_sales_rate")):
		self.validate_rate_with_reference_doc([["Quotation", "prevdoc_docname", "quotation_item"]])

def validate_drop_ship(self):
	for d in self.get("items"):
		if d.delivered_by_supplier and not d.supplier:
			frappe.throw(_("Row #{0}: Set Supplier for item {1}").format(d.idx, d.item_code))

def update_reserved_qty(self, so_item_rows=None):
	"""update requested qty (before ordered_qty is updated)"""
	item_wh_list = []

	def _valid_for_reserve(item_code, warehouse):
		if (
			item_code
			and warehouse
			and [item_code, warehouse] not in item_wh_list
			and frappe.get_cached_value("Item", item_code, "is_stock_item")
		):
			item_wh_list.append([item_code, warehouse])

	for d in self.get("items"):
		if (not so_item_rows or d.name in so_item_rows) and not d.delivered_by_supplier:
			if self.has_product_bundle(d.item_code):
				for p in self.get("packed_items"):
					if p.parent_detail_docname == d.name and p.parent_item == d.item_code:
						_valid_for_reserve(p.item_code, p.warehouse)
			else:
				_valid_for_reserve(d.item_code, d.warehouse)

	for item_code, warehouse in item_wh_list:
		update_bin_qty(item_code, warehouse, {"reserved_qty": get_reserved_qty(item_code, warehouse)})

def validate_supplier_after_submit(self):
	"""Check that supplier is the same after submit if PO is already made"""
	exc_list = []

	for item in self.items:
		if item.supplier:
			supplier = frappe.db.get_value("Sales Order Item", item.name, "supplier")
			if item.ordered_qty > 0.0 and item.supplier != supplier:
				exc_list.append(
					_("Row #{0}: Not allowed to change Supplier as Purchase Order already exists").format(
						item.idx
					)
				)

	if exc_list:
		frappe.throw("\n".join(exc_list))

def validate_serial_no_based_delivery(self):
	reserved_items = []
	normal_items = []
	for item in self.items:
		if item.ensure_delivery_based_on_produced_serial_no:
			if item.item_code in normal_items:
				frappe.throw(
					_(
						"Cannot ensure delivery by Serial No as Item {0} is added with and without Ensure Delivery by Serial No."
					).format(item.item_code)
				)
			if item.item_code not in reserved_items:
				if not frappe.get_cached_value("Item", item.item_code, "has_serial_no"):
					frappe.throw(
						_(
							"Item {0} has no Serial No. Only serialized items can have delivery based on Serial No"
						).format(item.item_code)
					)
				if not frappe.db.exists("BOM", {"item": item.item_code, "is_active": 1}):
					frappe.throw(
						_(
							"No active BOM found for item {0}. Delivery by Serial No cannot be ensured"
						).format(item.item_code)
					)
			reserved_items.append(item.item_code)
		else:
			normal_items.append(item.item_code)

		if not item.ensure_delivery_based_on_produced_serial_no and item.item_code in reserved_items:
			frappe.throw(
				_(
					"Cannot ensure delivery by Serial No as Item {0} is added with and without Ensure Delivery by Serial No."
				).format(item.item_code)
			)

def validate_reserved_stock(self):
	"""Clean reserved stock flag for non-stock Item"""

	enable_stock_reservation = frappe.get_single_value("Stock Settings", "enable_stock_reservation")

	for item in self.items:
		if item.reserve_stock and (not enable_stock_reservation or not cint(item.is_stock_item)):
			item.reserve_stock = 0

		if item.ensure_delivery_based_on_produced_serial_no:
			if not enable_stock_reservation:
				item.ensure_delivery_based_on_produced_serial_no = 0
			elif item.reserve_stock:
				# the produced Serial Nos are reserved by the Manufacture Stock Entry; reserving
				# existing stock here would use up the row's reservable qty and skip that
				item.reserve_stock = 0
				frappe.msgprint(
					_(
						"Row #{0}: Stock cannot be reserved for the Item {1} as its delivery is ensured based on the produced Serial Nos. The Work Order will reserve them on manufacture."
					).format(item.idx, frappe.bold(item.item_code)),
					title=_("Stock Reservation"),
					indicator="yellow",
				)

def get_qty_net_of_returns(so_item, credit_note_returned_qty: float = 0) -> float:
	"""Return the ordered quantity billable after returns and re-deliveries."""
	qty = flt(so_item.qty)
	returned_qty = flt(so_item.returned_qty) - flt(credit_note_returned_qty)

	return min(qty, max(qty - returned_qty, flt(so_item.delivered_qty)))

def update_produced_qty_in_so_item(sales_order, sales_order_item):
	# for multiple work orders against same sales order item
	linked_wo_with_so_item = frappe.db.get_all(
		"Work Order",
		["produced_qty"],
		{"sales_order_item": sales_order_item, "sales_order": sales_order, "docstatus": 1},
	)

	total_produced_qty = 0
	for wo in linked_wo_with_so_item:
		total_produced_qty += flt(wo.get("produced_qty"))

	if not total_produced_qty and frappe.flags.in_patch:
		return

	frappe.db.set_value("Sales Order Item", sales_order_item, "produced_qty", total_produced_qty)

def get_credit_note_return_criterion(invoice):
	"""Match return invoices that reverse both the delivery and the billing of Sales Order rows."""
	return (
		(invoice.is_return == 1)
		& (invoice.update_stock == 1)
		& (invoice.update_billed_amount_in_sales_order == 1)
	)

def set_has_unit_price_items(self):
	"""
	If permitted in settings and any item has 0 qty, the SO has unit price items.
	"""
	if not frappe.get_single_value("Selling Settings", "allow_zero_qty_in_sales_order"):
		return

	self.has_unit_price_items = any(
		not row.qty for row in self.get("items") if (row.item_code and not row.qty)
	)

def enable_auto_reserve_stock(self):
	if self.is_new() and frappe.get_single_value("Stock Settings", "auto_reserve_stock"):
		self.reserve_stock = 1

def product_bundle_has_stock_item(self, product_bundle):
	"""Returns true if product bundle has stock item"""
	ret = len(
		frappe.db.sql(
			"""select i.name from tabItem i, `tabProduct Bundle Item` pbi
		where pbi.parent = %s and pbi.item_code = i.name and i.is_stock_item = 1""",
			product_bundle,
		)
	)
	return ret

def update_prevdoc_status(self, flag=None):
	for quotation in set(d.prevdoc_docname for d in self.get("items")):
		if quotation:
			doc = frappe.get_doc("Quotation", quotation)
			if doc.docstatus.is_cancelled():
				frappe.throw(_("Quotation {0} is cancelled").format(quotation))

			doc.set_status(update=True)
			doc.update_opportunity("Converted" if flag == "submit" else "Quotation")

def delete_removed_delivery_schedule_items(self):
	items = [d.name for d in self.get("items")]
	doctype = frappe.qb.DocType("Delivery Schedule Item")
	frappe.qb.from_(doctype).delete().where(
		(doctype.sales_order == self.name) & (doctype.sales_order_item.notin(items))
	).run()

def update_project(self):
	if frappe.get_single_value("Selling Settings", "sales_update_frequency") != "Each Transaction":
		return

	if self.project:
		project = frappe.get_lazy_doc("Project", self.project)
		project.update_sales_amount()
		project.db_update()

def check_credit_limit(self):
	# if bypass credit limit check is set to true (1) at sales order level,
	# then we need not to check credit limit and vise versa
	if not cint(
		frappe.db.get_value(
			"Customer Credit Limit",
			{"parent": self.customer, "parenttype": "Customer", "company": self.company},
			"bypass_credit_limit_check",
		)
	):
		check_credit_limit(self.customer, self.company)

def check_nextdoc_docstatus(self):
	linked_invoices = frappe.db.sql_list(
		"""select distinct t1.name
		from `tabSales Invoice` t1,`tabSales Invoice Item` t2
		where t1.name = t2.parent and t2.sales_order = %s and t1.docstatus = 0""",
		self.name,
	)

	if linked_invoices:
		linked_invoices = [get_link_to_form("Sales Invoice", si) for si in linked_invoices]
		frappe.throw(
			_("Sales Invoice {0} must be deleted before cancelling this Sales Order").format(
				", ".join(linked_invoices)
			)
		)

def delete_delivery_schedule_items(self, sales_order_item=None, ignore_names=None):
	"""Delete delivery schedule items."""
	doctype = frappe.qb.DocType("Delivery Schedule Item")

	query = frappe.qb.from_(doctype).delete().where(doctype.sales_order == self.name)

	if ignore_names:
		query = query.where(doctype.name.notin(ignore_names))

	if sales_order_item:
		query = query.where(doctype.sales_order_item == sales_order_item)

	query.run()

