def update_receiving_percentage(self):
	total_qty, received_qty = 0.0, 0.0
	for item in self.items:
		received_qty += min(item.received_qty, item.qty)
		total_qty += item.qty
	if total_qty and received_qty:
		self.db_set("per_received", flt(received_qty / total_qty) * 100, update_modified=False)
	else:
		self.db_set("per_received", 0, update_modified=False)

def make_subcontracting_order(source_name, target_doc=None, save=False, submit=False, notify=False):
	if not is_po_fully_subcontracted(source_name):
		target_doc = get_mapped_subcontracting_order(source_name, target_doc)

		if (save or submit) and frappe.has_permission(target_doc.doctype, "create"):
			target_doc.save()

			if submit and frappe.has_permission(target_doc.doctype, "submit", target_doc):
				try:
					target_doc.submit()
				except Exception as e:
					target_doc.add_comment("Comment", _("Submit Action Failed") + "<br><br>" + str(e))

			if notify:
				frappe.msgprint(
					_("Subcontracting Order {0} created.").format(
						get_link_to_form(target_doc.doctype, target_doc.name)
					),
					indicator="green",
					alert=True,
				)

		return target_doc
	else:
		frappe.throw(_("This Purchase Order has been fully subcontracted."))

def is_po_fully_subcontracted(po_name):
	table = frappe.qb.DocType("Purchase Order Item")
	query = (
		frappe.qb.from_(table)
		.select(table.name)
		.where((table.parent == po_name) & (table.qty > table.subcontracted_qty))
	)
	return not query.run(as_dict=True)

def get_mapped_subcontracting_order(source_name, target_doc=None):
	def post_process(source_doc, target_doc):
		target_doc.populate_items_table()
		source_rows = {row.name: row for row in source_doc.items}

		if target_doc.set_warehouse:
			for item in target_doc.items:
				item.warehouse = target_doc.set_warehouse
		else:
			if source_doc.set_warehouse:
				for item in target_doc.items:
					item.warehouse = source_doc.set_warehouse
			else:
				for item in target_doc.items:
					item.warehouse = source_rows[item.purchase_order_item].warehouse

		for item in target_doc.items:
			item.job_card = source_rows[item.purchase_order_item].job_card
			if not target_doc.supplier_warehouse:
				# WIP warehouse is set as Supplier Warehouse in Job Card
				target_doc.supplier_warehouse = frappe.get_cached_value(
					"Job Card", item.job_card, "wip_warehouse"
				)

		production_plan = set([item.production_plan for item in source_doc.items if item.production_plan])
		if production_plan:
			target_doc.production_plan = production_plan.pop()
		target_doc.reserve_stock = frappe.get_single_value(
			"Stock Settings", "auto_reserve_stock"
		) or frappe.get_value("Production Plan", target_doc.production_plan, "reserve_stock")

	if target_doc and isinstance(target_doc, str):
		target_doc = json.loads(target_doc)
		for key in ["service_items", "items", "supplied_items"]:
			if key in target_doc:
				del target_doc[key]
		target_doc = json.dumps(target_doc)

	target_doc = get_mapped_doc(
		"Purchase Order",
		source_name,
		{
			"Purchase Order": {
				"doctype": "Subcontracting Order",
				"field_map": {},
				"field_no_map": ["total_qty", "total", "net_total"],
				"validation": {
					"docstatus": ["=", 1],
				},
			},
			"Purchase Order Item": {
				"doctype": "Subcontracting Order Service Item",
				"field_map": {
					"name": "purchase_order_item",
					"material_request": "material_request",
					"material_request_item": "material_request_item",
				},
				"field_no_map": ["qty", "fg_item_qty", "amount"],
				"condition": lambda item: item.qty > item.subcontracted_qty,
			},
		},
		target_doc,
		post_process,
	)

	return target_doc

@Override
@Transactional(rollbackOn = {Exception.class})
public void validateChanges(SaleOrder saleOrder) throws AxelorException {
  checkUnauthorizedDiscounts(saleOrder);
}

@Override
public void checkModifiedConfirmedOrder(SaleOrder saleOrder, SaleOrder saleOrderView)
    throws AxelorException {
  // Nothing to check if we don't have supplychain.
}

@Override
public void checkUnauthorizedDiscounts(SaleOrder saleOrder) throws AxelorException {
  List<SaleOrderLine> saleOrderLineList = saleOrder.getSaleOrderLineList();
  if (saleOrderLineList != null) {
    for (SaleOrderLine saleOrderLine : saleOrderLineList) {
      BigDecimal maxDiscountAuthorized =
          saleOrderLineDiscountService.computeMaxDiscount(saleOrder, saleOrderLine);
      if (saleOrderLine.getDiscountDerogation() != null && maxDiscountAuthorized != null) {
        maxDiscountAuthorized = saleOrderLine.getDiscountDerogation().max(maxDiscountAuthorized);
      }
      if (maxDiscountAuthorized != null
          && saleOrderLineDiscountService.isSaleOrderLineDiscountGreaterThanMaxDiscount(
              saleOrderLine, maxDiscountAuthorized)) {
        throw new AxelorException(
            TraceBackRepository.CATEGORY_INCONSISTENCY,
            I18n.get(SaleExceptionMessage.SALE_ORDER_DISCOUNT_TOO_HIGH));
      }
    }
  }
}

def validate_price_list_country(self):
	from erpnext.stock.doctype.price_list.price_list import validate_price_list_country

	if self.get("is_return") or not self.get("customer_address"):
		return

	country = frappe.db.get_value("Address", self.customer_address, "country")
	validate_price_list_country(self.get("selling_price_list"), country)

def validate_standalone_serial_nos_customer(self):
	if not self.is_return or self.return_against:
		return

	if self.doctype in ["Sales Invoice", "Delivery Note"]:
		bundle_ids = [d.serial_and_batch_bundle for d in self.get("items") if d.serial_and_batch_bundle]
		if not bundle_ids:
			return

		serial_nos = frappe.get_all(
			"Serial and Batch Entry",
			filters={"parent": ("in", bundle_ids), "serial_no": ("is", "set")},
			pluck="serial_no",
		)

		if not serial_nos:
			return

		if serial_nos := frappe.get_all(
			"Serial No",
			filters={"name": ("in", serial_nos), "customer": ("is", "set")},
			fields=["name", "customer"],
		):
			for sn in serial_nos:
				if sn.customer and sn.customer != self.customer:
					frappe.throw(
						_(
							"Serial No {0} is already assigned to customer {1}. Can only be returned against the customer {1}"
						).format(frappe.bold(sn.name), frappe.bold(sn.customer)),
						title=_("Serial No Already Assigned"),
					)

def validate_sales_team(self, sales_team):
	sales_persons = [d.sales_person for d in sales_team]

	if not sales_persons:
		return

	sales_person_status = frappe.db.get_all(
		"Sales Person", filters={"name": ["in", sales_persons]}, fields=["name", "enabled"]
	)

	for row in sales_person_status:
		if not row.enabled:
			frappe.throw(_("Sales Person <b>{0}</b> is disabled.").format(row.name))

def validate_max_discount(self):
	for d in self.get("items"):
		if d.item_code:
			discount = flt(frappe.get_cached_value("Item", d.item_code, "max_discount"))

			if discount and flt(d.discount_percentage) > discount:
				frappe.throw(_("Maximum discount for Item {0} is {1}%").format(d.item_code, discount))

def validate_selling_price(self):
	def throw_message(idx, item_name, rate, ref_rate_field):
		throw(
			_(
				"""Row #{0}: Selling rate for item {1} is lower than its {2}.
				Selling {3} should be atleast {4}.<br><br>Alternatively,
				you can disable '{5}' in {6} to bypass
				this validation."""
			).format(
				idx,
				bold(item_name),
				bold(ref_rate_field),
				bold("net rate"),
				bold(rate),
				bold(frappe.get_meta("Selling Settings").get_label("validate_selling_price")),
				get_link_to_form("Selling Settings"),
			),
			title=_("Invalid Selling Price"),
		)

	if self.get("is_return") or not frappe.get_single_value("Selling Settings", "validate_selling_price"):
		return

	is_internal_customer = self.get("is_internal_customer")

	for item in self.items:
		if not item.item_code or item.is_free_item:
			continue

		last_purchase_rate, is_stock_item = frappe.get_cached_value(
			"Item", item.item_code, ("last_purchase_rate", "is_stock_item")
		)

		last_purchase_rate_in_sales_uom = flt(
			last_purchase_rate * (item.conversion_factor or 1), item.precision("base_net_rate")
		)

		if flt(item.base_net_rate) < flt(last_purchase_rate_in_sales_uom):
			throw_message(item.idx, item.item_name, last_purchase_rate_in_sales_uom, "last purchase rate")

		if is_internal_customer or not is_stock_item:
			continue

		rate_field = "valuation_rate" if self.doctype in ["Sales Order", "Quotation"] else "incoming_rate"
		if item.get(rate_field) and item.base_net_rate < (
			valuation_rate := flt(
				item.get(rate_field) * (item.conversion_factor or 1), item.precision("base_net_rate")
			)
		):
			throw_message(
				item.idx,
				item.item_name,
				valuation_rate,
				"valuation rate",
			)

def update_reserved_qty(self):
	so_map = {}
	for d in self.get("items"):
		if d.so_detail:
			if self.doctype == "Delivery Note" and d.against_sales_order:
				so_map.setdefault(d.against_sales_order, []).append(d.so_detail)
			elif self.doctype == "Sales Invoice" and d.sales_order and self.update_stock:
				so_map.setdefault(d.sales_order, []).append(d.so_detail)

	for so, so_item_rows in so_map.items():
		if so and so_item_rows:
			sales_order = frappe.get_lazy_doc("Sales Order", so)

			if (sales_order.status == "Closed" and not self.is_return) or sales_order.status in [
				"Cancelled"
			]:
				frappe.throw(
					_("{0} {1} is cancelled or closed").format(_("Sales Order"), so),
					frappe.InvalidStatusError,
				)

			sales_order.update_reserved_qty(so_item_rows)

def validate_for_duplicate_items(self):
	check_list, chk_dupl_itm = [], []
	if cint(frappe.get_single_value("Selling Settings", "allow_multiple_items")):
		return
	if self.doctype == "Sales Invoice" and self.is_consolidated:
		return
	if self.doctype == "POS Invoice":
		return

	items = [item.item_code for item in self.get("items")]
	item_stock_map = frappe._dict(
		frappe.get_all(
			"Item",
			filters={"item_code": ["in", items]},
			fields=["item_code", "is_stock_item"],
			as_list=True,
		)
	)

	for d in self.get("items"):
		if self.doctype == "Sales Invoice":
			stock_items = [
				d.item_code,
				d.description,
				d.warehouse,
				d.sales_order or d.delivery_note,
				d.batch_no or "",
			]
			non_stock_items = [d.item_code, d.description, d.sales_order or d.delivery_note]
		elif self.doctype == "Delivery Note":
			stock_items = [
				d.item_code,
				d.description,
				d.warehouse,
				d.against_sales_order or d.against_sales_invoice,
				d.batch_no or "",
			]
			non_stock_items = [
				d.item_code,
				d.description,
				d.against_sales_order or d.against_sales_invoice,
			]
		elif self.doctype in ["Sales Order", "Quotation"]:
			stock_items = [d.item_code, d.description, d.warehouse, ""]
			non_stock_items = [d.item_code, d.description]

		duplicate_items_msg = _("Item {0} entered multiple times.").format(frappe.bold(d.item_code))
		duplicate_items_msg += "<br><br>"
		duplicate_items_msg += _("Please enable {} in {} to allow same item in multiple rows").format(
			frappe.bold(_("Allow Item to Be Added Multiple Times in a Transaction")),
			get_link_to_form("Selling Settings", "Selling Settings"),
		)
		if item_stock_map.get(d.item_code):
			if stock_items in check_list:
				frappe.throw(duplicate_items_msg)
			else:
				check_list.append(stock_items)
		else:
			if non_stock_items in chk_dupl_itm:
				frappe.throw(duplicate_items_msg)
			else:
				chk_dupl_itm.append(non_stock_items)

def validate_target_warehouse(self):
	items = self.get("items") + (self.get("packed_items") or [])

	for d in items:
		if d.get("target_warehouse") and d.get("warehouse") == d.get("target_warehouse"):
			warehouse = frappe.bold(d.get("target_warehouse"))
			frappe.throw(
				_(
					"Row {0}: Delivery Warehouse ({1}) and Customer Warehouse ({2}) can not be same"
				).format(d.idx, warehouse, warehouse)
			)

	if not self.get("is_internal_customer") and any(d.get("target_warehouse") for d in items):
		msg = _("Target Warehouse is set for some items but the customer is not an internal customer.")
		msg += " " + _("This {} will be treated as material transfer.").format(_(self.doctype))
		frappe.msgprint(msg, title="Internal Transfer", alert=True)

def validate_sample_retention_warehouse(self):
	if self.get("is_return"):
		return

	sample_retention_warehouse = frappe.get_cached_value(
		"Company", self.company, "sample_retention_warehouse"
	)
	if not sample_retention_warehouse:
		return

	items = self.get("items") + (self.get("packed_items"))
	for item in items:
		if item.get("warehouse") == sample_retention_warehouse:
			frappe.throw(
				_("Row {0}: Cannot sell item {1} from Sample Retention Warehouse {2}").format(
					item.idx, frappe.bold(item.item_code), frappe.bold(sample_retention_warehouse)
				),
				title=_("Not Allowed"),
			)

def set_qty_as_per_stock_uom(self):
	allow_to_edit_stock_qty = frappe.get_single_value(
		"Stock Settings", "allow_to_edit_stock_uom_qty_for_sales"
	)

	for d in self.get("items"):
		if d.meta.get_field("stock_qty"):
			if not d.conversion_factor:
				frappe.throw(_("Row {0}: Conversion Factor is mandatory").format(d.idx))
			d.stock_qty = flt(d.qty) * flt(d.conversion_factor)
			if allow_to_edit_stock_qty:
				d.stock_qty = flt(d.stock_qty, d.precision("stock_qty"))

def set_po_nos(self, for_validate=False):
	if self.doctype == "Sales Invoice" and hasattr(self, "items"):
		if for_validate and self.po_no:
			return
		self.set_pos_for_sales_invoice()
	if self.doctype == "Delivery Note" and hasattr(self, "items"):
		if for_validate and self.po_no:
			return
		self.set_pos_for_delivery_note()

def set_gross_profit(self):
	if self.doctype in ["Sales Order", "Quotation"]:
		for item in self.items:
			item.gross_profit = flt(
				((flt(item.stock_uom_rate) - flt(item.valuation_rate)) * item.stock_qty),
				self.precision("amount", item),
			)

def set_customer_address(self):
	address_dict = {
		"customer_address": "address_display",
		"shipping_address_name": "shipping_address",
		"company_address": "company_address_display",
		"dispatch_address_name": "dispatch_address",
	}

	for address_field, address_display_field in address_dict.items():
		if self.get(address_field):
			self.set(
				address_display_field, render_address(self.get(address_field), check_permissions=False)
			)

def get_po_nos(self, ref_doctype, ref_fieldname, po_nos):
	doc_list = list(set(d.get(ref_fieldname) for d in self.items if d.get(ref_fieldname)))
	if doc_list:
		po_nos += [
			d.po_no
			for d in frappe.get_all(ref_doctype, "po_no", filters={"name": ("in", doc_list)})
			if d.get("po_no")
		]

def validate_posting_date_with_po(self):
	po_list = {x.purchase_order for x in self.items if x.purchase_order}

	if not po_list:
		return

	invalid_po = []
	po_dates = frappe._dict(
		frappe.get_all(
			"Purchase Order",
			filters={"name": ["in", po_list]},
			fields=["name", "transaction_date"],
			as_list=True,
		)
	)

	for po in po_list:
		po_date = po_dates[po]
		if getdate(po_date) > getdate(self.posting_date):
			invalid_po.append((get_link_to_form("Purchase Order", po), format_date(po_date)))

	if not invalid_po:
		return

	msg = _("<p>Posting Date {0} cannot be before Purchase Order date for the following:</p><ul>").format(
		frappe.bold(format_date(self.posting_date))
	)

	for po, date in invalid_po:
		msg += f"<li>{po} ({date})</li>"
	msg += "</ul>"

	frappe.throw(_(msg))

def validate_stock_or_nonstock_items(self):
	if self.meta.get_field("taxes") and not self.get_stock_items() and not self.get_asset_items():
		msg = _('Tax Category has been changed to "Total" because all the Items are non-stock items')
		self.update_tax_category(msg)

def validate_asset_return(self):
	if self.doctype not in ["Purchase Receipt", "Purchase Invoice"] or not self.is_return:
		return

	purchase_doc_field = "purchase_receipt" if self.doctype == "Purchase Receipt" else "purchase_invoice"
	not_cancelled_asset = []
	if self.return_against:
		not_cancelled_asset = [
			d.name
			for d in frappe.db.get_all("Asset", {purchase_doc_field: self.return_against, "docstatus": 1})
		]

	if self.is_return and len(not_cancelled_asset):
		frappe.throw(
			_(
				"{} has submitted assets linked to it. You need to cancel the assets to create purchase return."
			).format(self.return_against),
			title=_("Not Allowed"),
		)

	self.validate_assets_left_after_return()

def validate_assets_left_after_return(self):
	if self.doctype == "Purchase Invoice" and not self.get("update_stock"):
		return

	detail_field = (
		"purchase_receipt_item" if self.doctype == "Purchase Receipt" else "purchase_invoice_item"
	)
	returned_qty, rows = self.get_returned_asset_qty(detail_field)
	if not returned_qty:
		return

	kept_qty = self.get_qty_kept_after_return(detail_field, returned_qty)
	for detail, asset_qty in get_linked_asset_qty(detail_field, list(returned_qty)).items():
		if flt(asset_qty) > kept_qty[detail]:
			frappe.throw(
				_(
					"Row #{0}: {1} assets of {2} are linked to {3}, which keeps only {4} after this return. Delete the extra draft assets first."
				).format(
					rows[detail].idx,
					flt(asset_qty),
					frappe.bold(rows[detail].item_code),
					get_link_to_form(self.doctype, self.return_against),
					kept_qty[detail],
				),
				title=_("Not Allowed"),
			)

def get_returned_asset_qty(self, detail_field):
	returned_qty, rows = {}, {}
	for d in self.items:
		if d.is_fixed_asset and d.get(detail_field):
			returned_qty[d.get(detail_field)] = returned_qty.get(d.get(detail_field), 0) + abs(flt(d.qty))
			rows.setdefault(d.get(detail_field), d)

	return returned_qty, rows

def validate_from_warehouse(self):
	for item in self.get("items"):
		if item.get("from_warehouse") and (item.get("from_warehouse") == item.get("warehouse")):
			frappe.throw(
				_("Row #{idx}: {from_warehouse_field} and {to_warehouse_field} cannot be same.").format(
					idx=item.idx,
					from_warehouse_field=_(item.meta.get_label("from_warehouse")),
					to_warehouse_field=_(item.meta.get_label("warehouse")),
				)
			)

		if item.get("from_warehouse") and self.get("is_subcontracted"):
			frappe.throw(
				_(
					"Row #{idx}: Cannot select Supplier Warehouse while suppling raw materials to subcontractor."
				).format(idx=item.idx)
			)

def get_validated_purchase_expense_details(self, item_code):
	fields = ("purchase_expense_account", "purchase_expense_contra_account")
	details = get_purchase_expense_account(item_code, self.company)

	for field in fields:
		if not details.get(field):
			details[field] = frappe.get_cached_value("Company", self.company, field)

	for field in fields:
		if not details.get(field):
			frappe.throw(
				_("Please set {0} in Company {1} or in the Item Defaults of Item {2}").format(
					frappe.bold(_(frappe.unscrub(field))), self.company, item_code
				)
			)

	return details

def validate_for_subcontracting(self):
	if self.is_subcontracted and self.get("is_old_subcontracting_flow"):
		if self.doctype in ["Purchase Receipt", "Purchase Invoice"] and not self.supplier_warehouse:
			frappe.throw(
				_("{field_label} is mandatory for sub-contracted {doctype}.").format(
					field_label=_(self.meta.get_label("supplier_warehouse")), doctype=_(self.doctype)
				)
			)

		for item in self.get("items"):
			if item in self.sub_contracted_items and not item.bom:
				frappe.throw(
					_("Please select BOM in BOM field for Item {item_code}.").format(
						item_code=frappe.bold(item.item_code)
					)
				)
		if self.doctype != "Purchase Order":
			return
		for row in self.get("supplied_items"):
			if not row.reserve_warehouse:
				frappe.throw(
					_(
						"Reserved Warehouse is mandatory for the Item {item_code} in Raw Materials supplied."
					).format(item_code=frappe.bold(row.rm_item_code))
				)
	else:
		for item in self.get("items"):
			if item.get("bom"):
				item.bom = None

def validate_purchase_return(self):
	for d in self.get("items"):
		if self.is_return and not flt(d.rejected_qty) and d.rejected_warehouse:
			d.rejected_warehouse = None

def validate_accepted_rejected_qty(self):
	for d in self.get("items"):
		self.validate_negative_quantity(d, ["received_qty", "qty", "rejected_qty"])

		if not flt(d.received_qty) and (flt(d.qty) or flt(d.rejected_qty)):
			d.received_qty = flt(d.qty) + flt(d.rejected_qty)

		# Check Received Qty = Accepted Qty + Rejected Qty
		val = flt(d.qty) + flt(d.rejected_qty)
		if flt(val, d.precision("received_qty")) != flt(d.received_qty, d.precision("received_qty")):
			message = _(
				"Row #{idx}: Received Qty must be equal to Accepted + Rejected Qty for Item {item_code}."
			).format(idx=d.idx, item_code=frappe.bold(d.item_code))
			frappe.throw(msg=message, title=_("Mismatch"), exc=QtyMismatchError)

def validate_negative_quantity(self, item_row, field_list):
	if self.is_return:
		return

	item_row = item_row.as_dict()
	for fieldname in field_list:
		if flt(item_row[fieldname]) < 0:
			frappe.throw(
				_("Row #{idx}: {field_label} can not be negative for item {item_code}.").format(
					idx=item_row["idx"],
					field_label=frappe.get_meta(item_row.doctype).get_label(fieldname),
					item_code=frappe.bold(item_row["item_code"]),
				)
			)

def update_ordered_and_reserved_qty(self):
	po_map = {}
	for d in self.get("items"):
		if self.doctype == "Purchase Receipt" and d.purchase_order:
			po_map.setdefault(d.purchase_order, []).append(d.purchase_order_item)

		elif self.doctype == "Purchase Invoice" and d.purchase_order and d.po_detail:
			po_map.setdefault(d.purchase_order, []).append(d.po_detail)

	for po, po_item_rows in po_map.items():
		if po and po_item_rows:
			po_obj = frappe.get_lazy_doc("Purchase Order", po)

			if po_obj.status == "Cancelled" or (po_obj.status == "Closed" and not self.get("is_return")):
				frappe.throw(
					_("{doctype} {name} is cancelled or closed.").format(
						doctype=frappe.bold(_("Purchase Order")),
						name=frappe.bold(po),
					),
					frappe.InvalidStatusError,
				)

			po_obj.update_ordered_qty(po_item_rows)
			if self.get("is_old_subcontracting_flow"):
				po_obj.update_reserved_qty_for_subcontract()

def on_submit(self):
	if self.get("is_return"):
		return

	if self.doctype in ["Purchase Receipt", "Purchase Invoice"]:
		self.process_fixed_asset()

	if self.doctype in ["Purchase Order", "Purchase Receipt", "Purchase Invoice"]:
		update_last_purchase_rate(self, is_submit=1)

def on_cancel(self):
	super().on_cancel()

	if self.get("is_return"):
		return

	if self.doctype in ["Purchase Order", "Purchase Receipt", "Purchase Invoice"]:
		update_last_purchase_rate(self, is_submit=0)

	if self.doctype in ["Purchase Receipt", "Purchase Invoice"]:
		field = "purchase_invoice" if self.doctype == "Purchase Invoice" else "purchase_receipt"

		self.delete_linked_asset()
		self.update_fixed_asset(field, delete_asset=True)

def validate_budget(self):
	if not frappe.get_single_value("Accounts Settings", "use_legacy_budget_controller"):
		from erpnext.controllers.budget_controller import BudgetValidation

		val = BudgetValidation(doc=self)
		val.validate()
	else:
		if self.docstatus == 1:
			for data in self.get("items"):
				args = data.as_dict()
				args.update(
					{
						"doctype": self.doctype,
						"company": self.company,
						"posting_date": (
							self.schedule_date
							if self.doctype == "Material Request"
							else self.transaction_date
						),
					}
				)

				validate_expense_against_budget(args)

def process_fixed_asset(self):
	if self.doctype == "Purchase Invoice" and not self.update_stock:
		return

	asset_items = self.get_asset_items()
	if asset_items:
		self.auto_make_assets(asset_items)

def validate_schedule_date(self):
	if not self.get("items"):
		return

	if any(d.schedule_date for d in self.get("items")):
		# Select earliest schedule_date.
		self.schedule_date = min(
			d.schedule_date for d in self.get("items") if d.schedule_date is not None
		)

	if self.schedule_date:
		for d in self.get("items"):
			if not d.schedule_date:
				d.schedule_date = self.schedule_date

			if (
				d.schedule_date
				and self.transaction_date
				and getdate(d.schedule_date) < getdate(self.transaction_date)
			):
				frappe.throw(
					_("Row #{idx}: {schedule_date} cannot be before {transaction_date}.").format(
						idx=d.idx,
						schedule_date=_(self.meta.get_label("schedule_date")),
						transaction_date=_(self.meta.get_label("transaction_date")),
					)
				)
	else:
		frappe.throw(
			_("Please enter the {schedule_date}.").format(
				schedule_date=_(self.meta.get_label("schedule_date"))
			)
		)

def validate_items(self):
	# validate items to see if they have is_purchase_item or is_subcontracted_item enabled
	if self.doctype == "Material Request":
		return

	if self.get("is_old_subcontracting_flow"):
		validate_item_type(self, "is_sub_contracted_item", "subcontracted")
	else:
		validate_item_type(self, "is_purchase_item", "purchase")

def validate_item_type(doc, fieldname, message):
	# iterate through items and check if they are valid sales or purchase items
	items = [d.item_code for d in doc.items if d.item_code]

	# No validation check inase of creating transaction using 'Opening Invoice Creation Tool'
	if not items:
		return

	item_list = ", ".join(["%s" % frappe.db.escape(d) for d in items])

	invalid_items = [
		d[0]
		for d in frappe.db.sql(
			f"""
		select item_code from tabItem where name in ({item_list}) and {fieldname}=0
		""",
			as_list=True,
		)
	]

	if invalid_items:
		items = ", ".join([d for d in invalid_items])

		if len(invalid_items) > 1:
			error_message = _(
				"The items {items} are not marked as {type_of} item. You can enable them as {type_of} item from their Item masters."
			).format(
				items=items,
				type_of=message,
			)
		else:
			error_message = _(
				"The item {item} is not marked as {type_of} item. You can enable it as {type_of} item from its Item master."
			).format(
				item=items,
				type_of=message,
			)

		frappe.throw(error_message)

def create_package_for_transfer(self) -> None:
	"""Create serial and batch package for Sourece Warehouse in case of inter transfer."""

	if self.is_internal_transfer() and (
		self.doctype == "Purchase Receipt" or (self.doctype == "Purchase Invoice" and self.update_stock)
	):
		field = "delivery_note_item" if self.doctype == "Purchase Receipt" else "sales_invoice_item"

		doctype = "Delivery Note Item" if self.doctype == "Purchase Receipt" else "Sales Invoice Item"

		ids = [d.get(field) for d in self.get("items") if d.get(field)]
		bundle_ids = {}
		if ids:
			for bundle in frappe.get_all(
				doctype, filters={"name": ("in", ids)}, fields=["serial_and_batch_bundle", "name"]
			):
				bundle_ids[bundle.name] = bundle.serial_and_batch_bundle

		bundle_ids.update(self.get_component_packages())

		if not bundle_ids:
			return

		for item in self.get("items"):
			reference = item.get(field) or item.get("delivery_note_packed_item")
			if reference and not item.serial_and_batch_bundle and bundle_ids.get(reference):
				item.serial_and_batch_bundle = self.make_package_for_transfer(
					bundle_ids.get(reference),
					item.from_warehouse,
					type_of_transaction="Outward",
					do_not_submit=True,
					qty=item.qty,
				)
			elif (
				not self.is_new()
				and item.serial_and_batch_bundle
				and next(
					(
						old_item
						for old_item in self.get_doc_before_save().items
						if old_item.name == item.name and old_item.qty != item.qty
					),
					None,
				)
				and len(
					sabe := frappe.get_all(
						"Serial and Batch Entry",
						filters={"parent": item.serial_and_batch_bundle, "serial_no": ["is", "not set"]},
						pluck="name",
					)
				)
				== 1
			):
				frappe.set_value("Serial and Batch Entry", sabe[0], "qty", item.qty)

def set_rate_for_standalone_debit_note(self):
	if self.get("is_return") and self.get("update_stock") and not self.return_against:
		for row in self.items:
			if row.rate <= 0:
				# override the rate with valuation rate
				row.rate = _get_incoming_rate(
					{
						"item_code": row.item_code,
						"warehouse": row.warehouse,
						"posting_date": self.get("posting_date"),
						"posting_time": self.get("posting_time"),
						"qty": row.qty,
						"serial_and_batch_bundle": row.get("serial_and_batch_bundle"),
						"company": self.company,
						"voucher_type": self.doctype,
						"voucher_no": self.name,
						"voucher_detail_no": row.name,
					},
					raise_error_if_no_rate=False,
				)

				row.discount_percentage = 0.0
				row.discount_amount = 0.0
				row.margin_rate_or_amount = 0.0

def set_supplier_address(self):
	address_dict = {
		"supplier_address": "address_display",
		"shipping_address": "shipping_address_display",
		"dispatch_address": "dispatch_address_display",
		"billing_address": "billing_address_display",
	}

	for address_field, address_display_field in address_dict.items():
		if self.get(address_field):
			self.set(
				address_display_field, render_address(self.get(address_field), check_permissions=False)
			)

def set_qty_as_per_stock_uom(self):
	allow_to_edit_stock_qty = frappe.get_single_value(
		"Stock Settings", "allow_to_edit_stock_uom_qty_for_purchase"
	)
	whole_number_uoms = get_whole_number_uoms(d.get("stock_uom") for d in self.get("items"))

	for d in self.get("items"):
		if d.meta.get_field("stock_qty"):
			# Check if item code is present
			# Conversion factor should not be mandatory for non itemized items
			if not d.conversion_factor and d.item_code:
				frappe.throw(
					_("Row #{idx}: {field_label} is mandatory.").format(
						idx=d.idx,
						field_label=_(d.meta.get_label("conversion_factor")),
					)
				)
			d.stock_qty = flt(d.qty) * flt(d.conversion_factor)

			if self.doctype == "Purchase Receipt" and d.meta.get_field("received_stock_qty"):
				# Set Received Qty in Stock UOM
				d.received_stock_qty = flt(d.received_qty) * flt(
					d.conversion_factor, d.precision("conversion_factor")
				)

			if allow_to_edit_stock_qty or d.get("stock_uom") in whole_number_uoms:
				d.stock_qty = flt(d.stock_qty, d.precision("stock_qty"))
				if d.get("received_stock_qty") and d.meta.get_field("received_stock_qty"):
					d.received_stock_qty = flt(d.received_stock_qty, d.precision("received_stock_qty"))

def get_asset_items(self):
	if self.doctype not in ["Purchase Order", "Purchase Invoice", "Purchase Receipt"]:
		return []

	return [d.item_code for d in self.items if d.is_fixed_asset]

def get_linked_asset_qty(detail_field, details):
	asset = frappe.qb.DocType("Asset")
	return dict(
		(
			frappe.qb.from_(asset)
			.select(asset[detail_field], Sum(asset.asset_quantity))
			.where((asset[detail_field].isin(details)) & (asset.docstatus < 2))
			.groupby(asset[detail_field])
		).run()
	)

def get_purchase_expense_account(item_code, company):
	defaults = get_item_defaults(item_code, company)

	details = frappe._dict(
		{
			"purchase_expense_account": defaults.get("purchase_expense_account"),
			"purchase_expense_contra_account": defaults.get("purchase_expense_contra_account"),
		}
	)

	if not details.purchase_expense_account:
		details = frappe.db.get_value(
			"Item Default",
			{"parent": defaults.item_group, "company": company},
			["purchase_expense_account", "purchase_expense_contra_account"],
			as_dict=1,
		) or frappe._dict({})

	if not details.purchase_expense_account:
		details = frappe.db.get_value(
			"Item Default",
			{"parent": defaults.brand, "company": company},
			["purchase_expense_account", "purchase_expense_contra_account"],
			as_dict=1,
		)

	return details or frappe._dict({})

def update_fixed_asset(self, field, delete_asset=False):
	for d in self.get("items"):
		if d.is_fixed_asset:
			is_auto_create_enabled = frappe.db.get_value("Item", d.item_code, "auto_create_assets")
			assets = frappe.db.get_all("Asset", filters={field: self.name, "item_code": d.item_code})

			for asset in assets:
				asset = frappe.get_doc("Asset", asset.name)
				if delete_asset and is_auto_create_enabled:
					# need to delete movements to delete assets otherwise throws link exists error
					movements = frappe.db.sql(
						"""SELECT asm.name
						FROM `tabAsset Movement` asm, `tabAsset Movement Item` asm_item
						WHERE asm_item.parent=asm.name and asm_item.asset=%s""",
						asset.name,
						as_dict=1,
					)
					for movement in movements:
						frappe.delete_doc("Asset Movement", movement.name, force=1)
					frappe.delete_doc("Asset", asset.name, force=1)
					continue

				if self.docstatus == 2:
					if asset.docstatus == 2:
						continue
					if asset.docstatus == 0:
						asset.set(field, None)
						asset.supplier = None
					if asset.docstatus == 1 and delete_asset:
						frappe.throw(
							_(
								"Cannot cancel this document as it is linked with the submitted asset {asset_link}. Please cancel the asset to continue."
							).format(asset_link=frappe.utils.get_link_to_form("Asset", asset.name))
						)

				asset.flags.ignore_validate_update_after_submit = True
				asset.flags.ignore_mandatory = True
				if asset.docstatus == 0:
					asset.flags.ignore_validate = True

				asset.save()

def delete_linked_asset(self):
	if self.doctype == "Purchase Invoice" and not self.get("update_stock"):
		return

	asset_movement = frappe.db.get_value("Asset Movement", {"reference_name": self.name}, "name")
	frappe.delete_doc("Asset Movement", asset_movement, force=1)

def auto_make_assets(self, asset_items):
	items_data = get_asset_item_details(asset_items)
	messages = []
	alert = False
	accounting_dimensions = get_dimensions(with_cost_center_and_project=True)

	for d in self.items:
		if d.is_fixed_asset:
			item_data = items_data.get(d.item_code)

			if item_data.get("auto_create_assets"):
				# If asset has to be auto created
				# Check for asset naming series
				if item_data.get("asset_naming_series"):
					created_assets = []
					if item_data.get("is_grouped_asset"):
						asset = self.make_asset(d, accounting_dimensions, is_grouped_asset=True)
						created_assets.append(asset)
					else:
						for _qty in range(cint(d.qty)):
							asset = self.make_asset(d, accounting_dimensions)
							created_assets.append(asset)

					if len(created_assets) > 5:
						# dont show asset form links if more than 5 assets are created
						messages.append(
							_("{count} Assets created for {item_code}").format(
								count=len(created_assets), item_code=frappe.bold(d.item_code)
							)
						)
					else:
						assets_link = list(
							map(lambda d: frappe.utils.get_link_to_form("Asset", d), created_assets)
						)
						assets_link = frappe.bold(",".join(assets_link))

						if len(created_assets) == 1:
							msg = _("Asset {assets_link} created for {item_code}").format(
								assets_link=assets_link,
								item_code=frappe.bold(d.item_code),
							)
						else:
							msg = _("Assets {assets_link} created for {item_code}").format(
								assets_link=assets_link,
								item_code=frappe.bold(d.item_code),
							)
						messages.append(msg)
				else:
					frappe.throw(
						_(
							"Row {idx}: Asset Naming Series is mandatory for the auto creation of assets for item {item_code}."
						).format(idx=d.idx, item_code=frappe.bold(d.item_code))
					)
			else:
				messages.append(
					_(
						"Assets not created for {item_code}. You will have to create asset manually."
					).format(item_code=frappe.bold(d.item_code))
				)
				alert = True

	for message in messages:
		frappe.msgprint(message, title="Success", indicator="green", alert=alert)

def get_component_packages(self) -> dict:
	packed_items = [
		d.delivery_note_packed_item for d in self.get("items") if d.get("delivery_note_packed_item")
	]
	if not packed_items:
		return {}

	return frappe._dict(
		frappe.get_all(
			"Packed Item",
			filters={"name": ("in", packed_items)},
			fields=["name", "serial_and_batch_bundle"],
			as_list=True,
		)
	)

def get_asset_item_details(asset_items):
	asset_items_data = {}
	for d in frappe.get_all(
		"Item",
		fields=["name", "auto_create_assets", "asset_naming_series", "is_grouped_asset"],
		filters={"name": ("in", asset_items)},
	):
		asset_items_data.setdefault(d.name, d)

	return asset_items_data

def set_supplier_from_item_default(self):
	if self.meta.get_field("supplier") and not self.supplier:
		for d in self.get("items"):
			supplier = frappe.db.get_value(
				"Item Default", {"parent": d.item_code, "company": self.company}, "default_supplier"
			)
			if supplier:
				self.supplier = supplier
			else:
				item_group = frappe.db.get_value("Item", d.item_code, "item_group")
				supplier = frappe.db.get_value(
					"Item Default", {"parent": item_group, "company": self.company}, "default_supplier"
				)
				if supplier:
					self.supplier = supplier
				break

def _unlink_except_confirmed(self):
    if self._check_line_unlink():
        raise UserError(
            self.env._(
                "Once a sales order is confirmed, you can't remove one of its lines (we need to"
                " track if something gets invoiced or delivered).\nSet the quantity to 0"
                " instead."
            )
        )

def _merge_po_line(self, rfq_line):
    self.product_qty += rfq_line.product_qty
    self.price_unit = min(self.price_unit, rfq_line.price_unit)

def _compute_display_name(self):
    super()._compute_display_name()
    for workcenter in self:
        # Show the red icon(workcenter is blocked) only when the Gantt view is accessed from MRP > Planning > Planning by Workcenter.
        if self.env.context.get('group_by') and self.env.context.get('show_workcenter_status') and workcenter.working_state == 'blocked':
            workcenter.display_name = f"{workcenter.display_name}\u00A0\u00A0🔴"

def _check_alternative_workcenter(self):
    for workcenter in self:
        if workcenter in workcenter.alternative_workcenter_ids:
            raise ValidationError(_("Workcenter %s cannot be an alternative of itself.", workcenter.name))

def _compute_kanban_dashboard_graph(self):
    week_range, date_start, date_stop = self._get_week_range_and_first_last_days()
    load_data = self._get_workcenter_load_per_week(week_range, date_start, date_stop)
    load_graph_data = self._prepare_graph_data(load_data, week_range)
    for wc in self:
        wc.kanban_dashboard_graph = json.dumps(load_graph_data[wc.id])

def _get_workcenter_load_per_week(self, week_range, date_start, date_stop):
    load_data = {rec: {} for rec in self}
    # demo data
    has_workorder = self.env['mrp.workorder'].search_count([('workcenter_id', 'in', self.ids)], limit=1)
    if not has_workorder:
        for wc in self:
            load_limit = 40     # default max load per week is 40 hours on a new workcenter
            load_data[wc] = {week_start: randint(0, int(load_limit * 2)) for week_start in week_range}
        return load_data

    result = self.env['mrp.workorder']._read_group(
        [('workcenter_id', 'in', self.ids), ('state', 'in', ('pending', 'waiting', 'ready', 'progress')),
         ('production_date', '>=', date_start), ('production_date', '<=', date_stop)],
        ['workcenter_id', 'production_date:week'], ['duration_expected:sum'])
    for r in result:
        load_in_hours = round(r[2] / 60, 1)
        load_data[r[0]].update({r[1]: load_in_hours})
    return load_data

def _prepare_graph_data(self, load_data, week_range):
    graph_data = {wid: [] for wid in self._ids}
    has_workorder = self.env['mrp.workorder'].search_count([('workcenter_id', 'in', self.ids)], limit=1)
    for workcenter in self:
        load_limit = workcenter.resource_calendar_id.hours_per_week
        wc_data = {'is_sample_data': not has_workorder, 'labels': list(week_range.values())}
        load_bar = []
        excess_bar = []
        for week_start in week_range:
            load_bar.append(min(load_data[workcenter].get(week_start, 0), load_limit))
            excess_bar.append(max(float_round(load_data[workcenter].get(week_start, 0) - load_limit, precision_digits=1, rounding_method='HALF-UP'), 0))
        wc_data['values'] = [load_bar, load_limit, excess_bar]
        graph_data[workcenter.id].append(wc_data)
    return graph_data

def _compute_working_state(self):
    # We search for a productivity line associated to this workcenter having no `date_end`.
    # If we do not find one, the workcenter is not currently being used. If we find one, according
    # to its `type_loss`, the workcenter is either being used or blocked.
    time_log_by_workcenter = {}
    for time_log in self.env['mrp.workcenter.productivity'].search([
        ('workcenter_id', 'in', self.ids),
        ('date_end', '=', False),
    ]):
        wc = time_log.workcenter_id
        if wc not in time_log_by_workcenter:
            time_log_by_workcenter[wc] = time_log

    for workcenter in self:
        time_log = time_log_by_workcenter.get(workcenter._origin)
        if not time_log:
            # the workcenter is not being used
            workcenter.working_state = 'normal'
        elif time_log.loss_type in ('productive', 'performance'):
            # the productivity line has a `loss_type` that means the workcenter is being used
            workcenter.working_state = 'done'
        else:
            # the workcenter is blocked
            workcenter.working_state = 'blocked'

def _compute_oee(self):
    time_data = self.env['mrp.workcenter.productivity']._read_group(
        domain=[
            ('date_start', '>=', fields.Datetime.to_string(datetime.now() - relativedelta.relativedelta(months=1))),
            ('workcenter_id', 'in', self.ids),
            ('date_end', '!=', False),
        ],
        groupby=['workcenter_id', 'loss_type'],
        aggregates=['duration:sum'],
    )
    time_by_workcenter = defaultdict(lambda: {'productive_time': 0.0, 'blocked_time': 0.0})
    for data in time_data:
        workcenter, loss_type, duration = data
        time_to_update = 'productive_time' if loss_type == 'productive' else 'blocked_time'
        time_by_workcenter[workcenter.id][time_to_update] += duration
    for workcenter in self:
        workcenter_time = time_by_workcenter[workcenter.id]
        productive_time = workcenter_time['productive_time']
        if productive_time:
            blocked_time = workcenter_time['blocked_time']
            workcenter.oee = float_round(productive_time * 100.0 / (productive_time + blocked_time), precision_digits=2)
        else:
            workcenter.oee = 0.0

def _compute_performance(self):
    wo_data = self.env['mrp.workorder']._read_group([
        ('date_start', '>=', fields.Datetime.to_string(datetime.now() - relativedelta.relativedelta(months=1))),
        ('workcenter_id', 'in', self.ids),
        ('state', '=', 'done')], ['workcenter_id'], ['duration_expected:sum', 'duration:sum'])
    duration_expected = {workcenter.id: expected for workcenter, expected, __ in wo_data}
    duration = {workcenter.id: duration for workcenter, __, duration in wo_data}
    for workcenter in self:
        if duration.get(workcenter.id):
            workcenter.performance = 100 * duration_expected.get(workcenter.id, 0.0) / duration[workcenter.id]
        else:
            workcenter.performance = 0.0

def _compute_has_routing_lines(self):
    for workcenter in self:
        workcenter.has_routing_lines = self.env['mrp.routing.workcenter'].search_count([('workcenter_id', 'in', workcenter.ids)], limit=1)

def unblock(self):
    self.ensure_one()
    if self.working_state != 'blocked':
        raise exceptions.UserError(_("It has already been unblocked."))
    times = self.env['mrp.workcenter.productivity'].search([('workcenter_id', '=', self.id), ('date_end', '=', False)])
    self.sudo().message_post(
        body=self.env._("Work Center Unblocked")
    )
    times.write({'date_end': datetime.now()})
    return True

def write(self, vals):
    if 'company_id' in vals:
        self.resource_id.company_id = vals['company_id']
    return super(MrpWorkcenter, self).write(vals)

def action_show_operations(self):
    self.ensure_one()
    action = self.env['ir.actions.actions']._for_xml_id('mrp.mrp_routing_action')
    action['domain'] = [('workcenter_id', '=', self.id)]
    action['context'] = {
        'default_workcenter_id': self.id,
    }
    return action

def action_work_order(self):
    action = self.env["ir.actions.actions"]._for_xml_id("mrp.action_work_orders")
    return action

def action_archive(self):
    res = super().action_archive()
    filtered_workcenters = ", ".join(workcenter.name for workcenter in self.filtered('routing_line_ids'))
    if filtered_workcenters:
        return {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
            'title': _("Note that archived work center(s): '%s' is/are still linked to active Bill of Materials, which means that operations can still be planned on it/them. "
                       "To prevent this, deletion of the work center is recommended instead.", filtered_workcenters),
            'type': 'warning',
            'sticky': True,  #True/False will display for few seconds if false
            'next': {'type': 'ir.actions.act_window_close'},
            },
        }
    return res

def _get_capacity(self, product, unit, default_capacity=1):
    capacity = self.capacity_ids.sorted(lambda c: (
        not (c.product_id == product and c.uom_id == product.uom_id),
        not (not c.product_id and c.uom_id == unit),
        not (not c.product_id and c.uom_id == product.uom_id),
    ))[:1]
    if capacity and capacity.product_id in [product, self.env['product.product']] and capacity.uom_id in [product.uom_id, unit]:
        if float_is_zero(capacity.capacity, 0):
            return (default_capacity, capacity.time_start, capacity.time_stop)
        return (capacity.uom_id._compute_quantity(capacity.capacity, unit), capacity.time_start, capacity.time_stop)
    return (default_capacity, self.time_start, self.time_stop)

def _convert_to_duration(self, date_start, date_stop, workcenter=False):
    """ Convert a date range into a duration in minutes.
    If the productivity type is not from an employee (extra hours are allow)
    and the workcenter has a calendar, convert the dates into a duration based on
    working hours.
    """
    duration = 0
    for productivity_loss in self:
        if (productivity_loss.loss_type not in ('productive', 'performance')) and workcenter and workcenter.resource_calendar_id:
            r = workcenter._get_work_days_data_batch(date_start, date_stop)[workcenter.id]['hours']
            duration = max(duration, r * 60)
        else:
            duration = max(duration, (date_stop - date_start).total_seconds() / 60.0)
    return round(duration, 2)

def _get_default_company_id(self):
    company_id = False
    if self.env.context.get('default_company_id'):
        company_id = self.env.context['default_company_id']
    if not company_id and self.env.context.get('default_workorder_id'):
        workorder = self.env['mrp.workorder'].browse(self.env.context['default_workorder_id'])
        company_id = workorder.company_id
    if not company_id and self.env.context.get('default_workcenter_id'):
        workcenter = self.env['mrp.workcenter'].browse(self.env.context['default_workcenter_id'])
        company_id = workcenter.company_id
    if not company_id:
        company_id = self.env.company
    return company_id

def _compute_duration(self):
    for blocktime in self:
        if blocktime.date_start and blocktime.date_end:
            blocktime.duration = blocktime.loss_id._convert_to_duration(blocktime.date_start.replace(microsecond=0), blocktime.date_end.replace(microsecond=0), blocktime.workcenter_id)
        else:
            blocktime.duration = 0.0

def _duration_changed(self):
    if not self.date_end:
        return
    self.date_start = self.date_end - timedelta(minutes=self.duration)
    self._loss_type_change()

def _date_start_changed(self):
    if not self.date_start:
        return
    self.date_end = self.date_start + timedelta(minutes=self.duration)
    self._loss_type_change()

def _date_end_changed(self):
    if not self.date_end:
        return
    self.date_start = self.date_end - timedelta(minutes=self.duration)
    self._loss_type_change()

def _check_open_time_ids(self):
    for workorder in self.workorder_id:
        open_time_ids_by_user = self.env["mrp.workcenter.productivity"]._read_group(
            [("id", "in", workorder.time_ids.ids), ("date_end", "=", False)],
            ["user_id"], having=[("__count", ">", 1)],
        )
        if open_time_ids_by_user:
            raise ValidationError(_('The Workorder (%s) cannot be started twice!', workorder.display_name))

def button_block(self):
    self.ensure_one()
    self.workcenter_id.order_ids.end_all()
    self.workcenter_id.sudo().message_post(
        body=self.env._("Work Center Blocked: %s", self.loss_id.display_name)
    )

def _loss_type_change(self):
    self.ensure_one()
    if self.workorder_id.duration > self.workorder_id.duration_expected:
        self.loss_id = self.env.ref("mrp.block_reason4").id
    else:
        self.loss_id = self.env.ref("mrp.block_reason7").id

def _close(self):
    underperformance_timers = self.env['mrp.workcenter.productivity']
    for timer in self:
        wo = timer.workorder_id
        timer.write({'date_end': fields.Datetime.now()})
        if wo.duration > wo.duration_expected:
            productive_date_end = timer.date_end - relativedelta.relativedelta(minutes=wo.duration - wo.duration_expected)
            if productive_date_end <= timer.date_start:
                underperformance_timers |= timer
            else:
                underperformance_timers |= timer.copy({'date_start': productive_date_end})
                timer.write({'date_end': productive_date_end})
    if underperformance_timers:
        underperformance_type = self.env['mrp.workcenter.productivity.loss'].search([('loss_type', '=', 'performance')], limit=1)
        if not underperformance_type:
            raise UserError(_("You need to define at least one unactive productivity loss in the category 'Performance'. Create one from the Manufacturing app, menu: Configuration / Productivity Losses."))
        underperformance_timers.write({'loss_id': underperformance_type.id})

def _default_time_start(self):
    workcenter_id = self.env.context.get('default_workcenter_id')
    return self.env['mrp.workcenter'].browse(workcenter_id).time_start if workcenter_id else 0.0

def _default_time_stop(self):
    workcenter_id = self.env.context.get('default_workcenter_id')
    return self.env['mrp.workcenter'].browse(workcenter_id).time_stop if workcenter_id else 0.0

def _compute_uom_id(self):
    for capacity in self:
        capacity.uom_id = capacity.product_id.uom_id or self.env.ref('uom.product_uom_unit')

def get_supply_state(self, name):
    state = super().get_supply_state(name)
    if self.productions:
        states = {p.state for p in self.productions}
        if states <= {'running', 'done', 'cancelled'}:
            if states == {'cancelled'}:
                state = 'cancelled'
            else:
                state = 'supplied'
        else:
            state = 'requested'
    return state

def create_productions(self, product_quantities):
    productions = []
    for line in self.lines:
        production = line.get_production(product_quantities)
        if not production:
            continue
        production.set_planned_start_date()
        productions.append(production)
        assert not line.productions
    return productions

@Override
public List<MrpLine> getMrpLineListCopy(List<MrpLine> mrpLineList) {
  List<MrpLine> copyMrpLineList = new ArrayList<>();
  mrpLineList =
      mrpLineRepo.findByIds(
          mrpLineList.stream().map(MrpLine::getId).collect(Collectors.toList()));
  for (MrpLine mrpLine : mrpLineList) {
    copyMrpLineList.add(mrpLineRepo.copy(mrpLine, true));
  }

  return copyMrpLineList;
}

protected String computeRelatedName(Model model) {

  if (model instanceof SaleOrderLine) {

    return ((SaleOrderLine) model).getSaleOrder().getSaleOrderSeq();

  } else if (model instanceof PurchaseOrderLine) {

    return ((PurchaseOrderLine) model).getPurchaseOrder().getPurchaseOrderSeq();

  } else if (model instanceof MrpForecast) {

    MrpForecast mrpForecast = (MrpForecast) model;
    return mrpForecast.getId() + "-" + mrpForecast.getForecastDate();
  }
  return null;
}

public MrpLineOrigin copyMrpLineOrigin(MrpLineOrigin mrpLineOrigin) {

  MrpLineOrigin copyMrpLineOrigin = new MrpLineOrigin();
  copyMrpLineOrigin.setRelatedToSelect(mrpLineOrigin.getRelatedToSelect());
  copyMrpLineOrigin.setRelatedToSelectId(mrpLineOrigin.getRelatedToSelectId());

  return copyMrpLineOrigin;
}

public MrpLineOrigin createMrpLineOrigin(Model model) {

  Class<?> klass = EntityHelper.getEntityClass(model);

  MrpLineOrigin mrpLineOrigin = new MrpLineOrigin();
  mrpLineOrigin.setRelatedToSelect(klass.getCanonicalName());
  mrpLineOrigin.setRelatedToSelectId(model.getId());

  return mrpLineOrigin;
}

protected void createMrpLineOrigins(MrpLine mrpLine, Model model) {

  if (model != null) {

    mrpLine.addMrpLineOriginListItem(this.createMrpLineOrigin(model));
    mrpLine.setRelatedToSelectName(this.computeRelatedName(model));
  }
}

protected MrpLine setMrpLineQty(MrpLine mrpLine, Product product, StockLocation stockLocation) {

  StockRules stockRules =
      stockRulesService.getStockRules(
          product,
          stockLocation,
          StockRulesRepository.TYPE_FUTURE,
          StockRulesRepository.USE_CASE_USED_FOR_MRP);

  if (stockRules != null) {
    mrpLine.setMinQty(stockRules.getMinQty());
    mrpLine.setIdealQty(stockRules.getIdealQty());
    mrpLine.setReOrderQty(stockRules.getReOrderQty());
  }
  return mrpLine;
}

public MrpLine createMrpLine(
    Mrp mrp,
    Product product,
    int maxLevel,
    MrpLineType mrpLineType,
    BigDecimal qty,
    LocalDate maturityDate,
    BigDecimal cumulativeQty,
    StockLocation stockLocation,
    Model model) {

  MrpLine mrpLine = new MrpLine();

  mrpLine.setMrp(mrp);
  mrpLine.setProduct(product);
  mrpLine.setMaxLevel(maxLevel);
  mrpLine.setMrpLineType(mrpLineType);
  if (mrpLineType.getTypeSelect() == MrpLineTypeRepository.TYPE_OUT) {
    mrpLine.setQty(qty.negate());
  } else {
    mrpLine.setQty(qty);
  }
  mrpLine.setMaturityDate(maturityDate);
  mrpLine.setCumulativeQty(cumulativeQty);
  mrpLine.setStockLocation(stockLocation);

  mrpLine = this.setMrpLineQty(mrpLine, product, stockLocation);

  if (mrpLineType.getElementSelect() == MrpLineTypeRepository.ELEMENT_PURCHASE_PROPOSAL) {
    mrpLine.setSupplierPartner(product.getDefaultSupplierPartner());
  }

  this.updatePartner(mrpLine, model);

  this.createMrpLineOrigins(mrpLine, model);

  log.debug(
      "Create mrp line for the product {}, level {}, mrpLineType {}, qty {}, maturity date {}, cumulative qty {}, stock location {}, related to {}",
      product.getCode(),
      maxLevel,
      mrpLineType.getCode(),
      qty,
      maturityDate,
      cumulativeQty,
      stockLocation.getName(),
      mrpLine.getRelatedToSelectName());

  return mrpLine;
}

protected String getMrpLineOriginStr(MrpLineOrigin mrpLineOrigin) {
  if (mrpLineOrigin
      .getRelatedToSelect()
      .equals(MrpLineOriginRepository.RELATED_TO_SALE_ORDER_LINE)) {
    SaleOrder saleOrder =
        saleOrderLineRepo.find(mrpLineOrigin.getRelatedToSelectId()).getSaleOrder();
    return saleOrder.getSaleOrderSeq();
  }
  if (mrpLineOrigin
      .getRelatedToSelect()
      .equals(MrpLineOriginRepository.RELATED_TO_PURCHASE_ORDER_LINE)) {
    PurchaseOrder purchaseOrder =
        purchaseOrderLineRepo.find(mrpLineOrigin.getRelatedToSelectId()).getPurchaseOrder();
    return purchaseOrder.getPurchaseOrderSeq();
  }
  if (mrpLineOrigin
      .getRelatedToSelect()
      .equals(MrpLineOriginRepository.RELATED_TO_MRP_FORECAST)) {
    return mrpLineOrigin.getMrpLine().getMrp().getMrpSeq() + "-" + I18n.get("MRP forecast");
  }
  return "";
}

protected void updatePartner(MrpLine mrpLine, Model model) {

  if (model != null) {
    mrpLine.setPartner(this.getPartner(model));
  }
}

protected Partner getPartner(Model model) {

  if (model instanceof SaleOrderLine) {

    return ((SaleOrderLine) model).getSaleOrder().getClientPartner();

  } else if (model instanceof PurchaseOrderLine) {

    return ((PurchaseOrderLine) model).getPurchaseOrder().getSupplierPartner();

  } else if (model instanceof MrpForecast) {

    return ((MrpForecast) model).getPartner();
  }
  return null;
}

def onload(self):
	self.set_onload(
		"enable_stock_reservation",
		frappe.db.get_single_value("Stock Settings", "enable_stock_reservation"),
	)

	if self.docstatus == 1:
		self.set_onload(
			"pending_work_order_qty",
			ProductionPlanWorkOrderQuantities(self.name).get_pending_quantities(self),
		)

def validate_raw_material_group_warehouse(self):
	if not self.raw_material_group_warehouse:
		return

	group = frappe.db.get_value(
		"Warehouse",
		{"name": self.raw_material_group_warehouse, "is_group": 1, "company": self.company},
		["lft", "rgt"],
		as_dict=True,
	)
	if not group:
		frappe.throw(
			_("{0} must be a group warehouse of company {1}.").format(
				frappe.bold(_("Raw Material Group Warehouse")), frappe.bold(self.company)
			)
		)

	if self.for_warehouse and not frappe.db.exists(
		"Warehouse",
		{"name": self.for_warehouse, "is_group": 0, "lft": (">", group.lft), "rgt": ("<", group.rgt)},
	):
		frappe.throw(
			_("For Warehouse {0} must be a non-group warehouse under {1}.").format(
				frappe.bold(self.for_warehouse), frappe.bold(self.raw_material_group_warehouse)
			)
		)

def enable_auto_reserve_stock(self):
	if self.is_new() and frappe.db.get_single_value("Stock Settings", "auto_reserve_stock"):
		self.reserve_stock = 1

def validate_material_request_type(self):
	for row in self.get("mr_items"):
		if row.from_warehouse and row.material_request_type != "Material Transfer":
			row.from_warehouse = ""

def validate_sales_orders(self, sales_order=None):
	sales_orders = []

	if sales_order:
		sales_orders.append(sales_order)
	else:
		sales_orders = [row.sales_order for row in self.sales_orders if row.sales_order]

	data = sales_order_query(filters={"company": self.company, "sales_orders": sales_orders})

	title = _("Production Plan Already Submitted")
	if not data and sales_orders:
		msg = _("No items are available in the sales order {0} for production").format(sales_orders[0])
		if len(sales_orders) > 1:
			sales_orders = ", ".join(sales_orders)
			msg = _("No items are available in sales orders {0} for production").format(sales_orders)

		frappe.throw(msg, title=title)

	data = [d[0] for d in data]

	for sales_order in sales_orders:
		if sales_order not in data:
			frappe.throw(
				_("No items are available in the sales order {0} for production").format(sales_order),
				title=title,
			)

def set_pending_qty_in_row_without_reference(self):
	"Set Pending Qty in independent rows (not from SO or MR)."
	if self.docstatus > 0:  # set only to initialise value before submit
		return

	for item in self.po_items:
		if not item.get("sales_order") or not item.get("material_request"):
			item.pending_qty = item.planned_qty

def calculate_total_planned_qty(self):
	self.total_planned_qty = 0
	for d in self.po_items:
		self.total_planned_qty += flt(d.planned_qty)

def validate_data(self):
	validated_boms = set()
	for d in self.get("po_items"):
		if not d.bom_no:
			frappe.throw(_("Please select BOM for Item in Row {0}").format(d.idx))
		elif (d.item_code, d.bom_no) not in validated_boms:
			validate_bom_no(d.item_code, d.bom_no)
			validated_boms.add((d.item_code, d.bom_no))

		if not flt(d.planned_qty):
			frappe.throw(
				_("Row #{0}: Planned Qty must be greater than 0 for Item {1}.").format(
					d.idx, frappe.bold(d.item_code)
				)
			)

def _rename_temporary_references(self):
	"""po_items and sub_assembly_items items are both constructed client side without saving.

	Attempt to fix linkages by using temporary names to map final row names.
	"""
	new_name_map = {d.temporary_name: d.name for d in self.po_items if d.temporary_name}
	actual_names = {d.name for d in self.po_items}

	for sub_assy in self.sub_assembly_items:
		if sub_assy.production_plan_item not in actual_names:
			sub_assy.production_plan_item = new_name_map.get(sub_assy.production_plan_item)

def get_open_sales_orders(self):
	"""Pull sales orders  which are pending to deliver based on criteria selected"""
	open_so = get_sales_orders(self)

	if open_so:
		self.add_so_in_table(open_so)
	else:
		frappe.msgprint(_("Sales orders are not available for production"))

def add_so_in_table(self, open_so):
	"""Add sales orders in the table"""
	self.set("sales_orders", [])

	for data in open_so:
		self.append(
			"sales_orders",
			{
				"sales_order": data.name,
				"sales_order_date": data.transaction_date,
				"customer": data.customer,
				"grand_total": data.base_grand_total,
			},
		)

def add_mr_in_table(self, pending_mr):
	"""Add Material Requests in the table"""
	self.set("material_requests", [])

	for data in pending_mr:
		self.append(
			"material_requests",
			{"material_request": data.name, "material_request_date": data.transaction_date},
		)

def combine_so_items(self):
	if self.combine_items and self.po_items and len(self.po_items) > 0:
		items = []
		for row in self.po_items:
			items.append(
				frappe._dict(
					{
						"parent": row.sales_order,
						"item_code": row.item_code,
						"warehouse": row.warehouse,
						"qty": row.pending_qty,
						"pending_qty": row.pending_qty,
						"conversion_factor": 1.0,
						"description": row.description,
						"bom_no": row.bom_no,
					}
				)
			)

		self.set("po_items", [])
		self.add_items(items)
	else:
		self.get_items()

def get_items(self):
	self.set("po_items", [])
	if self.get_items_from == "Sales Order":
		self.get_so_items()

	elif self.get_items_from == "Material Request":
		self.get_mr_items()

def add_items(self, items):
	refs = {}
	for data in items:
		if not data.pending_qty:
			continue

		item_details = get_item_details(data.item_code, throw=False)
		if self.combine_items:
			bom_no = item_details.get("bom_no")
			if data.get("bom_no"):
				bom_no = data.get("bom_no")

			if bom_no in refs:
				refs[bom_no]["so_details"].append(
					{"sales_order": data.parent, "sales_order_item": data.name, "qty": data.pending_qty}
				)
				refs[bom_no]["qty"] += data.pending_qty
				continue

			else:
				refs[bom_no] = {
					"qty": data.pending_qty,
					"po_item_ref": data.name,
					"so_details": [],
				}
				refs[bom_no]["so_details"].append(
					{"sales_order": data.parent, "sales_order_item": data.name, "qty": data.pending_qty}
				)

		bom_no = data.bom_no or item_details and item_details.get("bom_no") or ""
		if not bom_no:
			continue

		pi = self.append(
			"po_items",
			{
				"warehouse": data.warehouse,
				"item_code": data.item_code,
				"description": data.description or item_details.description,
				"stock_uom": item_details and item_details.stock_uom or "",
				"bom_no": bom_no,
				"planned_qty": data.pending_qty,
				"pending_qty": data.pending_qty,
				"planned_start_date": now_datetime(),
				"product_bundle_item": data.parent_item,
			},
		)
		pi._set_defaults()

		if self.get_items_from == "Sales Order":
			pi.sales_order = data.parent
			pi.sales_order_item = data.name
			pi.description = data.description

		elif self.get_items_from == "Material Request":
			pi.material_request = data.parent
			pi.material_request_item = data.name
			pi.description = data.description

	if refs:
		for po_item in self.po_items:
			po_item.planned_qty = refs[po_item.bom_no]["qty"]
			po_item.pending_qty = refs[po_item.bom_no]["qty"]
			po_item.sales_order = ""
		self.add_pp_ref(refs)

def add_pp_ref(self, refs):
	for bom_no in refs:
		for so_detail in refs[bom_no]["so_details"]:
			self.append(
				"prod_plan_references",
				{
					"item_reference": refs[bom_no]["po_item_ref"],
					"sales_order": so_detail["sales_order"],
					"sales_order_item": so_detail["sales_order_item"],
					"qty": so_detail["qty"],
				},
			)

def calculate_total_produced_qty(self):
	self.total_produced_qty = 0
	for d in self.po_items:
		self.total_produced_qty += flt(d.produced_qty)

	self.db_set("total_produced_qty", self.total_produced_qty, update_modified=False)

def update_produced_pending_qty(self, produced_qty, production_plan_item):
	for data in self.po_items:
		if data.name == production_plan_item:
			data.produced_qty = produced_qty
			data.pending_qty = flt(data.planned_qty - produced_qty)
			data.db_update()

	self.calculate_total_produced_qty()
	self.update_status_and_bin_qty()

def update_status_and_bin_qty(self):
	previous_status = self.status
	self.set_status()
	self.db_set("status", self.status)
	if previous_status != self.status and "Completed" in (previous_status, self.status):
		self.update_bin_qty()

def validate_sales_order_planned_qty(self):
	planned_qty = self.get_so_item_planned_qty()
	if not planned_qty:
		return

	already_planned = self.get_so_wise_planned_qty(list({key[0] for key in planned_qty}))
	so_items = {
		row.name: row
		for row in frappe.get_all(
			"Sales Order Item",
			filters={"name": ("in", [key[1] for key in planned_qty])},
			fields=["name", "item_code", "stock_qty", "stock_uom"],
		)
	}
	allowance = flt(
		frappe.db.get_single_value("Manufacturing Settings", "overproduction_percentage_for_sales_order")
	)
	precision = frappe.get_precision("Production Plan Item", "planned_qty")

	for (sales_order, so_item), qty in planned_qty.items():
		row = so_items[so_item]
		unplanned_qty = flt(
			flt(row.stock_qty) * (1 + allowance / 100) - flt(already_planned.get((sales_order, so_item))),
			precision,
		)
		if flt(qty, precision) > unplanned_qty:
			frappe.throw(
				_(
					"Cannot plan {0} {1} of Item {2} against Sales Order {3}. Only {4} {1} is left to plan."
				).format(
					qty, row.stock_uom, frappe.bold(row.item_code), sales_order, max(unplanned_qty, 0)
				),
				title=_("Sales Order Qty Exceeded"),
			)

def get_so_item_planned_qty(self):
	"""Planned qty per Sales Order line, excluding product bundle components."""
	planned_qty = {}
	for row in self.po_items:
		if row.sales_order and row.sales_order_item and not row.product_bundle_item:
			key = (row.sales_order, row.sales_order_item)
			planned_qty[key] = planned_qty.get(key, 0) + flt(row.planned_qty)

	return planned_qty

def add_reference_to_raw_materials(self):
	for item in self.mr_items:
		if reference := next(
			(
				sa_item.name
				for sa_item in self.sub_assembly_items
				if sa_item.production_item == item.main_item_code and sa_item.bom_no == item.from_bom
			),
			None,
		):
			item.db_set("sub_assembly_item_reference", reference)
		elif (
			self.reserve_stock
			and item.main_item_code
			and item.from_bom
			and item.main_item_code != frappe.get_cached_value("BOM", item.from_bom, "item")
		):
			frappe.throw(
				_(
					"Sub assembly item references are missing. Please fetch the sub assemblies and raw materials again."
				)
			)

def update_sales_order(self):
	so_items = {
		(row.sales_order, row.sales_order_item)
		for row in self.po_items + self.prod_plan_references
		if row.sales_order and row.sales_order_item
	}
	if not so_items:
		return

	so_wise_planned_qty = self.get_so_wise_planned_qty(list({key[0] for key in so_items}))
	for key in so_items:
		frappe.db.set_value(
			"Sales Order Item", key[1], "production_plan_qty", flt(so_wise_planned_qty.get(key))
		)

def update_bin_qty(self, item_codes: set[str] | None = None):
	rows = [(d.item_code, d.warehouse) for d in self.mr_items]
	rows += [
		(d.production_item, d.fg_warehouse)
		for d in self.sub_assembly_items
		if d.type_of_manufacturing == "In House"
	]
	for item_code, warehouse in rows:
		if warehouse and (item_codes is None or item_code in item_codes):
			bin_name = get_or_make_bin(item_code, warehouse)
			bin = frappe.get_doc("Bin", bin_name, for_update=True)
			bin.update_reserved_qty_for_production_plan()

def delete_draft_work_order(self):
	for d in frappe.get_all(
		"Work Order", fields=["name"], filters={"docstatus": 0, "production_plan": ("=", self.name)}
	):
		frappe.delete_doc("Work Order", d.name)

def set_status(self, close: bool | None = None, update_bin: bool = False):
	self.check_permission("write")

	if close is None and self.status == "Closed":
		return

	self.status = {0: "Draft", 1: "Submitted", 2: "Cancelled"}.get(self.docstatus)

	if close:
		self.db_set("status", "Closed")
		self.cancel_untouched_stock_reservations()
		self.update_bin_qty()
		return

	if self.total_produced_qty > 0:
		self.status = "In Process"
		if self.all_items_completed():
			self.status = "Completed"

	if self.status != "Completed":
		self.update_requested_status()
		self.update_ordered_status()

	if close is not None:
		self.db_set("status", self.status)

	if update_bin and self.docstatus == 1 and self.status != "Completed":
		self.update_bin_qty()

def update_ordered_status(self):
	for child_table in ["po_items", "sub_assembly_items"]:
		for item in self.get(child_table):
			if item.ordered_qty:
				self.status = "In Process"
				return

def update_requested_status(self):
	if self.mr_items and all(flt(d.requested_qty) >= flt(d.quantity) for d in self.mr_items):
		self.status = "Material Requested"

def validate_plan_is_open(self):
	status = (
		frappe.db.get_value("Production Plan", self.name, "status") if not self.is_new() else self.status
	)
	if status in ("Closed", "Completed"):
		frappe.throw(
			_("Production Plan {0} is {1}").format(frappe.bold(self.name), _(status)),
			frappe.InvalidStatusError,
		)

def make_work_order_for_finished_goods(self, wo_list, default_warehouses):
	items_data = self.get_production_items()

	for _key, item in items_data.items():
		if self.sub_assembly_items:
			item["use_multi_level_bom"] = 0

		set_default_warehouses(item, default_warehouses)
		work_order = self.create_work_order(item)
		if work_order:
			wo_list.append(work_order)

def make_work_order_for_subassembly_items(self, wo_list, subcontracted_po, default_warehouses):
	pending = ProductionPlanWorkOrderQuantities(self.name).get_pending_quantities(self)
	for row in self.sub_assembly_items:
		if row.type_of_manufacturing == "Subcontract":
			subcontracted_po.setdefault(row.supplier, []).append(row)
			continue

		if row.type_of_manufacturing == "Material Request":
			continue

		work_order_data = {
			"source_warehouse": frappe.get_value("BOM", row.bom_no, "default_source_warehouse"),
			"wip_warehouse": default_warehouses.get("wip_warehouse"),
			"fg_warehouse": default_warehouses.get("fg_warehouse"),
			"scrap_warehouse": default_warehouses.get("scrap_warehouse"),
			"company": self.get("company"),
		}

		self.prepare_data_for_sub_assembly_items(
			row, work_order_data, pending["production_plan_sub_assembly_item"][row.name]
		)

		if work_order_data.get("qty") <= 0:
			continue

		work_order = self.create_work_order(work_order_data)
		if work_order:
			wo_list.append(work_order)

def get_subcontracted_qty(self):
	po_item = frappe.qb.DocType("Purchase Order Item")
	return frappe._dict(
		(
			frappe.qb.from_(po_item)
			.select(po_item.production_plan_sub_assembly_item, Sum(po_item.fg_item_qty))
			.where((po_item.production_plan == self.name) & (po_item.docstatus < 2))
			.groupby(po_item.production_plan_sub_assembly_item)
		).run()
	)

def show_list_created_message(self, doctype, doc_list=None):
	if not doc_list:
		return

	frappe.flags.mute_messages = False
	msgprint(_("{0} created").format(get_filtered_list_link(doctype, doc_list)))

def validate_mr_subcontracted(self):
	for row in self.mr_items:
		if row.material_request_type == "Subcontracting":
			if not frappe.db.get_value("Item", row.item_code, "is_sub_contracted_item"):
				frappe.throw(
					_("Item {0} is not a subcontracted item").format(row.item_code),
					title=_("Invalid Item"),
				)

def make_material_request(self):
	self.load_saved_plan_for_material_request()
	self.validate_mr_subcontracted()

	"""Create Material Requests grouped by Sales Order and Material Request Type"""
	material_request_list = []
	material_request_map = {}
	draft_qty = self.get_draft_requested_qty()

	for item in self.mr_items:
		qty_to_request = get_qty_to_request(item, draft_qty)
		if qty_to_request <= 0:
			continue

		item_doc = frappe.get_cached_doc("Item", item.item_code)

		# a group warehouse cannot receive stock; it must never reach a Material Request line
		if item.warehouse and frappe.get_cached_value("Warehouse", item.warehouse, "is_group"):
			frappe.throw(
				_("Cannot create Material Request for item {0} in group warehouse {1}.").format(
					frappe.bold(item.item_code), frappe.bold(item.warehouse)
				)
			)

		material_request_type = item.material_request_type or item_doc.default_material_request_type

		# key for Sales Order:Material Request Type:Customer
		key = "{}:{}:{}".format(item.sales_order, material_request_type, "")
		schedule_date = item.schedule_date or add_days(nowdate(), cint(item_doc.lead_time_days))

		if key not in material_request_map:
			# make a new MR for the combination
			material_request_map[key] = frappe.new_doc("Material Request")
			material_request = material_request_map[key]
			material_request.update(
				{
					"transaction_date": nowdate(),
					"status": "Draft",
					"company": self.company,
					"material_request_type": material_request_type,
				}
			)
			material_request_list.append(material_request)
		else:
			material_request = material_request_map[key]

		# add item
		material_request.append(
			"items",
			{
				"item_code": item.item_code,
				"from_warehouse": item.from_warehouse
				if material_request_type == "Material Transfer"
				else None,
				"qty": qty_to_request,
				"uom": item.uom,
				"schedule_date": schedule_date,
				"warehouse": item.warehouse,
				"sales_order": item.sales_order,
				"production_plan": self.name,
				"material_request_plan_item": item.name,
				"project": frappe.db.get_value("Sales Order", item.sales_order, "project")
				if item.sales_order
				else None,
			},
		)

	if not material_request_list:
		msgprint(_("All items are already requested"))
		return

	for material_request in material_request_list:
		# submit
		material_request.flags.ignore_permissions = 1
		material_request.run_method("set_missing_values")

		material_request.save()
		if self.get("submit_material_request"):
			material_request.submit()

	frappe.flags.mute_messages = False

	if material_request_list:
		material_request_list = [
			get_link_to_form("Material Request", m.name) for m in material_request_list
		]
		msgprint(_("{0} created").format(comma_and(material_request_list)))
	else:
		msgprint(_("No material request created"))

def get_draft_requested_qty(self):
	mr_item = frappe.qb.DocType("Material Request Item")
	return frappe._dict(
		(
			frappe.qb.from_(mr_item)
			.select(mr_item.material_request_plan_item, Sum(mr_item.stock_qty))
			.where((mr_item.production_plan == self.name) & (mr_item.docstatus == 0))
			.groupby(mr_item.material_request_plan_item)
		).run()
	)

def set_sub_assembly_items_based_on_level(self, row, bom_data, manufacturing_type=None):
	"Modify bom_data, set additional details."
	is_group_warehouse = frappe.db.get_value("Warehouse", self.sub_assembly_warehouse, "is_group")

	for data in bom_data:
		data.qty = data.stock_qty
		data.production_plan_item = row.name
		data.schedule_date = row.planned_start_date
		data.type_of_manufacturing = manufacturing_type or (
			"Subcontract" if data.is_sub_contracted_item else "In House"
		)

		if not is_group_warehouse:
			data.fg_warehouse = self.sub_assembly_warehouse

		if not self.combine_sub_items:
			data.sales_order = row.sales_order
			data.sales_order_item = row.sales_order_item

def set_default_supplier_for_subcontracting_order(self):
	items = [
		d.production_item for d in self.sub_assembly_items if d.type_of_manufacturing == "Subcontract"
	]

	if not items:
		return

	default_supplier = frappe._dict(
		frappe.get_all(
			"Item Default",
			fields=["parent", "default_supplier"],
			filters={"parent": ("in", items), "default_supplier": ("is", "set")},
			as_list=1,
		)
	)

	if not default_supplier:
		return

	for row in self.sub_assembly_items:
		if row.type_of_manufacturing != "Subcontract":
			continue

		row.supplier = default_supplier.get(row.production_item)

def all_items_completed(self):
	all_items_produced = all(flt(d.planned_qty) - flt(d.produced_qty) < 0.000001 for d in self.po_items)
	if not all_items_produced:
		return False

	wo_status = frappe.get_all(
		"Work Order",
		filters={
			"production_plan": self.name,
			"status": ("not in", ["Closed", "Stopped"]),
			"docstatus": 1,
		},
		fields="status",
		pluck="status",
	)
	all_work_orders_completed = all(s == "Completed" for s in wo_status)
	return all_work_orders_completed

def get_mr_item_planned_qty_query(mr_item):
	plan_item = frappe.qb.DocType("Production Plan Item")
	return (
		frappe.qb.from_(plan_item)
		.select(Sum(plan_item.planned_qty))
		.where((plan_item.material_request_item == mr_item.name) & (plan_item.docstatus == 1))
	)

def get_planned_qty_by_order_row(plans):
	plan_item = frappe.qb.DocType("Production Plan Item")
	rows = (
		frappe.qb.from_(plan_item)
		.select(plan_item.parent, plan_item.sales_order_item, Sum(plan_item.planned_qty).as_("qty"))
		.where(plan_item.parent.isin(plans))
		.groupby(plan_item.parent, plan_item.sales_order_item)
	).run(as_dict=True)
	return {(row.parent, row.sales_order_item): flt(row.qty) for row in rows}

def get_qty_to_request(item, draft_qty):
	qty_to_request = flt(
		flt(item.quantity)
		- flt(item.requested_qty)
		- flt(draft_qty.get(item.name)) / (flt(item.conversion_factor) or 1),
		item.precision("quantity"),
	)
	if qty_to_request > 0 and frappe.get_cached_value("UOM", item.uom, "must_be_whole_number"):
		qty_to_request = ceil(qty_to_request)

	return qty_to_request

def get_requested_sub_assemblies(doc):
	requested_sub_assemblies = {}
	for row in doc.get("sub_assembly_items") or []:
		row = frappe._dict(row)
		if row.type_of_manufacturing == "Material Request":
			requested_sub_assemblies.setdefault(row.production_plan_item, set()).add(
				(row.production_item, row.bom_no)
			)

	return requested_sub_assemblies

def _authorize_mr_request(doc, warehouses=None):
	"""Scope a caller-supplied plan to what the caller may see; `doc` is often unsaved, so check only a real name.

	`warehouses` is accepted so the call site reads the same as on develop, where it also narrows
	the caller to their permitted companies. There is no Company Restriction on this branch.
	"""
	name = doc.get("name")
	if isinstance(name, str) and frappe.db.exists("Production Plan", name):
		frappe.has_permission("Production Plan", doc=name, throw=True)

	# Values arrive through frappe.parse_json, so container elements are untyped: a dict reaches
	# frappe.db.get_value() in its *name* position and becomes a filter.
	for row in _iter_mr_rows(doc):
		for fieldname in ("item_code", "warehouse", "bom_no", "sales_order", "uom", "purchase_uom"):
			value = row.get(fieldname)
			if value is not None and not isinstance(value, str):
				frappe.throw(_("Invalid {0}").format(fieldname), frappe.PermissionError)

def get_reserved_qty_for_production_plan(item_code, warehouse):
	plan_reservations = _get_plan_reservations(item_code)
	if not plan_reservations:
		return None

	work_order_reservations = _get_work_order_reservations(item_code, list(plan_reservations))
	reserved_qty = 0.0
	for plan, plan_qty_by_warehouse in plan_reservations.items():
		reserved_qty += _get_remaining_reserved_qty(
			plan_qty_by_warehouse, work_order_reservations.get(plan, {}), warehouse
		)

	return reserved_qty

def _group_by_plan_and_warehouse(*queries):
	reservations = defaultdict(lambda: defaultdict(float))
	for query in queries:
		for row in query.run(as_dict=True):
			reservations[row.production_plan][row.warehouse] += flt(row.reserved_qty)
	return reservations

def get_non_completed_production_plans():
	table = frappe.qb.DocType("Production Plan")

	return (
		frappe.qb.from_(table)
		.select(table.name)
		.distinct()
		.where((table.docstatus == 1) & (table.status.notin(["Completed", "Closed"])))
	).run(pluck="name")

def reserve_stock_for_production_plan(doc, items=None, table_name=None, notify=False):
	"""Reserve stock for a Production Plan. Internal: no permission check, because the Production
	Plan submit and cancel lifecycles reach it for a user who need not hold Production Plan write.
	The cancelled branch unreserves, so the whitelisted entry point above needs the same right as
	the cancel sibling.
	"""
	if items and isinstance(items, str):
		items = parse_json(items)

	mapper = {
		"sub_assembly_items": {
			"table_name": "sub_assembly_items",
			"qty_field": "required_qty",
			"warehouse_field": "fg_warehouse",
		},
		"mr_items": {
			"table_name": "mr_items",
			"qty_field": "required_bom_qty",
			"warehouse_field": "warehouse",
		},
	}

	for child_table_name in mapper:
		if table_name and table_name != child_table_name:
			continue

		sre = StockReservation(doc, items=items, kwargs=mapper[child_table_name], notify=notify)
		if doc.docstatus == 1:
			sre_created = sre.make_stock_reservation_entries()
			if sre_created:
				frappe.msgprint(_("Stock Reservation Entries Created"), alert=True)
		elif doc.docstatus == 2:
			sre.cancel_stock_reservation_entries()

	doc.reload()

def sales_order_query(doctype=None, txt=None, searchfield=None, start=None, page_len=None, filters=None):
	frappe.has_permission("Production Plan", throw=True)

	if not filters:
		filters = {}

	so_table = frappe.qb.DocType("Sales Order")
	table = frappe.qb.DocType("Sales Order Item")

	query = (
		frappe.qb.from_(so_table)
		.join(table)
		.on(table.parent == so_table.name)
		.select(table.parent)
		.distinct()
		.where((table.stock_qty > table.production_plan_qty) & (table.docstatus == 1))
	)

	if filters.get("company"):
		query = query.where(so_table.company == filters.get("company"))

	if filters.get("sales_orders"):
		query = query.where(so_table.name.isin(filters.get("sales_orders")))

	if filters.get("item_code"):
		query = query.where(table.item_code == filters.get("item_code"))

	if txt:
		query = query.where(table.parent.like(f"%{txt}%"))

	if page_len:
		query = query.limit(page_len)

	if start:
		query = query.offset(start)

	return query.run()

def set_default_warehouses(row, default_warehouses):
	for field in ["wip_warehouse", "fg_warehouse", "scrap_warehouse"]:
		if not row.get(field):
			row[field] = default_warehouses.get(field)

def consolidate_subcontracted_po(subcontracted_po, subcontracted_qty):
	items_to_remove = defaultdict(list)
	for supplier, items in subcontracted_po.items():
		for item in items:
			ordered_qty = flt(subcontracted_qty.get(item.name))
			if flt(item.qty) <= ordered_qty:
				items_to_remove[supplier].append(item)
			elif ordered_qty:
				item.qty -= ordered_qty

		subcontracted_po[supplier] = [item for item in items if item not in items_to_remove[supplier]]
	return {key: value for key, value in subcontracted_po.items() if value}

def round_up_whole_uom(quantity, uom):
	if uom and frappe.get_cached_value("UOM", uom, "must_be_whole_number"):
		return ceil(quantity)
	return quantity

def get_mr_purchase_uom(row):
	item_details = frappe.get_cached_value("Item", row.item_code, ["purchase_uom", "stock_uom"], as_dict=1)
	if (
		row.get("default_material_request_type") == "Purchase"
		and item_details.purchase_uom
		and item_details.purchase_uom != item_details.stock_uom
	):
		return item_details.purchase_uom

def _iter_mr_rows(doc):
	for key in ("po_items", "items", "sub_assembly_items"):
		for row in doc.get(key) or []:
			if isinstance(row, dict):
				yield row

def get_uom_conversion_factor(item_code, uom):
	item = frappe.get_cached_value("Item", item_code, ["variant_of", "stock_uom"], as_dict=True)
	conversion_factor = frappe.db.get_value(
		"UOM Conversion Detail", {"parent": item_code, "uom": uom}, "conversion_factor"
	)
	if not conversion_factor and item.variant_of:
		conversion_factor = frappe.db.get_value(
			"UOM Conversion Detail", {"parent": item.variant_of, "uom": uom}, "conversion_factor"
		)

	return conversion_factor or get_uom_conv_factor(uom, item.stock_uom)

def _apply_minimum_order_qty(mr_items):
	for rows in _purchase_rows_by_item(mr_items).values():
		surplus_qty = 0.0
		for order_rows in _rows_by_sales_order(rows):
			surplus_qty = _apply_minimum_order_qty_to_order(order_rows, surplus_qty)

def get_warehouse_list(warehouses):
	warehouse_list = []

	if isinstance(warehouses, str):
		warehouses = json.loads(warehouses)

	for row in warehouses:
		child_warehouses = frappe.db.get_descendants("Warehouse", row.get("warehouse"))
		if child_warehouses:
			warehouse_list.extend(child_warehouses)
		else:
			warehouse_list.append(row.get("warehouse"))

	return warehouse_list

def _validate_group_warehouse_target(doc):
	# the group only scopes availability; raw materials still need a concrete
	# receiving warehouse, so for_warehouse is required once we generate items.
	if doc.get("raw_material_group_warehouse") and not doc.get("for_warehouse"):
		frappe.throw(
			_("{0} is required to get raw materials when {1} is set.").format(
				frappe.bold(_("For Warehouse")), frappe.bold(_("Raw Material Group Warehouse"))
			)
		)

def _aggregate_bin_details(bin_list):
	qty_fields = (
		"projected_qty",
		"actual_qty",
		"ordered_qty",
		"reserved_qty_for_production",
		"planned_qty",
	)
	aggregated = {field: 0 for field in qty_fields}
	for row in bin_list or []:
		for field in qty_fields:
			aggregated[field] += flt(row.get(field))
	return aggregated

def _get_transfer_locations(mr_items, warehouses, company):
	from erpnext.stock.doctype.pick_list.pick_list import get_available_item_locations

	required_qty_by_item = defaultdict(float)
	for item in mr_items:
		required_qty_by_item[item.get("item_code")] += max(
			0, flt(item.get("quantity")) * flt(item.get("conversion_factor"))
		)

	return {
		item_code: get_available_item_locations(
			item_code, warehouses, required_qty, company, ignore_validation=True
		)
		if required_qty > 0
		else []
		for item_code, required_qty in required_qty_by_item.items()
	}

def _get_remaining_reserved_qty(plan_qty_by_warehouse, work_order_qty_by_warehouse, warehouse):
	remaining_qty_by_warehouse = {
		plan_warehouse: max(qty - work_order_qty_by_warehouse.get(plan_warehouse, 0.0), 0.0)
		for plan_warehouse, qty in plan_qty_by_warehouse.items()
	}
	total_remaining_qty = sum(remaining_qty_by_warehouse.values())
	if not total_remaining_qty:
		return 0.0

	matched_qty = sum(plan_qty_by_warehouse.values()) - total_remaining_qty
	unmatched_qty = min(sum(work_order_qty_by_warehouse.values()) - matched_qty, total_remaining_qty)
	remaining_qty = remaining_qty_by_warehouse.get(warehouse, 0.0)
	return remaining_qty - remaining_qty * unmatched_qty / total_remaining_qty

def _adjust_required_qty_for_uom(row, required_qty):
	if not row["purchase_uom"]:
		row["purchase_uom"] = row["stock_uom"]

	if row["purchase_uom"] != row["stock_uom"]:
		if not (row["conversion_factor"] or frappe.flags.show_qty_in_stock_uom):
			frappe.throw(
				_("UOM Conversion factor ({0} -> {1}) not found for item: {2}").format(
					row["purchase_uom"], row["stock_uom"], row.item_code
				)
			)

	return required_qty

def _merge_subitem(item_details, d):
	if d.item_code in item_details:
		item_details[d.item_code].qty = item_details[d.item_code].qty + d.qty
		return

	if not d.conversion_factor and d.purchase_uom:
		d.conversion_factor = get_uom_conversion_factor(d.item_code, d.purchase_uom)
	item_details[d.item_code] = d

def _should_explode_subitem(d, include_subcontracted_items):
	return bool(
		(d.default_material_request_type in ["Manufacture", "Purchase"] and not d.is_sub_contracted)
		or (d.is_sub_contracted and include_subcontracted_items)
		or d.is_phantom_item
	)

def _purchase_rows_by_item(mr_items):
	rows_by_item = defaultdict(list)
	for row in mr_items:
		if row.get("material_request_type") not in ("Purchase", "Subcontracting"):
			continue
		if flt(row.get("quantity")) <= 0:
			continue
		key = (
			row.get("item_code"),
			row.get("warehouse"),
			row.get("material_request_type"),
			row.get("supplier"),
		)
		rows_by_item[key].append(row)
	return rows_by_item

def _rows_by_sales_order(rows):
	rows_by_order = defaultdict(list)
	for row in rows:
		rows_by_order[row.get("sales_order") or ""].append(row)
	# Keep surplus allocation stable when upstream queries return orders in a different order.
	return [rows_by_order[sales_order] for sales_order in sorted(rows_by_order)]

def _transfer_from_locations(item, locations, new_mr_items, required_qty):
	precision = frappe.get_precision("Material Request Plan Item", "quantity")
	transfers_by_warehouse = {}
	for d in locations:
		if flt(required_qty, precision) <= 0:
			return required_qty

		quantity = flt(min(required_qty, d.get("qty")), precision)
		if quantity <= 0:
			continue
		d["qty"] -= quantity
		required_qty -= quantity

		warehouse = d.get("warehouse")
		if warehouse in transfers_by_warehouse:
			transfer = transfers_by_warehouse[warehouse]
			transfer["quantity"] = flt(transfer["quantity"] + quantity, precision)
			continue

		new_dict = copy.deepcopy(item)
		new_dict.update(
			{
				"quantity": quantity,
				"material_request_type": "Material Transfer",
				"uom": new_dict.get("stock_uom"),  # internal transfer should be in stock UOM
				"from_warehouse": warehouse,
				"conversion_factor": 1.0,
			}
		)
		transfers_by_warehouse[warehouse] = new_dict
		new_mr_items.append(new_dict)
	return required_qty

def _cover_from_surplus(rows, surplus_qty):
	for row in rows:
		covered_qty = min(surplus_qty, _stock_quantity(row))
		if covered_qty <= 0:
			break
		_set_stock_quantity(row, _stock_quantity(row) - covered_qty)
		surplus_qty -= covered_qty

def _set_stock_quantity(row, stock_qty):
	conversion_factor = flt(row.get("conversion_factor")) or 1
	quantity = _quantity_in_purchase_uom(stock_qty, conversion_factor, stock_qty)
	if frappe.get_cached_value("UOM", row.get("uom"), "must_be_whole_number"):
		quantity = ceil(quantity)
	row["quantity"] = quantity

