def check_quantity(self):
    sn_quants = self.filtered(lambda q: q.product_id.tracking == 'serial' and q.location_id.usage != 'inventory' and q.lot_id)
    if not sn_quants:
        return
    domain = [
        ('product_id', 'in', sn_quants.product_id.ids),
        ('location_id', 'child_of', sn_quants.location_id.ids),
        ('lot_id', 'in', sn_quants.lot_id.ids)
    ]
    groups = self._read_group(
        domain,
        ['product_id', 'location_id', 'lot_id'],
        ['quantity:sum'],
    )
    for product, _location, lot, qty in groups:
        if product.uom_id.compare(abs(qty), 1) > 0:
            raise ValidationError(_('The serial number has already been assigned: \n Product: %(product)s, Serial Number: %(serial_number)s', product=product.display_name, serial_number=lot.name))

def _get_available_quantity(self, product_id, location_id, lot_id=None, package_id=None, owner_id=None, strict=False, allow_negative=False):
    """ Return the available quantity, i.e. the sum of `quantity` minus the sum of
    `reserved_quantity`, for the set of quants sharing the combination of `product_id,
    location_id` if `strict` is set to False or sharing the *exact same characteristics*
    otherwise.
    The set of quants to filter from can be in `self`, if not a search will be done
    This method is called in the following usecases:
        - when a stock move checks its availability
        - when a stock move actually assign
        - when editing a move line, to check if the new value is forced or not
        - when validating a move line with some forced values and have to potentially unlink an
          equivalent move line in another picking
    In the two first usecases, `strict` should be set to `False`, as we don't know what exact
    quants we'll reserve, and the characteristics are meaningless in this context.
    In the last ones, `strict` should be set to `True`, as we work on a specific set of
    characteristics.

    :return: available quantity as a float
    """
    self = self.sudo()
    quants = self._gather(product_id, location_id, lot_id=lot_id, package_id=package_id, owner_id=owner_id, strict=strict)
    if not product_id.tracking:
        available_quantity = sum(quants.mapped('quantity')) - sum(quants.mapped('reserved_quantity'))
        if allow_negative:
            return available_quantity
        else:
            return available_quantity if product_id.uom_id.compare(available_quantity, 0.0) >= 0.0 else 0.0
    else:
        availaible_quantities = {lot_id: 0.0 for lot_id in list(set(quants.mapped('lot_id'))) + ['untracked']}
        for quant in quants:
            if not quant.lot_id and strict and lot_id:
                continue
            if not quant.lot_id:
                availaible_quantities['untracked'] += quant.quantity - quant.reserved_quantity
            else:
                availaible_quantities[quant.lot_id] += quant.quantity - quant.reserved_quantity
        if allow_negative:
            return sum(availaible_quantities.values())
        else:
            return sum(available_quantity for available_quantity in availaible_quantities.values() if product_id.uom_id.compare(available_quantity, 0) > 0)

def _onchange_inventory_quantity(self):
    if self.location_id and self.location_id.usage == 'inventory':
        warning = {
            'title': _('You cannot modify inventory loss quantity'),
            'message': _(
                'Editing quantities in an Inventory Adjustment location is forbidden,'
                'those locations are used as counterpart when correcting the quantities.'
            )
        }
        return {'warning': warning}

def _update_available_quantity(self, product_id, location_id, quantity=False, reserved_quantity=False, lot_id=None, package_id=None, owner_id=None, in_date=None):
    """ Increase or decrease `quantity` or 'reserved quantity' of a set of quants for a given set of
    product_id/location_id/lot_id/package_id/owner_id.

    :param product_id:
    :param location_id:
    :param quantity:
    :param lot_id:
    :param package_id:
    :param owner_id:
    :param datetime in_date: Should only be passed when calls to this method are done in
                             order to move a quant. When creating a tracked quant, the
                             current datetime will be used.
    :return: tuple (available_quantity, in_date as a datetime)
    """
    if not (quantity or reserved_quantity):
        raise ValidationError(_('Quantity or Reserved Quantity should be set.'))
    self = self.sudo()
    quants = self._gather(product_id, location_id, lot_id=lot_id, package_id=package_id, owner_id=owner_id, strict=True)
    if lot_id:
        if product_id.uom_id.compare(quantity, 0) > 0:
            quants = quants.filtered(lambda q: q.lot_id)
        else:
            # Don't remove quantity from a negative quant without lot
            quants = quants.filtered(lambda q: product_id.uom_id.compare(q.quantity, 0) > 0 or q.lot_id)

    if location_id.should_bypass_reservation():
        incoming_dates = []
    else:
        incoming_dates = [quant.in_date for quant in quants if quant.in_date and
                          quant.uom_id.compare(quant.quantity, 0) > 0]
    if in_date:
        incoming_dates += [in_date]
    # If multiple incoming dates are available for a given lot_id/package_id/owner_id, we
    # consider only the oldest one as being relevant.
    if incoming_dates:
        in_date = min(incoming_dates)
    else:
        in_date = fields.Datetime.now()

    quant = None
    if quants:
        # quants are already ordered in _gather
        # lock the first available
        quant = quants.try_lock_for_update(allow_referencing=True, limit=1)

    if quant:
        vals = {'in_date': in_date}
        if quantity:
            vals['quantity'] = quant.quantity + quantity
        if reserved_quantity:
            vals['reserved_quantity'] = max(0, quant.reserved_quantity + reserved_quantity)
        quant.write(vals)
    else:
        vals = {
            'product_id': product_id.id,
            'location_id': location_id.id,
            'lot_id': lot_id and lot_id.id,
            'package_id': package_id and package_id.id,
            'owner_id': owner_id and owner_id.id,
            'in_date': in_date,
        }
        if quantity:
            vals['quantity'] = quantity
        if reserved_quantity:
            vals['reserved_quantity'] = reserved_quantity
        self.create(vals)
    return self._get_available_quantity(product_id, location_id, lot_id=lot_id, package_id=package_id, owner_id=owner_id, strict=True, allow_negative=True), in_date

def _is_inventory_mode(self):
    """ Used to control whether a quant was written on or created during an
    "inventory session", meaning a mode where we need to create the stock.move
    record necessary to be consistent with the `inventory_quantity` field.
    """
    return self.env.context.get('inventory_mode') and self.env.user.has_group('stock.group_stock_user')

def _gather(self, product_id, location_id, lot_id=None, package_id=None, owner_id=None, strict=False, qty=0):
    """ if records in self, the records are filtered based on the wanted characteristics passed to this function
        if not, a search is done with all the characteristics passed.
    """
    removal_strategy = self._get_removal_strategy(product_id, location_id)
    domain = self._get_gather_domain(product_id, location_id, lot_id, package_id, owner_id, strict)
    if removal_strategy == 'least_packages' and qty:
        domain = self._run_least_packages_removal_strategy_astar(domain, qty)
    order = self._get_removal_strategy_order(removal_strategy)

    quants_cache = self.env.context.get('quants_cache')
    if quants_cache is not None and strict and removal_strategy != 'least_packages':
        res = self.env['stock.quant']
        if lot_id:
            res |= quants_cache[product_id.id, location_id.id, lot_id.id, package_id.id, owner_id.id]
        res |= quants_cache[product_id.id, location_id.id, False, package_id.id, owner_id.id]
    else:
        res = self.search(domain, order=order)
    if removal_strategy == "closest":
        res = res.sorted(lambda q: (q.location_id.complete_name, -q.id))
    return res.sorted(lambda q: not q.lot_id)

def create(self, vals_list):
    """ Override to handle the "inventory mode" and create a quant as
    superuser the conditions are met.
    """
    def _add_to_cache(quant):
        if 'quants_cache' in self.env.context:
            self.env.context['quants_cache'][
                quant.product_id.id, quant.location_id.id, quant.lot_id.id, quant.package_id.id, quant.owner_id.id
            ] |= quant

    quants = self.env['stock.quant']
    is_inventory_mode = self._is_inventory_mode()
    allowed_fields = self._get_inventory_fields_create()
    for vals in vals_list:
        if is_inventory_mode and any(f in vals for f in ['inventory_quantity', 'inventory_quantity_auto_apply']):
            if any(field for field in vals if not field.startswith('x_') and field not in allowed_fields):
                raise UserError(_("Quant's creation is restricted, you can't do this operation."))
            auto_apply = 'inventory_quantity_auto_apply' in vals
            inventory_quantity = vals.pop('inventory_quantity_auto_apply', False) or vals.pop(
                'inventory_quantity', False) or 0
            # Create an empty quant or write on a similar one.
            product = self.env['product.product'].browse(vals['product_id'])
            location = self.env['stock.location'].browse(vals['location_id'])
            lot_id = self.env['stock.lot'].browse(vals.get('lot_id'))
            package_id = self.env['stock.package'].browse(vals.get('package_id'))
            owner_id = self.env['res.partner'].browse(vals.get('owner_id'))
            quant = self.env['stock.quant']
            if not self.env.context.get('import_quant_lines'):
                # Merge quants later, to make sure one line = one record during batch import
                quant = self._gather(product, location, lot_id=lot_id, package_id=package_id, owner_id=owner_id, strict=True)
            if lot_id:
                if self.env.context.get('import_file') and lot_id.product_id != product:
                    lot_name = lot_id.name
                    lot_id = self.env['stock.lot'].search([('product_id', '=', product.id), ('name', '=', lot_name)], limit=1)
                    if not lot_id:
                        company_id = location.company_id or self.env.company
                        lot_id = self.env['stock.lot'].create({'name': lot_name, 'product_id': product.id, 'company_id': company_id.id})
                    vals['lot_id'] = lot_id.id
                quant = quant.filtered(lambda q: q.lot_id)
            if quant:
                quant = quant[0].sudo()
            else:
                quant = self.sudo().create(vals)
                _add_to_cache(quant)
            if auto_apply:
                quant.write({'inventory_quantity_auto_apply': inventory_quantity})
            else:
                # Set the `inventory_quantity` field to create the necessary move.
                quant.inventory_quantity = inventory_quantity
                quant.user_id = vals.get('user_id', self.env.user.id)
                quant.inventory_date = fields.Date.context_today(self)
            quants |= quant
        else:
            if 'inventory_quantity' not in vals:
                vals['inventory_quantity_set'] = vals.get('inventory_quantity_set', False)
            quant = super().create(vals)
            _add_to_cache(quant)
            quants |= quant
            if self._is_inventory_mode() and quant.company_id:
                quant._check_company()
    return quants

def write(self, vals):
    """ Override to handle the "inventory mode" and create the inventory move. """
    forbidden_fields = self._get_forbidden_fields_write()
    if self._is_inventory_mode() and any(field for field in forbidden_fields if field in vals.keys()):
        if any(quant.location_id.usage == 'inventory' for quant in self):
            # Do nothing when user tries to modify manually a inventory loss
            return
        self = self.sudo()
        raise UserError(_("Quant's editing is restricted, you can't do this operation."))
    return super(StockQuant, self).write(vals)

def _get_removal_strategy(self, product_id, location_id):
    product_id = product_id.sudo()
    location_id = location_id.sudo()
    if product_id.categ_id.removal_strategy_id:
        return product_id.categ_id.removal_strategy_id.with_context(lang=None).method
    loc = location_id
    while loc:
        if loc.removal_strategy_id:
            return loc.removal_strategy_id.with_context(lang=None).method
        loc = loc.location_id
    return 'fifo'

def _run_least_packages_removal_strategy_astar(self, domain, qty):
    # Fetch the available packages and contents
    domain = Domain(domain).optimize(self)
    query = self._search(domain, bypass_access=True)
    query.groupby = SQL("package_id")
    query.having = SQL("SUM(quantity - reserved_quantity) > 0")
    query.order = SQL("available_qty DESC")
    qty_by_package = self.env.execute_query(
        query.select(SQL('package_id'), SQL('SUM(quantity - reserved_quantity) AS available_qty')))

    # Items that do not belong to a package are added individually to the list, any empty packages get removed.
    pkg_found = False
    new_qty_by_package = []
    none_elements = []

    for elem in qty_by_package:
        if elem[0] is None:
            none_elements.extend([(None, 1) for _ in range(int(elem[1]))])
        elif elem[1] != 0:
            new_qty_by_package.append(elem)
            pkg_found = True

    new_qty_by_package.extend(none_elements)
    qty_by_package = new_qty_by_package

    if not pkg_found:
        return domain
    size = len(qty_by_package)

    class PriorityQueue:
        def __init__(self):
            self.elements = []

        def empty(self) -> bool:
            return not self.elements

        def put(self, item, priority):
            heapq.heappush(self.elements, (priority, item))

        def get(self):
            return heapq.heappop(self.elements)[1]

    def heuristic(node):
        if node.next_index < size:
            return len(node.taken_packages) + node.count_remaining / qty_by_package[node.next_index][1]
        return len(node.taken_packages)

    def generate_domain(node):
        selected_single_items = []
        single_item_ids = False
        for pkg in node.taken_packages:
            if pkg[0] is None:
                # Lazily retrieve ids for single items
                if not single_item_ids:
                    single_item_ids = self.search(Domain('package_id', '=', None) & domain).ids
                selected_single_items.append(single_item_ids.pop())

        return (
            Domain('package_id', 'in', [elem[0] for elem in node.taken_packages if elem[0] is not None])
            | Domain('id', 'in', selected_single_items)
        ) & domain

    Node = namedtuple("Node", "count_remaining taken_packages next_index")

    frontier = PriorityQueue()
    frontier.put(Node(qty, (), 0), 0)

    best_leaf = Node(qty, (), 0)

    try:
        while not frontier.empty():
            current = frontier.get()

            if current.count_remaining <= 0:
                return generate_domain(current)

            # Keep track of processed package amounts to only generate one branch for the same amount
            last_count = None
            i = current.next_index
            while i < size:
                pkg = qty_by_package[i]
                i += 1
                if pkg[1] == last_count:
                    continue
                last_count = pkg[1]

                count = current.count_remaining - pkg[1]
                taken = current.taken_packages + (pkg,)
                node = Node(count, taken, i)

                if count < 0:
                    # Overselect case
                    if best_leaf.count_remaining > 0 or len(node.taken_packages) < len(best_leaf.taken_packages) or (len(node.taken_packages) == len(best_leaf.taken_packages) and node.count_remaining > best_leaf.count_remaining):
                        best_leaf = node
                    continue

                if i >= size and count != 0:
                    # Not enough packages case
                    if node.count_remaining < best_leaf.count_remaining:
                        best_leaf = node
                    continue

                frontier.put(node, heuristic(node))
    except MemoryError:
        _logger.info('Ran out of memory while trying to use the least_packages strategy to get quants. Domain: %s', domain)
        return domain

    # no exact matching possible, use best leaf
    return generate_domain(best_leaf)

def _get_removal_strategy_order(self, removal_strategy):
    if removal_strategy in ['fifo', 'least_packages']:
        return 'in_date ASC, id'
    elif removal_strategy == 'lifo':
        return 'in_date DESC, id DESC'
    elif removal_strategy == 'closest':
        return False
    raise UserError(_('Removal strategy %s not implemented.', removal_strategy))

def _get_gather_domain(self, product_id, location_id, lot_id=None, package_id=None, owner_id=None, strict=False):
    domains = [Domain('product_id', '=', product_id.id)]
    if not strict:
        if lot_id:
            domains.append(Domain('lot_id', 'in', [lot_id.id, False]))
        if package_id:
            domains.append(Domain('package_id', '=', package_id.id))
        if owner_id:
            domains.append(Domain('owner_id', '=', owner_id.id))
        domains.append(Domain('location_id', 'child_of', location_id.id))
    else:
        domains.extend((
            Domain('lot_id', 'in', [False, lot_id.id if lot_id else False]),
            Domain('package_id', '=', package_id.id if package_id else False),
            Domain('owner_id', '=', owner_id.id if owner_id else False),
            Domain('location_id', '=', location_id.id),
        ))
    if self.env.context.get('with_expiration'):
        domains.append(Domain('removal_date', '>=', self.env.context['with_expiration']) | Domain('removal_date', '=', False))
    return Domain.AND(domains)

def _get_inventory_fields_create(self):
    """ Returns a list of fields user can edit when he want to create a quant in `inventory_mode`.
    """
    return ['product_id', 'owner_id'] + self._get_inventory_fields_write()

def _get_forbidden_fields_write(self):
    """ Returns a list of fields user can't edit when he want to edit a quant in `inventory_mode`."""
    return ['product_id', 'location_id', 'lot_id', 'package_id', 'owner_id']

def _search(self, domain, *args, **kwargs):
    domain = Domain(domain).map_conditions(
        lambda condition: Domain('lot_id', 'any', [condition]) if condition.field_expr.startswith('lot_properties.') else condition
    )
    return super()._search(domain, *args, **kwargs)

def _check_stock_quantity(cls, sales):
    for sale in sales:
        sale.check_stock_quantity()

def _stock_quantity_next_supply_date(cls, product):
    pool = Pool()
    try:
        PurchaseRequest = pool.get('purchase.request')
    except KeyError:
        PurchaseRequest = None

    if (getattr(PurchaseRequest, 'get_supply_dates', None)
            and product.purchasable):
        return PurchaseRequest.get_supply_dates(product)[0]
    else:
        # TODO compute supply date for production
        return datetime.date.max

@Override
public BigDecimal computeFutureQty(StockLocationLine stockLocationLine) throws AxelorException {
  // future quantity = current quantity - planned outgoing + planned incoming
  BigDecimal futureQty =
      stockLocationLine.getCurrentQty() != null
          ? stockLocationLine.getCurrentQty()
          : BigDecimal.ZERO;

  Product product = stockLocationLine.getProduct();

  if (stockLocationLine.getUnit() == null) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(StockExceptionMessage.LOCATION_LINE_MISSING_UNIT),
        stockLocationLine.getStockLocation().getName(),
        product.getFullName());
  }

  boolean isDetailsStockLocationLine = stockLocationLine.getDetailsStockLocation() != null;
  Long stockLocationId =
      isDetailsStockLocationLine
          ? stockLocationLine.getDetailsStockLocation().getId()
          : stockLocationLine.getStockLocation().getId();
  Long trackingNumberId =
      isDetailsStockLocationLine && stockLocationLine.getTrackingNumber() != null
          ? stockLocationLine.getTrackingNumber().getId()
          : null;

  StringBuilder jpql = new StringBuilder();
  jpql.append(
      "SELECT new com.axelor.apps.stock.utils.StockLocationLineQtyView("
          + " self.unit, "
          + " SUM(CASE WHEN self.toStockLocation.id = :stockLocationId THEN COALESCE(self.qty, 0) ELSE 0 END), "
          + " SUM(CASE WHEN self.fromStockLocation.id = :stockLocationId THEN COALESCE(self.qty, 0) ELSE 0 END) "
          + ") "
          + " FROM StockMoveLine self "
          + " WHERE (self.stockMove.archived IS NULL OR self.archived IS FALSE) "
          + " AND self.stockMove.statusSelect = :planned "
          + " AND self.product.id = :productId "
          + " AND (self.toStockLocation.id = :stockLocationId OR self.fromStockLocation.id = :stockLocationId) ");
  if (isDetailsStockLocationLine) {
    jpql.append(" AND self.trackingNumber.id = :trackingNumberId ");
  }
  jpql.append(" GROUP BY self.unit");

  var query =
      JPA.em()
          .createQuery(jpql.toString(), StockLocationLineQtyView.class)
          .setParameter("planned", StockMoveRepository.STATUS_PLANNED)
          .setParameter("productId", product.getId())
          .setParameter("stockLocationId", stockLocationId);
  if (isDetailsStockLocationLine) {
    query.setParameter("trackingNumberId", trackingNumberId);
  }
  query.setFlushMode(FlushModeType.COMMIT);
  List<StockLocationLineQtyView> aggregates = query.getResultList();

  for (StockLocationLineQtyView agg : aggregates) {
    Unit aggUnit = agg.getUnit();
    BigDecimal incoming = agg.getIncoming() != null ? agg.getIncoming() : BigDecimal.ZERO;
    BigDecimal outgoing = agg.getOutgoing() != null ? agg.getOutgoing() : BigDecimal.ZERO;

    if (incoming.compareTo(BigDecimal.ZERO) != 0) {
      BigDecimal incConverted =
          unitConversionService.convertWithAutoFlushFalse(
              aggUnit, stockLocationLine.getUnit(), incoming, incoming.scale(), product);
      futureQty = futureQty.add(incConverted);
    }

    if (outgoing.compareTo(BigDecimal.ZERO) != 0) {
      BigDecimal outConverted =
          unitConversionService.convertWithAutoFlushFalse(
              aggUnit, stockLocationLine.getUnit(), outgoing, outgoing.scale(), product);
      futureQty = futureQty.subtract(outConverted);
    }
  }

  return futureQty;
}

def get_available_qty_to_reserve(
	item_code: str, warehouse: str, batch_no: str | None = None, ignore_sre=None
) -> float:
	"""Returns `Available Qty to Reserve (Actual Qty - Reserved Qty)` for Item, Warehouse and Batch combination."""

	from erpnext.stock.doctype.batch.batch import get_batch_qty

	if batch_no:
		return get_batch_qty(
			item_code=item_code,
			warehouse=warehouse,
			batch_no=batch_no,
			ignore_voucher_nos=[ignore_sre] if ignore_sre else None,
		)

	available_qty = _get_stock_balance(item_code, warehouse)

	if available_qty:
		sre = frappe.qb.DocType("Stock Reservation Entry")
		query = (
			frappe.qb.from_(sre)
			.select(Sum(sre.reserved_qty - sre.delivered_qty - sre.transferred_qty - sre.consumed_qty))
			.where(
				(sre.docstatus == 1)
				& (sre.item_code == item_code)
				& (sre.warehouse == warehouse)
				& (sre.delivered_qty < sre.reserved_qty)
			)
			.for_update()
		)

		if ignore_sre:
			query = query.where(sre.name != ignore_sre)

		reserved_qty = query.run()[0][0] or 0.0

		if reserved_qty:
			return available_qty - reserved_qty

	return available_qty

def get_available_serial_nos_to_reserve(
	item_code: str, warehouse: str, has_batch_no: bool = False, ignore_sre=None
) -> list[tuple]:
	"""Returns Available Serial Nos to Reserve (Available Serial Nos - Reserved Serial Nos)` for Item, Warehouse and Batch combination."""

	from erpnext.stock.doctype.serial_and_batch_bundle.serial_and_batch_bundle import (
		get_available_serial_nos,
	)

	available_serial_nos = get_available_serial_nos(
		frappe._dict(
			{
				"item_code": item_code,
				"warehouse": warehouse,
				"has_batch_no": has_batch_no,
				"ignore_voucher_nos": [ignore_sre],
			}
		)
	)

	available_serial_nos_list = []
	if available_serial_nos:
		available_serial_nos_list = [tuple(d.values()) for d in available_serial_nos]

		sre = frappe.qb.DocType("Stock Reservation Entry")
		sb_entry = frappe.qb.DocType("Serial and Batch Entry")
		query = (
			frappe.qb.from_(sre)
			.left_join(sb_entry)
			.on(sre.name == sb_entry.parent)
			.select(sb_entry.serial_no, sre.warehouse)
			.where(
				(sre.docstatus == 1)
				& (sre.item_code == item_code)
				& (sre.warehouse == warehouse)
				& (sre.delivered_qty < sre.reserved_qty)
				& (sre.reservation_based_on == "Serial and Batch")
			)
		)

		if has_batch_no:
			query = query.select(sb_entry.batch_no)

		if ignore_sre:
			query = query.where(sre.name != ignore_sre)

		reserved_serial_nos = query.run()

		if reserved_serial_nos:
			return list(set(available_serial_nos_list) - set(reserved_serial_nos))

	return available_serial_nos_list

def get_sre_reserved_qty_for_items_and_warehouses(
	item_code_list: list, warehouse_list: list | None = None
) -> dict:
	"""Returns a dict like {("item_code", "warehouse"): "reserved_qty", ... }."""

	if not item_code_list:
		return {}

	sre = frappe.qb.DocType("Stock Reservation Entry")
	query = (
		frappe.qb.from_(sre)
		.select(
			sre.item_code,
			sre.warehouse,
			Sum(sre.reserved_qty - sre.delivered_qty - sre.transferred_qty - sre.consumed_qty).as_(
				"reserved_qty"
			),
		)
		.where(
			(sre.docstatus == 1)
			& sre.item_code.isin(item_code_list)
			& (sre.delivered_qty < sre.reserved_qty)
			& (sre.status.notin(["Closed", "Delivered"]))
		)
		.groupby(sre.item_code, sre.warehouse)
	)

	if warehouse_list:
		query = query.where(sre.warehouse.isin(warehouse_list))

	data = query.run(as_dict=True)

	return {(d["item_code"], d["warehouse"]): d["reserved_qty"] for d in data} if data else {}

def get_whole_sales_unit_qty(item, stock_qty: float, max_qty: float | None = None) -> float:
	conversion_factor = flt(item.get("conversion_factor")) or 1
	if conversion_factor == 1 or not frappe.get_cached_value("UOM", item.get("uom"), "must_be_whole_number"):
		return stock_qty

	if max_qty is not None:
		stock_qty = min(ceil(flt(flt(stock_qty) / conversion_factor, 6)) * conversion_factor, max_qty)

	return floor(flt(flt(stock_qty) / conversion_factor, 6)) * conversion_factor

def has_reserved_stock(voucher_type: str, voucher_no: str, voucher_detail_no: str | None = None) -> bool:
	"""Returns True if there is any Stock Reservation Entry for the given voucher."""

	if _get_stock_reservation_entries_for_voucher(
		voucher_type, voucher_no, voucher_detail_no, fields=["name"], ignore_status=True
	):
		return True

	return False

def set_reserved_serial_batch_entries(sre, bundle, qty_to_reserve, has_serial_no, has_batch_no):
	picked_qty = 0
	for entry in frappe.get_doc("Serial and Batch Bundle", bundle).entries:
		if picked_qty >= qty_to_reserve:
			break

		qty = 1 if has_serial_no else min(abs(entry.qty), qty_to_reserve - picked_qty)
		sre.append(
			"sb_entries",
			{
				"serial_no": entry.serial_no,
				"batch_no": entry.batch_no,
				"qty": qty,
				"warehouse": entry.warehouse,
			},
		)
		picked_qty += qty

	if picked_qty < qty_to_reserve:
		add_available_serial_batch_entries(sre, qty_to_reserve - picked_qty, has_serial_no, has_batch_no)

def add_available_serial_batch_entries(sre, qty_needed, has_serial_no, has_batch_no):
	if has_serial_no:
		add_available_serial_entries(sre, qty_needed, has_batch_no)
	else:
		add_available_batch_entries(sre, qty_needed)

def add_available_serial_entries(sre, qty_needed, has_batch_no):
	taken = {row.serial_no for row in sre.sb_entries}
	for serial in get_available_serial_nos_to_reserve(sre.item_code, sre.warehouse, has_batch_no):
		if qty_needed <= 0:
			return
		if serial[0] in taken:
			continue

		batch_no = serial[2] if has_batch_no and len(serial) > 2 else None
		sre.append(
			"sb_entries", {"serial_no": serial[0], "batch_no": batch_no, "qty": 1, "warehouse": sre.warehouse}
		)
		qty_needed -= 1

def add_available_batch_entries(sre, qty_needed):
	from erpnext.stock.doctype.serial_and_batch_bundle.serial_and_batch_bundle import get_auto_batch_nos

	taken = {}
	for row in sre.sb_entries:
		taken[row.batch_no] = taken.get(row.batch_no, 0) + flt(row.qty)

	for batch in get_auto_batch_nos(frappe._dict(item_code=sre.item_code, warehouse=sre.warehouse)):
		qty = min(flt(batch.qty) - taken.get(batch.batch_no, 0), qty_needed)
		if qty <= 0:
			continue

		if existing := next((row for row in sre.sb_entries if row.batch_no == batch.batch_no), None):
			existing.qty = flt(existing.qty) + qty
		else:
			sre.append("sb_entries", {"batch_no": batch.batch_no, "qty": qty, "warehouse": sre.warehouse})
		qty_needed -= qty
		if qty_needed <= 0:
			return

def get_serial_batch_open_qty(sre_names: list[str]) -> dict[str, float]:
	"""Undelivered serial and batch qty of each reservation that has serial and batch entries, read under a lock."""
	if not sre_names:
		return {}

	sb_entry = frappe.qb.DocType("Serial and Batch Entry")
	open_qty = defaultdict(float)
	for parent, qty in (
		frappe.qb.from_(sb_entry)
		.select(sb_entry.parent, sb_entry.qty - sb_entry.delivered_qty)
		.where((sb_entry.parenttype == "Stock Reservation Entry") & sb_entry.parent.isin(sre_names))
		.for_update()
	).run():
		open_qty[parent] += flt(qty)

	return open_qty

def set_delivered_qty(sre: frappe._dict, delivered_qty: float) -> None:
	sre.delivered_qty = delivered_qty
	frappe.db.set_value(
		"Stock Reservation Entry", sre.name, {"delivered_qty": delivered_qty, "status": get_status(sre)}
	)

def allocate_serial_batch_qty(
	entries: list[dict], limits: dict[str, float], serial_batch: frappe._dict
) -> dict[str, float]:
	"""Qty to move on each row, within its open qty, the serial and batch qty to move and its reservation's limit."""
	limits = defaultdict(float, limits)
	serial_nos = set(serial_batch.get("serial_nos") or [])
	batches = defaultdict(float, serial_batch.get("batches") or {})
	moved_qty = {}
	for entry in entries:
		qty = 0
		if entry.serial_no and entry.serial_no in serial_nos and limits[entry.parent] >= entry.open_qty:
			qty = entry.open_qty
			serial_nos.remove(entry.serial_no)
		elif not entry.serial_no and entry.batch_no:
			qty = min(entry.open_qty, batches[entry.batch_no], limits[entry.parent])
			batches[entry.batch_no] -= qty

		limits[entry.parent] -= qty
		if qty > 0:
			moved_qty[entry.name] = qty

	return moved_qty

def add_serial_batch_delivered_qty(deltas: dict[str, float]) -> None:
	"""Add each delta to its row's delivered qty, one statement per distinct delta."""
	rows_by_delta = defaultdict(list)
	for name, delta in deltas.items():
		rows_by_delta[delta].append(name)

	sb_entry = frappe.qb.DocType("Serial and Batch Entry")
	for delta, names in rows_by_delta.items():
		frappe.qb.update(sb_entry).set(sb_entry.delivered_qty, sb_entry.delivered_qty + delta).where(
			sb_entry.name.isin(names)
		).run()

def get_status(sre) -> str:
	"""Status of a reservation from its docstatus and quantities."""
	if sre.docstatus == 2:
		return "Cancelled"
	if sre.docstatus != 1:
		return "Draft"
	if sre.transferred_qty:
		return "Partially Used" if sre.transferred_qty < sre.reserved_qty else "Closed"
	if flt(sre.delivered_qty) + flt(sre.consumed_qty) >= flt(sre.reserved_qty):
		return "Delivered"
	if sre.delivered_qty:
		return "Partially Delivered"
	if sre.consumed_qty:
		return "Partially Used"
	if sre.reserved_qty >= sre.voucher_qty:
		return "Reserved"
	return "Partially Reserved"

def set_stock_qty(self):
	if not self.docstatus.is_draft() and getattr(self, "_action", None) != "submit":
		return

	conversion_factors = get_uom_conversion_factors(
		{row.item_code for row in self.locations if row.item_code}
	)
	for row in self.locations:
		if not row.item_code:
			continue

		stock_uom = frappe.get_cached_value("Item", row.item_code, "stock_uom")
		row.uom = row.uom or stock_uom
		if row.uom == stock_uom:
			row.conversion_factor = 1
		elif (row.item_code, row.uom) in conversion_factors:
			row.conversion_factor = conversion_factors[(row.item_code, row.uom)]

		row.stock_qty = flt(flt(row.qty) * flt(row.conversion_factor), row.precision("stock_qty"))

def validate_stock_qty(self):
	from erpnext.stock.doctype.batch.batch import get_batch_qty

	for row in self.get("locations"):
		row_qty = self.get_qty_to_pick(row)
		if not row_qty:
			continue

		if row.batch_no:
			batch_qty = get_batch_qty(row.batch_no, row.warehouse, row.item_code)

			if row_qty > batch_qty:
				frappe.throw(
					_(
						"At Row #{0}: The picked quantity {1} for the item {2} is greater than available stock {3} for the batch {4} in the warehouse {5}. Please restock the item."
					).format(
						row.idx,
						row_qty,
						row.item_code,
						batch_qty,
						row.batch_no,
						bold(row.warehouse),
					),
					title=_("Insufficient Stock"),
				)

			continue

		bin_qty = flt(
			frappe.db.get_value(
				"Bin",
				{"item_code": row.item_code, "warehouse": row.warehouse},
				"actual_qty",
			)
		)

		if row_qty > bin_qty:
			frappe.throw(
				_(
					"At Row #{0}: The picked quantity {1} for the item {2} is greater than available stock {3} in the warehouse {4}."
				).format(row.idx, row_qty, bold(row.item_code), bin_qty, bold(row.warehouse)),
				title=_("Insufficient Stock"),
			)

def get_qty_to_pick(self, row):
	if row.picked_qty or self.scan_mode or not self.docstatus.is_submitted():
		return flt(row.picked_qty)

	return flt(row.stock_qty)

def update_reference_qty(self):
	packed_items = []
	so_items = []

	for item in self.locations:
		if item.product_bundle_item:
			packed_items.append(item.product_bundle_item)
		elif item.sales_order_item:
			so_items.append(item.sales_order_item)

	if packed_items:
		self.update_packed_items_qty(packed_items)

	if so_items:
		self.update_sales_order_item_qty(so_items)

def update_packed_items_qty(self, packed_items):
	picked_items = get_picked_items_qty(packed_items, contains_packed_items=True)
	self.validate_picked_qty(picked_items, "Packed Item")

	doc_updates = {item: {"picked_qty": 0} for item in set(packed_items)}
	for d in picked_items:
		doc_updates[d.product_bundle_item] = {"picked_qty": flt(d.picked_qty)}

	if doc_updates:
		frappe.db.bulk_update("Packed Item", doc_updates, update_modified=False)

def update_sales_order_item_qty(self, so_items):
	picked_items = get_picked_items_qty(so_items)
	self.validate_picked_qty(picked_items)

	doc_updates = {item: {"picked_qty": 0} for item in set(so_items)}
	for d in picked_items:
		doc_updates[d.sales_order_item] = {"picked_qty": flt(d.picked_qty)}

	if doc_updates:
		frappe.db.bulk_update("Sales Order Item", doc_updates, update_modified=False)

def validate_picked_qty(self, data, ordered_doctype="Sales Order Item"):
	allowance = 1 + flt(frappe.get_single_value("Stock Settings", "over_picking_allowance")) / 100
	qty_field = "qty" if ordered_doctype == "Packed Item" else "stock_qty"
	reference_field = "product_bundle_item" if ordered_doctype == "Packed Item" else "sales_order_item"
	ordered_qty = dict(
		frappe.get_all(
			ordered_doctype,
			filters={"name": ("in", [row.get(reference_field) for row in data])},
			fields=["name", qty_field],
			as_list=True,
		)
	)

	for row in data:
		ordered = flt(ordered_qty.get(row.get(reference_field)))
		if ordered and flt(row.picked_qty, 6) > flt(ordered * allowance, 6):
			frappe.throw(
				_(
					"You are picking more than required quantity for the item {0}. Check if there is any other pick list created for the sales order {1}."
				).format(row.item_code, row.sales_order)
			)

def aggregate_item_qty(self):
	locations = self.get("locations")
	self.item_count_map = {}
	# aggregate qty for same item
	item_map = OrderedDict()
	for item in locations:
		if item.picked_qty:
			continue

		if not item.item_code:
			frappe.throw(f"Row #{item.idx}: Item Code is Mandatory")
		if not cint(
			frappe.get_cached_value("Item", item.item_code, "is_stock_item")
		) and not frappe.db.exists("Product Bundle", {"new_item_code": item.item_code, "disabled": 0}):
			continue
		item_code = item.item_code
		reference = item.sales_order_item or item.material_request_item
		key = (item_code, item.uom, item.warehouse, item.batch_no, reference)

		item.idx = None
		item.name = None

		if item_map.get(key):
			item_map[key].qty += item.qty
			item_map[key].stock_qty += flt(item.stock_qty, item.precision("stock_qty"))
		else:
			item_map[key] = item

		# maintain count of each item (useful to limit get query)
		self.item_count_map.setdefault(item_code, 0)
		self.item_count_map[item_code] += flt(item.stock_qty, item.precision("stock_qty"))
	return item_map.values()

def validate_for_qty(self):
	if self.purpose == "Material Transfer for Manufacture" and (
		self.for_qty is None or self.for_qty == 0
	):
		frappe.throw(_("Qty of Finished Goods Item should be greater than 0."))

def _get_product_bundle_qty_map(self, bundles) -> dict[str, dict[str, float]]:
	product_bundle_qty_map = {}
	for data in bundles:
		bundle = frappe.get_last_doc("Product Bundle", {"new_item_code": data.item_code, "disabled": 0})
		product_bundle_qty_map[data.item_code] = {item.item_code: item.qty for item in bundle.items}
	return product_bundle_qty_map

def _compute_picked_qty_for_bundle(self, bundle_row, bundle_items) -> int:
	"""Compute how many full bundles can be created from picked items."""
	precision = frappe.get_precision("Stock Ledger Entry", "qty_after_transaction")
	possible_bundles = {}
	for item in self.locations:
		if item.sales_order_item != bundle_row:
			continue

		if qty_in_bundle := bundle_items.get(item.item_code):
			possible_bundles.setdefault(item.product_bundle_item, 0)
			possible_bundles[item.product_bundle_item] += item.picked_qty / qty_in_bundle

	return int(flt(min(possible_bundles.values()), precision or 6)) if possible_bundles else 0

def has_unreserved_stock(self):
	if self.purpose == "Delivery":
		for location in self.locations:
			if (
				location.sales_order
				and location.sales_order_item
				and (flt(location.picked_qty) - flt(location.stock_reserved_qty)) > 0
			):
				return True

	return False

def has_reserved_stock(self):
	if self.purpose == "Delivery":
		for location in self.locations:
			if (
				location.sales_order
				and location.sales_order_item
				and flt(location.stock_reserved_qty) > 0
			):
				return True

	return False

def get_picked_items_qty(items, contains_packed_items=False) -> list[dict]:
	pi_item = frappe.qb.DocType("Pick List Item")

	query = (
		frappe.qb.from_(pi_item)
		.select(
			pi_item.sales_order_item,
			pi_item.product_bundle_item,
			pi_item.item_code,
			pi_item.sales_order,
			Sum(pi_item.stock_qty).as_("stock_qty"),
			Sum(pi_item.picked_qty).as_("picked_qty"),
		)
		.where(pi_item.docstatus == 1)
		.for_update()
	)

	if contains_packed_items:
		query = query.groupby(
			pi_item.product_bundle_item,
			pi_item.sales_order,
		).where(pi_item.product_bundle_item.isin(items))
	else:
		query = query.groupby(
			pi_item.sales_order_item,
			pi_item.sales_order,
		).where(pi_item.sales_order_item.isin(items))

	return query.run(as_dict=True)

def get_locations_based_on_required_qty(locations, required_qty, priority_warehouses):
	filtered_locations = []

	for location in prioritize_locations(locations, priority_warehouses):
		if location.qty >= required_qty:
			location.qty = required_qty
			filtered_locations.append(location)
			break

		required_qty -= location.qty
		filtered_locations.append(location)

	return filtered_locations

def get_available_item_locations_for_serialized_item(
	item_code,
	from_warehouses,
	company,
	consider_rejected_warehouses=False,
):
	sn = frappe.qb.DocType("Serial No")
	query = (
		frappe.qb.from_(sn)
		.select(sn.name, sn.warehouse)
		.where(sn.item_code == item_code)
		.orderby(sn.creation)
	)

	if from_warehouses:
		query = query.where(sn.warehouse.isin(from_warehouses))
	else:
		query = query.where(Coalesce(sn.warehouse, "") != "")
		query = query.where(sn.company == company)

	if not consider_rejected_warehouses:
		if rejected_warehouses := get_rejected_warehouses():
			query = query.where(sn.warehouse.notin(rejected_warehouses))

	serial_nos = query.run(as_list=True)

	warehouse_serial_nos_map = frappe._dict()
	for serial_no, warehouse in serial_nos:
		warehouse_serial_nos_map.setdefault(warehouse, []).append(serial_no)

	locations = []

	for warehouse, serial_nos in warehouse_serial_nos_map.items():
		qty = len(serial_nos)

		locations.append(
			frappe._dict(
				{
					"qty": qty,
					"warehouse": warehouse,
					"item_code": item_code,
					"serial_nos": serial_nos,
				}
			)
		)

	return locations

def get_available_item_locations_for_batched_item(
	item_code,
	from_warehouses,
	company,
	consider_rejected_warehouses=False,
):
	locations = []
	data = get_auto_batch_nos(
		frappe._dict(
			{
				"item_code": item_code,
				"warehouse": from_warehouses,
				"company": company,
				"based_on": frappe.get_single_value("Stock Settings", "pick_serial_and_batch_based_on"),
			}
		)
	)

	warehouse_wise_batches = frappe._dict()
	rejected_warehouses = get_rejected_warehouses()

	for d in data:
		if not consider_rejected_warehouses and rejected_warehouses and d.warehouse in rejected_warehouses:
			continue

		if d.warehouse not in warehouse_wise_batches:
			warehouse_wise_batches.setdefault(d.warehouse, defaultdict(float))

		warehouse_wise_batches[d.warehouse][d.batch_no] += d.qty

	for warehouse, batches in warehouse_wise_batches.items():
		for batch_no, qty in batches.items():
			locations.append(
				frappe._dict(
					{
						"qty": qty,
						"warehouse": warehouse,
						"item_code": item_code,
						"batch_no": batch_no,
					}
				)
			)

	return locations

def get_available_item_locations_for_other_item(
	item_code,
	from_warehouses,
	company,
	consider_rejected_warehouses=False,
):
	bin = frappe.qb.DocType("Bin")
	query = (
		frappe.qb.from_(bin)
		.select(bin.warehouse, bin.actual_qty.as_("qty"))
		.where((bin.item_code == item_code) & (bin.actual_qty > 0))
		.orderby(bin.creation)
	)

	if from_warehouses:
		query = query.where(bin.warehouse.isin(from_warehouses))
	else:
		wh = frappe.qb.DocType("Warehouse")
		query = query.from_(wh).where((bin.warehouse == wh.name) & (wh.company == company))

	if not consider_rejected_warehouses:
		if rejected_warehouses := get_rejected_warehouses():
			query = query.where(bin.warehouse.notin(rejected_warehouses))

	item_locations = query.run(as_dict=True)

	return item_locations

def get_actual_qty(item_code, warehouse):
	return frappe.db.get_value(
		"Bin",
		{"item_code": item_code, "warehouse": warehouse},
		"actual_qty",
	)

def get_pending_transfer_stock_qty(location):
	"""Stock qty of this pick list row still to be moved into a Stock Entry."""
	return flt(location.picked_qty) - flt(location.transferred_qty)

def get_uom_conversion_factors(item_codes) -> dict:
	if not item_codes:
		return {}

	return {
		(row.parent, row.uom): flt(row.conversion_factor)
		for row in frappe.get_all(
			"UOM Conversion Detail",
			filters={"parent": ("in", list(item_codes)), "parenttype": "Item"},
			fields=["parent", "uom", "conversion_factor"],
		)
	}

def _get_product_bundles(self) -> dict[str, str]:
	# Dict[so_item_row: item_code]
	product_bundles = {}
	for item in self.locations:
		if not item.product_bundle_item:
			continue

		product_bundles[item.sales_order_item] = frappe._dict(
			{
				"item_code": frappe.db.get_value(
					"Sales Order Item",
					item.sales_order_item,
					"item_code",
				),
				"pick_list_item": item.name,
			}
		)
	return product_bundles

def prioritize_locations(locations, priority_warehouses):
	if not priority_warehouses:
		return locations

	priority_locations = [loc for loc in locations if loc.warehouse in priority_warehouses]
	fallback_locations = [loc for loc in locations if loc.warehouse not in priority_warehouses]
	return priority_locations + fallback_locations

def validate_picked_materials(item_code, required_qty, locations, picked_item_details=None):
	for location in list(locations):
		if location["qty"] < 0:
			locations.remove(location)

	total_qty_available = sum(location.get("qty") for location in locations)
	remaining_qty = required_qty - total_qty_available

	if remaining_qty > 0:
		if picked_item_details:
			frappe.msgprint(
				_(
					"{0} units of Item {1} is not available in any of the warehouses. Other Pick Lists exist for this item."
				).format(remaining_qty, get_link_to_form("Item", item_code)),
				title=_("Already Picked"),
			)
		else:
			frappe.msgprint(
				_("{0} units of Item {1} is not available in any of the warehouses.").format(
					remaining_qty, get_link_to_form("Item", item_code)
				),
				title=_("Insufficient Stock"),
			)

def filter_locations_by_picked_materials(locations, picked_item_details) -> list[dict]:
	filterd_locations = []
	precision = frappe.get_precision("Pick List Item", "qty")
	for row in locations:
		key = row.warehouse
		if row.batch_no:
			key = (row.warehouse, row.batch_no)

		picked_qty = picked_item_details.get(key, {}).get("picked_qty", 0)
		if not picked_qty:
			filterd_locations.append(row)
			continue
		if picked_qty > row.qty:
			row.qty = 0
			picked_item_details[key]["picked_qty"] -= row.qty
		else:
			row.qty -= picked_qty
			picked_item_details[key]["picked_qty"] = 0.0
			if row.serial_nos:
				row.serial_nos = list(set(row.serial_nos) - set(picked_item_details[key].get("serial_no")))

		if flt(row.qty, precision) > 0:
			filterd_locations.append(row)

	return filterd_locations

def get_rejected_warehouses():
	if not hasattr(frappe.local, "rejected_warehouses"):
		frappe.local.rejected_warehouses = []

	if not frappe.local.rejected_warehouses:
		frappe.local.rejected_warehouses = frappe.get_all(
			"Warehouse", filters={"is_rejected_warehouse": 1}, pluck="name"
		)

	return frappe.local.rejected_warehouses

@Override
@Transactional(rollbackOn = {Exception.class})
public void requestQty(StockMoveLine stockMoveLine) throws AxelorException {
  if (stockMoveLine.getProduct() == null || !stockMoveLine.getProduct().getStockManaged()) {
    return;
  }
  SaleOrderLine saleOrderLine = stockMoveLine.getSaleOrderLine();
  if (saleOrderLine != null) {
    requestQty(saleOrderLine);
  } else {
    stockMoveLine.setReservationDateTime(appBaseService.getTodayDateTime().toLocalDateTime());
    stockMoveLine.setIsQtyRequested(true);
    if (stockMoveLine.getQty().signum() < 0) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_REQUEST_QTY_NEGATIVE));
    }
    this.updateRequestedReservedQty(stockMoveLine, stockMoveLine.getQty());
  }
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void requestQty(SaleOrderLine saleOrderLine) throws AxelorException {
  if (saleOrderLine.getProduct() == null || !saleOrderLine.getProduct().getStockManaged()) {
    return;
  }
  saleOrderLine.setIsQtyRequested(true);
  if (saleOrderLine.getQty().signum() < 0) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_REQUEST_QTY_NEGATIVE));
  }
  StockMoveLine stockMoveLine = getPlannedStockMoveLine(saleOrderLine);
  if (stockMoveLine != null) {
    stockMoveLine.setIsQtyRequested(true);
  }
  BigDecimal qtyToDeliver = saleOrderLine.getQtyToDeliver();
  BigDecimal effectiveQty =
      qtyToDeliver != null && qtyToDeliver.compareTo(BigDecimal.ZERO) > 0
          ? qtyToDeliver
          : saleOrderLine.getQty();
  this.updateRequestedReservedQty(saleOrderLine, effectiveQty);
}

@Override
public void updateReservedQty(StockLocationLine stockLocationLine) throws AxelorException {
  // compute from stock move lines
  List<StockMoveLine> stockMoveLineList =
      stockMoveLineRepository
          .all()
          .filter(
              "self.product.id = :productId "
                  + "AND self.fromStockLocation.id = :stockLocationId "
                  + "AND self.stockMove.statusSelect = :planned")
          .bind("productId", stockLocationLine.getProduct().getId())
          .bind("stockLocationId", stockLocationLine.getStockLocation().getId())
          .bind("planned", StockMoveRepository.STATUS_PLANNED)
          .fetch();
  BigDecimal reservedQty = BigDecimal.ZERO;
  for (StockMoveLine stockMoveLine : stockMoveLineList) {
    reservedQty =
        reservedQty.add(
            convertUnitWithProduct(
                stockMoveLine.getUnit(),
                stockLocationLine.getUnit(),
                stockMoveLine.getReservedQty(),
                stockLocationLine.getProduct()));
  }
  stockLocationLine.setReservedQty(reservedQty);
}

@Override
public void updateReservedQty(SaleOrderLine saleOrderLine) throws AxelorException {
  // compute from stock move lines
  List<StockMoveLine> stockMoveLineList =
      stockMoveLineRepository
          .all()
          .filter(
              "self.saleOrderLine.id = :saleOrderLineId "
                  + "AND self.stockMove.statusSelect = :planned")
          .bind("saleOrderLineId", saleOrderLine.getId())
          .bind("planned", StockMoveRepository.STATUS_PLANNED)
          .fetch();
  BigDecimal reservedQty = BigDecimal.ZERO;
  for (StockMoveLine stockMoveLine : stockMoveLineList) {
    reservedQty =
        reservedQty.add(
            convertUnitWithProduct(
                stockMoveLine.getUnit(),
                saleOrderLine.getUnit(),
                stockMoveLine.getReservedQty(),
                saleOrderLine.getProduct()));
  }
  saleOrderLine.setReservedQty(reservedQty);
}

@Override
public void updateRequestedReservedQty(StockLocationLine stockLocationLine)
    throws AxelorException {
  StockLocation stockLocation = stockLocationLine.getStockLocation();
  if (stockLocation == null) {
    return;
  }

  // compute from stock move lines
  List<StockMoveLine> stockMoveLineList =
      stockMoveLineRepository
          .all()
          .filter(
              "self.product.id = :productId "
                  + "AND self.fromStockLocation.id = :stockLocationId "
                  + "AND self.stockMove.statusSelect = :planned")
          .bind("productId", stockLocationLine.getProduct().getId())
          .bind("stockLocationId", stockLocation.getId())
          .bind("planned", StockMoveRepository.STATUS_PLANNED)
          .fetch();
  BigDecimal requestedReservedQty = BigDecimal.ZERO;
  for (StockMoveLine stockMoveLine : stockMoveLineList) {
    requestedReservedQty =
        requestedReservedQty.add(
            convertUnitWithProduct(
                stockMoveLine.getUnit(),
                stockLocationLine.getUnit(),
                stockMoveLine.getRequestedReservedQty(),
                stockLocationLine.getProduct()));
  }
  stockLocationLine.setRequestedReservedQty(requestedReservedQty);
}

protected void updateRequestedReservedQty(
    StockLocationLine stockLocationLine, StockMoveLine stockMoveLine, BigDecimal newReservedQty)
    throws AxelorException {

  BigDecimal diffReservedQuantity =
      newReservedQty.subtract(stockMoveLine.getRequestedReservedQty());
  BigDecimal diffReservedQuantityLocation =
      convertUnitWithProduct(
          stockMoveLine.getUnit(),
          stockLocationLine.getUnit(),
          diffReservedQuantity,
          stockMoveLine.getProduct());
  stockLocationLine.setRequestedReservedQty(
      stockLocationLine.getRequestedReservedQty().add(diffReservedQuantityLocation));

  stockMoveLine.setRequestedReservedQty(newReservedQty);
  if (stockMoveLine.getRequestedReservedQty().compareTo(stockMoveLine.getReservedQty()) < 0) {
    updateReservedQty(stockMoveLine, stockMoveLine.getRequestedReservedQty());
  }
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void updateRequestedReservedQty(StockMoveLine stockMoveLine, BigDecimal newReservedQty)
    throws AxelorException {
  StockLocationLine stockLocationLine =
      stockLocationLineService.getOrCreateStockLocationLine(
          stockMoveLine.getFromStockLocation(), stockMoveLine.getProduct());
  updateRequestedReservedQty(stockLocationLine, stockMoveLine, newReservedQty);
}

protected void updateReservedQty(
    StockLocationLine stockLocationLine, StockMoveLine stockMoveLine, BigDecimal newReservedQty)
    throws AxelorException {
  if (stockMoveLine.getProduct() == null || !stockMoveLine.getProduct().getStockManaged()) {
    return;
  }
  SaleOrderLine saleOrderLine = stockMoveLine.getSaleOrderLine();
  if (saleOrderLine != null) {
    updateReservedQty(saleOrderLine, newReservedQty);
  } else {
    checkBeforeUpdatingQties(stockMoveLine, newReservedQty);
    if (Beans.get(AppSupplychainService.class)
        .getAppSupplychain()
        .getBlockDeallocationOnAvailabilityRequest()) {
      checkAvailabilityRequest(stockMoveLine, newReservedQty, false);
    }
    if (stockMoveLine.getRequestedReservedQty().compareTo(newReservedQty) < 0
        && newReservedQty.compareTo(BigDecimal.ZERO) > 0) {
      updateRequestedReservedQty(stockLocationLine, stockMoveLine, newReservedQty);
      requestQty(stockMoveLine);
    }

    BigDecimal availableQtyToBeReserved =
        stockLocationLine.getCurrentQty().subtract(stockLocationLine.getReservedQty());
    BigDecimal diffReservedQuantity = newReservedQty.subtract(stockMoveLine.getReservedQty());
    Product product = stockMoveLine.getProduct();
    BigDecimal diffReservedQuantityLocation =
        convertUnitWithProduct(
            stockMoveLine.getUnit(), stockLocationLine.getUnit(), diffReservedQuantity, product);
    if (availableQtyToBeReserved.compareTo(diffReservedQuantityLocation) < 0) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_QTY_NOT_AVAILABLE));
    }
    stockMoveLine.setReservedQty(newReservedQty);

    // update in stock location line
    updateReservedQty(stockLocationLine);
  }
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void updateReservedQty(StockMoveLine stockMoveLine, BigDecimal newReservedQty)
    throws AxelorException {
  StockLocationLine stockLocationLine =
      stockLocationLineService.getOrCreateStockLocationLine(
          stockMoveLine.getFromStockLocation(), stockMoveLine.getProduct());
  updateReservedQty(stockLocationLine, stockMoveLine, newReservedQty);
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void updateRequestedReservedQty(SaleOrderLine saleOrderLine, BigDecimal newReservedQty)
    throws AxelorException {
  if (saleOrderLine.getProduct() == null || !saleOrderLine.getProduct().getStockManaged()) {
    return;
  }

  StockMoveLine stockMoveLine = getPlannedStockMoveLine(saleOrderLine);

  if (stockMoveLine == null) {
    // only change requested quantity in sale order line
    saleOrderLine.setRequestedReservedQty(newReservedQty);
    return;
  }

  checkBeforeUpdatingQties(stockMoveLine, newReservedQty);
  if (Beans.get(AppSupplychainService.class)
      .getAppSupplychain()
      .getBlockDeallocationOnAvailabilityRequest()) {
    checkAvailabilityRequest(stockMoveLine, newReservedQty, true);
  }

  BigDecimal diffReservedQuantity =
      newReservedQty.subtract(saleOrderLine.getRequestedReservedQty());

  // update in stock move line and sale order line
  BigDecimal newAllocatedQty =
      updateRequestedReservedQuantityInStockMoveLines(
          saleOrderLine, stockMoveLine.getProduct(), newReservedQty);

  StockLocationLine stockLocationLine =
      stockLocationLineService.getOrCreateStockLocationLine(
          stockMoveLine.getFromStockLocation(), stockMoveLine.getProduct());

  Product product = stockMoveLine.getProduct();
  // update in stock location line
  BigDecimal diffReservedQuantityLocation =
      convertUnitWithProduct(
          stockMoveLine.getUnit(), stockLocationLine.getUnit(), diffReservedQuantity, product);
  stockLocationLine.setRequestedReservedQty(
      stockLocationLine.getRequestedReservedQty().add(diffReservedQuantityLocation));

  // update reserved qty
  if (newAllocatedQty.compareTo(saleOrderLine.getReservedQty()) < 0) {
    updateReservedQty(saleOrderLine, newAllocatedQty);
  }
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void updateReservedQty(SaleOrderLine saleOrderLine, BigDecimal newReservedQty)
    throws AxelorException {
  if (saleOrderLine.getProduct() == null || !saleOrderLine.getProduct().getStockManaged()) {
    return;
  }
  StockMoveLine stockMoveLine = getPlannedStockMoveLine(saleOrderLine);

  checkBeforeUpdatingQties(stockMoveLine, newReservedQty);
  if (Beans.get(AppSupplychainService.class)
      .getAppSupplychain()
      .getBlockDeallocationOnAvailabilityRequest()) {
    checkAvailabilityRequest(stockMoveLine, newReservedQty, false);
  }

  BigDecimal newRequestedReservedQty = newReservedQty.add(saleOrderLine.getDeliveredQty());
  // update requested reserved qty
  if (newRequestedReservedQty.compareTo(saleOrderLine.getRequestedReservedQty()) > 0
      && newReservedQty.compareTo(BigDecimal.ZERO) > 0) {
    requestQty(saleOrderLine);
  }

  StockLocationLine stockLocationLine =
      stockLocationLineService.getOrCreateStockLocationLine(
          stockMoveLine.getFromStockLocation(), stockMoveLine.getProduct());
  BigDecimal availableQtyToBeReserved =
      stockLocationLine.getCurrentQty().subtract(stockLocationLine.getReservedQty());
  BigDecimal diffReservedQuantity = newReservedQty.subtract(saleOrderLine.getReservedQty());
  Product product = stockMoveLine.getProduct();
  BigDecimal diffReservedQuantityLocation =
      convertUnitWithProduct(
          saleOrderLine.getUnit(), stockLocationLine.getUnit(), diffReservedQuantity, product);
  if (availableQtyToBeReserved.compareTo(diffReservedQuantityLocation) < 0) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_QTY_NOT_AVAILABLE));
  }
  // update in stock move line and sale order line
  updateReservedQuantityInStockMoveLineFromSaleOrderLine(
      saleOrderLine, stockMoveLine.getProduct(), newReservedQty);

  // update in stock location line
  updateReservedQty(stockLocationLine);
}

@Override
public BigDecimal computeRealReservedQty(
    StockLocationLine stockLocationLine, BigDecimal requestedReservedQty) {

  BigDecimal qtyLeftToBeAllocated =
      stockLocationLine.getCurrentQty().subtract(stockLocationLine.getReservedQty());
  return qtyLeftToBeAllocated.min(requestedReservedQty).max(BigDecimal.ZERO);
}

protected void checkReservedQtyStocks(
    StockLocationLine stockLocationLine, StockMoveLine stockMoveLine, int toStatus)
    throws AxelorException {

  if (stockMoveLine.getStockMove() != null
      && stockMoveLine.getStockMove().getTypeSelect() == StockMoveRepository.TYPE_INCOMING) {
    return;
  }
  if (((toStatus == StockMoveRepository.STATUS_REALIZED)
          || toStatus == StockMoveRepository.STATUS_CANCELED)
      && stockLocationLine.getReservedQty().compareTo(stockLocationLine.getCurrentQty()) > 0) {
    BigDecimal convertedAvailableQtyInStockMove =
        convertUnitWithProduct(
            stockMoveLine.getUnit(),
            stockLocationLine.getUnit(),
            stockMoveLine.getRealQty(),
            stockLocationLine.getProduct());
    BigDecimal convertedReservedQtyInStockMove =
        convertUnitWithProduct(
            stockMoveLine.getUnit(),
            stockLocationLine.getUnit(),
            stockMoveLine.getReservedQty(),
            stockLocationLine.getProduct());

    BigDecimal availableQty =
        convertedAvailableQtyInStockMove
            .add(stockLocationLine.getCurrentQty())
            .subtract(convertedReservedQtyInStockMove.add(stockLocationLine.getReservedQty()));
    BigDecimal neededQty =
        convertedAvailableQtyInStockMove.subtract(convertedReservedQtyInStockMove);
    throw new AxelorException(
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(SupplychainExceptionMessage.LOCATION_LINE_NOT_ENOUGH_AVAILABLE_QTY),
        stockLocationLine.getProduct().getFullName(),
        availableQty.setScale(
            appBaseService.getNbDecimalDigitForUnitPrice(), RoundingMode.HALF_UP),
        neededQty.setScale(appBaseService.getNbDecimalDigitForUnitPrice(), RoundingMode.HALF_UP));
  }
}

@Override
public BigDecimal updateRequestedReservedQuantityInStockMoveLines(
    SaleOrderLine saleOrderLine, Product product, BigDecimal newReservedQty)
    throws AxelorException {
  if (product == null || !product.getStockManaged()) {
    return BigDecimal.ZERO;
  }
  List<StockMoveLine> stockMoveLineList = getPlannedStockMoveLines(saleOrderLine);
  BigDecimal deliveredQty = saleOrderLine.getDeliveredQty();
  BigDecimal allocatedRequestedQty = newReservedQty.subtract(deliveredQty);
  if (allocatedRequestedQty.signum() < 0) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_REQUESTED_QTY_TOO_LOW));
  }
  for (StockMoveLine stockMoveLine : stockMoveLineList) {
    BigDecimal stockMoveRequestedQty =
        convertUnitWithProduct(
            saleOrderLine.getUnit(), stockMoveLine.getUnit(), allocatedRequestedQty, product);
    BigDecimal requestedQtyInStockMoveLine = stockMoveLine.getQty().min(stockMoveRequestedQty);
    stockMoveLine.setRequestedReservedQty(requestedQtyInStockMoveLine);
    BigDecimal saleOrderRequestedQtyInStockMoveLine =
        convertUnitWithProduct(
            stockMoveLine.getUnit(),
            saleOrderLine.getUnit(),
            requestedQtyInStockMoveLine,
            product);
    allocatedRequestedQty = allocatedRequestedQty.subtract(saleOrderRequestedQtyInStockMoveLine);
  }
  saleOrderLine.setRequestedReservedQty(newReservedQty.subtract(allocatedRequestedQty));
  return saleOrderLine.getRequestedReservedQty().subtract(deliveredQty);
}

@Override
public void updateReservedQuantityInStockMoveLineFromSaleOrderLine(
    SaleOrderLine saleOrderLine, Product product, BigDecimal newReservedQty)
    throws AxelorException {
  if (product == null || !product.getStockManaged()) {
    return;
  }

  List<StockMoveLine> stockMoveLineList = getPlannedStockMoveLines(saleOrderLine);
  BigDecimal allocatedQty = newReservedQty;
  for (StockMoveLine stockMoveLine : stockMoveLineList) {
    BigDecimal stockMoveAllocatedQty =
        convertUnitWithProduct(
            saleOrderLine.getUnit(), stockMoveLine.getUnit(), allocatedQty, product);
    BigDecimal reservedQtyInStockMoveLine =
        stockMoveLine.getRequestedReservedQty().min(stockMoveAllocatedQty);
    stockMoveLine.setReservedQty(reservedQtyInStockMoveLine);
    BigDecimal saleOrderReservedQtyInStockMoveLine =
        convertUnitWithProduct(
            stockMoveLine.getUnit(),
            saleOrderLine.getUnit(),
            reservedQtyInStockMoveLine,
            product);
    allocatedQty = allocatedQty.subtract(saleOrderReservedQtyInStockMoveLine);
  }
  updateReservedQty(saleOrderLine);
}

@Override
public void updateReservedQuantityFromStockMoveLine(
    StockMoveLine stockMoveLine, Product product, BigDecimal reservedQtyToAdd)
    throws AxelorException {
  if (product == null || !product.getStockManaged()) {
    return;
  }
  SaleOrderLine saleOrderLine = stockMoveLine.getSaleOrderLine();
  stockMoveLine.setReservedQty(stockMoveLine.getReservedQty().add(reservedQtyToAdd));
  if (saleOrderLine != null) {
    updateReservedQty(saleOrderLine);
  }
}

protected BigDecimal allocateReservedQuantityInSaleOrderLines(
    BigDecimal qtyToAllocate,
    StockLocation stockLocation,
    Product product,
    Unit stockLocationLineUnit,
    Optional<StockMoveLine> allocatedStockMoveLine)
    throws AxelorException {
  List<StockMoveLine> stockMoveLineListToAllocate =
      stockMoveLineRepository
          .all()
          .filter(
              "self.fromStockLocation.id = :stockLocationId "
                  + "AND self.product.id = :productId "
                  + "AND self.stockMove.statusSelect = :planned "
                  + "AND self.reservationDateTime IS NOT NULL "
                  + "AND self.reservedQty < self.requestedReservedQty")
          .bind("stockLocationId", stockLocation.getId())
          .bind("productId", product.getId())
          .bind("planned", StockMoveRepository.STATUS_PLANNED)
          .order("reservationDateTime")
          .order("stockMove.estimatedDate")
          .fetch();

  // put stock move lines with the same stock move on the beginning of the list.
  allocatedStockMoveLine.ifPresent(
      stockMoveLine ->
          stockMoveLineListToAllocate.sort(
              // Note: this comparator imposes orderings that are inconsistent with equals.
              (sml1, sml2) -> {
                if (sml1.getStockMove().equals(sml2.getStockMove())) {
                  return 0;
                } else if (sml1.getStockMove().equals(stockMoveLine.getStockMove())) {
                  return -1;
                } else if (sml2.getStockMove().equals(stockMoveLine.getStockMove())) {
                  return 1;
                } else {
                  return 0;
                }
              }));
  BigDecimal leftQtyToAllocate = qtyToAllocate;
  for (StockMoveLine stockMoveLine : stockMoveLineListToAllocate) {
    BigDecimal leftQtyToAllocateStockMove =
        convertUnitWithProduct(
            stockLocationLineUnit, stockMoveLine.getUnit(), leftQtyToAllocate, product);
    BigDecimal neededQtyToAllocate =
        stockMoveLine.getRequestedReservedQty().subtract(stockMoveLine.getReservedQty());
    BigDecimal allocatedStockMoveQty = leftQtyToAllocateStockMove.min(neededQtyToAllocate);

    BigDecimal allocatedQty =
        convertUnitWithProduct(
            stockMoveLine.getUnit(), stockLocationLineUnit, allocatedStockMoveQty, product);

    // update reserved qty in stock move line and sale order line
    updateReservedQuantityFromStockMoveLine(stockMoveLine, product, allocatedStockMoveQty);
    // update left qty to allocate
    leftQtyToAllocate = leftQtyToAllocate.subtract(allocatedQty);
  }

  return qtyToAllocate.subtract(leftQtyToAllocate);
}

@Override
public BigDecimal allocateReservedQuantityInSaleOrderLines(
    BigDecimal qtyToAllocate,
    StockLocation stockLocation,
    Product product,
    Unit stockLocationLineUnit)
    throws AxelorException {
  if (product == null || !product.getStockManaged()) {
    return BigDecimal.ZERO;
  }
  return allocateReservedQuantityInSaleOrderLines(
      qtyToAllocate, stockLocation, product, stockLocationLineUnit, Optional.empty());
}

protected void reallocateQty(
    StockMoveLine stockMoveLine,
    StockLocation stockLocation,
    StockLocationLine stockLocationLine,
    Product product,
    BigDecimal qty)
    throws AxelorException {

  Unit stockMoveLineUnit = stockMoveLine.getUnit();
  Unit stockLocationLineUnit = stockLocationLine.getUnit();

  BigDecimal stockLocationQty =
      convertUnitWithProduct(stockMoveLineUnit, stockLocationLineUnit, qty, product);
  // the quantity that will be allocated in stock location line
  BigDecimal realReservedQty;

  // the quantity that will be allocated in stock move line
  BigDecimal leftToAllocate =
      stockLocationLine.getRequestedReservedQty().subtract(stockLocationLine.getReservedQty());
  realReservedQty = stockLocationQty.min(leftToAllocate);

  allocateReservedQuantityInSaleOrderLines(
      realReservedQty, stockLocation, product, stockLocationLineUnit, Optional.of(stockMoveLine));
  updateReservedQty(stockLocationLine);
}

@Override
public void updateRequestedQuantityInToStockLocation(
    StockMoveLine stockMoveLine,
    StockLocation stockLocation,
    Product product,
    int toStatus,
    BigDecimal qty)
    throws AxelorException {
  if (product == null || !product.getStockManaged()) {
    return;
  }
  StockLocationLine stockLocationLine =
      stockLocationLineFetchService.getStockLocationLine(stockLocation, product);
  if (stockLocationLine == null) {
    return;
  }
  Company company = stockLocationLine.getStockLocation().getCompany();
  SupplyChainConfig supplyChainConfig = supplychainConfigService.getSupplyChainConfig(company);
  if (toStatus == StockMoveRepository.STATUS_REALIZED
      && supplyChainConfig.getAutoAllocateOnReceipt()) {
    reallocateQty(stockMoveLine, stockLocation, stockLocationLine, product, qty);
  }
  updateRequestedReservedQty(stockLocationLine);
  checkReservedQtyStocks(stockLocationLine, stockMoveLine, toStatus);
}

protected boolean isReallocatingQtyOnCancel(StockMoveLine stockMoveLine) {
  return Optional.of(stockMoveLine)
      .map(StockMoveLine::getStockMove)
      .map(StockMove::getCancelReason)
      .map(CancelReason::getCancelQuantityAllocation)
      .orElse(false);
}

@Override
public void updateRequestedQuantityInFromStockLocation(
    StockMoveLine stockMoveLine,
    StockLocation stockLocation,
    Product product,
    int toStatus,
    BigDecimal requestedReservedQty)
    throws AxelorException {
  if (product == null || !product.getStockManaged()) {
    return;
  }
  Unit stockMoveLineUnit = stockMoveLine.getUnit();

  StockLocationLine stockLocationLine =
      stockLocationLineFetchService.getStockLocationLine(stockLocation, product);
  if (stockLocationLine == null) {
    return;
  }
  Unit stockLocationLineUnit = stockLocationLine.getUnit();
  // the quantity that will be allocated in stock location line
  BigDecimal realReservedQty;

  // the quantity that will be allocated in stock move line
  BigDecimal realReservedStockMoveQty;

  // if we cancel, subtract the quantity using the previously allocated quantity.
  if (toStatus == StockMoveRepository.STATUS_CANCELED
      || toStatus == StockMoveRepository.STATUS_REALIZED) {
    realReservedStockMoveQty = stockMoveLine.getReservedQty();

    // convert the quantity for stock location line

    realReservedQty =
        convertUnitWithProduct(
            stockMoveLineUnit,
            stockLocationLineUnit,
            realReservedStockMoveQty,
            stockMoveLine.getProduct());

    // reallocate quantity in other stock move lines
    if (isReallocatingQtyOnCancel(stockMoveLine)) {
      reallocateQty(stockMoveLine, stockLocation, stockLocationLine, product, realReservedQty);
    }

    // no more reserved qty in stock move and sale order lines
    updateReservedQuantityFromStockMoveLine(
        stockMoveLine, product, stockMoveLine.getReservedQty().negate());

    // update requested quantity in sale order line
    SaleOrderLine saleOrderLine = stockMoveLine.getSaleOrderLine();
    if (saleOrderLine != null) {
      // requested quantity should never be below delivered quantity.
      if (toStatus == StockMoveRepository.STATUS_REALIZED) {
        saleOrderLine.setRequestedReservedQty(
            saleOrderLine.getRequestedReservedQty().max(saleOrderLine.getDeliveredQty()));
      } else if (!saleOrderLine.getIsQtyRequested()) {
        // if we cancel and do not want to request quantity, the requested quantity become the new
        // delivered quantity.
        saleOrderLine.setRequestedReservedQty(saleOrderLine.getDeliveredQty());
      }
    }

  } else {
    BigDecimal requestedReservedQtyInLocation =
        convertUnitWithProduct(
            stockMoveLineUnit, stockLocationLine.getUnit(), requestedReservedQty, product);
    realReservedQty = computeRealReservedQty(stockLocationLine, requestedReservedQtyInLocation);
    // convert back the quantity for the stock move line
    realReservedStockMoveQty =
        convertUnitWithProduct(
            stockLocationLineUnit,
            stockMoveLineUnit,
            realReservedQty,
            stockMoveLine.getProduct());
    updateReservedQuantityFromStockMoveLine(stockMoveLine, product, realReservedStockMoveQty);

    // reallocate quantity in other stock move lines
    if (supplychainConfigService
        .getSupplyChainConfig(stockLocation.getCompany())
        .getAutoAllocateOnAllocation()) {
      BigDecimal availableQuantityInLocation =
          stockLocationLine.getCurrentQty().subtract(stockLocationLine.getReservedQty());
      availableQuantityInLocation =
          convertUnitWithProduct(
              stockLocationLineUnit, stockMoveLineUnit, availableQuantityInLocation, product);
      BigDecimal qtyRemainingToAllocate =
          availableQuantityInLocation.subtract(realReservedStockMoveQty);
      reallocateQty(
          stockMoveLine, stockLocation, stockLocationLine, product, qtyRemainingToAllocate);
    }
  }

  updateReservedQty(stockLocationLine);
  updateRequestedReservedQty(stockLocationLine);
  checkReservedQtyStocks(stockLocationLine, stockMoveLine, toStatus);
}

@Override
public void updateRequestedQuantityInLocations(
    StockMoveLine stockMoveLine,
    StockLocation fromStockLocation,
    StockLocation toStockLocation,
    Product product,
    BigDecimal qty,
    BigDecimal requestedReservedQty,
    int toStatus)
    throws AxelorException {
  if (fromStockLocation.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
    updateRequestedQuantityInFromStockLocation(
        stockMoveLine, fromStockLocation, product, toStatus, requestedReservedQty);
  }
  if (toStockLocation.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
    updateRequestedQuantityInToStockLocation(
        stockMoveLine, toStockLocation, product, toStatus, qty);
  }
}

@Override
public void consolidateReservedQtyInStockMoveLineByProduct(StockMove stockMove) {
  if (stockMove == null || stockMove.getId() == null) {
    return;
  }

  Map<Long, BigDecimal> reservedQtyByProduct = new HashMap<>();
  Map<Long, Long> firstLineIdByProduct = new HashMap<>();

  BatchProcessorHelper.builder()
      .clearEveryNBatch(0)
      .build()
      .<StockMoveLine>forEachByQuery(
          getManagedStockMoveLineQuery(stockMove.getId()),
          line -> {
            Product product = line.getProduct();
            if (product == null || !product.getStockManaged()) {
              return;
            }
            Long productId = product.getId();
            BigDecimal reservedQty =
                line.getReservedQty() == null ? BigDecimal.ZERO : line.getReservedQty();
            reservedQtyByProduct.merge(productId, reservedQty, BigDecimal::add);
            firstLineIdByProduct.merge(
                productId,
                line.getId(),
                (currentMin, candidate) ->
                    currentMin == null || candidate < currentMin ? candidate : currentMin);
          });

  BatchProcessorHelper.builder()
      .build()
      .<StockMoveLine>forEachByQuery(
          getManagedStockMoveLineQuery(stockMove.getId()),
          line -> {
            Product product = line.getProduct();
            if (product == null || !product.getStockManaged()) {
              return;
            }
            Long productId = product.getId();
            Long firstLineId = firstLineIdByProduct.get(productId);
            if (firstLineId == null) {
              return;
            }
            if (line.getId().equals(firstLineId)) {
              line.setReservedQty(reservedQtyByProduct.getOrDefault(productId, BigDecimal.ZERO));
            } else {
              line.setReservedQty(BigDecimal.ZERO);
            }
          });
}

protected void checkRequestedAndReservedQty(StockMoveLine stockMoveLine) throws AxelorException {
  BigDecimal plannedQty = stockMoveLine.getQty().max(BigDecimal.ZERO);
  BigDecimal requestedReservedQty = stockMoveLine.getRequestedReservedQty();
  BigDecimal reservedQty = stockMoveLine.getReservedQty();

  String stockMoveLineSeq =
      stockMoveLine.getStockMove() == null
          ? stockMoveLine.getId().toString()
          : stockMoveLine.getStockMove().getStockMoveSeq() + "-" + stockMoveLine.getSequence();

  if (reservedQty.signum() < 0 || requestedReservedQty.signum() < 0) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_RESERVATION_QTY_NEGATIVE));
  }
  if (requestedReservedQty.compareTo(plannedQty) > 0) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_REQUESTED_QTY_TOO_HIGH),
        stockMoveLineSeq);
  }
  if (reservedQty.compareTo(plannedQty) > 0) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_ALLOCATED_QTY_TOO_HIGH),
        stockMoveLineSeq);
  }
}

protected void changeRequestedQtyLowerThanQty(StockMoveLine stockMoveLine)
    throws AxelorException {
  boolean autoFillDeliveryRealQty =
      Beans.get(AppSupplychainService.class).getAppSupplychain().getAutoFillDeliveryRealQty();
  BigDecimal qty =
      autoFillDeliveryRealQty
          ? stockMoveLine.getRealQty().max(BigDecimal.ZERO)
          : stockMoveLine.getQty().max(BigDecimal.ZERO);
  BigDecimal requestedReservedQty = stockMoveLine.getRequestedReservedQty();
  if (requestedReservedQty.compareTo(qty) > 0) {
    Product product = stockMoveLine.getProduct();
    BigDecimal diffRequestedQty = requestedReservedQty.subtract(qty);
    stockMoveLine.setRequestedReservedQty(qty);
    // update in stock location line
    StockLocationLine stockLocationLine =
        stockLocationLineService.getOrCreateStockLocationLine(
            stockMoveLine.getFromStockLocation(), product);
    BigDecimal diffRequestedQuantityLocation =
        convertUnitWithProduct(
            stockMoveLine.getUnit(), stockLocationLine.getUnit(), diffRequestedQty, product);
    stockLocationLine.setRequestedReservedQty(
        stockLocationLine.getRequestedReservedQty().add(diffRequestedQuantityLocation));
  }
}

@Override
public void updateReservedQuantity(StockMove stockMove, int status) throws AxelorException {
  if (stockMove == null || stockMove.getId() == null) {
    return;
  }

  Query<StockMoveLine> query = getManagedStockMoveLineQuery(stockMove.getId());

  BatchProcessorHelper helper = BatchProcessorHelper.builder().clearEveryNBatch(0).build();

  helper.<StockMoveLine, AxelorException>forEachByQuery(
      query,
      line -> {
        if (status == StockMoveRepository.STATUS_PLANNED) {
          changeRequestedQtyLowerThanQty(line);
        }
        checkRequestedAndReservedQty(line);
      });

  if (status == StockMoveRepository.STATUS_REALIZED) {
    consolidateReservedQtyInStockMoveLineByProduct(stockMove);
  }

  helper.<StockMoveLine, AxelorException>forEachByQuery(
      getManagedStockMoveLineQuery(stockMove.getId()),
      line -> {
        BigDecimal qty = line.getRealQty();
        BigDecimal requestedReservedQty =
            line.getRequestedReservedQty().subtract(line.getReservedQty());
        updateRequestedQuantityInLocations(
            line,
            line.getFromStockLocation(),
            line.getToStockLocation(),
            line.getProduct(),
            qty,
            requestedReservedQty,
            status);
      });
}

protected StockMoveLine getPlannedStockMoveLine(SaleOrderLine saleOrderLine) {
  return stockMoveLineRepository
      .all()
      .filter(
          "self.saleOrderLine = :saleOrderLine " + "AND self.stockMove.statusSelect = :planned")
      .bind("saleOrderLine", saleOrderLine)
      .bind("planned", StockMoveRepository.STATUS_PLANNED)
      .fetchOne();
}

protected BigDecimal convertUnitWithProduct(
    Unit startUnit, Unit endUnit, BigDecimal qtyToConvert, Product product)
    throws AxelorException {
  startUnit = JpaModelHelper.ensureManaged(startUnit);
  endUnit = JpaModelHelper.ensureManaged(endUnit);

  if (startUnit != null && !startUnit.equals(endUnit)) {
    return unitConversionService.convert(
        startUnit, endUnit, qtyToConvert, qtyToConvert.scale(), product);
  } else {
    return qtyToConvert;
  }
}

protected void checkAvailabilityRequest(
    StockMoveLine stockMoveLine, BigDecimal qty, boolean isRequested) throws AxelorException {
  BigDecimal stockMoveLineQty =
      isRequested ? stockMoveLine.getRequestedReservedQty() : stockMoveLine.getReservedQty();
  if (stockMoveLine.getStockMove().getAvailabilityRequest()
      && stockMoveLineQty.compareTo(qty) > 0) {
    throw new AxelorException(
        stockMoveLine.getStockMove(),
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_AVAILABILITY_REQUEST));
  }
}

protected void checkBeforeUpdatingQties(StockMoveLine stockMoveLine, BigDecimal qty)
    throws AxelorException {
  if (stockMoveLine == null) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_NO_STOCK_MOVE));
  }
  if (qty.signum() < 0) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_RESERVATION_QTY_NEGATIVE));
  }
}

