def get_default_cost_center(ctx: ItemDetailsCtx, item=None, item_group=None, brand=None, company=None):
	cost_center = None

	if not company and ctx.get("company"):
		company = ctx.get("company")

	if ctx.get("project"):
		cost_center = frappe.db.get_value("Project", ctx.get("project"), "cost_center", cache=True)

	if not cost_center and (item and item_group and brand):
		if ctx.get("customer"):
			cost_center = (
				item.get("selling_cost_center")
				or item_group.get("selling_cost_center")
				or brand.get("selling_cost_center")
			)
		else:
			cost_center = (
				item.get("buying_cost_center")
				or item_group.get("buying_cost_center")
				or brand.get("buying_cost_center")
			)

	elif not cost_center and ctx.get("item_code") and company:
		for method in ["get_item_defaults", "get_item_group_defaults", "get_brand_defaults"]:
			path = f"erpnext.stock.get_item_details.{method}"
			data = frappe.get_attr(path)(ctx.get("item_code"), company)

			if data and (data.selling_cost_center or data.buying_cost_center):
				if ctx.get("customer") and data.selling_cost_center:
					return data.selling_cost_center

				elif ctx.get("supplier") and data.buying_cost_center:
					return data.buying_cost_center

				return data.selling_cost_center or data.buying_cost_center

	if not cost_center and ctx.get("cost_center"):
		cost_center = ctx.get("cost_center")

	if company and cost_center and frappe.get_cached_value("Cost Center", cost_center, "company") != company:
		return None

	if not cost_center and company:
		cost_center = frappe.get_cached_value("Company", company, "cost_center")

	return cost_center

def get_conversion_factor(item_code, uom):
	item = frappe.get_cached_value("Item", item_code, ["variant_of", "stock_uom"], as_dict=True)
	if not item_code or not item or uom == item.stock_uom:
		return {"conversion_factor": 1.0}

	item_codes = [item_code]
	if item.variant_of:
		item_codes.append(item.variant_of)

	parent = frappe.qb.DocType("Item")
	child = frappe.qb.DocType("UOM Conversion Detail")
	query = (
		frappe.qb.from_(parent)
		.join(child)
		.on(parent.name == child.parent)
		.select(child.conversion_factor)
		.where((parent.name.isin(item_codes)) & (child.uom == uom))
		.orderby(parent.has_variants)
		.limit(1)
	)
	conversion_factor = query.run(pluck="conversion_factor")

	if not conversion_factor:
		conversion_factor = get_uom_conv_factor(uom, item.stock_uom)
	else:
		conversion_factor = conversion_factor[0]

	return {"conversion_factor": conversion_factor or 1.0}

def insert_item_price(ctx: ItemDetailsCtx):
	"""Insert Item Price if Price List and Price List Rate are specified and currency is the same"""
	if not ctx.price_list or not ctx.rate or ctx.is_internal_supplier or ctx.is_internal_customer:
		return

	stock_settings = frappe.get_cached_doc("Stock Settings")

	if (
		not frappe.db.get_value("Price List", ctx.price_list, "currency", cache=True) == ctx.currency
		or not stock_settings.auto_insert_price_list_rate_if_missing
		or not frappe.has_permission("Item Price", "write")
	):
		return

	transaction_date = (
		getdate(ctx.get("posting_date") or ctx.get("transaction_date") or ctx.get("posting_datetime"))
		or getdate()
	)

	item_prices = get_item_prices_to_auto_update(ctx)
	item_price = next(
		(
			row
			for row in item_prices
			if (not row.valid_from or getdate(row.valid_from) <= transaction_date)
			and (not row.valid_upto or getdate(row.valid_upto) >= transaction_date)
		),
		item_prices[0] if item_prices else None,
	)

	update_based_on_price_list_rate = stock_settings.update_price_list_based_on == "Price List Rate"

	if item_price and item_price.name:
		if not stock_settings.update_existing_price_list_rate:
			return

		rate_to_consider = flt(ctx.price_list_rate) if update_based_on_price_list_rate else flt(ctx.rate)
		price_list_rate = _get_stock_uom_rate(rate_to_consider, ctx)

		if not price_list_rate or item_price.price_list_rate == price_list_rate:
			return

		is_price_valid_for_transaction = (
			not item_price.valid_from or getdate(item_price.valid_from) <= transaction_date
		) and (not item_price.valid_upto or getdate(item_price.valid_upto) >= transaction_date)
		if is_price_valid_for_transaction:
			frappe.db.set_value("Item Price", item_price.name, "price_list_rate", price_list_rate)
			frappe.msgprint(
				_("Item Price updated for {0} in Price List {1}").format(ctx.item_code, ctx.price_list),
				alert=True,
			)
		else:
			# if price is not valid for the transaction date, insert a new price list rate with updated price and future validity

			item_price = frappe.new_doc(
				"Item Price",
				item_code=ctx.item_code,
				price_list_rate=price_list_rate,
				currency=ctx.currency,
				uom=ctx.stock_uom,
				price_list=ctx.price_list,
				valid_from=transaction_date,
			)
			item_price.insert()
			frappe.msgprint(
				_("Item Price added for {0} in Price List - {1}").format(
					get_link_to_form("Item", ctx.item_code), ctx.price_list
				),
				alert=True,
			)
	else:
		rate_to_consider = (
			(flt(ctx.price_list_rate) or flt(ctx.rate)) if update_based_on_price_list_rate else flt(ctx.rate)
		)
		price_list_rate = _get_stock_uom_rate(rate_to_consider, ctx)

		item_price = frappe.get_doc(
			{
				"doctype": "Item Price",
				"price_list": ctx.price_list,
				"item_code": ctx.item_code,
				"currency": ctx.currency,
				"price_list_rate": price_list_rate,
				"uom": ctx.stock_uom,
				"valid_from": transaction_date,
			}
		)
		item_price.insert()
		frappe.msgprint(
			_("Item Price added for {0} in Price List - {1}").format(
				get_link_to_form("Item", ctx.item_code), ctx.price_list
			),
			alert=True,
		)

def get_price_list_rate_for(ctx: ItemDetailsCtx, item_code):
	"""
	:param customer: link to Customer DocType
	:param supplier: link to Supplier DocType
	:param price_list: str (Standard Buying or Standard Selling)
	:param item_code: str, Item Doctype field item_code
	:param qty: Desired Qty
	:param transaction_date: Date of the price
	"""
	pctx = ItemPriceCtx(
		{
			"item_code": item_code,
			"price_list": ctx.get("price_list"),
			"customer": ctx.get("customer"),
			"supplier": ctx.get("supplier"),
			"uom": ctx.get("uom"),
			"transaction_date": ctx.get("transaction_date"),
			"batch_no": ctx.get("batch_no"),
		}
	)

	item_price_data = 0
	price_list_rate = get_item_price(pctx, item_code, limit=None)
	if price_list_rate:
		if desired_qty := ctx.get("qty"):
			item_price_data = get_prices_fitting_packing_unit(price_list_rate, desired_qty)
	else:
		general_price_list_rate = get_item_price(pctx, item_code, ignore_party=ctx.get("ignore_party"))

		if not general_price_list_rate and ctx.get("uom") != ctx.get("stock_uom"):
			pctx.uom = ctx.get("stock_uom")
			general_price_list_rate = get_item_price(pctx, item_code, ignore_party=ctx.get("ignore_party"))

		if general_price_list_rate:
			item_price_data = general_price_list_rate

	if item_price_data:
		if item_price_data[0].uom == ctx.get("uom"):
			return item_price_data[0].price_list_rate
		elif not ctx.get("price_list_uom_dependant"):
			return flt(item_price_data[0].price_list_rate * flt(ctx.get("conversion_factor", 1)))
		else:
			return item_price_data[0].price_list_rate

def validate_conversion_rate(ctx: ItemDetailsCtx, meta):
	from erpnext.controllers.accounts_controller import validate_conversion_rate

	company_currency = frappe.get_cached_value("Company", ctx.company, "default_currency")
	if not ctx.conversion_rate and ctx.currency == company_currency:
		ctx.conversion_rate = 1.0

	if not ctx.ignore_conversion_rate and ctx.conversion_rate == 1 and ctx.currency != company_currency:
		ctx.conversion_rate = (
			get_exchange_rate(ctx.currency, company_currency, ctx.transaction_date, "for_buying") or 1.0
		)

	# validate currency conversion rate
	validate_conversion_rate(
		ctx.currency, ctx.conversion_rate, meta.get_label("conversion_rate"), ctx.company
	)

	ctx.conversion_rate = flt(
		ctx.conversion_rate,
		get_field_precision(meta.get_field("conversion_rate"), frappe._dict({"fields": ctx})),
	)

	if ctx.price_list:
		if not ctx.plc_conversion_rate and ctx.price_list_currency == frappe.db.get_value(
			"Price List", ctx.price_list, "currency", cache=True
		):
			ctx.plc_conversion_rate = 1.0

		# validate price list currency conversion rate
		if not ctx.price_list_currency:
			throw(_("Price List Currency not selected"))
		else:
			validate_conversion_rate(
				ctx.price_list_currency,
				ctx.plc_conversion_rate,
				meta.get_label("plc_conversion_rate"),
				ctx.company,
			)

			if meta.get_field("plc_conversion_rate"):
				ctx.plc_conversion_rate = flt(
					ctx.plc_conversion_rate,
					get_field_precision(meta.get_field("plc_conversion_rate"), frappe._dict({"fields": ctx})),
				)

def get_price_list_currency_and_exchange_rate(ctx: ItemDetailsCtx):
	if not ctx.price_list:
		return {}

	if ctx.doctype in ["Quotation", "Sales Order", "Delivery Note", "Sales Invoice", "POS Invoice"]:
		ctx.update({"exchange_rate": "for_selling"})
	elif ctx.doctype in ["Supplier Quotation", "Purchase Order", "Purchase Receipt", "Purchase Invoice"]:
		ctx.update({"exchange_rate": "for_buying"})

	price_list_details = get_price_list_details(ctx.price_list)

	price_list_currency = price_list_details.get("currency")
	price_list_uom_dependant = price_list_details.get("price_list_uom_dependant")

	plc_conversion_rate = ctx.plc_conversion_rate
	company_currency = get_company_currency(ctx.company)

	if (not plc_conversion_rate) or (
		price_list_currency and ctx.price_list_currency and price_list_currency != ctx.price_list_currency
	):
		# cksgb 19/09/2016: added args.transaction_date as posting_date argument for get_exchange_rate
		plc_conversion_rate = (
			get_exchange_rate(price_list_currency, company_currency, ctx.transaction_date, ctx.exchange_rate)
			or plc_conversion_rate
		)

	return frappe._dict(
		{
			"price_list_currency": price_list_currency,
			"price_list_uom_dependant": price_list_uom_dependant,
			"plc_conversion_rate": plc_conversion_rate or 1,
		}
	)

def has_incorrect_serial_nos(ctx, out):
	from erpnext.stock.doctype.serial_no.serial_no import get_serial_nos

	if not ctx.get("serial_no"):
		return True

	serial_nos = get_serial_nos(ctx.get("serial_no"))
	if len(serial_nos) != out.get("stock_qty"):
		return True

	return False

def get_filtered_serial_nos(serial_nos, doc, table=None):
	from erpnext.stock.doctype.serial_no.serial_no import get_serial_nos

	if not table:
		table = "items"

	for row in doc.get(table):
		if row.get("serial_no"):
			for serial_no in get_serial_nos(row.get("serial_no")):
				if serial_no in serial_nos:
					serial_nos.remove(serial_no)

	return serial_nos

def get_company_total_stock(item_code, company):
	bin = frappe.qb.DocType("Bin")
	wh = frappe.qb.DocType("Warehouse")

	return (
		frappe.qb.from_(bin)
		.inner_join(wh)
		.on(bin.warehouse == wh.name)
		.select(Sum(bin.actual_qty))
		.where((wh.company == company) & (bin.item_code == item_code))
	).run()[0][0]

def get_barcode_data(items_list=None, item_code=None):
	# get item-wise batch no data
	# example: {'LED-GRE': [Batch001, Batch002]}
	# where LED-GRE is item code, SN0001 is serial no and Pune is warehouse

	itemwise_barcode = {}
	if not items_list and item_code:
		_dict_item_code = frappe._dict(
			{
				"item_code": item_code,
			}
		)

		items_list = [frappe._dict(_dict_item_code)]

	for item in items_list:
		barcodes = frappe.db.get_all("Item Barcode", filters={"parent": item.item_code}, fields="barcode")

		for barcode in barcodes:
			if item.item_code not in itemwise_barcode:
				itemwise_barcode.setdefault(item.item_code, [])
			itemwise_barcode[item.item_code].append(barcode.get("barcode"))

	return itemwise_barcode

def get_default_deferred_account(ctx: ItemDetailsCtx, item, fieldname=None):
	if item.get("enable_deferred_revenue") or item.get("enable_deferred_expense"):
		return (
			frappe.get_cached_value(
				"Item Default",
				{"parent": ctx.item_code, "company": ctx.company},
				fieldname,
			)
			or ctx.get(fieldname)
			or frappe.get_cached_value("Company", ctx.company, "default_" + fieldname)
		)
	else:
		return None

def get_item_prices_to_auto_update(ctx):
	ip = frappe.qb.DocType("Item Price")
	query = (
		frappe.qb.from_(ip)
		.select(ip.name, ip.price_list_rate, ip.valid_from, ip.valid_upto)
		.where(
			(ip.item_code == ctx.item_code)
			& (ip.price_list == ctx.price_list)
			& (ip.currency == ctx.currency)
			& (ip.uom == ctx.stock_uom)
		)
	)

	for fieldname in ("customer", "supplier", "batch_no"):
		query = query.where(IfNull(ip[fieldname], "").isin(["", cstr(ctx.get(fieldname))]))
		query = query.orderby(IfNull(ip[fieldname], ""), order=frappe.qb.desc)

	return (
		query.orderby(ip.valid_from.isnull(), order=frappe.qb.asc)
		.orderby(ip.valid_from, order=frappe.qb.desc)
		.orderby(ip.creation, order=frappe.qb.desc)
	).run(as_dict=True)

def get_prices_fitting_packing_unit(item_prices, desired_qty):
	for item_price in item_prices:
		if not item_price.packing_unit or flt(desired_qty) % flt(item_price.packing_unit) == 0:
			return [item_price]

	return []

def _get_item_price_query(
	pctx: ItemPriceCtx,
	item_codes: list[str],
	ignore_party=False,
	force_batch_no=False,
	match_uom=True,
):
	ip = frappe.qb.DocType("Item Price")
	query = frappe.qb.from_(ip).where((ip.item_code.isin(item_codes)) & (ip.price_list == pctx.price_list))
	if match_uom:
		query = query.where(IfNull(ip.uom, "").isin(["", pctx.uom]))

	if force_batch_no:
		query = query.where(ip.batch_no == pctx.batch_no)
	else:
		query = query.where(IfNull(ip.batch_no, "").isin(["", pctx.batch_no]))

	if not ignore_party:
		if pctx.customer:
			query = query.where(
				(ip.customer == pctx.customer)
				| ((IfNull(ip.customer, "") == "") & (IfNull(ip.supplier, "") == ""))
			)
		elif pctx.supplier:
			query = query.where(
				(ip.supplier == pctx.supplier)
				| ((IfNull(ip.customer, "") == "") & (IfNull(ip.supplier, "") == ""))
			)
		else:
			query = query.where((IfNull(ip.customer, "") == "") & (IfNull(ip.supplier, "") == ""))

	if pctx.transaction_date:
		query = query.where(
			(IfNull(ip.valid_from, "2000-01-01") <= pctx.transaction_date)
			& (IfNull(ip.valid_upto, "2500-12-31") >= pctx.transaction_date)
		)

	return query, ip

def _order_item_prices(query, ip, pctx):
	if pctx.customer:
		query = query.orderby(IfNull(ip.customer, ""), order=Order.desc)
	elif pctx.supplier:
		query = query.orderby(IfNull(ip.supplier, ""), order=Order.desc)

	return (
		query.orderby(IfNull(ip.batch_no, ""), order=Order.desc)
		.orderby(ip.valid_from, order=Order.desc)
		.orderby(ip.uom, order=Order.desc)
	)

def update_work_order_qty(self):
	"""Update **Manufactured Qty** and **Material Transferred for Qty** in Work Order
	based on Stock Entry"""

	if self.track_semi_finished_goods:
		return

	# Lock the plan row before any Work Order quantity update takes a row lock.
	self.set_process_loss_qty()
	overproduction_percentage = flt(
		frappe.db.get_single_value("Manufacturing Settings", "overproduction_percentage_for_work_order")
	)
	transfer_extra_percentage = flt(
		frappe.db.get_single_value("Manufacturing Settings", "transfer_extra_materials_percentage")
	)

	for purpose, fieldname in (
		("Manufacture", "produced_qty"),
		("Material Transfer for Manufacture", "material_transferred_for_manufacturing"),
		("Material Transfer for Manufacture", "additional_transferred_qty"),
	):
		if (
			purpose == "Material Transfer for Manufacture"
			and self.operations
			and self.transfer_material_against == "Job Card"
		):
			continue

		qty = self.get_transferred_or_manufactured_qty(purpose, fieldname)

		allowance_percentage = overproduction_percentage
		if purpose == "Material Transfer for Manufacture":
			allowance_percentage = transfer_extra_percentage or overproduction_percentage

		completed_qty = self.qty + (allowance_percentage / 100 * self.qty)
		qty_to_validate = qty + flt(self.process_loss_qty) if purpose == "Manufacture" else qty
		precision = self.precision(fieldname)
		if flt(qty_to_validate, precision) > flt(completed_qty, precision):
			frappe.throw(
				_("{0} ({1}) cannot be greater than planned quantity ({2}) in Work Order {3}").format(
					_("Manufactured Qty (including Process Loss)")
					if purpose == "Manufacture"
					else _(self.meta.get_label(fieldname)),
					flt(qty_to_validate, precision),
					completed_qty,
					self.name,
				),
				StockOverProductionError,
			)

		if purpose == "Manufacture":
			self.validate_produced_qty_covers_disassembly(qty, precision)

		self.db_set(fieldname, qty)
		if purpose == "Manufacture" and self.production_plan:
			ProductionPlanWorkOrderQuantities(self.production_plan).validate_work_order(
				self, process_loss_qty=self.process_loss_qty
			)

		from erpnext.selling.doctype.sales_order.sales_order import update_produced_qty_in_so_item

		if self.sales_order and self.sales_order_item and not self.production_plan_sub_assembly_item:
			update_produced_qty_in_so_item(self.sales_order, self.sales_order_item)

	if self.production_plan:
		self.set_produced_qty_for_sub_assembly_item()
		self.update_production_plan_status()

	if self.additional_transferred_qty:
		self.validate_additional_transferred_qty()

def validate_additional_transferred_qty(self):
	transfer_extra_materials_percentage = frappe.db.get_single_value(
		"Manufacturing Settings", "transfer_extra_materials_percentage"
	)

	allowed_qty = flt(self.qty) + flt(flt(self.qty) * flt(transfer_extra_materials_percentage) / 100)

	actual_qty = flt(self.material_transferred_for_manufacturing) + flt(self.additional_transferred_qty)

	precision = frappe.get_precision("Work Order", "qty")
	if flt(allowed_qty - actual_qty, precision) < 0:
		frappe.throw(
			_(
				"""Additional Transferred Qty {0}
				cannot be greater than {1}.
				To fix this, increase the percentage value
				of the field 'Transfer Extra Raw Materials to WIP'
				in Manufacturing Settings."""
			).format(actual_qty, allowed_qty),
		)

def validate_produced_qty_covers_disassembly(self, produced_qty, precision):
	if flt(produced_qty, precision) >= flt(self.disassembled_qty, precision):
		return

	frappe.throw(
		_(
			"Manufactured Qty ({0}) cannot be less than the Disassembled Qty ({1}) of Work Order {2}. Cancel the disassembly first."
		).format(flt(produced_qty, precision), flt(self.disassembled_qty, precision), self.name)
	)

def update_disassembled_qty(self, qty, is_cancel=False):
	precision = self.precision("disassembled_qty")
	if is_cancel:
		self.disassembled_qty = max(0, flt(self.disassembled_qty - qty, precision))
	else:
		if self.docstatus == 1:
			self.disassembled_qty = flt(self.disassembled_qty + qty, precision)

	if not is_cancel and self.disassembled_qty > self.produced_qty:
		frappe.throw(_("Cannot disassemble more than produced quantity."))

	self.db_set("disassembled_qty", self.disassembled_qty)

def get_transferred_or_manufactured_qty(self, purpose, fieldname):
	parent = frappe.qb.DocType("Stock Entry")

	query = frappe.qb.from_(parent).where(
		(parent.work_order == self.name)
		& (parent.docstatus == 1)
		& (parent.purpose == purpose)
		& (parent.is_additional_transfer_entry == cint(fieldname == "additional_transferred_qty"))
	)

	if purpose == "Manufacture":
		child = frappe.qb.DocType("Stock Entry Detail")
		query = (
			query.join(child)
			.on(parent.name == child.parent)
			.select(Sum(child.transfer_qty))
			.where(child.is_finished_item == 1)
		)
	else:
		query = query.select(Sum(parent.fg_completed_qty))

	return flt(query.run()[0][0])

def set_process_loss_qty(self):
	quantities = None
	if self.docstatus == 1 and self.production_plan:
		quantities = ProductionPlanWorkOrderQuantities(self.production_plan)
		quantities.lock_plan_row(self)

	process_loss_qty = self._process_loss_qty()
	if quantities:
		previous_loss_qty = frappe.db.get_value(
			"Work Order", self.name, "process_loss_qty", for_update=True
		)
		if process_loss_qty < flt(previous_loss_qty):
			# Replacement Work Orders may have consumed the recorded loss.
			quantities.validate_work_order(self, process_loss_qty=process_loss_qty)
	self.db_set("process_loss_qty", process_loss_qty)

def _process_loss_qty(self):
	if self.track_semi_finished_goods:
		return flt(sum(flt(row.process_loss_qty) for row in self.operations))

	table = frappe.qb.DocType("Stock Entry")
	process_loss_qty = (
		frappe.qb.from_(table)
		.select(Sum(table.process_loss_qty))
		.where(
			(table.work_order == self.name) & (table.purpose == "Manufacture") & (table.docstatus == 1)
		)
	).run()[0][0]

	return flt(process_loss_qty)

def set_qty_change(self):
	"""Excess received qty to move into this Work Order's reservation on submit."""
	if scio_item_name := self.get("subcontracting_inward_order_item"):
		self.qty_change = frappe._dict()

		data = frappe.get_all(
			"Subcontracting Inward Order Received Item",
			{"reference_name": scio_item_name, "docstatus": 1, "is_customer_provided_item": 1},
			["rm_item_code", "required_qty as bom_qty", "work_order_qty", "received_qty"],
		)
		for d in data:
			wo_item = next(
				(
					wo_item
					for wo_item in self.get("required_items")
					if wo_item.item_code == d.rm_item_code
				),
				None,
			)

			if wo_item and d.work_order_qty == d.bom_qty and d.received_qty > d.bom_qty:
				self.qty_change[wo_item.name] = d.received_qty - d.bom_qty

def update_planned_qty(self):
	if self.track_semi_finished_goods:
		return

	update_bin_qty(
		self.production_item,
		self.fg_warehouse,
		{"planned_qty": get_planned_qty(self.production_item, self.fg_warehouse)},
	)

	if self.material_request:
		mr_obj = frappe.get_doc("Material Request", self.material_request)
		mr_obj.update_requested_qty([self.material_request_item])

def update_ordered_qty(self):
	if self.production_plan and (self.production_plan_item or self.production_plan_sub_assembly_item):
		table = frappe.qb.DocType("Work Order")

		query = (
			frappe.qb.from_(table)
			.select(Sum(table.qty))
			.where((table.production_plan == self.production_plan) & (table.docstatus == 1))
		)

		if self.production_plan_item:
			query = query.where(table.production_plan_item == self.production_plan_item)
		elif self.production_plan_sub_assembly_item:
			query = query.where(
				table.production_plan_sub_assembly_item == self.production_plan_sub_assembly_item
			)

		query = query.run()
		qty = flt(query[0][0]) if query else 0

		if self.production_plan_item:
			frappe.db.set_value("Production Plan Item", self.production_plan_item, "ordered_qty", qty)
		elif self.production_plan_sub_assembly_item:
			frappe.db.set_value(
				"Production Plan Sub Assembly Item",
				self.production_plan_sub_assembly_item,
				"ordered_qty",
				qty,
			)

		doc = frappe.get_doc("Production Plan", self.production_plan)
		doc.flags.ignore_permissions = True
		doc.update_status_and_bin_qty()
		doc.update_bin_qty({d.item_code for d in self.required_items})

def get_work_order_qty_against_sales_order(self):
	wo = frappe.qb.DocType("Work Order")
	query = (
		frappe.qb.from_(wo)
		.select(Sum(qty_against_sales_order(wo, wo.qty)))
		.where((wo.sales_order == self.sales_order) & (wo.docstatus == 1))
	)
	if self.product_bundle_item:
		query = query.where(wo.product_bundle_item == self.product_bundle_item)
	else:
		query = query.where(
			(wo.production_item == self.production_item) & (wo.sales_order_item == self.sales_order_item)
		)

	return query.run(as_list=1)

def get_ordered_qty_of_plan_item(self):
	work_order = frappe.qb.DocType("Work Order")
	return flt(
		(
			frappe.qb.from_(work_order)
			.select(Sum(work_order.qty))
			.where(
				(work_order.production_plan_item == self.production_plan_item)
				& (work_order.docstatus == 1)
				& (work_order.status != "Closed")
			)
		).run()[0][0]
	)

def update_completed_qty_in_material_request(self):
	if self.material_request and self.material_request_item:
		frappe.get_doc("Material Request", self.material_request).update_completed_qty(
			[self.material_request_item]
		)

def validate_qty(self):
	if self.qty <= 0:
		frappe.throw(_("Quantity to Manufacture must be greater than 0."))

	if flt(self.batch_size) < 0:
		frappe.throw(_("Batch Size cannot be negative."))

	if (
		self.stock_uom
		and frappe.get_cached_value("UOM", self.stock_uom, "must_be_whole_number")
		and abs(cint(self.qty) - flt(self.qty, self.precision("qty"))) > 0.0000001
	):
		frappe.throw(
			_(
				"Qty To Manufacture ({0}) cannot be a fraction for the UOM {2}. To allow this, disable '{1}' in the UOM {2}."
			).format(
				flt(self.qty, self.precision("qty")),
				frappe.bold(_("Must be Whole Number")),
				frappe.bold(self.stock_uom),
			),
		)

	if self.subcontracting_inward_order and self.qty > self.max_producible_qty:
		frappe.msgprint(
			_(
				"Warning: Quantity exceeds maximum producible quantity based on quantity of raw materials received through the Subcontracting Inward Order {0}."
			).format(get_link_to_form("Subcontracting Inward Order", self.subcontracting_inward_order)),
			alert=True,
			indicator="orange",
		)

def update_reserved_qty_for_production(self, items=None):
	"""update reserved_qty_for_production in bins"""
	for d in self.required_items:
		if d.source_warehouse:
			stock_bin = get_bin(d.item_code, d.source_warehouse)
			stock_bin.update_reserved_qty_for_production()

def set_available_qty(self):
	for d in self.get("required_items"):
		if d.source_warehouse:
			d.available_qty_at_source_warehouse = get_latest_stock_qty(d.item_code, d.source_warehouse)

		if self.wip_warehouse:
			d.available_qty_at_wip_warehouse = get_latest_stock_qty(d.item_code, self.wip_warehouse)

def update_transferred_qty_for_required_items(self):
	if self.skip_transfer:
		return

	transferred_by_key = self._material_transfer_qty_by_item_warehouse_and_operation()
	transferred_items = frappe._dict()
	for (item_code, _warehouse, _operation_row_id, _operation), qty in transferred_by_key.items():
		transferred_items[item_code] = flt(transferred_items.get(item_code)) + qty

	row_wise_serial_batch = frappe._dict({})
	if self.reserve_stock:
		row_wise_serial_batch = get_row_wise_serial_batch(self.name)

	transferred_by_row = distribute_transfers_over_rows(self.required_items, transferred_by_key)
	for row in self.required_items:
		transferred_qty = transferred_by_row[row.name]
		row.db_set("transferred_qty", transferred_qty, update_modified=False)
		if self.reserve_stock:
			self.update_qty_in_stock_reservation(row, transferred_qty, row_wise_serial_batch)

	self.recompute_material_transferred_for_manufacturing(transferred_items)

def update_returned_qty(self):
	returned_by_row = distribute_over_rows(
		self.required_items, self._material_transfer_qty_by_item(is_return=1)
	)
	for row in self.required_items:
		row.db_set("returned_qty", returned_by_row[row.name], update_modified=False)

def validate_reserved_qty(self):
	sre_details = get_sre_details(self.name)
	for item in self.required_items:
		if details := sre_details.get(item.name):
			if details.reserved_qty < details.consumed_qty:
				frappe.throw(
					_("Consumed Qty cannot be greater than Reserved Qty for item {0}").format(
						details.consumed_qty, details.reserved_qty, item.item_code
					)
				)

def set_reserved_qty_for_wip_and_fg(self, stock_entry):
	if stock_entry.is_return:
		return

	items = frappe._dict()

	stock_entry.reload()
	if stock_entry.purpose == "Manufacture" and (
		self.sales_order
		or self.production_plan_sub_assembly_item
		or self.subcontracting_inward_order
		or stock_entry.job_card
	):
		items = self.get_finished_goods_for_reservation(stock_entry)
	elif stock_entry.purpose == "Material Transfer for Manufacture":
		items = self.get_list_of_materials_for_reservation(stock_entry)

	if not items:
		return

	item_list = list(items.values())
	reserve_stock_for_work_order(self, item_list, is_transfer=False, notify=True)

def cancel_reserved_qty_for_wip_and_fg(self, ste_doc):
	for row in ste_doc.items:
		sre_list = frappe.get_all(
			"Stock Reservation Entry",
			filters={
				"from_voucher_no": ste_doc.name,
				"from_voucher_detail_no": row.name,
				"docstatus": 1,
			},
			pluck="name",
		)

		if sre_list:
			unreserve_stock_for_work_order(self, sre_list)

def _subcontract_transferred_qty_by_item(self):
	"""Qty sent to subcontractors for this Work Order, keyed by (item_code, source warehouse).

	The transfer Stock Entries are linked to the Work Order through its subcontracted Job Cards
	(Job Card -> Subcontracting Order / Purchase Order -> Send to Subcontractor entry), since the
	entry itself does not retain ``work_order``. Only submitted (docstatus 1) entries contribute,
	so a cancelled transfer drops out and the reservation is restored on the next recompute.
	"""
	job_cards = frappe.get_all(
		"Job Card", filters={"work_order": self.name, "is_subcontracted": 1}, pluck="name"
	)
	if not job_cards:
		return {}

	sco_names = frappe.get_all(
		"Subcontracting Order Item", filters={"job_card": ["in", job_cards]}, pluck="parent"
	)
	po_names = frappe.get_all(
		"Purchase Order Item", filters={"job_card": ["in", job_cards]}, pluck="parent"
	)
	if not sco_names and not po_names:
		return {}

	ste = frappe.qb.DocType("Stock Entry")
	ste_child = frappe.qb.DocType("Stock Entry Detail")

	link = None
	if sco_names:
		link = ste.subcontracting_order.isin(list(set(sco_names)))
	if po_names:
		po_link = ste.purchase_order.isin(list(set(po_names)))
		link = po_link if link is None else (link | po_link)

	rows = (
		frappe.qb.from_(ste)
		.inner_join(ste_child)
		.on(ste_child.parent == ste.name)
		.select(ste_child.item_code, ste_child.s_warehouse, fn.Sum(ste_child.transfer_qty).as_("qty"))
		.where(
			(ste.docstatus == 1)
			& (ste.purpose == "Send to Subcontractor")
			& (ste_child.s_warehouse.isnotnull())
			& link
		)
		.groupby(ste_child.item_code, ste_child.s_warehouse)
	).run(as_dict=1)
	return {(d.item_code, d.s_warehouse): flt(d.qty) for d in rows}

def get_disassembly_available_qty(stock_entry_name: str, current_se_name: str | None = None) -> float:
	frappe.has_permission("Stock Entry", "read", doc=stock_entry_name, throw=True)
	se = frappe.db.get_value("Stock Entry", stock_entry_name, ["fg_completed_qty"], as_dict=True)
	if not se:
		return 0.0

	filters = {
		"source_stock_entry": stock_entry_name,
		"purpose": "Disassemble",
		"docstatus": 1,
	}

	if current_se_name:
		filters["name"] = ("!=", current_se_name)

	already_disassembled = flt(frappe.db.get_value("Stock Entry", filters, [{"SUM": "fg_completed_qty"}]))

	return flt(
		flt(se.fg_completed_qty) - already_disassembled,
		frappe.get_precision("Stock Entry", "fg_completed_qty"),
	)

def split_qty_based_on_batch_size(wo_doc, row, qty):
	if not cint(frappe.db.get_value("Operation", row.operation, "create_job_card_based_on_batch_size")):
		row.batch_size = row.get("qty") or wo_doc.qty

	row.job_card_qty = row.batch_size
	if row.batch_size and qty >= row.batch_size:
		qty -= row.batch_size
	elif qty > 0:
		row.job_card_qty = qty
		qty = 0

	get_serial_nos_for_job_card(row, wo_doc)

	return qty

def recompute_material_transferred_for_manufacturing(self, transferred_items):
	"""Set material_transferred_for_manufacturing based on actual item-level transfers, not fg_completed_qty."""
	# Job Card transfers use the minimum completed quantity across operations.
	if self.operations and self.transfer_material_against == "Job Card":
		return

	# When fg_completed_qty > 0 (direct stock entries, excess transfer), preserve the
	# SUM(fg_completed_qty) approach so excess-transfer tracking works correctly.
	sum_fg_completed_qty = self.get_transferred_or_manufactured_qty(
		"Material Transfer for Manufacture", "material_transferred_for_manufacturing"
	)
	if sum_fg_completed_qty:
		self.db_set("material_transferred_for_manufacturing", sum_fg_completed_qty)
		return

	# Pick list flow sets fg_completed_qty=0; use min-fraction of actual item transfers
	# so partial availability does not prematurely mark the work order as fully transferred.
	required_by_item = {}
	for row in self.required_items:
		if not row.include_item_in_manufacturing or flt(row.required_qty) <= 0:
			continue
		required_by_item[row.item_code] = required_by_item.get(row.item_code, 0.0) + flt(row.required_qty)

	if not required_by_item:
		return

	min_fraction = min(
		flt(transferred_items.get(item_code) or 0) / required_qty
		for item_code, required_qty in required_by_item.items()
	)
	min_fraction = min(min_fraction, 1.0)
	material_transferred = min_fraction * flt(self.qty)
	self.db_set("material_transferred_for_manufacturing", material_transferred)

def distribute_transfers_over_rows(rows, qty_by_item_warehouse_and_operation):
	"""Split each transfer over the rows of its item, keeping a Job Card's transfer on its operation."""
	rows_by_item = {}
	for row in rows:
		rows_by_item.setdefault(row.item_code, []).append(row)

	qty_by_row = {row.name: 0.0 for row in rows}
	for key, qty in qty_by_item_warehouse_and_operation.items():
		item_code, warehouse, operation_row_id, operation = key
		item_rows = rows_by_item.get(item_code)
		if not item_rows:
			continue

		if operation:
			job_card_operation = frappe._dict(operation_row_id=operation_row_id, operation=operation)
			item_rows = [
				row for row in item_rows if is_row_of_operation(row, job_card_operation)
			] or item_rows

		share_by_row = {}
		matching_rows = [row for row in item_rows if row.source_warehouse == warehouse] or item_rows
		split_item_qty(matching_rows, flt(qty), share_by_row)
		for name, share in share_by_row.items():
			qty_by_row[name] += share

	return qty_by_row

def get_row_wise_serial_batch(work_order, purpose=None):
	if not purpose:
		purpose = "Material Transfer for Manufacture"

	purposes = [purpose] if isinstance(purpose, str) else purpose
	stock_entries = frappe.get_all(
		"Stock Entry",
		filters={
			"work_order": work_order,
			"purpose": ("in", purposes),
			"docstatus": 1,
		},
		pluck="name",
	)

	serial_batch_entries = frappe.get_all(
		"Serial and Batch Bundle",
		fields=[
			"`tabSerial and Batch Entry`.`serial_no`",
			"`tabSerial and Batch Entry`.`batch_no`",
			"`tabSerial and Batch Entry`.`qty`",
			"`tabSerial and Batch Bundle`.`warehouse`",
			"`tabSerial and Batch Bundle`.`item_code`",
			"`tabSerial and Batch Bundle`.`voucher_detail_no`",
		],
		filters=[
			["Serial and Batch Bundle", "voucher_type", "=", "Stock Entry"],
			["Serial and Batch Bundle", "voucher_no", "in", stock_entries],
			["Serial and Batch Bundle", "voucher_detail_no", "is", "set"],
			["Serial and Batch Bundle", "docstatus", "<", 2],
			["Serial and Batch Bundle", "is_cancelled", "=", 0],
			["Serial and Batch Entry", "qty", "<", 0],
		],
	)

	row_wise_serial_batch = {}
	for entry in serial_batch_entries:
		key = (entry.item_code, entry.warehouse)
		if key not in row_wise_serial_batch:
			row_wise_serial_batch[key] = frappe._dict(
				{
					"serial_nos": [],
					"batch_nos": defaultdict(float),
				}
			)

		details = row_wise_serial_batch[key]
		if entry.serial_no:
			details.serial_nos.append(entry.serial_no)
		if entry.batch_no:
			details.batch_nos[entry.batch_no] += abs(entry.qty)

	return row_wise_serial_batch

def distribute_over_rows(rows, qty_by_item):
	rows_by_item = {}
	for row in rows:
		rows_by_item.setdefault(row.item_code, []).append(row)

	qty_by_row = {}
	for item_code, item_rows in rows_by_item.items():
		split_item_qty(item_rows, flt(qty_by_item.get(item_code)), qty_by_row)
	return qty_by_row

def reserve_stock_for_work_order(doc, items=None, is_transfer=True, notify=False):
	"""Reserve stock for a Work Order. Internal: no permission check, because the Work Order and
	Stock Entry lifecycles reach it for a user who need not hold Work Order write. The cancelled and
	closed branches unreserve, so the whitelisted entry point above needs the same right as the
	cancel sibling.
	"""
	is_transfer = cint(is_transfer)
	if items and isinstance(items, str):
		items = parse_json(items)

	sre = StockReservation(doc, items=items, notify=notify)
	if doc.docstatus == 2 or doc.status == "Closed":
		sre.cancel_stock_reservation_entries()
	elif doc.docstatus == 1:
		if doc.production_plan and is_transfer:
			sre.transfer_reservation_entries_to(
				doc.production_plan, from_doctype="Production Plan", to_doctype="Work Order"
			)
		elif doc.subcontracting_inward_order and is_transfer:
			doc.set_qty_change()
			sre.transfer_reservation_entries_to(
				doc.subcontracting_inward_order,
				from_doctype="Subcontracting Inward Order",
				to_doctype="Work Order",
				against_fg_item=doc.subcontracting_inward_order_item,
				qty_change=doc.get("qty_change"),
			)
		else:
			sre_created = sre.make_stock_reservation_entries()
			if sre_created:
				frappe.msgprint(_("Stock Reservation Entries Created"), alert=True)

	doc.reload()
	doc.db_set("status", doc.get_status())

def update_status(self, status=None):
	"""Update status of work order if unknown"""
	if self.docstatus == 1:
		# Refresh material_transferred_for_manufacturing before deciding status so pick-list-
		# driven transfers (where this qty is derived from item transfers, not fg_completed_qty)
		# are reflected immediately, instead of only after the next status update call.
		self.refresh_material_transferred_for_manufacturing()

	if self.status != "Closed":
		if status not in ["Stopped", "Closed"]:
			status = self.get_status(status)

		if status != self.status:
			self.db_set("status", status)

	self.update_required_items()

	return status or self.status

def get_serial_nos_for_job_card(row, wo_doc):
	if not wo_doc.has_serial_no:
		return

	serial_nos = get_serial_nos_for_work_order(wo_doc.name, wo_doc.production_item)
	used_serial_nos = []
	for d in frappe.get_all(
		"Job Card",
		fields=["serial_no"],
		filters={"docstatus": ("<", 2), "work_order": wo_doc.name, "operation_id": row.name},
	):
		used_serial_nos.extend(get_serial_nos(d.serial_no))

	serial_nos = sorted(list(set(serial_nos) - set(used_serial_nos)))
	row.serial_no = "\n".join(serial_nos[0 : cint(row.job_card_qty)])

def _earlier_operation_making_item(wo, wo_item):
	"""An earlier operation of the Work Order that makes the row's item for the operation using it."""
	operation = frappe.qb.DocType("Work Order Operation")
	return (
		frappe.qb.from_(operation)
		.select(operation.name)
		.where(
			(operation.parent == wo.name)
			& (operation.finished_good == wo_item.item_code)
			& (operation.idx < wo_item.operation_row_id)
		)
	)

def is_row_of_operation(row, operation):
	"""Whether a required item row belongs to a Job Card's operation."""
	if cint(row.operation_row_id) and cint(operation.operation_row_id):
		return cint(row.operation_row_id) == cint(operation.operation_row_id)

	return not row.operation or row.operation == operation.operation

def get_status(self, status=None):
	"""Return the status based on stock entries against this work order"""
	if not status:
		status = self.status

	if self.docstatus == 1 and status == "Closed":
		return status

	if self.docstatus == 0:
		status = "Draft"
	elif self.docstatus == 1:
		if status not in ["Closed", "Stopped"]:
			status = "Not Started"
			if flt(self.material_transferred_for_manufacturing) > 0 or self._has_transferred_material():
				status = "In Process"

			precision = frappe.get_precision("Work Order", "produced_qty")
			total_qty = flt(self.produced_qty, precision) + flt(self.process_loss_qty, precision)
			if flt(total_qty, precision) >= flt(self.qty, precision):
				status = "Completed"
	else:
		status = "Cancelled"

	if self.skip_transfer and self.produced_qty:
		precision = frappe.get_precision("Work Order", "produced_qty")
		total_qty = flt(self.produced_qty, precision) + flt(self.process_loss_qty, precision)
		if flt(self.qty, precision) > flt(total_qty, precision):
			status = "In Process"

	if status != "Completed":
		if not all(d.status == "Pending" for d in self.operations):
			status = "In Process"

	if status == "Not Started" and self.reserve_stock:
		if any(row.stock_reserved_qty for row in self.required_items):
			if any(row.stock_reserved_qty < row.required_qty for row in self.required_items):
				status = "Stock Partially Reserved"
			else:
				status = "Stock Reserved"

	return status

def get_serial_nos_for_work_order(work_order, production_item):
	serial_nos = []
	for d in frappe.get_all(
		"Serial No",
		fields=["name"],
		filters={
			"work_order": work_order,
			"item_code": production_item,
		},
	):
		serial_nos.append(d.name)

	return serial_nos

def update_subcontracting_inward_order_received_items(self):
	"""Recompute the qty of each raw material allocated to Work Orders on the inward order."""
	if not (scio_item_name := self.get("subcontracting_inward_order_item")):
		return

	scio_rm_data = frappe.get_all(
		"Subcontracting Inward Order Received Item",
		filters={
			"reference_name": scio_item_name,
			"docstatus": 1,
			"rm_item_code": ["in", [d.item_code for d in self.get("required_items")]],
		},
		fields=["name", "rm_item_code"],
	)
	if not scio_rm_data:
		return

	allocated_qty = get_work_order_allocated_qty(scio_item_name, [d.rm_item_code for d in scio_rm_data])
	table = frappe.qb.DocType("Subcontracting Inward Order Received Item")
	case_expr = Case()
	for item in scio_rm_data:
		case_expr = case_expr.when(
			table.rm_item_code == item.rm_item_code, flt(allocated_qty.get(item.rm_item_code))
		)

	frappe.qb.update(table).set(table.work_order_qty, case_expr).where(
		(table.name.isin([d.name for d in scio_rm_data])) & (table.docstatus == 1)
	).run()

def default_get(self, fields):
    res = super().default_get(fields)
    if not res.get('name') and res.get('company_id'):
        res['name'] = self.env._('Working Hours of %s', self.env['res.company'].browse(res['company_id']).name)
    return res

def copy_data(self, default=None):
    vals_list = super().copy_data(default=default)
    for calendar, vals in zip(self, vals_list):
        # the rates of a fixed calendar are computed from its attendances, those of the other
        # calendars are set by the user: they are kept on the copy
        if vals.get('calendar_type', calendar.calendar_type) != 'fixed':
            vals.setdefault('days_per_week', calendar.days_per_week)
            vals.setdefault('hours_per_week', calendar.hours_per_week)
    return vals_list

def _get_attendances_to_unlink(self, next_calendar_type=None):
    """ Return the attendances that do not fit the calendar's ``calendar_type`` (or
    ``next_calendar_type`` when given), and must be dropped:

    - ``fixed``: attendances with a date (fixed calendars use undated weekly lines);
    - ``undefined``: every attendance (flexible calendars have no predefined slots);
    - ``variable``: attendances without a date (variable calendars use dated lines).

    Called after every ``create``/``write`` of calendars.

    :rtype: ``resource.calendar.attendance`` recordset
    """
    def to_unlink(attendance):
        calendar_type = next_calendar_type or attendance.calendar_id.calendar_type
        if calendar_type == 'undefined':
            return True
        return bool(attendance.date) if calendar_type == 'fixed' else not attendance.date
    return self.attendance_ids.filtered(to_unlink)

def _convert_single_occurrence_recurrencies(self):
    """Convert recurrent attendances with only one visible occurrence into ad-hoc attendances."""
    def _has_single_remaining_occurrence(att):
        if not att.recurrency or not att.date or att.recurrency_end_type == 'forever':
            return False
        excluded = set(att.recurrency_excluded_occurences or [])
        delta = timedelta(**{att.recurrency_type: att.recurrency_interval})
        current = att.date + delta
        while current <= att.recurrency_until:
            if fields.Date.to_string(current) not in excluded:
                return False
            current += delta
        return True

    single_occurrence = self.attendance_ids.filtered(_has_single_remaining_occurrence)
    single_occurrence.write({'recurrency': False, 'recurrency_excluded_occurences': False})

def _clean_excluded_occurrences(self):
    """Remove stale or duplicate entries from ``recurrency_excluded_occurences``.

    Removes dates before the attendance start, dates past ``recurrency_until``,
    dates that don't fall on a valid recurrency occurrence, and duplicates —
    in a single pass per attendance.
    """
    for att in self.attendance_ids.filtered(lambda a: a.recurrency and a.recurrency_excluded_occurences and a.date):
        date_str = fields.Date.to_string(att.date)
        until_str = fields.Date.to_string(att.recurrency_until) if att.recurrency_end_type != 'forever' else None
        seen = set()
        cleaned = []
        for d in att.recurrency_excluded_occurences:
            if d < date_str or (until_str and d > until_str) or d in seen:
                continue
            diff_days = (fields.Date.from_string(d) - att.date).days
            if att.recurrency_type == 'days' and diff_days % att.recurrency_interval:
                continue
            if att.recurrency_type == 'weeks' and (diff_days % 7 or (diff_days // 7) % att.recurrency_interval):
                continue
            seen.add(d)
            cleaned.append(d)
        if cleaned != att.recurrency_excluded_occurences:
            att.recurrency_excluded_occurences = cleaned

def _compute_full_time_required_hours(self):
    for calendar in self:
        if calendar.reference_calendar_id:
            calendar.full_time_required_hours = calendar.reference_calendar_id.hours_per_week
        elif calendar.company_id.resource_calendar_id:
            calendar.full_time_required_hours = calendar.company_id.resource_calendar_id.hours_per_week
        else:
            calendar.full_time_required_hours = calendar.hours_per_week

def _compute_attendance_ids(self):
    for calendar in self:
        calendar_changed = calendar._origin and calendar._origin.company_id != calendar.company_id
        if (not calendar.id or calendar_changed) and calendar.calendar_type == "fixed" and not calendar.attendance_ids:
            calendar.attendance_ids = calendar._get_default_attendance_ids(calendar.company_id)

def _compute_global_leave_ids(self):
    for calendar in self.filtered(lambda c: not c._origin or c._origin.company_id != c.company_id):
        calendar.update({
            'global_leave_ids': [(5, 0, 0)] + [
                (0, 0, leave._copy_leave_vals()) for leave in calendar.company_id.resource_calendar_id.global_leave_ids],
        })

def _compute_days_per_week(self):
    for calendar in self:
        # variable/undefined calendars don't have a reliable attendance pattern to derive
        # this from (undefined calendars have none at all); the user sets it directly instead.
        if calendar.calendar_type != 'fixed':
            continue
        attendances = calendar.attendance_ids.filtered(lambda a: a._is_work_period())
        calendar.days_per_week = len(set(attendances.mapped('dayofweek')))

def _compute_hours_per_day(self):
    for calendar in self:
        calendar.hours_per_day = calendar.hours_per_week / calendar.days_per_week if calendar.days_per_week else 0

def _compute_hours_per_week(self):
    """ Compute the average hours per week """
    for calendar in self:
        # see _compute_days_per_week: variable/undefined calendars are set directly by the user
        if calendar.calendar_type != 'fixed':
            continue
        attendances = calendar.attendance_ids.filtered(lambda a: a._is_work_period())
        calendar.hours_per_week = sum(attendances.mapped('duration_hours'))

def _verify_hours(self):
    for calendar in self:
        # fixed calendars derive these from their attendance lines, always valid by construction
        if calendar.calendar_type == 'fixed':
            continue
        if calendar.hours_per_week < 0 or calendar.hours_per_week > 168:
            raise ValidationError(self.env._("Hours per week must be between 0 and 168."))
        if calendar.hours_per_day < 0 or calendar.hours_per_day > 24:
            raise ValidationError(self.env._("Average hours per day must be between 0 and 24."))

def _compute_is_fulltime(self):
    for calendar in self:
        calendar.is_fulltime = float_compare(calendar.full_time_required_hours, calendar.hours_per_week, 3) == 0

def _compute_work_time_rate(self):
    for calendar in self:
        if calendar.full_time_required_hours:
            calendar.work_time_rate = calendar.hours_per_week / calendar.full_time_required_hours
        else:
            calendar.work_time_rate = 1.0

def _unavailable_intervals(self, start_dt, end_dt, resource=None, domain=None, tz=None):
    """ Single-resource shortcut of :meth:`_unavailable_intervals_batch`.

    :param resource: a ``resource.resource`` record, or ``None`` / empty for the
        calendar-level result
    :param tz: unused, kept for compatibility
    :return: ``Intervals`` in UTC, empty for a flexible resource without leave
    """
    if resource is None:
        resource = self.env['resource.resource']
    resources_per_tz = resource._get_resources_per_tz()
    return self._unavailable_intervals_batch(
        start_dt, end_dt, resources_per_tz=resources_per_tz, domain=domain,
    ).get(resource.id, Intervals())

def _get_default_attendance_ids(self, company_id=None):
    """ Return ``attendance_ids`` commands copying the attendances of the company's fixed
    calendar, or, by default, 5 duration-based days of 8 hours (Monday to Friday).

    :param company_id: ``res.company`` record, or ``None``
    :rtype: list
    """
    if company_id and company_id.resource_calendar_id.calendar_type == "fixed" and (attendances := company_id.resource_calendar_id.attendance_ids):
        return [Command.clear()] + [Command.create(attendance) for attendance in attendances._to_dict()]
    return [Command.clear()] + [
        Command.create({'dayofweek': str(dayofweek), 'duration_hours': 8, 'hour_from': 0, 'hour_to': 0})
        for dayofweek in range(5)
    ]

def plan_days(self, days, day_dt, compute_leaves=False, domain=None):
    """ Return the end of the first work interval of the ``days``-th work day counted
    from ``day_dt`` (the day of ``day_dt`` included if it has work time after
    ``day_dt``), or, for a negative ``days``, the start of the last work interval of the
    ``abs(days)``-th work day counted backwards. ``days=0`` returns ``day_dt``.

    Beware: with several attendances per day (e.g. a lunch break), the result is the end
    of the morning attendance of the last day, not the end of that day.

    Calendar-level only (no resource, only global leaves), computed in the company
    timezone by windows of 14 days, for at most 100 windows.

    :param int days: number of work days to plan, negative to plan backwards
    :param datetime day_dt: starting point; naive means UTC
    :param bool compute_leaves: deduct global leaves
    :param list domain: leave domain, see :meth:`_leave_intervals_batch`
    :return: the resulting datetime, in the timezone of ``day_dt`` (naive UTC if
        ``day_dt`` is naive), or ``False`` if not found within the search range
    :rtype: datetime | bool
    """
    revert = to_timezone(day_dt.tzinfo)
    day_dt = day_dt.astimezone(ZoneInfo(self.env.company.tz))

    # which method to use for retrieving intervals
    if compute_leaves:
        get_intervals = partial(self._work_intervals_batch, domain=domain)
    else:
        get_intervals = self._attendance_intervals_batch

    if days > 0:
        found = set()
        delta = timedelta(days=14)
        for n in range(100):
            dt = day_dt + delta * n
            for start, stop, _meta in get_intervals(dt, dt + delta)[False]:
                found.add(start.date())
                if len(found) == days:
                    return revert(stop)
        return False

    if days < 0:
        days = abs(days)
        found = set()
        delta = timedelta(days=14)
        for n in range(100):
            dt = day_dt - delta * n
            for start, _stop, _meta in reversed(get_intervals(dt - delta, dt)[False]):
                found.add(start.date())
                if len(found) == days:
                    return revert(start)
        return False

    return revert(day_dt)

def set_duration(self, now):
    if self.duration is None:
        self.duration = now - self.last_modified_at

protected MachineTimeSlot getFurthestAvailableMachineTimeSlot(
    Machine machine,
    OperationOrder operationOrder,
    long initialDuration,
    LocalDateTime plannedStartDateT,
    LocalDateTime plannedEndDateT,
    int loopNb)
    throws AxelorException {

  if (loopNb >= MAX_RECURSIVE_CALL) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        ProductionExceptionMessage.TOO_MANY_CALL_GETTING_TIME_SLOT,
        operationOrder.getName());
  }
  long timeBeforeNextOperation =
      Optional.ofNullable(operationOrder.getWorkCenter())
          .map(WorkCenter::getTimeBeforeNextOperation)
          .orElse(0l);
  // Must check if dates are occupied by other operation orders
  // The first one of the list will be the first to start
  List<OperationOrder> concurrentOperationOrders =
      operationOrderRepository
          .all()
          .filter(
              "self.machine = :machine"
                  + " AND ((self.plannedStartDateT <= :startDate AND self.plannedEndDateT > :startDateWithTime)"
                  + " OR (self.plannedStartDateT < :endDate AND self.plannedEndDateT > :endDateWithTime)"
                  + " OR (self.plannedStartDateT >= :startDate AND self.plannedEndDateT <= :endDateWithTime))"
                  + " AND (self.manufOrder.statusSelect != :cancelled AND self.manufOrder.statusSelect != :finished)"
                  + " AND self.id != :operationOrderId"
                  + " AND self.outsourcing = false")
          .bind("startDate", plannedStartDateT)
          .bind("endDate", plannedEndDateT)
          .bind("startDateWithTime", plannedStartDateT.minusSeconds(timeBeforeNextOperation))
          .bind("endDateWithTime", plannedEndDateT.minusSeconds(timeBeforeNextOperation))
          .bind("machine", machine)
          .bind("cancelled", ManufOrderRepository.STATUS_CANCELED)
          .bind("finished", ManufOrderRepository.STATUS_FINISHED)
          .bind("operationOrderId", operationOrder.getId())
          .order("plannedStartDateT")
          .fetch();

  if (concurrentOperationOrders.isEmpty()) {
    return new MachineTimeSlot(plannedStartDateT, plannedEndDateT);
  } else {
    OperationOrder firstOperationOrder = concurrentOperationOrders.get(0);

    // Can not compute next slot with concurrency if these values are 0
    if (timeBeforeNextOperation == 0 && initialDuration == 0) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          I18n.get(
              ProductionExceptionMessage.MANUF_ORDER_CANT_COMPUTE_NEXT_SLOT_WITH_CURRENT_CONFIG),
          operationOrder.getName());
    }

    return getFurthestAvailableTimeSlotFrom(
        machine,
        firstOperationOrder
            .getPlannedStartDateT()
            .minusSeconds(initialDuration + timeBeforeNextOperation),
        firstOperationOrder.getPlannedStartDateT().minusSeconds(timeBeforeNextOperation),
        operationOrder,
        initialDuration,
        false,
        loopNb + 1);
  }
}

@SuppressWarnings("unchecked")
protected MachineTimeSlot getFurthestAvailableTimeSlotFrom(
    Machine machine,
    LocalDateTime startDateT,
    LocalDateTime endDateT,
    OperationOrder operationOrder,
    long initialDuration,
    boolean ignoreConcurrency,
    int loopNb)
    throws AxelorException {

  EventsPlanning planning = machine.getPublicHolidayEventsPlanning();

  if (planning != null
      && planning.getEventsPlanningLineList() != null
      && planning.getEventsPlanningLineList().stream()
          .anyMatch(epl -> epl.getDate().equals(endDateT.toLocalDate()))) {

    // If endDate is not available because of planning
    // Then we try for the previous day
    LocalDateTime previousDayDateT = endDateT.plusDays(1).with(LocalTime.MIN);

    return getFurthestAvailableTimeSlotFrom(
        machine,
        previousDayDateT.minusSeconds(initialDuration),
        previousDayDateT,
        operationOrder,
        initialDuration,
        ignoreConcurrency,
        loopNb);
  }

  LocalDateTime plannedStartDateT = null;
  LocalDateTime plannedEndDateT = null;

  if (machine.getWeeklyPlanning() != null) {
    // Planning on date at endDateT
    DayPlanning dayPlanning =
        findDayPlanningOrClosed(machine.getWeeklyPlanning(), endDateT.toLocalDate());
    Optional<LocalDateTime> allowedEndDateTPeriodAt =
        dayPlanningService.getAllowedEndDateTPeriodAt(dayPlanning, endDateT);

    if (allowedEndDateTPeriodAt.isEmpty()) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
          I18n.get(ProductionExceptionMessage.OPERATION_ORDER_NO_PERIOD_FOUND_FOR_PLAN_DATES),
          operationOrder.getName());
    }

    plannedEndDateT = allowedEndDateTPeriodAt.get();
    plannedStartDateT = plannedEndDateT.minusSeconds(initialDuration);

    // Must start in an existing period. The start date may have jumped onto a
    // different calendar day than endDateT, so its DayPlanning must be looked
    // up again instead of reusing the one resolved for endDateT.
    plannedStartDateT =
        dayPlanningService
            .getAllowedEndDateTPeriodAt(
                findDayPlanningOrClosed(
                    machine.getWeeklyPlanning(), plannedStartDateT.toLocalDate()),
                plannedStartDateT)
            .get();
    // Void duration is time when machine is not used (not in any period)

    long remainingTime = 0l;
    int counter = 0;
    do {

      long voidDuration =
          dayPlanningService.computeVoidDurationBetween(
              dayPlanning, plannedStartDateT, plannedEndDateT);

      remainingTime =
          initialDuration
              - DurationHelper.getSecondsDuration(
                  Duration.between(plannedStartDateT, plannedEndDateT)
                      .minusSeconds(voidDuration));
      // So the time 'spent' must be reported
      plannedStartDateT = plannedStartDateT.minusSeconds(remainingTime);

      // And of course it must start also in an existing period, resolved for its own day.
      plannedStartDateT =
          dayPlanningService
              .getAllowedEndDateTPeriodAt(
                  findDayPlanningOrClosed(
                      machine.getWeeklyPlanning(), plannedStartDateT.toLocalDate()),
                  plannedStartDateT)
              .get();

      counter++;
    } while (remainingTime > 0 && counter < MAX_LOOP_CALL);

    if (counter == MAX_LOOP_CALL) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          ProductionExceptionMessage.TOO_MANY_CALL_GETTING_START_DATE);
    }

  } else {
    // The machine does not have weekly planning so dates are ok for now.
    plannedStartDateT = startDateT;
    plannedEndDateT = endDateT;
  }

  if (ignoreConcurrency) {
    return new MachineTimeSlot(plannedStartDateT, plannedEndDateT);
  }
  return getFurthestAvailableMachineTimeSlot(
      machine, operationOrder, initialDuration, plannedStartDateT, plannedEndDateT, loopNb);
}

@Override
public MachineTimeSlot getFurthestTimeSlotFrom(
    Machine machine,
    LocalDateTime startDateT,
    LocalDateTime endDateT,
    OperationOrder operationOrder)
    throws AxelorException {

  return getFurthestAvailableTimeSlotFrom(
      machine,
      startDateT,
      endDateT,
      operationOrder,
      DurationHelper.getSecondsDuration(Duration.between(startDateT, endDateT)),
      true,
      0);
}

@Override
public MachineTimeSlot getFurthestAvailableTimeSlotFrom(
    Machine machine,
    LocalDateTime startDateT,
    LocalDateTime endDateT,
    OperationOrder operationOrder)
    throws AxelorException {

  return getFurthestAvailableTimeSlotFrom(
      machine,
      startDateT,
      endDateT,
      operationOrder,
      DurationHelper.getSecondsDuration(Duration.between(startDateT, endDateT)),
      false,
      0);
}

protected MachineTimeSlot getClosestAvailableMachineTimeSlot(
    Machine machine,
    OperationOrder operationOrder,
    long initialDuration,
    LocalDateTime plannedStartDateT,
    LocalDateTime plannedEndDateT,
    int loopNb)
    throws AxelorException {
  long timeBeforeNextOperation =
      Optional.ofNullable(operationOrder.getWorkCenter())
          .map(WorkCenter::getTimeBeforeNextOperation)
          .orElse(0l);
  // Must check if dates are occupied by other operation orders
  // The first one of the list will be the last to finish

  if (loopNb >= MAX_RECURSIVE_CALL) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        ProductionExceptionMessage.TOO_MANY_CALL_GETTING_TIME_SLOT,
        operationOrder.getName());
  }

  List<OperationOrder> concurrentOperationOrders =
      operationOrderRepository
          .all()
          .filter(
              "self.machine = :machine"
                  + " AND ((self.plannedStartDateT <= :startDate AND self.plannedEndDateT > :startDateWithTime)"
                  + " OR (self.plannedStartDateT <= :endDate AND self.plannedEndDateT > :endDateWithTime)"
                  + " OR (self.plannedStartDateT >= :startDate AND self.plannedEndDateT <= :endDateWithTime))"
                  + " AND (self.manufOrder.statusSelect != :cancelled AND self.manufOrder.statusSelect != :finished)"
                  + " AND self.id != :operationOrderId"
                  + " AND self.outsourcing = false")
          .bind("startDate", plannedStartDateT)
          .bind("endDate", plannedEndDateT)
          .bind("startDateWithTime", plannedStartDateT.minusSeconds(timeBeforeNextOperation))
          .bind("endDateWithTime", plannedEndDateT.minusSeconds(timeBeforeNextOperation))
          .bind("machine", machine)
          .bind("cancelled", ManufOrderRepository.STATUS_CANCELED)
          .bind("finished", ManufOrderRepository.STATUS_FINISHED)
          .bind("operationOrderId", operationOrder.getId())
          .order("-plannedEndDateT")
          .fetch();

  if (concurrentOperationOrders.isEmpty()) {
    return new MachineTimeSlot(plannedStartDateT, plannedEndDateT);
  } else {
    OperationOrder lastOperationOrder = concurrentOperationOrders.get(0);

    if (timeBeforeNextOperation == 0 && initialDuration == 0) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          I18n.get(
              ProductionExceptionMessage.MANUF_ORDER_CANT_COMPUTE_NEXT_SLOT_WITH_CURRENT_CONFIG),
          operationOrder.getName());
    }

    return getClosestAvailableTimeSlotFrom(
        machine,
        lastOperationOrder.getPlannedEndDateT().plusSeconds(timeBeforeNextOperation),
        lastOperationOrder
            .getPlannedEndDateT()
            .plusSeconds(timeBeforeNextOperation + initialDuration),
        operationOrder,
        initialDuration,
        false,
        loopNb + 1);
  }
}

@SuppressWarnings("unchecked")
protected MachineTimeSlot getClosestAvailableTimeSlotFrom(
    Machine machine,
    LocalDateTime startDateT,
    LocalDateTime endDateT,
    OperationOrder operationOrder,
    long initialDuration,
    boolean ignoreConcurrency,
    int loopNb)
    throws AxelorException {

  EventsPlanning planning = machine.getPublicHolidayEventsPlanning();

  // If startDate is not available because of planning
  // Then we try for the next day
  LocalDateTime nextDayDateT = startDateT.plusDays(1).with(LocalTime.MIN);
  LocalDateTime plannedStartDateT = null;
  LocalDateTime plannedEndDateT = null;

  if (planning != null
      && planning.getEventsPlanningLineList() != null
      && planning.getEventsPlanningLineList().stream()
          .anyMatch(epl -> epl.getDate().equals(startDateT.toLocalDate()))) {

    return getClosestAvailableTimeSlotFrom(
        machine,
        nextDayDateT,
        nextDayDateT.plusSeconds(initialDuration),
        operationOrder,
        initialDuration,
        ignoreConcurrency,
        loopNb);
  }

  if (machine.getWeeklyPlanning() != null) {
    // Planning on date at startDateT
    DayPlanning dayPlanning =
        findDayPlanningOrClosed(machine.getWeeklyPlanning(), startDateT.toLocalDate());
    Optional<LocalDateTime> allowedStartDateTPeriodAt =
        dayPlanningService.getAllowedStartDateTPeriodAt(dayPlanning, startDateT);

    if (allowedStartDateTPeriodAt.isEmpty()) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
          I18n.get(ProductionExceptionMessage.OPERATION_ORDER_NO_PERIOD_FOUND_FOR_PLAN_DATES),
          operationOrder.getName());
    }

    plannedStartDateT = allowedStartDateTPeriodAt.get();
    plannedEndDateT = plannedStartDateT.plusSeconds(initialDuration);

    // Must end in a existing period. The end date may have jumped onto a
    // different calendar day than startDateT, so its DayPlanning must be
    // looked up again instead of reusing the one resolved for startDateT.
    plannedEndDateT =
        dayPlanningService
            .getAllowedStartDateTPeriodAt(
                findDayPlanningOrClosed(
                    machine.getWeeklyPlanning(), plannedEndDateT.toLocalDate()),
                plannedEndDateT)
            .get();
    // Void duration is time where machine is not used (not in any period)
    long remainingTime = 0l;
    int counter = 0;
    do {

      long voidDuration =
          dayPlanningService.computeVoidDurationBetween(
              dayPlanning, plannedStartDateT, plannedEndDateT);

      remainingTime =
          initialDuration
              - DurationHelper.getSecondsDuration(
                  Duration.between(plannedStartDateT, plannedEndDateT)
                      .minusSeconds(voidDuration));

      // So the time 'spent' must be reported
      plannedEndDateT = plannedEndDateT.plusSeconds(remainingTime);

      // And of course it must end in a existing period, resolved for its own day.
      plannedEndDateT =
          dayPlanningService
              .getAllowedStartDateTPeriodAt(
                  findDayPlanningOrClosed(
                      machine.getWeeklyPlanning(), plannedEndDateT.toLocalDate()),
                  plannedEndDateT)
              .get();

      counter++;

    } while (remainingTime > 0 && counter < MAX_LOOP_CALL);

    if (counter == MAX_LOOP_CALL) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          ProductionExceptionMessage.TOO_MANY_CALL_GETTING_END_DATE);
    }

  } else {
    // The machine does not have weekly planning so dates are ok for now.
    plannedStartDateT = startDateT;
    plannedEndDateT = endDateT;
  }

  if (ignoreConcurrency) {
    return new MachineTimeSlot(plannedStartDateT, plannedEndDateT);
  }

  return getClosestAvailableMachineTimeSlot(
      machine, operationOrder, initialDuration, plannedStartDateT, plannedEndDateT, loopNb);
}

@Override
public MachineTimeSlot getClosestTimeSlotFrom(
    Machine machine,
    LocalDateTime startDateT,
    LocalDateTime endDateT,
    OperationOrder operationOrder)
    throws AxelorException {

  return getClosestAvailableTimeSlotFrom(
      machine,
      startDateT,
      endDateT,
      operationOrder,
      DurationHelper.getSecondsDuration(Duration.between(startDateT, endDateT)),
      true,
      0);
}

