protected DayPlanning findDayPlanningOrClosed(WeeklyPlanning weeklyPlanning, LocalDate date) {
  DayPlanning dayPlanning = weeklyPlanningService.findDayPlanning(weeklyPlanning, date);
  if (dayPlanning == null) {
    dayPlanning = new DayPlanning();
    dayPlanning.setWeeklyPlanning(weeklyPlanning);
  }
  return dayPlanning;
}

protected long computeVoidDurationBetween(
    DayPlanning dayPlanning,
    LocalDateTime startDateT,
    LocalDateTime endDateT,
    LocalDateTime initialEndDateT) {

  long duration = 0;

  if (dayPlanning == null
      || dayPlanning.getWeeklyPlanning() == null
      || startDateT.compareTo(endDateT) >= 0) {
    return 0;
  }

  if (endDateT.toLocalDate().isAfter(initialEndDateT.toLocalDate())) {
    return 0;
  }

  if (endDateT.toLocalDate().isEqual(initialEndDateT.toLocalDate())) {
    endDateT = initialEndDateT;
  }

  // Keep the WeeklyPlanning anchor from the original (non-null) dayPlanning: the day-specific
  // lookup below may return null if this date has no DayPlanning at all (e.g. a week-end not
  // configured), and the recursive call for the next day still needs the WeeklyPlanning to keep
  // going past it instead of the whole chain silently stopping there.
  DayPlanning currentDayPlanning =
      weeklyPlanningService.findDayPlanning(
          dayPlanning.getWeeklyPlanning(), startDateT.toLocalDate());
  duration +=
      computeVoidDurationBetween(
          currentDayPlanning, startDateT.toLocalTime(), endDateT.toLocalTime());

  LocalDateTime nextDay = startDateT.plusDays(1).with(LocalTime.MIN);
  return duration
      + computeVoidDurationBetween(
          dayPlanning, nextDay, nextDay.with(LocalTime.MAX), initialEndDateT);
}

protected long computeVoidDurationBetween(
    DayPlanning dayPlanning, LocalTime startT, LocalTime endT) {

  if (dayPlanning == null) {
    // No day planning at all for this date (e.g. week-end not configured in the
    // WeeklyPlanning): the whole span is void, consistently with a day planning that
    // exists but has no period defined.
    return DurationHelper.getSecondsDuration(Duration.between(startT, endT));
  }
  LocalTime morningFromTime = dayPlanning.getMorningFrom();
  LocalTime morningToTime = dayPlanning.getMorningTo();
  LocalTime afternoonFromTime = dayPlanning.getAfternoonFrom();
  LocalTime afternoonToTime = dayPlanning.getAfternoonTo();

  if ((morningFromTime == null || morningToTime == null)
      && (afternoonFromTime == null || afternoonToTime == null)) {
    // Day fully closed (e.g. week-end/day off): the whole span is void.
    return DurationHelper.getSecondsDuration(Duration.between(startT, endT));
  }

  long duration = 0;

  if (afternoonFromTime != null && afternoonToTime != null) {
    duration += computeVoidSecondPeriod(dayPlanning, startT, endT);
  }

  if (morningFromTime != null && morningToTime != null) {
    duration += computeVoidFirstPeriod(dayPlanning, startT, endT);
  }

  return duration;
}

@Override
public long computeVoidDurationBetween(
    DayPlanning dayPlanning, LocalDateTime startDateT, LocalDateTime endDateT) {

  if (startDateT.isAfter(endDateT)) {
    return 0;
  }

  // If it is not the same day
  if (startDateT.toLocalDate().compareTo(endDateT.toLocalDate()) < 0) {
    return computeVoidDurationBetween(
        dayPlanning, startDateT, startDateT.with(LocalTime.MAX), endDateT);
  }

  // Same day
  return computeVoidDurationBetween(
      dayPlanning, startDateT.toLocalTime(), endDateT.toLocalTime());
}

protected LocalDateTime getDateTAtLocalTime(LocalDateTime dateT, LocalTime localTime) {

  return dateT
      .withHour(localTime.getHour())
      .withMinute(localTime.getMinute())
      .withSecond(localTime.getSecond());
}

protected long computeVoidSecondPeriod(
    DayPlanning dayPlanning, LocalTime startT, LocalTime endT) {
  LocalTime cursorTime = endT;

  LocalTime morningToTime = dayPlanning.getMorningTo();
  LocalTime afternoonFromTime = dayPlanning.getAfternoonFrom();
  LocalTime afternoonToTime = dayPlanning.getAfternoonTo();

  long duration = 0;

  if (cursorTime.isAfter(afternoonToTime)) {
    LocalTime maxTime = max(afternoonToTime, startT);
    duration += DurationHelper.getSecondsDuration(Duration.between(maxTime, cursorTime));

    cursorTime = maxTime;
  }

  if (cursorTime.compareTo(startT) == 0) {
    return duration;
  }

  cursorTime = afternoonFromTime;

  if (cursorTime.isAfter(startT) && morningToTime == null) {
    duration += DurationHelper.getSecondsDuration(Duration.between(startT, cursorTime));
  } else if (cursorTime.isAfter(startT) && endT.isAfter(morningToTime)) {
    LocalTime maxTime = max(morningToTime, startT);
    duration += DurationHelper.getSecondsDuration(Duration.between(maxTime, cursorTime));
  }

  return duration;
}

protected long computeVoidFirstPeriod(DayPlanning dayPlanning, LocalTime startT, LocalTime endT) {
  LocalTime cursorTime = null;

  LocalTime morningFromTime = dayPlanning.getMorningFrom();
  LocalTime morningToTime = dayPlanning.getMorningTo();
  LocalTime afternoonFromTime = dayPlanning.getAfternoonFrom();
  LocalTime afternoonToTime = dayPlanning.getAfternoonTo();

  long duration = 0;

  // This checks if we have a second period.
  if ((afternoonFromTime == null || afternoonToTime == null) && endT.isAfter(morningToTime)) {
    // If second period does not exist, we need to compute the duration
    // between morningToTime and endT
    cursorTime = endT;
    LocalTime maxTime = max(morningToTime, startT);

    duration += DurationHelper.getSecondsDuration(Duration.between(maxTime, cursorTime));

    cursorTime = maxTime;

    if (cursorTime.compareTo(startT) == 0) {
      return duration;
    }
  }

  cursorTime = morningFromTime;
  if (cursorTime.isAfter(startT)) {
    duration += DurationHelper.getSecondsDuration(Duration.between(startT, cursorTime));
  }

  return duration;
}

protected LocalTime max(LocalTime t1, LocalTime t2) {

  if (t1 == null && t2 == null) return null;
  if (t1 == null) return t2;
  if (t2 == null) return t1;
  return (t1.isAfter(t2)) ? t1 : t2;
}

protected PurchaseOrderLine createOrUpdatePurchaseOrderLine(
    PurchaseOrder purchaseOrder,
    Product product,
    Unit unit,
    BigDecimal qty,
    LocalDate desiredReceiptDate)
    throws AxelorException {
  PurchaseOrderLine poLine =
      findMatchingPurchaseOrderLine(purchaseOrder, product, unit, desiredReceiptDate);
  if (poLine != null) {
    poLine.setQty(poLine.getQty().add(qty));
    return poLine;
  }

  poLine =
      purchaseOrderLineService.createPurchaseOrderLine(
          purchaseOrder, product, null, null, qty, unit);
  poLine.setDesiredReceiptDate(desiredReceiptDate);
  poLine.setEstimatedReceiptDate(desiredReceiptDate);
  purchaseOrder.addPurchaseOrderLineListItem(poLine);
  return poLine;
}

@Transactional(rollbackOn = {Exception.class})
protected void generatePurchaseProposal(
    MrpLine mrpLine,
    Map<Pair<Partner, LocalDate>, PurchaseOrder> purchaseOrders,
    Map<Partner, PurchaseOrder> purchaseOrdersPerSupplier,
    boolean isProposalsPerSupplier)
    throws AxelorException {

  Product product = mrpLine.getProduct();
  StockLocation stockLocation = mrpLine.getStockLocation();
  LocalDate maturityDate = mrpLine.getMaturityDate();

  Partner supplierPartner = mrpLine.getSupplierPartner();

  if (supplierPartner == null) {
    supplierPartner = product.getDefaultSupplierPartner();

    if (supplierPartner == null) {
      throw new AxelorException(
          mrpLine,
          TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
          I18n.get(SupplychainExceptionMessage.MRP_LINE_1),
          product.getFullName());
    }
  }

  Company company = stockLocation.getCompany();

  Pair<Partner, LocalDate> key = null;
  PurchaseOrder purchaseOrder = null;

  if (isProposalsPerSupplier) {
    if (purchaseOrdersPerSupplier != null && !purchaseOrdersPerSupplier.isEmpty()) {
      purchaseOrder = purchaseOrdersPerSupplier.get(supplierPartner);
      if (purchaseOrder != null) {
        purchaseOrder = purchaseOrderRepo.find(purchaseOrder.getId());
      }
    }
  } else {
    if (purchaseOrders != null) {
      key = Pair.of(supplierPartner, maturityDate);
      purchaseOrder = purchaseOrders.get(key);
    }
  }

  if (purchaseOrder == null) {
    purchaseOrder =
        purchaseOrderRepo.save(
            purchaseOrderCreateSupplychainService.createPurchaseOrder(
                AuthUtils.getUser(),
                company,
                null,
                supplierPartner.getCurrency(),
                null,
                this.getPurchaseOrderOrigin(mrpLine),
                null,
                stockLocation,
                appBaseService.getTodayDate(company),
                Beans.get(PartnerPriceListService.class)
                    .getDefaultPriceList(supplierPartner, PriceListRepository.TYPE_PURCHASE),
                supplierPartner,
                null,
                supplierPartner.getFiscalPosition()));
    if (isProposalsPerSupplier) {
      if (purchaseOrdersPerSupplier != null) {
        purchaseOrdersPerSupplier.put(supplierPartner, purchaseOrder);
      }
    } else {
      if (purchaseOrders != null) {
        purchaseOrders.put(key, purchaseOrder);
      }
    }
    if (mrpLine.getMrpLineOriginList().size() == 1) {
      if (mrpLine
          .getMrpLineOriginList()
          .get(0)
          .getRelatedToSelect()
          .equals(MrpLineOriginRepository.RELATED_TO_SALE_ORDER_LINE)) {
        purchaseOrder.setGeneratedSaleOrderId(
            saleOrderLineRepo
                .find(mrpLine.getMrpLineOriginList().get(0).getRelatedToSelectId())
                .getSaleOrder()
                .getId());
      }
    }
  }
  Unit unit = product.getPurchasesUnit();
  BigDecimal qty = mrpLine.getQty();
  if (unit == null) {
    unit = product.getUnit();
  } else {
    qty =
        Beans.get(UnitConversionService.class)
            .convert(product.getUnit(), unit, qty, qty.scale(), product);
  }
  purchaseOrder.setNotes(supplierPartner.getPurchaseOrderComments());
  LocalDate desiredReceiptDate = maturityDate;
  if (mrpLine.getEstimatedDeliveryMrpLine() != null) {
    desiredReceiptDate = mrpLine.getEstimatedDeliveryMrpLine().getMaturityDate();
  }

  PurchaseOrderLine poLine =
      createOrUpdatePurchaseOrderLine(purchaseOrder, product, unit, qty, desiredReceiptDate);

  purchaseOrderLineService.compute(poLine, purchaseOrder);

  purchaseOrderService.computePurchaseOrder(purchaseOrder);

  linkToOrder(mrpLine, purchaseOrder);
}

@Override
public void generateProposal(
    MrpLine mrpLine,
    Map<Pair<Partner, LocalDate>, PurchaseOrder> purchaseOrders,
    Map<Partner, PurchaseOrder> purchaseOrdersPerSupplier,
    boolean isProposalsPerSupplier)
    throws AxelorException {

  if (mrpLine.getMrpLineType().getElementSelect()
      == MrpLineTypeRepository.ELEMENT_PURCHASE_PROPOSAL) {

    this.generatePurchaseProposal(
        mrpLine, purchaseOrders, purchaseOrdersPerSupplier, isProposalsPerSupplier);
  }
}

@Override
public void generateProposal(MrpLine mrpLine) throws AxelorException {
  generateProposal(mrpLine, null, null, false);
}

protected PurchaseOrderLine findMatchingPurchaseOrderLine(
    PurchaseOrder purchaseOrder, Product product, Unit unit, LocalDate desiredReceiptDate) {
  if (purchaseOrder.getPurchaseOrderLineList() == null) {
    return null;
  }

  return purchaseOrder.getPurchaseOrderLineList().stream()
      .filter(Objects::nonNull)
      .filter(purchaseOrderLine -> product.equals(purchaseOrderLine.getProduct()))
      .filter(purchaseOrderLine -> Objects.equals(unit, purchaseOrderLine.getUnit()))
      .filter(
          purchaseOrderLine ->
              Objects.equals(desiredReceiptDate, purchaseOrderLine.getDesiredReceiptDate()))
      .findFirst()
      .orElse(null);
}

protected void linkToOrder(MrpLine mrpLine, AuditableModel order) {
  mrpLine.setProposalSelect(order.getClass().getName());
  mrpLine.setProposalSelectId(order.getId());
  mrpLine.setProposalGenerated(true);
}

protected String getPurchaseOrderOrigin(MrpLine mrpLine) {
  StringBuilder origin = new StringBuilder();
  int count = 0;
  for (MrpLineOrigin mrpLineOrigin : mrpLine.getMrpLineOriginList()) {
    count++;
    origin.append(getMrpLineOriginStr(mrpLineOrigin));
    if (count < mrpLine.getMrpLineOriginList().size()) {
      origin.append(" & ");
    }
  }
  return origin.toString();
}

protected String getMrpLineOriginStr(MrpLineOrigin mrpLineOrigin) {
  if (mrpLineOrigin
      .getRelatedToSelect()
      .equals(MrpLineOriginRepository.RELATED_TO_SALE_ORDER_LINE)) {
    SaleOrder saleOrder =
        saleOrderLineRepo.find(mrpLineOrigin.getRelatedToSelectId()).getSaleOrder();
    return saleOrder.getSaleOrderSeq();
  }
  if (mrpLineOrigin
      .getRelatedToSelect()
      .equals(MrpLineOriginRepository.RELATED_TO_PURCHASE_ORDER_LINE)) {
    PurchaseOrder purchaseOrder =
        purchaseOrderLineRepo.find(mrpLineOrigin.getRelatedToSelectId()).getPurchaseOrder();
    return purchaseOrder.getPurchaseOrderSeq();
  }
  if (mrpLineOrigin
      .getRelatedToSelect()
      .equals(MrpLineOriginRepository.RELATED_TO_MRP_FORECAST)) {
    return mrpLineOrigin.getMrpLine().getMrp().getMrpSeq() + "-" + I18n.get("MRP forecast");
  }
  return "";
}

def default_get(self, fields):
    res = super().default_get(fields)
    if not res.get('name') and res.get('company_id'):
        res['name'] = self.env._('Working Hours of %s', self.env['res.company'].browse(res['company_id']).name)
    return res

def copy_data(self, default=None):
    vals_list = super().copy_data(default=default)
    for calendar, vals in zip(self, vals_list):
        # the rates of a fixed calendar are computed from its attendances, those of the other
        # calendars are set by the user: they are kept on the copy
        if vals.get('calendar_type', calendar.calendar_type) != 'fixed':
            vals.setdefault('days_per_week', calendar.days_per_week)
            vals.setdefault('hours_per_week', calendar.hours_per_week)
    return vals_list

def _get_attendances_to_unlink(self, next_calendar_type=None):
    """ Return the attendances that do not fit the calendar's ``calendar_type`` (or
    ``next_calendar_type`` when given), and must be dropped:

    - ``fixed``: attendances with a date (fixed calendars use undated weekly lines);
    - ``undefined``: every attendance (flexible calendars have no predefined slots);
    - ``variable``: attendances without a date (variable calendars use dated lines).

    Called after every ``create``/``write`` of calendars.

    :rtype: ``resource.calendar.attendance`` recordset
    """
    def to_unlink(attendance):
        calendar_type = next_calendar_type or attendance.calendar_id.calendar_type
        if calendar_type == 'undefined':
            return True
        return bool(attendance.date) if calendar_type == 'fixed' else not attendance.date
    return self.attendance_ids.filtered(to_unlink)

def _convert_single_occurrence_recurrencies(self):
    """Convert recurrent attendances with only one visible occurrence into ad-hoc attendances."""
    def _has_single_remaining_occurrence(att):
        if not att.recurrency or not att.date or att.recurrency_end_type == 'forever':
            return False
        excluded = set(att.recurrency_excluded_occurences or [])
        delta = timedelta(**{att.recurrency_type: att.recurrency_interval})
        current = att.date + delta
        while current <= att.recurrency_until:
            if fields.Date.to_string(current) not in excluded:
                return False
            current += delta
        return True

    single_occurrence = self.attendance_ids.filtered(_has_single_remaining_occurrence)
    single_occurrence.write({'recurrency': False, 'recurrency_excluded_occurences': False})

def _clean_excluded_occurrences(self):
    """Remove stale or duplicate entries from ``recurrency_excluded_occurences``.

    Removes dates before the attendance start, dates past ``recurrency_until``,
    dates that don't fall on a valid recurrency occurrence, and duplicates —
    in a single pass per attendance.
    """
    for att in self.attendance_ids.filtered(lambda a: a.recurrency and a.recurrency_excluded_occurences and a.date):
        date_str = fields.Date.to_string(att.date)
        until_str = fields.Date.to_string(att.recurrency_until) if att.recurrency_end_type != 'forever' else None
        seen = set()
        cleaned = []
        for d in att.recurrency_excluded_occurences:
            if d < date_str or (until_str and d > until_str) or d in seen:
                continue
            diff_days = (fields.Date.from_string(d) - att.date).days
            if att.recurrency_type == 'days' and diff_days % att.recurrency_interval:
                continue
            if att.recurrency_type == 'weeks' and (diff_days % 7 or (diff_days // 7) % att.recurrency_interval):
                continue
            seen.add(d)
            cleaned.append(d)
        if cleaned != att.recurrency_excluded_occurences:
            att.recurrency_excluded_occurences = cleaned

def _compute_full_time_required_hours(self):
    for calendar in self:
        if calendar.reference_calendar_id:
            calendar.full_time_required_hours = calendar.reference_calendar_id.hours_per_week
        elif calendar.company_id.resource_calendar_id:
            calendar.full_time_required_hours = calendar.company_id.resource_calendar_id.hours_per_week
        else:
            calendar.full_time_required_hours = calendar.hours_per_week

def _compute_attendance_ids(self):
    for calendar in self:
        calendar_changed = calendar._origin and calendar._origin.company_id != calendar.company_id
        if (not calendar.id or calendar_changed) and calendar.calendar_type == "fixed" and not calendar.attendance_ids:
            calendar.attendance_ids = calendar._get_default_attendance_ids(calendar.company_id)

def _compute_global_leave_ids(self):
    for calendar in self.filtered(lambda c: not c._origin or c._origin.company_id != c.company_id):
        calendar.update({
            'global_leave_ids': [(5, 0, 0)] + [
                (0, 0, leave._copy_leave_vals()) for leave in calendar.company_id.resource_calendar_id.global_leave_ids],
        })

def _compute_days_per_week(self):
    for calendar in self:
        # variable/undefined calendars don't have a reliable attendance pattern to derive
        # this from (undefined calendars have none at all); the user sets it directly instead.
        if calendar.calendar_type != 'fixed':
            continue
        attendances = calendar.attendance_ids.filtered(lambda a: a._is_work_period())
        calendar.days_per_week = len(set(attendances.mapped('dayofweek')))

def _compute_hours_per_day(self):
    for calendar in self:
        calendar.hours_per_day = calendar.hours_per_week / calendar.days_per_week if calendar.days_per_week else 0

def _compute_hours_per_week(self):
    """ Compute the average hours per week """
    for calendar in self:
        # see _compute_days_per_week: variable/undefined calendars are set directly by the user
        if calendar.calendar_type != 'fixed':
            continue
        attendances = calendar.attendance_ids.filtered(lambda a: a._is_work_period())
        calendar.hours_per_week = sum(attendances.mapped('duration_hours'))

def _verify_hours(self):
    for calendar in self:
        # fixed calendars derive these from their attendance lines, always valid by construction
        if calendar.calendar_type == 'fixed':
            continue
        if calendar.hours_per_week < 0 or calendar.hours_per_week > 168:
            raise ValidationError(self.env._("Hours per week must be between 0 and 168."))
        if calendar.hours_per_day < 0 or calendar.hours_per_day > 24:
            raise ValidationError(self.env._("Average hours per day must be between 0 and 24."))

def _compute_is_fulltime(self):
    for calendar in self:
        calendar.is_fulltime = float_compare(calendar.full_time_required_hours, calendar.hours_per_week, 3) == 0

def _compute_work_time_rate(self):
    for calendar in self:
        if calendar.full_time_required_hours:
            calendar.work_time_rate = calendar.hours_per_week / calendar.full_time_required_hours
        else:
            calendar.work_time_rate = 1.0

def _unavailable_intervals(self, start_dt, end_dt, resource=None, domain=None, tz=None):
    """ Single-resource shortcut of :meth:`_unavailable_intervals_batch`.

    :param resource: a ``resource.resource`` record, or ``None`` / empty for the
        calendar-level result
    :param tz: unused, kept for compatibility
    :return: ``Intervals`` in UTC, empty for a flexible resource without leave
    """
    if resource is None:
        resource = self.env['resource.resource']
    resources_per_tz = resource._get_resources_per_tz()
    return self._unavailable_intervals_batch(
        start_dt, end_dt, resources_per_tz=resources_per_tz, domain=domain,
    ).get(resource.id, Intervals())

def _get_default_attendance_ids(self, company_id=None):
    """ Return ``attendance_ids`` commands copying the attendances of the company's fixed
    calendar, or, by default, 5 duration-based days of 8 hours (Monday to Friday).

    :param company_id: ``res.company`` record, or ``None``
    :rtype: list
    """
    if company_id and company_id.resource_calendar_id.calendar_type == "fixed" and (attendances := company_id.resource_calendar_id.attendance_ids):
        return [Command.clear()] + [Command.create(attendance) for attendance in attendances._to_dict()]
    return [Command.clear()] + [
        Command.create({'dayofweek': str(dayofweek), 'duration_hours': 8, 'hour_from': 0, 'hour_to': 0})
        for dayofweek in range(5)
    ]

def plan_days(self, days, day_dt, compute_leaves=False, domain=None):
    """ Return the end of the first work interval of the ``days``-th work day counted
    from ``day_dt`` (the day of ``day_dt`` included if it has work time after
    ``day_dt``), or, for a negative ``days``, the start of the last work interval of the
    ``abs(days)``-th work day counted backwards. ``days=0`` returns ``day_dt``.

    Beware: with several attendances per day (e.g. a lunch break), the result is the end
    of the morning attendance of the last day, not the end of that day.

    Calendar-level only (no resource, only global leaves), computed in the company
    timezone by windows of 14 days, for at most 100 windows.

    :param int days: number of work days to plan, negative to plan backwards
    :param datetime day_dt: starting point; naive means UTC
    :param bool compute_leaves: deduct global leaves
    :param list domain: leave domain, see :meth:`_leave_intervals_batch`
    :return: the resulting datetime, in the timezone of ``day_dt`` (naive UTC if
        ``day_dt`` is naive), or ``False`` if not found within the search range
    :rtype: datetime | bool
    """
    revert = to_timezone(day_dt.tzinfo)
    day_dt = day_dt.astimezone(ZoneInfo(self.env.company.tz))

    # which method to use for retrieving intervals
    if compute_leaves:
        get_intervals = partial(self._work_intervals_batch, domain=domain)
    else:
        get_intervals = self._attendance_intervals_batch

    if days > 0:
        found = set()
        delta = timedelta(days=14)
        for n in range(100):
            dt = day_dt + delta * n
            for start, stop, _meta in get_intervals(dt, dt + delta)[False]:
                found.add(start.date())
                if len(found) == days:
                    return revert(stop)
        return False

    if days < 0:
        days = abs(days)
        found = set()
        delta = timedelta(days=14)
        for n in range(100):
            dt = day_dt - delta * n
            for start, _stop, _meta in reversed(get_intervals(dt - delta, dt)[False]):
                found.add(start.date())
                if len(found) == days:
                    return revert(start)
        return False

    return revert(day_dt)

def set_duration(self, now):
    if self.duration is None:
        self.duration = now - self.last_modified_at

protected MachineTimeSlot getFurthestAvailableMachineTimeSlot(
    Machine machine,
    OperationOrder operationOrder,
    long initialDuration,
    LocalDateTime plannedStartDateT,
    LocalDateTime plannedEndDateT,
    int loopNb)
    throws AxelorException {

  if (loopNb >= MAX_RECURSIVE_CALL) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        ProductionExceptionMessage.TOO_MANY_CALL_GETTING_TIME_SLOT,
        operationOrder.getName());
  }
  long timeBeforeNextOperation =
      Optional.ofNullable(operationOrder.getWorkCenter())
          .map(WorkCenter::getTimeBeforeNextOperation)
          .orElse(0l);
  // Must check if dates are occupied by other operation orders
  // The first one of the list will be the first to start
  List<OperationOrder> concurrentOperationOrders =
      operationOrderRepository
          .all()
          .filter(
              "self.machine = :machine"
                  + " AND ((self.plannedStartDateT <= :startDate AND self.plannedEndDateT > :startDateWithTime)"
                  + " OR (self.plannedStartDateT < :endDate AND self.plannedEndDateT > :endDateWithTime)"
                  + " OR (self.plannedStartDateT >= :startDate AND self.plannedEndDateT <= :endDateWithTime))"
                  + " AND (self.manufOrder.statusSelect != :cancelled AND self.manufOrder.statusSelect != :finished)"
                  + " AND self.id != :operationOrderId"
                  + " AND self.outsourcing = false")
          .bind("startDate", plannedStartDateT)
          .bind("endDate", plannedEndDateT)
          .bind("startDateWithTime", plannedStartDateT.minusSeconds(timeBeforeNextOperation))
          .bind("endDateWithTime", plannedEndDateT.minusSeconds(timeBeforeNextOperation))
          .bind("machine", machine)
          .bind("cancelled", ManufOrderRepository.STATUS_CANCELED)
          .bind("finished", ManufOrderRepository.STATUS_FINISHED)
          .bind("operationOrderId", operationOrder.getId())
          .order("plannedStartDateT")
          .fetch();

  if (concurrentOperationOrders.isEmpty()) {
    return new MachineTimeSlot(plannedStartDateT, plannedEndDateT);
  } else {
    OperationOrder firstOperationOrder = concurrentOperationOrders.get(0);

    // Can not compute next slot with concurrency if these values are 0
    if (timeBeforeNextOperation == 0 && initialDuration == 0) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          I18n.get(
              ProductionExceptionMessage.MANUF_ORDER_CANT_COMPUTE_NEXT_SLOT_WITH_CURRENT_CONFIG),
          operationOrder.getName());
    }

    return getFurthestAvailableTimeSlotFrom(
        machine,
        firstOperationOrder
            .getPlannedStartDateT()
            .minusSeconds(initialDuration + timeBeforeNextOperation),
        firstOperationOrder.getPlannedStartDateT().minusSeconds(timeBeforeNextOperation),
        operationOrder,
        initialDuration,
        false,
        loopNb + 1);
  }
}

@SuppressWarnings("unchecked")
protected MachineTimeSlot getFurthestAvailableTimeSlotFrom(
    Machine machine,
    LocalDateTime startDateT,
    LocalDateTime endDateT,
    OperationOrder operationOrder,
    long initialDuration,
    boolean ignoreConcurrency,
    int loopNb)
    throws AxelorException {

  EventsPlanning planning = machine.getPublicHolidayEventsPlanning();

  if (planning != null
      && planning.getEventsPlanningLineList() != null
      && planning.getEventsPlanningLineList().stream()
          .anyMatch(epl -> epl.getDate().equals(endDateT.toLocalDate()))) {

    // If endDate is not available because of planning
    // Then we try for the previous day
    LocalDateTime previousDayDateT = endDateT.plusDays(1).with(LocalTime.MIN);

    return getFurthestAvailableTimeSlotFrom(
        machine,
        previousDayDateT.minusSeconds(initialDuration),
        previousDayDateT,
        operationOrder,
        initialDuration,
        ignoreConcurrency,
        loopNb);
  }

  LocalDateTime plannedStartDateT = null;
  LocalDateTime plannedEndDateT = null;

  if (machine.getWeeklyPlanning() != null) {
    // Planning on date at endDateT
    DayPlanning dayPlanning =
        findDayPlanningOrClosed(machine.getWeeklyPlanning(), endDateT.toLocalDate());
    Optional<LocalDateTime> allowedEndDateTPeriodAt =
        dayPlanningService.getAllowedEndDateTPeriodAt(dayPlanning, endDateT);

    if (allowedEndDateTPeriodAt.isEmpty()) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
          I18n.get(ProductionExceptionMessage.OPERATION_ORDER_NO_PERIOD_FOUND_FOR_PLAN_DATES),
          operationOrder.getName());
    }

    plannedEndDateT = allowedEndDateTPeriodAt.get();
    plannedStartDateT = plannedEndDateT.minusSeconds(initialDuration);

    // Must start in an existing period. The start date may have jumped onto a
    // different calendar day than endDateT, so its DayPlanning must be looked
    // up again instead of reusing the one resolved for endDateT.
    plannedStartDateT =
        dayPlanningService
            .getAllowedEndDateTPeriodAt(
                findDayPlanningOrClosed(
                    machine.getWeeklyPlanning(), plannedStartDateT.toLocalDate()),
                plannedStartDateT)
            .get();
    // Void duration is time when machine is not used (not in any period)

    long remainingTime = 0l;
    int counter = 0;
    do {

      long voidDuration =
          dayPlanningService.computeVoidDurationBetween(
              dayPlanning, plannedStartDateT, plannedEndDateT);

      remainingTime =
          initialDuration
              - DurationHelper.getSecondsDuration(
                  Duration.between(plannedStartDateT, plannedEndDateT)
                      .minusSeconds(voidDuration));
      // So the time 'spent' must be reported
      plannedStartDateT = plannedStartDateT.minusSeconds(remainingTime);

      // And of course it must start also in an existing period, resolved for its own day.
      plannedStartDateT =
          dayPlanningService
              .getAllowedEndDateTPeriodAt(
                  findDayPlanningOrClosed(
                      machine.getWeeklyPlanning(), plannedStartDateT.toLocalDate()),
                  plannedStartDateT)
              .get();

      counter++;
    } while (remainingTime > 0 && counter < MAX_LOOP_CALL);

    if (counter == MAX_LOOP_CALL) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          ProductionExceptionMessage.TOO_MANY_CALL_GETTING_START_DATE);
    }

  } else {
    // The machine does not have weekly planning so dates are ok for now.
    plannedStartDateT = startDateT;
    plannedEndDateT = endDateT;
  }

  if (ignoreConcurrency) {
    return new MachineTimeSlot(plannedStartDateT, plannedEndDateT);
  }
  return getFurthestAvailableMachineTimeSlot(
      machine, operationOrder, initialDuration, plannedStartDateT, plannedEndDateT, loopNb);
}

