@Transactional(rollbackOn = {Exception.class})
protected String realizeStockMove(StockMove stockMove, boolean checkOngoingInventoryFlag)
    throws AxelorException {
  if (stockMove.getStatusSelect() == null
      || stockMove.getStatusSelect() != StockMoveRepository.STATUS_PLANNED) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_REALIZATION_WRONG_STATUS));
  }

  LOG.debug("Stock realization : {} ", stockMove.getStockMoveSeq());

  if (stockMove.getTypeSelect() == StockMoveRepository.TYPE_INCOMING
      && !stockMove.getIsReversion()
      && appStockService.getAppStock().getIsRequiredShipmentSupplierDetails()
      && (stockMove.getSupplierShipmentDate() == null
          || Strings.isNullOrEmpty(stockMove.getSupplierShipmentRef()))) {
    throw new AxelorException(
        stockMove,
        TraceBackRepository.CATEGORY_MISSING_FIELD,
        I18n.get(StockExceptionMessage.STOCK_MOVE_MISSING_SUPPLIER_SHIPMENT_DETAILS));
  }

  if (checkOngoingInventoryFlag) {
    checkOngoingInventory(stockMove);
  }

  int initialStatus = stockMove.getStatusSelect();

  String newStockSeq = null;
  stockMoveLineService.checkTrackingNumber(stockMove);
  stockMoveLineService.checkConformitySelection(stockMove);
  fillRealizeWapPriceForStockMove(stockMove);

  stockMoveLineService.checkExpirationDates(stockMove);

  BigDecimal exTaxTotal = stockMoveToolService.compute(stockMove);
  stockMove = JpaModelHelper.ensureManaged(stockMove);
  setRealizedStatus(stockMove);
  stockMove.setRealDate(appBaseService.getTodayDate(stockMove.getCompany()));
  stockMove.setExTaxTotal(exTaxTotal);

  stockMove = stockMoveRepo.save(stockMove);

  stockMoveLineService.updateLocations(
      initialStatus,
      StockMoveRepository.STATUS_CANCELED,
      getPlannedStockMoveLineIds(stockMove, true),
      stockMove.getEstimatedDate(),
      false,
      false,
      true);

  stockMoveLineService.updateLocations(
      StockMoveRepository.STATUS_DRAFT,
      StockMoveRepository.STATUS_REALIZED,
      getStockMoveLineIds(stockMove),
      stockMove.getEstimatedDate(),
      true,
      true,
      true);

  stockMove = JpaModelHelper.ensureManaged(stockMove);
  clearPlannedStockMoveLine(stockMove, true);
  storeCustomsCodesForStockMove(stockMove);
  resetMasses(stockMove);

  boolean mustBeSplit = mustBeSplit(stockMove);
  if (stockMove.getIsWithBackorder() && mustBeSplit) {
    Optional<StockMove> newStockMove =
        copyAndSplitStockMove(JpaModelHelper.ensureManaged(stockMove));
    if (newStockMove.isPresent()) {
      newStockSeq = newStockMove.get().getStockMoveSeq();
    }
  }

  if (stockMove.getIsWithReturnSurplus() && mustBeSplit) {
    Optional<StockMove> newStockMove =
        copyAndSplitStockMoveReverse(JpaModelHelper.ensureManaged(stockMove), true);
    if (newStockMove.isPresent()) {
      if (newStockSeq != null) {
        newStockSeq = newStockSeq + " " + newStockMove.get().getStockMoveSeq();
      } else {
        newStockSeq = newStockMove.get().getStockMoveSeq();
      }
    }
  }
  computeMasses(stockMove);

  stockMove = stockMoveRepo.find(stockMove.getId());
  if (stockMove.getTypeSelect() == StockMoveRepository.TYPE_INCOMING
      && !stockMove.getIsReversion()) {
    partnerProductQualityRatingService.calculate(stockMove);
  }

  return newStockSeq;
}

@Transactional(rollbackOn = {Exception.class})
protected void planStockMove(StockMove stockMove, boolean splitByTrackingNumber)
    throws AxelorException {
  if (stockMove.getStatusSelect() == null
      || stockMove.getStatusSelect() != StockMoveRepository.STATUS_DRAFT) {
    throw new AxelorException(
        stockMove,
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_PLAN_WRONG_STATUS));
  }

  LOG.debug("Stock move planification : {} ", stockMove.getStockMoveSeq());

  // This call will split move line by tracking number
  // But only works if the line has not been already splited
  if (splitByTrackingNumber) {
    stockMoveLineService.splitStockMoveLineByTrackingNumber(stockMove);
  }

  stockMove = JpaModelHelper.ensureManaged(stockMove);
  String draftSeq;

  // Set the sequence.
  if (Beans.get(SequenceService.class)
      .isEmptyOrDraftSequenceNumber(stockMove.getStockMoveSeq())) {
    draftSeq = stockMove.getStockMoveSeq();
    stockMove.setStockMoveSeq(
        stockMoveToolService.getSequenceStockMove(
            stockMove.getTypeSelect(), stockMove.getCompany(), stockMove));
  } else {
    draftSeq = null;
  }

  if (Strings.isNullOrEmpty(stockMove.getName())
      || draftSeq != null && stockMove.getName().startsWith(draftSeq)) {
    stockMove.setName(stockMoveToolService.computeName(stockMove));
  }

  int initialStatus = stockMove.getStatusSelect();

  setPlannedStatus(stockMove);

  updateLocations(stockMove, initialStatus);
  stockMove = JpaModelHelper.ensureManaged(stockMove);
  stockMove.setCancelReason(null);
  stockMove.setRealDate(null);

  stockMove.setExTaxTotal(stockMoveToolService.compute(stockMove));

  stockMoveRepo.save(stockMove);
}

protected Set<Long> getPlannedStockMoveLineIds(StockMove stockMove, boolean clearOnEachBatch) {
  final Set<Long> plannedLineIds = new LinkedHashSet<>();
  int clearOnBatch = clearOnEachBatch ? 1 : 0;
  BatchProcessorHelper.builder()
      .clearEveryNBatch(clearOnBatch)
      .flushAfterBatch(false)
      .build()
      .<StockMoveLine>forEachByQuery(
          getPlannedStockMoveLineQuery(stockMove.getId()),
          line -> plannedLineIds.add(line.getId()));
  return plannedLineIds;
}

protected Set<Long> getStockMoveLineIds(StockMove stockMove) {
  final Set<Long> lineIds = new LinkedHashSet<>();
  final long stockMoveId = stockMove.getId();
  BatchProcessorHelper.builder()
      .flushAfterBatch(false)
      .build()
      .<StockMoveLine>forEachByQuery(
          getStockMoveLineQuery(stockMoveId), line -> lineIds.add(line.getId()));
  return lineIds;
}

protected void storeCustomsCodesForStockMove(StockMove stockMove) throws AxelorException {

  Long stockMoveId = stockMove.getId();
  Query<StockMoveLine> query = getStockMoveLineQuery(stockMoveId);

  BatchProcessorHelper.of()
      .<StockMoveLine, AxelorException>forEachByQuery(
          query, stockMoveLineService::storeCustomsCodes);
}

@Override
@Transactional(rollbackOn = {Exception.class})
public Optional<StockMove> copyAndSplitStockMoveReverse(
    StockMove stockMove, List<StockMoveLine> stockMoveLines, boolean split)
    throws AxelorException {

  stockMoveLines = MoreObjects.firstNonNull(stockMoveLines, Collections.emptyList());
  StockMove newStockMove =
      createStockMove(
          stockMove.getToAddress(),
          stockMove.getFromAddress(),
          stockMove.getCompany(),
          stockMove.getPartner(),
          stockMove.getToStockLocation(),
          stockMove.getFromStockLocation(),
          null,
          stockMove.getEstimatedDate(),
          null,
          null,
          null,
          null,
          null,
          stockMove.getIncoterm(),
          0);

  copyStockMoveLines(newStockMove, stockMoveLines, split);

  List<StockMoveLine> newStockMoveLineList = newStockMove.getStockMoveLineList();

  if (ObjectUtils.isEmpty(newStockMoveLineList)) {
    return Optional.empty();
  }

  reverseStockMoveLineStockLocation(newStockMoveLineList);

  fillNewStockMoveFields(newStockMove, stockMove);

  return Optional.of(stockMoveRepo.save(newStockMove));
}

@Override
public Optional<StockMove> copyAndSplitStockMoveReverse(StockMove stockMove, boolean split)
    throws AxelorException {
  return copyAndSplitStockMoveReverse(stockMove, stockMove.getStockMoveLineList(), split);
}

@Override
public Optional<StockMove> copyAndSplitStockMove(StockMove stockMove) throws AxelorException {

  if (stockMove == null || !isNewBackorderLinePossible(stockMove)) {
    return Optional.empty();
  }

  StockMove newStockMove = stockMoveRepo.copy(stockMove, false);

  setOrigin(stockMove, newStockMove);
  newStockMove.setOrigin(stockMove.getOrigin());
  newStockMove.setRealDate(null);
  newStockMove.setStockMoveSeq(
      stockMoveToolService.getSequenceStockMove(
          newStockMove.getTypeSelect(), newStockMove.getCompany(), stockMove));
  newStockMove.setName(
      stockMoveToolService.computeName(
          newStockMove,
          newStockMove.getStockMoveSeq()
              + " "
              + I18n.get(StockExceptionMessage.STOCK_MOVE_7)
              + " "
              + stockMove.getStockMoveSeq()
              + " )"));
  newStockMove.setExTaxTotal(stockMoveToolService.compute(newStockMove));
  newStockMove.setShipmentMode(null);
  newStockMove.setFreightCarrierMode(null);
  newStockMove.setCarrierPartner(null);
  newStockMove.setForwarderPartner(null);
  newStockMove.setIncoterm(null);
  newStockMove.setTrackingNumber(null);
  newStockMove.setModeOfTransport(null);
  newStockMove.setNumOfPackages(0);
  newStockMove.setNumOfPalettes(0);
  newStockMove.setGrossMass(BigDecimal.ZERO);
  newStockMove.setIsIspmRequired(false);
  newStockMove.setIsNeedingConformityCertificate(false);
  newStockMove.setSignatoryUser(null);
  newStockMove.setIsConformityCertifSigned(false);
  newStockMove.setElectronicSignature(null);
  newStockMove.setStockMoveOrigin(stockMove);
  newStockMove = stockMoveRepo.save(newStockMove);
  stockMove.setBackorderId(newStockMove.getId());
  stockMoveRepo.save(stockMove);
  final StockMove[] newStockMoveHolder = new StockMove[] {newStockMove};
  BatchProcessorHelper.of()
      .<StockMoveLine, AxelorException>forEachByQuery(
          getStockMoveLineQuery(stockMove.getId()),
          line -> processBackorderLine(line, newStockMoveHolder[0]),
          () -> newStockMoveHolder[0] = stockMoveRepo.find(newStockMoveHolder[0].getId()));
  newStockMove = stockMoveRepo.find(newStockMove.getId());
  plan(newStockMove);
  return Optional.of(stockMoveRepo.find(newStockMove.getId()));
}

@Override
public boolean mustBeSplit(StockMove stockMove) {
  return stockMoveLineRepo
          .all()
          .filter("self.stockMove.id = :stockMoveId AND self.realQty != self.qty")
          .bind("stockMoveId", stockMove.getId())
          .count()
      > 0;
}

protected void computeMasses(StockMove stockMove) throws AxelorException {
  Company company = Beans.get(CompanyRepository.class).find(stockMove.getCompany().getId());
  StockConfig stockConfig = company.getStockConfig();
  Unit endUnit = stockConfig != null ? stockConfig.getCustomsMassUnit() : null;
  UnitConversionService unitConversionService = Beans.get(UnitConversionService.class);

  final long stockMoveId = stockMove.getId();
  final StockMove[] stockMoveHolder = {stockMoveRepo.find(stockMoveId)};

  Query<StockMoveLine> query =
      stockMoveLineRepo
          .all()
          .filter(
              "self.stockMove.id = :stockMoveId "
                  + "AND self.product IS NOT NULL "
                  + "AND self.product.productTypeSelect = :storable "
                  + "AND self.id > :lastSeenId")
          .bind("stockMoveId", stockMove.getId())
          .bind("storable", ProductRepository.PRODUCT_TYPE_STORABLE)
          .order("id");

  BatchProcessorHelper.of()
      .<StockMoveLine, AxelorException>forEachByQuery(
          query,
          stockMoveLine -> {
            Product product = stockMoveLine.getProduct();
            if (product == null
                || !ProductRepository.PRODUCT_TYPE_STORABLE.equals(
                    product.getProductTypeSelect())) {
              return;
            }

            boolean massesRequiredForStockMoveLine =
                stockMoveLineService.checkMassesRequired(stockMoveHolder[0], stockMoveLine);

            if (massesRequiredForStockMoveLine && endUnit == null) {
              throw new AxelorException(
                  stockMoveHolder[0],
                  TraceBackRepository.CATEGORY_NO_VALUE,
                  I18n.get(StockExceptionMessage.STOCK_MOVE_17));
            }

            computeNetMass(stockMoveLine, endUnit, unitConversionService);
            computeTotalNetMass(stockMoveLine, massesRequiredForStockMoveLine);
          },
          () -> stockMoveHolder[0] = stockMoveRepo.find(stockMoveId));
}

protected void resetMasses(StockMove stockMove) {

  Long stockMoveId = stockMove.getId();
  Query<StockMoveLine> query = getStockMoveLineQuery(stockMoveId);

  BatchProcessorHelper.of()
      .<StockMoveLine>forEachByQuery(query, (StockMoveLine sml) -> sml.setTotalNetMass(null));
}

protected void clearPlannedStockMoveLine(StockMove stockMove, boolean clearOnEachBatch) {
  final long stockMoveId = stockMove.getId();
  final StockMove[] stockMoveHolder = {stockMoveRepo.find(stockMoveId)};
  int clearOnBatch = clearOnEachBatch ? 1 : 0;
  Query<StockMoveLine> plannedStockMoveLineQuery = getPlannedStockMoveLineQuery(stockMoveId);
  BatchProcessorHelper.builder()
      .clearEveryNBatch(clearOnBatch)
      .build()
      .<StockMoveLine>forEachByQuery(
          plannedStockMoveLineQuery,
          stockMoveLineRepo::remove,
          () -> stockMoveHolder[0] = stockMoveRepo.find(stockMoveId));
}

@Override
public void updateLocations(StockMove stockMove, int initialStatus) throws AxelorException {

  copyPlannedStockMoveLines(stockMove);
  final Set<Long> plannedLineIds = getPlannedStockMoveLineIds(stockMove, true);
  stockMoveLineService.updateLocations(
      initialStatus,
      StockMoveRepository.STATUS_PLANNED,
      plannedLineIds,
      stockMove.getEstimatedDate(),
      false,
      true,
      true);
}

protected Query<StockMoveLine> getPlannedStockMoveLineQuery(final long stockMoveId) {
  return stockMoveLineRepo
      .all()
      .filter("self.plannedStockMove.id = :stockMoveId AND self.id > :lastSeenId")
      .bind("stockMoveId", stockMoveId)
      .order("id");
}

protected void fillNewStockMoveFields(StockMove newStockMove, StockMove stockMove)
    throws AxelorException {
  if (stockMove.getToAddress() != null) {
    newStockMove.setFromAddress(stockMove.getToAddress());
  }

  setStockMoveTypeSelect(newStockMove, stockMove);

  newStockMove.setStockMoveSeq(
      stockMoveToolService.getSequenceStockMove(
          newStockMove.getTypeSelect(), newStockMove.getCompany(), stockMove));

  setStockMoveName(newStockMove, stockMove);

  if (stockMove.getPartner() != null) {
    newStockMove.setShipmentMode(stockMove.getPartner().getShipmentMode());
    newStockMove.setFreightCarrierMode(stockMove.getPartner().getFreightCarrierMode());
    newStockMove.setCarrierPartner(stockMove.getPartner().getCarrierPartner());
  }
  newStockMove.setIsReversion(!stockMove.getIsReversion());
  newStockMove.setReversionOriginStockMove(stockMove);
  newStockMove.setFromAddressStr(stockMove.getToAddressStr());
  newStockMove.setNote(stockMove.getNote());
  newStockMove.setNumOfPackages(stockMove.getNumOfPackages());
  newStockMove.setNumOfPalettes(stockMove.getNumOfPalettes());
  newStockMove.setGrossMass(stockMove.getGrossMass());
  newStockMove.setExTaxTotal(stockMoveToolService.compute(newStockMove));
  newStockMove.setIsWithBackorder(stockMove.getIsWithBackorder());
  newStockMove.setOrigin(stockMove.getOrigin());
  setOrigin(stockMove, newStockMove);
  newStockMove.setGroupProductsOnPrintings(stockMove.getGroupProductsOnPrintings());
}

protected void copyStockMoveLines(
    StockMove newStockMove, List<StockMoveLine> stockMoveLines, boolean split) {
  for (StockMoveLine stockMoveLine : stockMoveLines) {
    if (!split || stockMoveLine.getRealQty().compareTo(stockMoveLine.getQty()) > 0) {
      newStockMove.addStockMoveLineListItem(copyStockMoveLine(stockMoveLine, split));
    }
  }
}

protected void reverseStockMoveLineStockLocation(List<StockMoveLine> newStockMoveLineList) {
  for (StockMoveLine stockMoveLine : newStockMoveLineList) {

    StockLocation toStockLocation = stockMoveLine.getToStockLocation();
    StockLocation fromStockLocation = stockMoveLine.getFromStockLocation();

    stockMoveLine.setFromStockLocation(toStockLocation);
    stockMoveLine.setToStockLocation(fromStockLocation);
  }
}

@Override
public StockMove createStockMove(
    Address fromAddress,
    Address toAddress,
    Company company,
    StockLocation fromStockLocation,
    StockLocation toStockLocation,
    LocalDate realDate,
    LocalDate estimatedDate,
    String note,
    int typeSelect)
    throws AxelorException {

  StockMove stockMove = new StockMove();

  if (stockMove.getStockMoveLineList() == null) {
    stockMove.setStockMoveLineList(new ArrayList<>());
  }

  stockMove.setFromAddress(fromAddress);
  stockMove.setToAddress(toAddress);
  stockMoveToolService.computeAddressStr(stockMove);
  stockMove.setCompany(company);
  stockMove.setStatusSelect(StockMoveRepository.STATUS_DRAFT);
  stockMove.setRealDate(realDate);
  stockMove.setEstimatedDate(estimatedDate);
  stockMove.setFromStockLocation(fromStockLocation);
  stockMove.setToStockLocation(toStockLocation);
  stockMove.setNote(note);
  stockMove.setPrintingSettings(
      Beans.get(TradingNameService.class).getDefaultPrintingSettings(null, company));

  stockMove.setTypeSelect(typeSelect);
  stockMove.setIsWithBackorder(company.getStockConfig().getIsWithBackorder());
  if (typeSelect == StockMoveRepository.TYPE_INCOMING) {
    stockMove.setIsWithReturnSurplus(company.getStockConfig().getIsWithReturnSurplus());
  }
  return stockMove;
}

@Override
public StockMove createStockMove(
    Address fromAddress,
    Address toAddress,
    Company company,
    Partner clientPartner,
    StockLocation fromStockLocation,
    StockLocation toStockLocation,
    LocalDate realDate,
    LocalDate estimatedDate,
    String note,
    ShipmentMode shipmentMode,
    FreightCarrierMode freightCarrierMode,
    Partner carrierPartner,
    Partner forwarderPartner,
    Incoterm incoterm,
    int typeSelect)
    throws AxelorException {

  StockMove stockMove =
      this.createStockMove(
          fromAddress,
          toAddress,
          company,
          fromStockLocation,
          toStockLocation,
          realDate,
          estimatedDate,
          note,
          typeSelect);
  stockMove.setPartner(clientPartner);
  stockMove.setShipmentMode(shipmentMode);
  stockMove.setFreightCarrierMode(freightCarrierMode);
  stockMove.setCarrierPartner(carrierPartner);
  stockMove.setForwarderPartner(forwarderPartner);
  if (appStockService.getAppStock().getIsIncotermEnabled()) {
    stockMove.setIncoterm(incoterm);
  }
  stockMove.setNote(note);
  stockMove.setIsIspmRequired(stockMoveToolService.getDefaultISPM(clientPartner, toAddress));

  return stockMove;
}

@Override
public void setOrigin(StockMove oldStockMove, StockMove newStockMove) {
  if (oldStockMove.getInventory() != null) {
    newStockMove.setInventory(oldStockMove.getInventory());
  } else if (oldStockMove.getStockCorrection() != null) {
    newStockMove.setStockCorrection(oldStockMove.getStockCorrection());
  }
}

protected boolean isNewBackorderLinePossible(StockMove stockMove) throws AxelorException {
  return stockMoveLineRepo
          .all()
          .filter("self.stockMove.id = :stockMoveId AND self.qty > self.realQty")
          .bind("stockMoveId", stockMove.getId())
          .count()
      > 0;
}

protected void computeTotalNetMass(
    StockMoveLine stockMoveLine, boolean massesRequiredForStockMoveLine) throws AxelorException {
  BigDecimal netMass = stockMoveLine.getNetMass();
  if (netMass.signum() != 0) {
    BigDecimal totalNetMass = netMass.multiply(stockMoveLine.getRealQty());
    stockMoveLine.setTotalNetMass(totalNetMass);
  } else if (massesRequiredForStockMoveLine) {
    throw new AxelorException(
        stockMoveLine.getStockMove(),
        TraceBackRepository.CATEGORY_NO_VALUE,
        I18n.get(StockExceptionMessage.STOCK_MOVE_18));
  }
}

protected void computeNetMass(
    StockMoveLine stockMoveLine, Unit endUnit, UnitConversionService unitConversionService)
    throws AxelorException {
  BigDecimal netMass = stockMoveLine.getNetMass();
  Product product = stockMoveLine.getProduct();
  if (netMass.signum() == 0) {
    Unit startUnit = product.getMassUnit();
    if (startUnit != null && endUnit != null) {
      netMass =
          unitConversionService.convert(
              startUnit, endUnit, product.getNetMass(), product.getNetMass().scale(), null);
      stockMoveLine.setNetMass(netMass);
    }
  }
}

protected void copyPlannedStockMoveLines(StockMove stockMove) {
  clearPlannedStockMoveLine(stockMove, true);

  final long stockMoveId = stockMove.getId();
  Query<StockMoveLine> query = getStockMoveLineQuery(stockMoveId);
  final StockMove[] stockMoveHolder = {stockMoveRepo.find(stockMoveId)};
  BatchProcessorHelper.of()
      .<StockMoveLine>forEachByQuery(
          query,
          line -> {
            StockMoveLine copy = stockMoveLineRepo.copy(line, false);
            copy.setArchived(true);
            copy.setPlannedStockMove(stockMoveHolder[0]);
            stockMoveLineRepo.save(copy);
          },
          () -> stockMoveHolder[0] = stockMoveRepo.find(stockMoveId));
}

protected void setStockMoveName(StockMove newStockMove, StockMove stockMove) {
  newStockMove.setName(
      stockMoveToolService.computeName(
          newStockMove,
          String.format(
              I18n.get(StockExceptionMessage.STOCK_MOVE_8),
              newStockMove.getStockMoveSeq(),
              stockMove.getStockMoveSeq())));
}

protected void setStockMoveTypeSelect(StockMove newStockMove, StockMove stockMove) {
  switch (stockMove.getTypeSelect()) {
    case StockMoveRepository.TYPE_INCOMING:
      newStockMove.setTypeSelect(StockMoveRepository.TYPE_OUTGOING);
      break;
    case StockMoveRepository.TYPE_OUTGOING:
      newStockMove.setTypeSelect(StockMoveRepository.TYPE_INCOMING);
      break;
    default:
      newStockMove.setTypeSelect(StockMoveRepository.TYPE_INTERNAL);
      break;
  }
}

protected StockMoveLine copyStockMoveLine(StockMoveLine stockMoveLine, boolean split) {
  StockMoveLine newStockMoveLine = stockMoveLineRepo.copy(stockMoveLine, false);

  if (split) {
    newStockMoveLine.setQty(stockMoveLine.getRealQty().subtract(stockMoveLine.getQty()));
    newStockMoveLine.setRealQty(newStockMoveLine.getQty());
  } else {
    newStockMoveLine.setQty(stockMoveLine.getRealQty());
    newStockMoveLine.setRealQty(stockMoveLine.getRealQty());
  }
  return newStockMoveLine;
}

protected Set<Long> getSiblingAssignedTrackingNumberIds(
    StockMoveLine stockMoveLine, Product product) {
  StockMove stockMove = stockMoveLine.getStockMove();
  if (stockMove == null || CollectionUtils.isEmpty(stockMove.getStockMoveLineList())) {
    return new HashSet<>();
  }
  return stockMove.getStockMoveLineList().stream()
      .filter(line -> line != stockMoveLine)
      .filter(line -> product.equals(line.getProduct()))
      .map(StockMoveLine::getTrackingNumber)
      .filter(Objects::nonNull)
      .map(TrackingNumber::getId)
      .filter(Objects::nonNull)
      .collect(Collectors.toSet());
}

protected void checkSplitConditions(StockMoveLine stockMoveLine) throws AxelorException {
  StockMove stockMove = stockMoveLine.getStockMove();
  if (stockMove != null) {
    Integer statusSelect = stockMove.getStatusSelect();
    List<Integer> authorizedStatus = new ArrayList<>();
    authorizedStatus.add(StockMoveRepository.STATUS_DRAFT);
    authorizedStatus.add(StockMoveRepository.STATUS_PLANNED);
    if (!authorizedStatus.contains(statusSelect)) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          I18n.get(StockExceptionMessage.SPLIT_MOVE_LINE_WRONG_STATUS));
    }

    if (stockMove.getTypeSelect().equals(StockMoveRepository.TYPE_INTERNAL)) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          I18n.get(StockExceptionMessage.SPLIT_MOVE_LINE_WRONG_TYPE));
    }
  }

  BigDecimal realQty = stockMoveLine.getRealQty();
  BigDecimal qty = stockMoveLine.getQty();
  if (realQty != null && (realQty.signum() < 1 || realQty.compareTo(qty) >= 0)) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.SPLIT_MOVE_LINE_WRONG_REAL_QTY));
  }
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void splitIntoFulfilledMoveLineAndUnfulfilledOne(StockMoveLine stockMoveLine)
    throws AxelorException {
  checkSplitConditions(stockMoveLine);
  StockMoveLine newStockMoveLine = stockMoveLineRepository.copy(stockMoveLine, false);
  this.updateStockMoveLinesOfSplit(newStockMoveLine, stockMoveLine);
  stockMoveLineRepository.save(newStockMoveLine);
}

protected void processTrackingNumberSplit(
    StockMove stockMove, StockMoveLine stockMoveLine, int splitType) throws AxelorException {
  Product product = stockMoveLine.getProduct();
  if (product == null) {
    return;
  }
  TrackingNumberConfiguration trackingNumberConfiguration =
      (TrackingNumberConfiguration)
          productCompanyService.get(
              product, "trackingNumberConfiguration", stockMove.getCompany());

  assignOrGenerateTrackingNumber(
      stockMoveLine, stockMove, product, trackingNumberConfiguration, splitType);
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void splitStockMoveLineByTrackingNumber(StockMove stockMove) throws AxelorException {
  Integer type = stockMove.getTypeSelect();
  if (type == StockMoveRepository.TYPE_INTERNAL || stockMove.getId() == null) {
    return;
  }

  ThrowConsumer<StockMoveLine, AxelorException> processor =
      stockMoveLine ->
          processTrackingNumberSplit(
              stockMoveLine.getStockMove(),
              stockMoveLine,
              type == StockMoveRepository.TYPE_OUTGOING ? TYPE_SALES : TYPE_PURCHASES);

  Query<StockMoveLine> query =
      stockMoveLineRepository
          .all()
          .filter("self.stockMove.id = :stockMoveId AND self.id > :lastSeenId")
          .bind("stockMoveId", stockMove.getId())
          .order("id");

  BatchProcessorHelper.of().<StockMoveLine, AxelorException>forEachByQuery(query, processor);
}

@Override
public List<TrackingNumber> getAvailableTrackingNumbers(StockMoveLine stockMoveLine) {
  String domain =
      "self.product.id = :productId"
          + " AND (self.id in (select stockLocationLine.trackingNumber.id from StockLocationLine stockLocationLine"
          + " join StockLocation sl on sl.id = stockLocationLine.detailsStockLocation.id WHERE sl.id = :fromStockLocationId"
          + " AND coalesce(stockLocationLine.currentQty, 0) != 0)"
          + " OR self.id not in (select stockLocationLine.trackingNumber.id from StockLocationLine stockLocationLine"
          + " join StockLocation sl on sl.id = stockLocationLine.detailsStockLocation.id))";
  return trackingNumberRepo
      .all()
      .filter(domain)
      .bind("productId", stockMoveLine.getProduct().getId())
      .bind("fromStockLocationId", stockMoveLine.getFromStockLocation().getId())
      .fetch();
}

@Override
public Map<String, Object> setAvailableStatus(StockMoveLine stockMoveLine, StockMove stockMove)
    throws AxelorException {
  if (stockMove != null) {
    this.updateAvailableQty(stockMoveLine, stockMoveLine.getFromStockLocation());
  }
  Map<String, Object> availabilityMap = new HashMap<>();
  if (stockMoveLine.getProduct() != null
      && !stockMoveLine
          .getProduct()
          .getProductTypeSelect()
          .equals(ProductRepository.PRODUCT_TYPE_SERVICE)) {
    BigDecimal availableQty = stockMoveLine.getAvailableQty();
    BigDecimal availableQtyForProduct = stockMoveLine.getAvailableQtyForProduct();
    BigDecimal realQty = stockMoveLine.getRealQty();

    if (availableQty.compareTo(realQty) >= 0 || !stockMoveLine.getProduct().getStockManaged()) {
      stockMoveLine.setAvailableStatus(I18n.get("Available"));
      stockMoveLine.setAvailableStatusSelect(StockMoveLineRepository.STATUS_AVAILABLE);
      availabilityMap.put("availability", stockMoveLine.getAvailableStatus());
    } else if (availableQtyForProduct.compareTo(realQty) >= 0) {
      stockMoveLine.setAvailableStatus(I18n.get("Av. for product"));
      stockMoveLine.setAvailableStatusSelect(
          StockMoveLineRepository.STATUS_AVAILABLE_FOR_PRODUCT);
      availabilityMap.put("availability", stockMoveLine.getAvailableStatus());
    } else if (availableQty.compareTo(realQty) < 0
        && availableQtyForProduct.compareTo(realQty) < 0) {
      BigDecimal missingQty = computeMissingQty(stockMoveLine);
      stockMoveLine.setAvailableStatus(
          I18n.get("Missing")
              + " ("
              + missingQty.setScale(appBaseService.getNbDecimalDigitForQty())
              + ")");
      stockMoveLine.setAvailableStatusSelect(StockMoveLineRepository.STATUS_MISSING);
      availabilityMap.put("availability", I18n.get("Missing"));
      availabilityMap.put("missingQty", missingQty);
    }
  }
  return availabilityMap;
}

@Override
@Transactional
public void splitStockMoveLineByTrackingNumber(
    StockMoveLine stockMoveLine, List<LinkedHashMap<String, Object>> trackingNumbers)
    throws AxelorException {
  //    boolean draft = true;
  //    if (stockMoveLine.getStockMove() != null
  //        && stockMoveLine.getStockMove().getStatusSelect() ==
  // StockMoveRepository.STATUS_PLANNED) {
  //      draft = false;
  //    }
  BigDecimal totalSplitQty = BigDecimal.ZERO;
  boolean isAlreadyExceeded = false;
  for (LinkedHashMap<String, Object> trackingNumberItem : trackingNumbers) {
    BigDecimal counter = new BigDecimal(trackingNumberItem.get("counter").toString());
    if (counter.compareTo(BigDecimal.ZERO) == 0) {
      continue;
    }

    TrackingNumber trackingNumber =
        trackingNumberRepo
            .all()
            .filter(
                "self.product.id = ?1 and self.trackingNumberSeq = ?2",
                stockMoveLine.getProduct(),
                trackingNumberItem.get("trackingNumberSeq").toString())
            .fetchOne();

    if (trackingNumber == null) {
      trackingNumber = new TrackingNumber();
      trackingNumber.setTrackingNumberSeq(trackingNumberItem.get("trackingNumberSeq").toString());
      boolean hasWarranty =
          trackingNumberItem.get("hasWarranty") != null
              && Boolean.parseBoolean(trackingNumberItem.get("hasWarranty").toString());
      trackingNumber.setHasWarranty(hasWarranty);
      if (trackingNumberItem.get("warrantyExpirationDate") != null) {
        trackingNumber.setWarrantyExpirationDate(
            LocalDate.parse(trackingNumberItem.get("warrantyExpirationDate").toString()));
      }
      boolean isPerishable =
          trackingNumberItem.get("isPerishable") != null
              && Boolean.parseBoolean(trackingNumberItem.get("isPerishable").toString());
      trackingNumber.setIsPerishable(isPerishable);
      if (trackingNumberItem.get("perishableExpirationDate") != null) {
        trackingNumber.setPerishableExpirationDate(
            LocalDate.parse(trackingNumberItem.get("perishableExpirationDate").toString()));
      }
      if (trackingNumberItem.get("origin") != null) {
        trackingNumber.setOrigin(trackingNumberItem.get("origin").toString());
      }
      if (trackingNumberItem.get("note") != null) {
        trackingNumber.setNote(trackingNumberItem.get("note").toString());
      }
      if (trackingNumberItem.get("serialNbr") != null) {
        trackingNumber.setSerialNumber(trackingNumberItem.get("serialNbr").toString());
      }
      trackingNumber.setProduct(stockMoveLine.getProduct());

      if (stockMoveLine.getProduct() != null) {
        // In case of barcode generation, retrieve the one set on tracking number configuration
        AppStock appStock = appStockService.getAppStock();
        TrackingNumberConfiguration trackingNumberConfiguration =
            (TrackingNumberConfiguration)
                productCompanyService.get(
                    stockMoveLine.getProduct(),
                    "trackingNumberConfiguration",
                    Optional.ofNullable(stockMoveLine.getStockMove())
                        .map(StockMove::getCompany)
                        .orElse(null));
        if (appStock != null
            && appStock.getActivateTrackingNumberBarCodeGeneration()
            && trackingNumberConfiguration != null) {
          if (appStock.getEditTrackingNumberBarcodeType()) {
            trackingNumber.setBarcodeTypeConfig(
                trackingNumberConfiguration.getBarcodeTypeConfig());
          } else {
            trackingNumber.setBarcodeTypeConfig(appStock.getTrackingNumberBarcodeTypeConfig());
          }
          if (trackingNumberConfiguration.getUseTrackingNumberSeqAsSerialNbr()) {
            trackingNumber.setSerialNumber(trackingNumber.getTrackingNumberSeq());
          }
          // It will launch barcode generation
          trackingNumberRepo.save(trackingNumber);
        }
      }
    }

    StockMoveLine newStockMoveLine = stockMoveLineRepository.copy(stockMoveLine, true);
    boolean isExceeded = totalSplitQty.add(counter).compareTo(stockMoveLine.getQty()) > 0;
    BigDecimal remainder = stockMoveLine.getQty().subtract(totalSplitQty);
    totalSplitQty = totalSplitQty.add(counter);
    if (!isAlreadyExceeded) {
      if (isExceeded) {
        newStockMoveLine.setQty(remainder);
        isAlreadyExceeded = true;
      } else {
        newStockMoveLine.setQty(counter);
      }
    } else {
      newStockMoveLine.setQty(BigDecimal.ZERO);
    }

    newStockMoveLine.setRealQty(counter);
    newStockMoveLine.setTrackingNumber(trackingNumber);
    newStockMoveLine.setStockMove(stockMoveLine.getStockMove());
    stockMoveLineRepository.save(newStockMoveLine);
  }

  if (totalSplitQty.compareTo(stockMoveLine.getQty()) < 0) {
    BigDecimal remainingQty = stockMoveLine.getQty().subtract(totalSplitQty);
    stockMoveLine.setQty(remainingQty);
    stockMoveLine.setRealQty(remainingQty);
    stockMoveLine.setTrackingNumber(null);
    stockMoveLine.setStockMove(stockMoveLine.getStockMove());
  } else {
    stockMoveLineRepository.remove(stockMoveLine);
  }

  StockMove stockMove = stockMoveLine.getStockMove();
  stockMoveService.updateLocations(stockMove, stockMove.getStatusSelect());
}

@Override
public boolean checkMassesRequired(StockMove stockMove, StockMoveLine stockMoveLine) {
  Address fromAddress = stockMoveToolService.getFromAddress(stockMove, stockMoveLine);
  Address toAddress = stockMoveToolService.getToAddress(stockMove, stockMoveLine);

  Country fromCountry = fromAddress != null ? fromAddress.getCountry() : null;
  Country toCountry = toAddress != null ? toAddress.getCountry() : null;

  return fromCountry != null
      && toCountry != null
      && !fromCountry.equals(toCountry)
      && stockMoveLine.getProduct() != null
      && fromCountry.getEconomicArea() != null
      && fromCountry.getEconomicArea().equals(toCountry.getEconomicArea())
      && stockMoveLine.getProduct().getUsedInDEB();
}

@Override
public void checkTrackingNumber(StockMove stockMove) throws AxelorException {
  final Set<String> productsWithErrors = new HashSet<>();

  BatchProcessorHelper batch = BatchProcessorHelper.builder().flushAfterBatch(false).build();

  Query<StockMoveLine> query =
      stockMoveLineRepository
          .all()
          .filter(
              "self.stockMove.id = :stockMoveId AND self.product IS NOT NULL AND self.id > :lastSeenId")
          .bind("stockMoveId", stockMove.getId())
          .order("id");

  batch.<StockMoveLine, AxelorException>forEachByQuery(
      query,
      sml -> {
        final Product product = sml.getProduct();
        final TrackingNumberConfiguration trackingNumberConfiguration =
            (TrackingNumberConfiguration)
                productCompanyService.get(
                    product, "trackingNumberConfiguration", sml.getStockMove().getCompany());

        // Require tracking when: purchase OR production OR (sale & outgoing)
        final boolean trackingRequired =
            trackingNumberConfiguration != null
                && (Boolean.TRUE.equals(
                        trackingNumberConfiguration.getIsPurchaseTrackingManaged())
                    || Boolean.TRUE.equals(
                        trackingNumberConfiguration.getIsProductionTrackingManaged())
                    || (Boolean.TRUE.equals(
                            trackingNumberConfiguration.getIsSaleTrackingManaged())
                        && stockMove.getTypeSelect() == StockMoveRepository.TYPE_OUTGOING));

        if (trackingRequired
            && sml.getTrackingNumber() == null
            && sml.getRealQty().compareTo(BigDecimal.ZERO) != 0) {
          productsWithErrors.add(product.getFullName());
        }
      });

  if (!productsWithErrors.isEmpty()) {
    final String productWithErrorsStr =
        productsWithErrors.stream().collect(Collectors.joining(", "));
    throw new AxelorException(
        TraceBackRepository.CATEGORY_NO_VALUE,
        I18n.get(StockExceptionMessage.STOCK_MOVE_LINE_MUST_FILL_TRACKING_NUMBER),
        productWithErrorsStr);
  }
}

@Override
public void checkExpirationDates(StockMove stockMove) {
  final Set<String> productsWithExpired = new LinkedHashSet<>();
  Company company = Beans.get(CompanyRepository.class).find(stockMove.getCompany().getId());
  final LocalDate today = appBaseService.getTodayDate(company);

  BatchProcessorHelper batch = BatchProcessorHelper.builder().flushAfterBatch(false).build();

  Query<StockMoveLine> query =
      stockMoveLineRepository
          .all()
          .filter(
              "self.stockMove.id = :stockMoveId "
                  + "AND self.trackingNumber IS NOT NULL "
                  + "AND self.trackingNumber.checkExpirationDateAtStockMoveRealization = true "
                  + "AND self.id > :lastSeenId")
          .bind("stockMoveId", stockMove.getId())
          .order("id");

  batch.<StockMoveLine>forEachByQuery(
      query,
      sml -> {
        final TrackingNumber tn = sml.getTrackingNumber();

        boolean warrantyExpired =
            Boolean.TRUE.equals(tn.getHasWarranty())
                && tn.getWarrantyExpirationDate() != null
                && tn.getWarrantyExpirationDate().isBefore(today);

        boolean perishableExpired =
            Boolean.TRUE.equals(tn.getIsPerishable())
                && tn.getPerishableExpirationDate() != null
                && tn.getPerishableExpirationDate().isBefore(today);

        if (warrantyExpired || perishableExpired) {
          String name =
              Optional.ofNullable(tn.getProduct())
                  .map(Product::getName)
                  .filter(Objects::nonNull)
                  .orElseGet(sml::getProductName);
          productsWithExpired.add(name);
        }
      });

  if (!productsWithExpired.isEmpty()) {
    String errorStr = String.join(", ", productsWithExpired);
    TraceBackService.trace(
        new AxelorAlertException(
            stockMove,
            TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
            I18n.get(StockExceptionMessage.STOCK_MOVE_LINE_EXPIRED_PRODUCTS),
            errorStr));
  }
}

@Override
public void checkConformitySelection(StockMove stockMove) throws AxelorException {

  if (!appStockService.getAppStock().getRequireToFillConformityOnReceipt()) {
    return;
  }

  final Map<Long, String> productsWithErrors = new LinkedHashMap<>();

  final long smId = stockMove.getId();
  final StockMove[] smHolder = {stockMoveRepository.find(smId)};

  BatchProcessorHelper batch = BatchProcessorHelper.builder().flushAfterBatch(false).build();

  Query<StockMoveLine> query =
      stockMoveLineRepository
          .all()
          .filter(
              "self.stockMove.id = :stockMoveId AND self.product IS NOT NULL AND self.id > :lastSeenId")
          .bind("stockMoveId", stockMove.getId())
          .order("id");

  batch.<StockMoveLine, AxelorException>forEachByQuery(
      query,
      sml -> checkLineConformity(sml, smHolder[0], productsWithErrors),
      () -> smHolder[0] = stockMoveRepository.find(smId));

  if (!productsWithErrors.isEmpty()) {
    String productsWithErrorStr =
        productsWithErrors.values().stream().collect(Collectors.joining(", "));
    throw new AxelorException(
        stockMove,
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(StockExceptionMessage.STOCK_MOVE_LINE_MUST_FILL_CONFORMITY),
        productsWithErrorStr);
  }
}

protected void checkLineConformity(
    StockMoveLine stockMoveLine, StockMove stockMove, Map<Long, String> productsWithErrors)
    throws AxelorException {
  final Product product = stockMoveLine.getProduct();
  Object type = productCompanyService.get(product, "productTypeSelect", stockMove.getCompany());
  if (!ProductRepository.PRODUCT_TYPE_STORABLE.equals(type)) {
    return;
  }
  if (checkConformitySelection(stockMoveLine, stockMove)) {
    productsWithErrors.putIfAbsent(
        product.getId(),
        (String) productCompanyService.get(product, "name", stockMove.getCompany()));
  }
}

@Override
public boolean checkConformitySelection(StockMoveLine stockMoveLine, StockMove stockMove)
    throws AxelorException {
  Product product = stockMoveLine.getProduct();
  // check if the product configuration forces to select a conformity
  if (product == null) {
    return false;
  }
  Boolean controlOnReceipt =
      (Boolean) productCompanyService.get(product, "controlOnReceipt", stockMove.getCompany());
  // check the stock move type
  if (!controlOnReceipt
      || stockMove.getTypeSelect() != StockMoveRepository.TYPE_INCOMING
      || stockMoveLine.getRealQty().compareTo(BigDecimal.ZERO) == 0) {
    return false;
  }

  // check the conformity
  return stockMoveLine.getConformitySelect() <= StockMoveLineRepository.CONFORMITY_NONE;
}

@Override
public void assignTrackingNumber(
    StockMoveLine stockMoveLine, Product product, Set<Long> excludedTrackingNumberIds)
    throws AxelorException {
  Set<Long> trackingNumberIdsToExclude =
      excludedTrackingNumberIds != null ? excludedTrackingNumberIds : new HashSet<>();
  List<? extends StockLocationLine> stockLocationLineList =
      this.getStockLocationLines(
          product, stockMoveLine.getFromStockLocation(), trackingNumberIdsToExclude);

  if (stockLocationLineList != null) {
    for (StockLocationLine stockLocationLine : stockLocationLineList) {
      TrackingNumber trackingNumber = stockLocationLine.getTrackingNumber();
      if (trackingNumber == null
          || trackingNumber.getId() == null
          || trackingNumberIdsToExclude.contains(trackingNumber.getId())) {
        continue;
      }

      BigDecimal qty =
          unitConversionService.convert(
              stockLocationLine.getUnit(),
              stockMoveLine.getUnit(),
              stockLocationLine.getFutureQty(),
              appBaseService.getNbDecimalDigitForQty(),
              product);
      if (stockMoveLine.getQty().compareTo(qty) > 0) {
        this.splitStockMoveLine(stockMoveLine, qty, trackingNumber);
      } else {
        stockMoveLine.setTrackingNumber(trackingNumber);
      }
      trackingNumberIdsToExclude.add(trackingNumber.getId());
      if (stockMoveLine.getTrackingNumber() != null) {
        break;
      }
    }
  }
}

@Override
public void assignTrackingNumber(StockMoveLine stockMoveLine, Product product)
    throws AxelorException {
  assignTrackingNumber(
      stockMoveLine, product, getSiblingAssignedTrackingNumberIds(stockMoveLine, product));
}

@Transactional(rollbackOn = {Exception.class})
protected void fillOriginTrackingNumber(StockMoveLine stockMoveLine) {
  TrackingNumber trackingNumber = stockMoveLine.getTrackingNumber();
  if (trackingNumber != null) {
    trackingNumber.setOriginMoveTypeSelect(0);
    trackingNumber.setOriginStockMoveLine(stockMoveLine);

    trackingNumberRepo.save(trackingNumber);
  }
}

protected void splitStockMoveLineByQtyByTracking(
    StockMoveLine stockMoveLine, BigDecimal qtyByTracking) throws AxelorException {
  if (qtyByTracking == null || qtyByTracking.compareTo(BigDecimal.ZERO) <= 0) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(StockExceptionMessage.STOCK_MOVE_QTY_BY_TRACKING));
  }

  int splitCounter = 0;
  while (stockMoveLine.getQty().compareTo(qtyByTracking) > 0) {
    BigDecimal minQty = stockMoveLine.getQty().min(qtyByTracking);
    StockMoveLine newStockMoveLine = this.splitStockMoveLine(stockMoveLine, minQty, null);
    stockMoveLineRepository.save(newStockMoveLine);
    splitCounter++;

    if (splitCounter == 1000) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          I18n.get(StockExceptionMessage.STOCK_MOVE_TOO_MANY_ITERATION));
    }
  }
}

@Override
public void generateTrackingNumber(
    StockMoveLine stockMoveLine,
    TrackingNumberConfiguration trackingNumberConfiguration,
    Product product,
    BigDecimal qtyByTracking)
    throws AxelorException {

  int generateTrakingNumberCounter = 0;

  StockMove stockMove = stockMoveLine.getStockMove();

  if (qtyByTracking.compareTo(BigDecimal.ZERO) <= 0) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(StockExceptionMessage.STOCK_MOVE_QTY_BY_TRACKING));
  }
  Partner supplier =
      stockMove.getTypeSelect() == StockMoveRepository.TYPE_INCOMING
              && !stockMove.getIsReversion()
          ? stockMove.getPartner()
          : null;
  Integer maxSequence = 0;
  while (stockMoveLine.getQty().compareTo(qtyByTracking) > 0) {

    BigDecimal minQty = stockMoveLine.getQty().min(qtyByTracking);

    StockMoveLine newStockMoveLine =
        this.splitStockMoveLine(
            stockMoveLine,
            minQty,
            trackingNumberCreateService.getTrackingNumber(
                product,
                stockMove.getCompany(),
                stockMove.getEstimatedDate(),
                stockMove.getOrigin(),
                supplier));
    this.fillOriginTrackingNumber(newStockMoveLine);
    maxSequence = newStockMoveLine.getSequence();
    generateTrakingNumberCounter++;
    if (generateTrakingNumberCounter == 1000) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          I18n.get(StockExceptionMessage.STOCK_MOVE_TOO_MANY_ITERATION));
    }
  }
  if (stockMoveLine.getTrackingNumber() == null) {
    stockMoveLine.setTrackingNumber(
        trackingNumberCreateService.getTrackingNumber(
            product,
            stockMove.getCompany(),
            stockMove.getEstimatedDate(),
            stockMove.getOrigin(),
            supplier));
    fillOriginTrackingNumber(stockMoveLine);
    stockMoveLine.setSequence(maxSequence + 1);
  }
}

@Override
public StockMoveLine assignOrGenerateTrackingNumber(
    StockMoveLine stockMoveLine,
    StockMove stockMove,
    Product product,
    TrackingNumberConfiguration trackingNumberConfiguration,
    int type)
    throws AxelorException {

  if (trackingNumberConfiguration != null) {

    switch (type) {
      case StockMoveLineService.TYPE_SALES:
        if (trackingNumberConfiguration.getIsSaleTrackingManaged()) {
          if (trackingNumberConfiguration.getGenerateSaleAutoTrackingNbr()) {
            // Générer numéro de série si case cochée
            this.generateTrackingNumber(
                stockMoveLine,
                trackingNumberConfiguration,
                product,
                trackingNumberConfiguration.getSaleQtyByTracking());
          } else if (trackingNumberConfiguration.getHasSaleAutoSelectTrackingNbr()) {
            // Rechercher le numéro de suivi d'apèrs FIFO/LIFO
            this.assignTrackingNumber(stockMoveLine, product);
          }
        }
        break;
      case StockMoveLineService.TYPE_PURCHASES:
        if (trackingNumberConfiguration.getIsPurchaseTrackingManaged()) {
          BigDecimal purchaseQtyByTracking =
              trackingNumberConfiguration.getPurchaseQtyByTracking();
          if (trackingNumberConfiguration.getGeneratePurchaseAutoTrackingNbr()) {
            // Générer numéro de série si case cochée
            this.generateTrackingNumber(
                stockMoveLine, trackingNumberConfiguration, product, purchaseQtyByTracking);
          } else {
            this.splitStockMoveLineByQtyByTracking(stockMoveLine, purchaseQtyByTracking);
          }
        }
        break;
      case StockMoveLineService.TYPE_OUT_PRODUCTIONS:
        if (trackingNumberConfiguration.getIsProductionTrackingManaged()
            && trackingNumberConfiguration.getGenerateProductionAutoTrackingNbr()) {
          // Générer numéro de série si case cochée
          this.generateTrackingNumber(
              stockMoveLine,
              trackingNumberConfiguration,
              product,
              trackingNumberConfiguration.getProductionQtyByTracking());
        }
        break;
      case StockMoveLineService.TYPE_IN_PRODUCTIONS:
        if (trackingNumberConfiguration.getHasProductAutoSelectTrackingNbr()) {
          // searching for the tracking number using FIFO or LIFO
          this.assignTrackingNumber(stockMoveLine, product);
        }
        break;
      case StockMoveLineService.TYPE_WASTE_PRODUCTIONS:
        break;
      default:
        break;
    }
  }
  return stockMoveLine;
}

protected void updateStockMoveLinesOfSplit(
    StockMoveLine unfulfilledStockMoveLine, StockMoveLine fulfilledStockMoveLine) {
  BigDecimal realQty = fulfilledStockMoveLine.getRealQty();
  unfulfilledStockMoveLine.setQty(fulfilledStockMoveLine.getQty().subtract(realQty));
  fulfilledStockMoveLine.setQty(realQty);
  unfulfilledStockMoveLine.setTotalNetMass(BigDecimal.ZERO);
  unfulfilledStockMoveLine.setRealQty(BigDecimal.ZERO);
  unfulfilledStockMoveLine.setStockMove(fulfilledStockMoveLine.getStockMove());
  unfulfilledStockMoveLine.setConformitySelect(0);
}

protected BigDecimal computeMissingQty(StockMoveLine stockMoveLine) throws AxelorException {
  TrackingNumberConfiguration trackingNumberConfiguration =
      (TrackingNumberConfiguration)
          productCompanyService.get(
              stockMoveLine.getProduct(),
              "trackingNumberConfiguration",
              Optional.ofNullable(stockMoveLine.getStockMove())
                  .map(StockMove::getCompany)
                  .orElse(null));

  if (trackingNumberConfiguration != null) {
    return stockMoveLine.getAvailableQtyForProduct().subtract(stockMoveLine.getRealQty());
  } else {
    return stockMoveLine.getAvailableQty().subtract(stockMoveLine.getRealQty());
  }
}

@Override
public void updateAvailableQty(StockMoveLine stockMoveLine, StockLocation stockLocation)
    throws AxelorException {
  BigDecimal availableQty = BigDecimal.ZERO;
  BigDecimal availableQtyForProduct = BigDecimal.ZERO;
  Unit targetUnit = getStockUnit(stockMoveLine);

  if (stockMoveLine.getProduct() != null && stockLocation != null) {
    TrackingNumberConfiguration trackingNumberConfiguration =
        (TrackingNumberConfiguration)
            productCompanyService.get(
                stockMoveLine.getProduct(),
                "trackingNumberConfiguration",
                Optional.ofNullable(stockMoveLine.getStockMove())
                    .map(StockMove::getCompany)
                    .orElse(null));
    if (trackingNumberConfiguration != null) {

      if (stockMoveLine.getTrackingNumber() != null) {
        StockLocationLine stockLocationLine =
            stockLocationLineFetchService.getDetailLocationLine(
                stockLocation, stockMoveLine.getProduct(), stockMoveLine.getTrackingNumber());

        if (stockLocationLine != null) {
          availableQty =
              computeAvailableQtyInMoveLineUnit(stockMoveLine, stockLocationLine, targetUnit);
        }
      }

      if (availableQty.compareTo(stockMoveLine.getRealQty()) < 0) {
        StockLocationLine stockLocationLineForProduct =
            stockLocationLineFetchService.getStockLocationLine(
                stockLocation, stockMoveLine.getProduct());

        if (stockLocationLineForProduct != null) {
          availableQtyForProduct =
              computeAvailableQtyInMoveLineUnit(
                  stockMoveLine, stockLocationLineForProduct, targetUnit);
        }
      }
    } else {
      StockLocationLine stockLocationLine =
          stockLocationLineFetchService.getStockLocationLine(
              stockLocation, stockMoveLine.getProduct());

      if (stockLocationLine != null) {
        availableQty =
            computeAvailableQtyInMoveLineUnit(stockMoveLine, stockLocationLine, targetUnit);
      }
    }
  }
  stockMoveLine.setAvailableQty(availableQty);
  stockMoveLine.setAvailableQtyForProduct(availableQtyForProduct);
}

@Override
public StockMoveLine splitStockMoveLine(
    StockMoveLine stockMoveLine, BigDecimal qty, TrackingNumber trackingNumber)
    throws AxelorException {

  StockMoveLine newStockMoveLine =
      this.createStockMoveLine(
          stockMoveLine.getProduct(),
          stockMoveLine.getProductName(),
          stockMoveLine.getDescription(),
          qty,
          stockMoveLine.getUnitPriceUntaxed(),
          stockMoveLine.getUnitPriceTaxed(),
          stockMoveLine.getCompanyUnitPriceUntaxed(),
          stockMoveLine.getCompanyPurchasePrice(),
          stockMoveLine.getUnit(),
          stockMoveLine.getStockMove(),
          trackingNumber,
          stockMoveLine.getFromStockLocation(),
          stockMoveLine.getToStockLocation());

  StockMove stockMove = newStockMoveLine.getStockMove();
  if (stockMove != null) {
    if (stockMove.getId() != null) {
      stockMoveLineRepository.save(newStockMoveLine);
    } else {
      stockMove.addStockMoveLineListItem(newStockMoveLine);
    }
  }

  stockMoveLine.setQty(stockMoveLine.getQty().subtract(qty));

  this.fillRealQuantities(
      stockMoveLine, stockMoveLine.getStockMove(), stockMoveLine.getRealQty().subtract(qty));

  return newStockMoveLine;
}

@Override
public List<? extends StockLocationLine> getStockLocationLines(
    Product product, StockLocation stockLocation, Set<Long> excludedTrackingNumberIds)
    throws AxelorException {
  TrackingNumberConfiguration trackingNumberConfiguration =
      (TrackingNumberConfiguration)
          productCompanyService.get(
              product,
              "trackingNumberConfiguration",
              Optional.of(stockLocation.getCompany()).orElse(null));
  List<? extends StockLocationLine> stockLocationLineList =
      Beans.get(StockLocationLineRepository.class)
          .all()
          .filter(
              "self.product = ?1 AND self.futureQty > 0 AND self.trackingNumber IS NOT NULL AND self.detailsStockLocation = ?2"
                  + trackingNumberService.getOrderMethod(trackingNumberConfiguration),
              product,
              stockLocation)
          .fetch();

  if (CollectionUtils.isEmpty(stockLocationLineList)
      || CollectionUtils.isEmpty(excludedTrackingNumberIds)) {
    return stockLocationLineList;
  }

  return stockLocationLineList.stream()
      .filter(
          stockLocationLine ->
              stockLocationLine.getTrackingNumber() == null
                  || stockLocationLine.getTrackingNumber().getId() == null
                  || !excludedTrackingNumberIds.contains(
                      stockLocationLine.getTrackingNumber().getId()))
      .toList();
}

@Override
public List<? extends StockLocationLine> getStockLocationLines(
