@Override
@Transactional(rollbackOn = {Exception.class})
public Optional<StockMove> copyAndSplitStockMoveReverse(
    StockMove stockMove, List<StockMoveLine> stockMoveLines, boolean split)
    throws AxelorException {

  stockMoveLines = MoreObjects.firstNonNull(stockMoveLines, Collections.emptyList());
  StockMove newStockMove =
      createStockMove(
          stockMove.getToAddress(),
          stockMove.getFromAddress(),
          stockMove.getCompany(),
          stockMove.getPartner(),
          stockMove.getToStockLocation(),
          stockMove.getFromStockLocation(),
          null,
          stockMove.getEstimatedDate(),
          null,
          null,
          null,
          null,
          null,
          stockMove.getIncoterm(),
          0);

  copyStockMoveLines(newStockMove, stockMoveLines, split);

  List<StockMoveLine> newStockMoveLineList = newStockMove.getStockMoveLineList();

  if (ObjectUtils.isEmpty(newStockMoveLineList)) {
    return Optional.empty();
  }

  reverseStockMoveLineStockLocation(newStockMoveLineList);

  fillNewStockMoveFields(newStockMove, stockMove);

  return Optional.of(stockMoveRepo.save(newStockMove));
}

@Override
public Optional<StockMove> copyAndSplitStockMoveReverse(StockMove stockMove, boolean split)
    throws AxelorException {
  return copyAndSplitStockMoveReverse(stockMove, stockMove.getStockMoveLineList(), split);
}

@Override
public Optional<StockMove> copyAndSplitStockMove(StockMove stockMove) throws AxelorException {

  if (stockMove == null || !isNewBackorderLinePossible(stockMove)) {
    return Optional.empty();
  }

  StockMove newStockMove = stockMoveRepo.copy(stockMove, false);

  setOrigin(stockMove, newStockMove);
  newStockMove.setOrigin(stockMove.getOrigin());
  newStockMove.setRealDate(null);
  newStockMove.setStockMoveSeq(
      stockMoveToolService.getSequenceStockMove(
          newStockMove.getTypeSelect(), newStockMove.getCompany(), stockMove));
  newStockMove.setName(
      stockMoveToolService.computeName(
          newStockMove,
          newStockMove.getStockMoveSeq()
              + " "
              + I18n.get(StockExceptionMessage.STOCK_MOVE_7)
              + " "
              + stockMove.getStockMoveSeq()
              + " )"));
  newStockMove.setExTaxTotal(stockMoveToolService.compute(newStockMove));
  newStockMove.setShipmentMode(null);
  newStockMove.setFreightCarrierMode(null);
  newStockMove.setCarrierPartner(null);
  newStockMove.setForwarderPartner(null);
  newStockMove.setIncoterm(null);
  newStockMove.setTrackingNumber(null);
  newStockMove.setModeOfTransport(null);
  newStockMove.setNumOfPackages(0);
  newStockMove.setNumOfPalettes(0);
  newStockMove.setGrossMass(BigDecimal.ZERO);
  newStockMove.setIsIspmRequired(false);
  newStockMove.setIsNeedingConformityCertificate(false);
  newStockMove.setSignatoryUser(null);
  newStockMove.setIsConformityCertifSigned(false);
  newStockMove.setElectronicSignature(null);
  newStockMove.setStockMoveOrigin(stockMove);
  newStockMove = stockMoveRepo.save(newStockMove);
  stockMove.setBackorderId(newStockMove.getId());
  stockMoveRepo.save(stockMove);
  final StockMove[] newStockMoveHolder = new StockMove[] {newStockMove};
  BatchProcessorHelper.of()
      .<StockMoveLine, AxelorException>forEachByQuery(
          getStockMoveLineQuery(stockMove.getId()),
          line -> processBackorderLine(line, newStockMoveHolder[0]),
          () -> newStockMoveHolder[0] = stockMoveRepo.find(newStockMoveHolder[0].getId()));
  newStockMove = stockMoveRepo.find(newStockMove.getId());
  plan(newStockMove);
  return Optional.of(stockMoveRepo.find(newStockMove.getId()));
}

@Override
public boolean mustBeSplit(StockMove stockMove) {
  return stockMoveLineRepo
          .all()
          .filter("self.stockMove.id = :stockMoveId AND self.realQty != self.qty")
          .bind("stockMoveId", stockMove.getId())
          .count()
      > 0;
}

protected void computeMasses(StockMove stockMove) throws AxelorException {
  Company company = Beans.get(CompanyRepository.class).find(stockMove.getCompany().getId());
  StockConfig stockConfig = company.getStockConfig();
  Unit endUnit = stockConfig != null ? stockConfig.getCustomsMassUnit() : null;
  UnitConversionService unitConversionService = Beans.get(UnitConversionService.class);

  final long stockMoveId = stockMove.getId();
  final StockMove[] stockMoveHolder = {stockMoveRepo.find(stockMoveId)};

  Query<StockMoveLine> query =
      stockMoveLineRepo
          .all()
          .filter(
              "self.stockMove.id = :stockMoveId "
                  + "AND self.product IS NOT NULL "
                  + "AND self.product.productTypeSelect = :storable "
                  + "AND self.id > :lastSeenId")
          .bind("stockMoveId", stockMove.getId())
          .bind("storable", ProductRepository.PRODUCT_TYPE_STORABLE)
          .order("id");

  BatchProcessorHelper.of()
      .<StockMoveLine, AxelorException>forEachByQuery(
          query,
          stockMoveLine -> {
            Product product = stockMoveLine.getProduct();
            if (product == null
                || !ProductRepository.PRODUCT_TYPE_STORABLE.equals(
                    product.getProductTypeSelect())) {
              return;
            }

            boolean massesRequiredForStockMoveLine =
                stockMoveLineService.checkMassesRequired(stockMoveHolder[0], stockMoveLine);

            if (massesRequiredForStockMoveLine && endUnit == null) {
              throw new AxelorException(
                  stockMoveHolder[0],
                  TraceBackRepository.CATEGORY_NO_VALUE,
                  I18n.get(StockExceptionMessage.STOCK_MOVE_17));
            }

            computeNetMass(stockMoveLine, endUnit, unitConversionService);
            computeTotalNetMass(stockMoveLine, massesRequiredForStockMoveLine);
          },
          () -> stockMoveHolder[0] = stockMoveRepo.find(stockMoveId));
}

protected void resetMasses(StockMove stockMove) {

  Long stockMoveId = stockMove.getId();
  Query<StockMoveLine> query = getStockMoveLineQuery(stockMoveId);

  BatchProcessorHelper.of()
      .<StockMoveLine>forEachByQuery(query, (StockMoveLine sml) -> sml.setTotalNetMass(null));
}

protected void setRealizedStatus(StockMove stockMove) {
  stockMove.setStatusSelect(StockMoveRepository.STATUS_REALIZED);
}

protected void setPlannedStatus(StockMove stockMove) {
  stockMove.setStatusSelect(StockMoveRepository.STATUS_PLANNED);
  stockMoveRepo.save(stockMove);
}

protected void fillNewStockMoveFields(StockMove newStockMove, StockMove stockMove)
    throws AxelorException {
  if (stockMove.getToAddress() != null) {
    newStockMove.setFromAddress(stockMove.getToAddress());
  }

  setStockMoveTypeSelect(newStockMove, stockMove);

  newStockMove.setStockMoveSeq(
      stockMoveToolService.getSequenceStockMove(
          newStockMove.getTypeSelect(), newStockMove.getCompany(), stockMove));

  setStockMoveName(newStockMove, stockMove);

  if (stockMove.getPartner() != null) {
    newStockMove.setShipmentMode(stockMove.getPartner().getShipmentMode());
    newStockMove.setFreightCarrierMode(stockMove.getPartner().getFreightCarrierMode());
    newStockMove.setCarrierPartner(stockMove.getPartner().getCarrierPartner());
  }
  newStockMove.setIsReversion(!stockMove.getIsReversion());
  newStockMove.setReversionOriginStockMove(stockMove);
  newStockMove.setFromAddressStr(stockMove.getToAddressStr());
  newStockMove.setNote(stockMove.getNote());
  newStockMove.setNumOfPackages(stockMove.getNumOfPackages());
  newStockMove.setNumOfPalettes(stockMove.getNumOfPalettes());
  newStockMove.setGrossMass(stockMove.getGrossMass());
  newStockMove.setExTaxTotal(stockMoveToolService.compute(newStockMove));
  newStockMove.setIsWithBackorder(stockMove.getIsWithBackorder());
  newStockMove.setOrigin(stockMove.getOrigin());
  setOrigin(stockMove, newStockMove);
  newStockMove.setGroupProductsOnPrintings(stockMove.getGroupProductsOnPrintings());
}

protected void copyStockMoveLines(
    StockMove newStockMove, List<StockMoveLine> stockMoveLines, boolean split) {
  for (StockMoveLine stockMoveLine : stockMoveLines) {
    if (!split || stockMoveLine.getRealQty().compareTo(stockMoveLine.getQty()) > 0) {
      newStockMove.addStockMoveLineListItem(copyStockMoveLine(stockMoveLine, split));
    }
  }
}

protected void reverseStockMoveLineStockLocation(List<StockMoveLine> newStockMoveLineList) {
  for (StockMoveLine stockMoveLine : newStockMoveLineList) {

    StockLocation toStockLocation = stockMoveLine.getToStockLocation();
    StockLocation fromStockLocation = stockMoveLine.getFromStockLocation();

    stockMoveLine.setFromStockLocation(toStockLocation);
    stockMoveLine.setToStockLocation(fromStockLocation);
  }
}

@Override
public void setOrigin(StockMove oldStockMove, StockMove newStockMove) {
  if (oldStockMove.getInventory() != null) {
    newStockMove.setInventory(oldStockMove.getInventory());
  } else if (oldStockMove.getStockCorrection() != null) {
    newStockMove.setStockCorrection(oldStockMove.getStockCorrection());
  }
}

protected boolean isNewBackorderLinePossible(StockMove stockMove) throws AxelorException {
  return stockMoveLineRepo
          .all()
          .filter("self.stockMove.id = :stockMoveId AND self.qty > self.realQty")
          .bind("stockMoveId", stockMove.getId())
          .count()
      > 0;
}

protected void computeTotalNetMass(
    StockMoveLine stockMoveLine, boolean massesRequiredForStockMoveLine) throws AxelorException {
  BigDecimal netMass = stockMoveLine.getNetMass();
  if (netMass.signum() != 0) {
    BigDecimal totalNetMass = netMass.multiply(stockMoveLine.getRealQty());
    stockMoveLine.setTotalNetMass(totalNetMass);
  } else if (massesRequiredForStockMoveLine) {
    throw new AxelorException(
        stockMoveLine.getStockMove(),
        TraceBackRepository.CATEGORY_NO_VALUE,
        I18n.get(StockExceptionMessage.STOCK_MOVE_18));
  }
}

protected void computeNetMass(
    StockMoveLine stockMoveLine, Unit endUnit, UnitConversionService unitConversionService)
    throws AxelorException {
  BigDecimal netMass = stockMoveLine.getNetMass();
  Product product = stockMoveLine.getProduct();
  if (netMass.signum() == 0) {
    Unit startUnit = product.getMassUnit();
    if (startUnit != null && endUnit != null) {
      netMass =
          unitConversionService.convert(
              startUnit, endUnit, product.getNetMass(), product.getNetMass().scale(), null);
      stockMoveLine.setNetMass(netMass);
    }
  }
}

protected void setStockMoveName(StockMove newStockMove, StockMove stockMove) {
  newStockMove.setName(
      stockMoveToolService.computeName(
          newStockMove,
          String.format(
              I18n.get(StockExceptionMessage.STOCK_MOVE_8),
              newStockMove.getStockMoveSeq(),
              stockMove.getStockMoveSeq())));
}

protected void setStockMoveTypeSelect(StockMove newStockMove, StockMove stockMove) {
  switch (stockMove.getTypeSelect()) {
    case StockMoveRepository.TYPE_INCOMING:
      newStockMove.setTypeSelect(StockMoveRepository.TYPE_OUTGOING);
      break;
    case StockMoveRepository.TYPE_OUTGOING:
      newStockMove.setTypeSelect(StockMoveRepository.TYPE_INCOMING);
      break;
    default:
      newStockMove.setTypeSelect(StockMoveRepository.TYPE_INTERNAL);
      break;
  }
}

protected StockMoveLine copyStockMoveLine(StockMoveLine stockMoveLine, boolean split) {
  StockMoveLine newStockMoveLine = stockMoveLineRepo.copy(stockMoveLine, false);

  if (split) {
    newStockMoveLine.setQty(stockMoveLine.getRealQty().subtract(stockMoveLine.getQty()));
    newStockMoveLine.setRealQty(newStockMoveLine.getQty());
  } else {
    newStockMoveLine.setQty(stockMoveLine.getRealQty());
    newStockMoveLine.setRealQty(stockMoveLine.getRealQty());
  }
  return newStockMoveLine;
}

@Transactional
public void createControlPointListItem(
    ControlPointModel model, ControlPoint point, QualityControl qualityControl) {

  point.setStatusSelect(ControlPointRepository.STATUS_ON_HOLD);
  point.setName(model.getName());
  point.setSequence(model.getSequence());
  point.setNotes(model.getNotes());
  point.setControlFrequency(model.getControlFrequency());
  point.setControlPointType(model.getControlPointType());

  for (QualityMeasuringPoint measuringPoint : model.getMeasuringPointList()) {
    measuringPoint = Beans.get(QualityMeasuringPointRepository.class).copy(measuringPoint, true);
    point.addMeasuringPointListItem(measuringPoint);
  }

  point.setControlPointDate(qualityControl.getStartDate());

  controlPointRepo.save(point);
}

def validate_stock_qty(self):
	from erpnext.stock.doctype.batch.batch import get_batch_qty

	for row in self.get("locations"):
		row_qty = self.get_qty_to_pick(row)
		if not row_qty:
			continue

		if row.batch_no:
			batch_qty = get_batch_qty(row.batch_no, row.warehouse, row.item_code)

			if row_qty > batch_qty:
				frappe.throw(
					_(
						"At Row #{0}: The picked quantity {1} for the item {2} is greater than available stock {3} for the batch {4} in the warehouse {5}. Please restock the item."
					).format(
						row.idx,
						row_qty,
						row.item_code,
						batch_qty,
						row.batch_no,
						bold(row.warehouse),
					),
					title=_("Insufficient Stock"),
				)

			continue

		bin_qty = flt(
			frappe.db.get_value(
				"Bin",
				{"item_code": row.item_code, "warehouse": row.warehouse},
				"actual_qty",
			)
		)

		if row_qty > bin_qty:
			frappe.throw(
				_(
					"At Row #{0}: The picked quantity {1} for the item {2} is greater than available stock {3} in the warehouse {4}."
				).format(row.idx, row_qty, bold(row.item_code), bin_qty, bold(row.warehouse)),
				title=_("Insufficient Stock"),
			)

def validate_warehouses(self):
	for location in self.locations:
		if not location.warehouse:
			frappe.throw(
				_("Row {0}: Warehouse is required").format(location.idx),
				title=_("Missing Warehouse"),
				exc=MissingWarehouseValidationError,
			)

		company = frappe.get_cached_value("Warehouse", location.warehouse, "company")

		if company != self.company:
			frappe.throw(
				_(
					"Row {0}: Warehouse {1} is linked to company {2}. Please select a warehouse belonging to company {3}."
				).format(
					location.idx,
					frappe.bold(location.warehouse),
					frappe.bold(company),
					frappe.bold(self.company),
				),
				title=_("Incorrect Warehouse"),
				exc=IncorrectWarehouseValidationError,
			)

def check_serial_no_status(self):
	from erpnext.stock.doctype.serial_no.serial_no import get_serial_nos

	for row in self.get("locations"):
		if not row.serial_no:
			continue

		picked_serial_nos = get_serial_nos(row.serial_no)
		validated_serial_nos = frappe.get_all(
			"Serial No",
			filters={"name": ("in", picked_serial_nos), "warehouse": row.warehouse},
			pluck="name",
		)

		incorrect_serial_nos = set(picked_serial_nos) - set(validated_serial_nos)
		if incorrect_serial_nos:
			frappe.throw(
				_("The Serial No at Row #{0}: {1} is not available in warehouse {2}.").format(
					row.idx, ", ".join(incorrect_serial_nos), row.warehouse
				),
				title=_("Incorrect Warehouse"),
			)

def validate_with_previous_doc(self):
	super().validate_with_previous_doc(
		{
			"Sales Order": {
				"ref_dn_field": "sales_order",
				"compare_fields": [
					["company", "="],
				],
			},
		}
	)

def validate_sales_order_percentage(self):
	# set percentage picked in SO
	for location in self.get("locations"):
		if (
			location.sales_order
			and frappe.db.get_value("Sales Order", location.sales_order, "per_picked", cache=True) == 100
		):
			frappe.throw(
				_("Row #{}: item {} has been picked already.").format(location.idx, location.item_code)
			)

def validate_sales_order(self):
	"""Raises an exception if the `Sales Order` has reserved stock."""

	if self.purpose != "Delivery":
		return

	so_list = set(location.sales_order for location in self.locations if location.sales_order)

	if so_list:
		for so in so_list:
			so_doc = frappe.get_doc("Sales Order", so)
			for item in so_doc.items:
				if item.stock_reserved_qty > 0:
					frappe.throw(
						_(
							"Cannot create a pick list for Sales Order {0} because it has reserved stock. Please unreserve the stock in order to create a pick list."
						).format(frappe.bold(so))
					)

def validate_picked_items(self):
	for item in self.locations:
		if self.scan_mode and item.picked_qty < item.stock_qty:
			frappe.throw(
				_(
					"Row {0} picked quantity is less than the required quantity, additional {1} {2} required."
				).format(item.idx, item.stock_qty - item.picked_qty, item.stock_uom),
				title=_("Pick List Incomplete"),
			)

		if not self.scan_mode and not item.picked_qty:
			# if the user has not entered any picked qty, set it to stock_qty, before submit
			item.picked_qty = item.stock_qty

def validate_expired_batches(self):
	batches = []
	for row in self.get("locations"):
		if row.get("batch_no") and (row.get("picked_qty") or self.pick_manually):
			batches.append(row.batch_no)

	if batches:
		batch = frappe.qb.DocType("Batch")
		query = (
			frappe.qb.from_(batch)
			.select(batch.name)
			.where(
				(batch.name.isin(batches))
				& (batch.expiry_date < frappe.utils.nowdate())
				& (batch.expiry_date.isnotnull())
			)
		)

		expired_batches = query.run(as_dict=True)
		if expired_batches:
			msg = "<ul>" + "".join(f"<li>{batch.name}</li>" for batch in expired_batches) + "</ul>"

			frappe.throw(
				_("The following batches are expired, please restock them: <br> {0}").format(msg),
				title=_("Expired Batches"),
			)

def validate_serial_and_batch_bundle(self):
	for row in self.locations:
		if row.serial_and_batch_bundle:
			doc = frappe.get_doc("Serial and Batch Bundle", row.serial_and_batch_bundle)
			if doc.docstatus == 0:
				doc.submit()

def update_packed_items_qty(self, packed_items):
	picked_items = get_picked_items_qty(packed_items, contains_packed_items=True)
	self.validate_picked_qty(picked_items, "Packed Item")

	doc_updates = {item: {"picked_qty": 0} for item in set(packed_items)}
	for d in picked_items:
		doc_updates[d.product_bundle_item] = {"picked_qty": flt(d.picked_qty)}

	if doc_updates:
		frappe.db.bulk_update("Packed Item", doc_updates, update_modified=False)

def validate_picked_qty(self, data, ordered_doctype="Sales Order Item"):
	allowance = 1 + flt(frappe.get_single_value("Stock Settings", "over_picking_allowance")) / 100
	qty_field = "qty" if ordered_doctype == "Packed Item" else "stock_qty"
	reference_field = "product_bundle_item" if ordered_doctype == "Packed Item" else "sales_order_item"
	ordered_qty = dict(
		frappe.get_all(
			ordered_doctype,
			filters={"name": ("in", [row.get(reference_field) for row in data])},
			fields=["name", qty_field],
			as_list=True,
		)
	)

	for row in data:
		ordered = flt(ordered_qty.get(row.get(reference_field)))
		if ordered and flt(row.picked_qty, 6) > flt(ordered * allowance, 6):
			frappe.throw(
				_(
					"You are picking more than required quantity for the item {0}. Check if there is any other pick list created for the sales order {1}."
				).format(row.item_code, row.sales_order)
			)

def validate_for_qty(self):
	if self.purpose == "Material Transfer for Manufacture" and (
		self.for_qty is None or self.for_qty == 0
	):
		frappe.throw(_("Qty of Finished Goods Item should be greater than 0."))

def validate_item_locations(pick_list):
	if not pick_list.locations:
		frappe.throw(_("Add items in the Item Locations table"))

def validate_picked_materials(item_code, required_qty, locations, picked_item_details=None):
	for location in list(locations):
		if location["qty"] < 0:
			locations.remove(location)

	total_qty_available = sum(location.get("qty") for location in locations)
	remaining_qty = required_qty - total_qty_available

	if remaining_qty > 0:
		if picked_item_details:
			frappe.msgprint(
				_(
					"{0} units of Item {1} is not available in any of the warehouses. Other Pick Lists exist for this item."
				).format(remaining_qty, get_link_to_form("Item", item_code)),
				title=_("Already Picked"),
			)
		else:
			frappe.msgprint(
				_("{0} units of Item {1} is not available in any of the warehouses.").format(
					remaining_qty, get_link_to_form("Item", item_code)
				),
				title=_("Insufficient Stock"),
			)

def create_delivery(
	source_name: str, target_doc: str | dict | Document | None = None, target: str | None = None
):
	pick_list = frappe.get_doc("Pick List", source_name)
	pick_list.check_permission("read")
	target = target or (frappe.flags.args or {}).get("target") or "Delivery Note"
	validate_item_locations(pick_list)
	sales_dict = dict()
	documents = []
	sales_orders = get_sales_order_headers({location.sales_order for location in pick_list.locations})

	for key, rows in groupby(sorted(sales_orders, key=get_header_key), key=get_header_key):
		sales_dict[key] = {row.sales_order for row in rows}

	if sales_dict:
		documents.extend(create_delivery_with_so(sales_dict, pick_list, target))

	if not all(item.sales_order for item in pick_list.locations):
		documents.append(create_delivery_wo_so(pick_list, target, target_doc))

	if len(documents) == 1:
		return documents[0]
	else:
		from frappe.utils import comma_and

		doc_list = [get_link_to_form(target, p.name) for p in documents]
		frappe.msgprint(_("{0} created").format(comma_and(doc_list)))

def create_delivery_wo_so(pick_list, target, target_doc=None, selected_locations=None):
	if not target_doc:
		target_doc = frappe.new_doc(target)

	target_doc.company = pick_list.company

	if not target_doc.customer:
		target_doc.customer = pick_list.customer

	item_table_mapper_without_so = {
		"doctype": f"{target} Item",
		"field_map": {
			"rate": "rate",
			"name": "name",
			"parent": "",
		},
	}
	map_pl_locations(
		pick_list, item_table_mapper_without_so, target_doc, selected_locations=selected_locations
	)
	target_doc.flags.ignore_mandatory = True
	if target == "Sales Invoice":
		target_doc.update_stock = 1
	target_doc.save()

	return target_doc

def create_dn_for_pick_lists(
	source_name: str, target_doc: str | dict | Document | None = None, kwargs: str | dict | None = None
):
	"""Get Items from Multiple Pick Lists and create a Delivery Note for filtered customer"""
	if kwargs is None:
		kwargs = {}
	if isinstance(kwargs, str):
		kwargs = json.loads(kwargs)

	pick_list = frappe.get_doc("Pick List", source_name)
	pick_list.check_permission("read")
	validate_item_locations(pick_list)

	sales_order_arg = kwargs.get("sales_order")
	customer_arg = kwargs.get("customer")

	if sales_order_arg:
		sales_orders = {sales_order_arg}
	else:
		sales_orders = {row.sales_order for row in pick_list.locations if row.sales_order}

		if customer_arg:
			sales_orders = frappe.get_all(
				"Sales Order",
				filters={"customer": customer_arg, "name": ["in", list(sales_orders)]},
				pluck="name",
			)

	delivery_note = create_delivery_from_so(
		pick_list, sales_orders, "Delivery Note", target_doc=target_doc, kwargs=kwargs
	)

	if not sales_order_arg and not all(item.sales_order for item in pick_list.locations):
		if isinstance(delivery_note, str):
			delivery_note = frappe.get_doc(frappe.parse_json(delivery_note))

		delivery_note = create_delivery_wo_so(
			pick_list, "Delivery Note", delivery_note, set(kwargs.get("filtered_children") or [])
		)

	return delivery_note

def create_dn_from_so(pick_list, sales_order_list, delivery_note=None, kwargs=None):
	return create_delivery_from_so(
		pick_list, sales_order_list, "Delivery Note", target_doc=delivery_note, kwargs=kwargs
	)

def create_delivery_from_so(pick_list, sales_order_list, target, target_doc=None, kwargs=None):
	if not sales_order_list:
		return target_doc

	if kwargs is None:
		kwargs = {}

	item_table_mapper = {
		"doctype": f"{target} Item",
		"field_map": {
			"rate": "rate",
			"name": "so_detail",
			"parent": "against_sales_order" if target == "Delivery Note" else "sales_order",
		},
		"condition": lambda doc: abs(doc.delivered_qty) < abs(doc.qty) and doc.delivered_by_supplier != 1,
	}
	selected_locations = set(kwargs.get("filtered_children") or [])

	mapper_kwargs = {"skip_item_mapping": True, "ignore_pricing_rule": pick_list.ignore_pricing_rule}

	target_doc = (
		create_delivery_note_from_sales_order(next(iter(sales_order_list)), target_doc, kwargs=mapper_kwargs)
		if target == "Delivery Note"
		else create_sales_invoice_from_sales_order(
			next(iter(sales_order_list)), target_doc, args=mapper_kwargs
		)
	)

	if not target_doc:
		return

	for so in sales_order_list:
		map_pl_locations(pick_list, item_table_mapper, target_doc, so, selected_locations)

	return target_doc

def create_stock_entry(pick_list: str | dict):
	pick_list = frappe.get_doc(frappe.parse_json(pick_list))
	pick_list.check_permission("read")
	validate_item_locations(pick_list)

	stock_entry = frappe.new_doc("Stock Entry")
	stock_entry.pick_list = pick_list.get("name")
	stock_entry.purpose = pick_list.get("purpose")
	stock_entry.company = pick_list.get("company")

	job_card = pick_list.get("material_request") and frappe.db.get_value(
		"Material Request", pick_list.get("material_request"), "job_card"
	)

	if job_card:
		stock_entry = update_stock_entry_based_on_job_card(pick_list, stock_entry, job_card)
	elif pick_list.get("work_order"):
		stock_entry = update_stock_entry_based_on_work_order(pick_list, stock_entry)
	elif pick_list.get("material_request"):
		stock_entry = update_stock_entry_based_on_material_request(pick_list, stock_entry)
	else:
		stock_entry = update_stock_entry_items_with_no_reference(pick_list, stock_entry)

	stock_entry.set_stock_entry_type()

	if not stock_entry.get("items"):
		return frappe.msgprint(_("All picked items have already been transferred against this Pick List"))

	stock_entry.set_missing_values()

	return stock_entry.as_dict()

def set_stock_qty(self):
	if not self.docstatus.is_draft() and getattr(self, "_action", None) != "submit":
		return

	conversion_factors = get_uom_conversion_factors(
		{row.item_code for row in self.locations if row.item_code}
	)
	for row in self.locations:
		if not row.item_code:
			continue

		stock_uom = frappe.get_cached_value("Item", row.item_code, "stock_uom")
		row.uom = row.uom or stock_uom
		if row.uom == stock_uom:
			row.conversion_factor = 1
		elif (row.item_code, row.uom) in conversion_factors:
			row.conversion_factor = conversion_factors[(row.item_code, row.uom)]

		row.stock_qty = flt(flt(row.qty) * flt(row.conversion_factor), row.precision("stock_qty"))

def get_qty_to_pick(self, row):
	if row.picked_qty or self.scan_mode or not self.docstatus.is_submitted():
		return flt(row.picked_qty)

	return flt(row.stock_qty)

def delink_serial_and_batch_bundle(self):
	for row in self.locations:
		if (
			row.serial_and_batch_bundle
			and frappe.db.get_value("Serial and Batch Bundle", row.serial_and_batch_bundle, "docstatus")
			== 1
		):
			frappe.db.set_value(
				"Serial and Batch Bundle",
				row.serial_and_batch_bundle,
				{"is_cancelled": 1, "voucher_no": ""},
			)

			frappe.get_doc("Serial and Batch Bundle", row.serial_and_batch_bundle).cancel()
			row.db_set("serial_and_batch_bundle", None)

def update_status(self, status=None, update_modified=True):
	if not status:
		status = self.get_status().get("status")

	if status:
		self.db_set("status", status)

def update_reference_qty(self):
	packed_items = []
	so_items = []

	for item in self.locations:
		if item.product_bundle_item:
			packed_items.append(item.product_bundle_item)
		elif item.sales_order_item:
			so_items.append(item.sales_order_item)

	if packed_items:
		self.update_packed_items_qty(packed_items)

	if so_items:
		self.update_sales_order_item_qty(so_items)

def update_sales_order_picking_status(self) -> None:
	sales_orders = []
	for row in self.locations:
		if row.sales_order and row.sales_order not in sales_orders:
			sales_orders.append(row.sales_order)

	for sales_order in sales_orders:
		frappe.get_doc("Sales Order", sales_order, for_update=True).update_picking_status()

def get_picked_items_qty(items, contains_packed_items=False) -> list[dict]:
	pi_item = frappe.qb.DocType("Pick List Item")

	query = (
		frappe.qb.from_(pi_item)
		.select(
			pi_item.sales_order_item,
			pi_item.product_bundle_item,
			pi_item.item_code,
			pi_item.sales_order,
			Sum(pi_item.stock_qty).as_("stock_qty"),
			Sum(pi_item.picked_qty).as_("picked_qty"),
		)
		.where(pi_item.docstatus == 1)
		.for_update()
	)

	if contains_packed_items:
		query = query.groupby(
			pi_item.product_bundle_item,
			pi_item.sales_order,
		).where(pi_item.product_bundle_item.isin(items))
	else:
		query = query.groupby(
			pi_item.sales_order_item,
			pi_item.sales_order,
		).where(pi_item.sales_order_item.isin(items))

	return query.run(as_dict=True)

def get_sales_order_headers(sales_orders):
	sales_orders = [so for so in sales_orders if so]
	if not sales_orders:
		return []

	headers = frappe.get_all(
		"Sales Order",
		filters={"name": ("in", sales_orders)},
		fields=["name as sales_order", *SALES_ORDER_HEADER_FIELDS],
	)
	taxes = get_sales_order_taxes(sales_orders)
	for header in headers:
		header.taxes = taxes.get(header.sales_order, [])

	return headers

def map_pl_locations(pick_list, item_mapper, target_doc, sales_order=None, selected_locations=None):
	sales_order_items = (
		{d.name: d for d in frappe.get_doc("Sales Order", sales_order).items} if sales_order else {}
	)
	condition = item_mapper.get("condition")

	for location in pick_list.locations:
		if location.sales_order != sales_order or location.product_bundle_item:
			continue

		if flt(location.picked_qty) - flt(location.delivered_qty) <= 0:
			continue

		if selected_locations and location.name not in selected_locations:
			continue

		sales_order_item = sales_order_items.get(location.sales_order_item)
		if sales_order_item and condition and not condition(sales_order_item):
			continue

		source_doc = sales_order_item or location

		child_item = map_child_doc(source_doc, target_doc, item_mapper)

		if child_item:
			child_item.against_pick_list = pick_list.name
			child_item.pick_list_item = location.name
			child_item.warehouse = location.warehouse
			child_item.qty = flt(location.picked_qty - location.delivered_qty) / (
				flt(child_item.conversion_factor) or 1
			)
			child_item.batch_no = location.batch_no
			child_item.serial_no = location.serial_no
			child_item.use_serial_batch_fields = location.use_serial_batch_fields

			if not child_item.qty:
				target_doc.items.remove(child_item)
				continue

			update_child_item(source_doc, child_item, target_doc)

	if sales_order:
		add_product_bundles_to_target(pick_list, target_doc, item_mapper, sales_order, selected_locations)

	set_target_missing_values(target_doc)

	target_doc.company = pick_list.company
	if sales_order:
		target_doc.customer = frappe.get_value("Sales Order", sales_order, "customer")

def update_stock_entry_based_on_material_request(pick_list, stock_entry):
	for location in pick_list.locations:
		if get_pending_transfer_stock_qty(location) <= 0:
			continue
		target_warehouse = None
		if location.material_request_item:
			target_warehouse = frappe.get_value(
				"Material Request Item", location.material_request_item, "warehouse"
			)
		item = frappe._dict()
		update_common_item_properties(item, location)
		item.t_warehouse = target_warehouse
		stock_entry.append("items", item)

	return stock_entry

def update_stock_entry_items_with_no_reference(pick_list, stock_entry):
	for location in pick_list.locations:
		if get_pending_transfer_stock_qty(location) <= 0:
			continue
		item = frappe._dict()
		update_common_item_properties(item, location)

		stock_entry.append("items", item)

	return stock_entry

def get_uom_conversion_factors(item_codes) -> dict:
	if not item_codes:
		return {}

	return {
		(row.parent, row.uom): flt(row.conversion_factor)
		for row in frappe.get_all(
			"UOM Conversion Detail",
			filters={"parent": ("in", list(item_codes)), "parenttype": "Item"},
			fields=["parent", "uom", "conversion_factor"],
		)
	}

def update_sales_order_item_qty(self, so_items):
	picked_items = get_picked_items_qty(so_items)
	self.validate_picked_qty(picked_items)

	doc_updates = {item: {"picked_qty": 0} for item in set(so_items)}
	for d in picked_items:
		doc_updates[d.sales_order_item] = {"picked_qty": flt(d.picked_qty)}

	if doc_updates:
		frappe.db.bulk_update("Sales Order Item", doc_updates, update_modified=False)

def _get_product_bundles(self) -> dict[str, str]:
	# Dict[so_item_row: item_code]
	product_bundles = {}
	for item in self.locations:
		if not item.product_bundle_item:
			continue

		product_bundles[item.sales_order_item] = frappe._dict(
			{
				"item_code": frappe.db.get_value(
					"Sales Order Item",
					item.sales_order_item,
					"item_code",
				),
				"pick_list_item": item.name,
			}
		)
	return product_bundles

def _get_product_bundle_qty_map(self, bundles) -> dict[str, dict[str, float]]:
	product_bundle_qty_map = {}
	for data in bundles:
		bundle = frappe.get_last_doc("Product Bundle", {"new_item_code": data.item_code, "disabled": 0})
		product_bundle_qty_map[data.item_code] = {item.item_code: item.qty for item in bundle.items}
	return product_bundle_qty_map

def _compute_picked_qty_for_bundle(self, bundle_row, bundle_items) -> int:
	"""Compute how many full bundles can be created from picked items."""
	precision = frappe.get_precision("Stock Ledger Entry", "qty_after_transaction")
	possible_bundles = {}
	for item in self.locations:
		if item.sales_order_item != bundle_row:
			continue

		if qty_in_bundle := bundle_items.get(item.item_code):
			possible_bundles.setdefault(item.product_bundle_item, 0)
			possible_bundles[item.product_bundle_item] += item.picked_qty / qty_in_bundle

	return int(flt(min(possible_bundles.values()), precision or 6)) if possible_bundles else 0

def add_product_bundles_to_target(
	pick_list, target_doc, item_mapper, sales_order=None, selected_locations=None
) -> None:
	"""Add product bundles found in pick list to target document.

	When mapping pick list items, the bundle item itself isn't part of the
	locations. Dynamically fetch and add parent bundle item into target document."""
	product_bundles = pick_list._get_product_bundles()
	if selected_locations:
		selected_bundles = {
			row.sales_order_item
			for row in pick_list.locations
			if row.product_bundle_item and row.name in selected_locations
		}
		product_bundles = {key: value for key, value in product_bundles.items() if key in selected_bundles}

	product_bundle_qty_map = pick_list._get_product_bundle_qty_map(product_bundles.values())

	for so_row, value in product_bundles.items():
		sales_order_item = frappe.get_doc("Sales Order Item", so_row)
		if sales_order and sales_order_item.parent != sales_order:
			continue

		target_bundle_item = map_child_doc(sales_order_item, target_doc, item_mapper)
		target_bundle_item.qty = pick_list._compute_picked_qty_for_bundle(
			so_row, product_bundle_qty_map[value.item_code]
		)
		target_bundle_item.pick_list_item = value.pick_list_item
		target_bundle_item.against_pick_list = pick_list.name
		update_child_item(sales_order_item, target_bundle_item, target_doc)

def update_child_item(source, target, target_doc):
	cost_center = frappe.db.get_value("Project", target_doc.project, "cost_center")
	if not cost_center:
		cost_center = get_cost_center(source.item_code, "Item", target_doc.company)

	if not cost_center:
		cost_center = get_cost_center(source.item_group, "Item Group", target_doc.company)

	target.cost_center = cost_center

def get_job_card_items_by_material_request_item(pick_list):
	material_request_items = [
		location.material_request_item for location in pick_list.locations if location.material_request_item
	]
	if not material_request_items:
		return {}

	return dict(
		frappe.get_all(
			"Material Request Item",
			filters={"name": ["in", material_request_items]},
			fields=["name", "job_card_item"],
			as_list=True,
		)
	)

def get_pending_transfer_stock_qty(location):
	"""Stock qty of this pick list row still to be moved into a Stock Entry."""
	return flt(location.picked_qty) - flt(location.transferred_qty)

def get_cost_center(for_item, from_doctype, company):
	"""Returns Cost Center for Item or Item Group"""
	return frappe.db.get_value(
		"Item Default",
		fieldname=["buying_cost_center"],
		filters={"parent": for_item, "parenttype": from_doctype, "company": company},
	)

def before_cancel(self):
	if self.flags.cancelled_by_delivery_note:
		return

	if cint(frappe.db.get_value("Delivery Note", self.delivery_note, "docstatus")) == 1:
		frappe.throw(
			_("Packing Slip cannot be cancelled as Delivery Note {0} is already submitted.").format(
				frappe.bold(self.delivery_note)
			)
		)

def validate_delivery_note(self):
	"""Raises an exception if the `Delivery Note` status is not Draft"""

	if cint(frappe.db.get_value("Delivery Note", self.delivery_note, "docstatus")) != 0:
		frappe.throw(
			_("A Packing Slip can only be created for Draft Delivery Note.").format(self.delivery_note)
		)

def validate_case_nos(self):
	"""Validate if case nos overlap. If they do, recommend next case no."""

	if cint(self.from_case_no) <= 0:
		frappe.throw(_("The 'From Package No.' field must neither be empty nor it's value less than 1."))
	elif not self.to_case_no:
		self.to_case_no = self.from_case_no
	elif cint(self.to_case_no) < cint(self.from_case_no):
		frappe.throw(_("'To Package No.' cannot be less than 'From Package No.'"))
	else:
		ps = frappe.qb.DocType("Packing Slip")
		res = (
			frappe.qb.from_(ps)
			.select(
				ps.name,
			)
			.where(
				(ps.delivery_note == self.delivery_note)
				& (ps.docstatus == 1)
				& (
					(ps.from_case_no.between(self.from_case_no, self.to_case_no))
					| (ps.to_case_no.between(self.from_case_no, self.to_case_no))
					| ((ps.from_case_no <= self.from_case_no) & (ps.to_case_no >= self.from_case_no))
				)
			)
		).run()

		if res:
			frappe.throw(
				_("""Package No(s) already in use. Try from Package No {0}""").format(
					self.get_recommended_case_no()
				)
			)

def validate_items(self):
	references = {}
	for item in self.items:
		if item.qty <= 0:
			frappe.throw(_("Row {0}: Qty must be greater than 0.").format(item.idx))

		if not item.dn_detail and not item.pi_detail:
			frappe.throw(
				_("Row {0}: Either Delivery Note Item or Packed Item reference is mandatory.").format(
					item.idx
				)
			)

		reference = self.get_reference_row(item)
		self.validate_reference_row(item, reference)
		self.validate_remaining_qty(item, flt(reference.qty) - flt(reference.packed_qty))
		references[item.dn_detail or item.pi_detail] = reference

	self.validate_total_qty_per_reference(references)

def validate_total_qty_per_reference(self, references):
	qty_by_reference = {}
	for item in self.items:
		key = item.dn_detail or item.pi_detail
		qty_by_reference[key] = qty_by_reference.get(key, 0) + flt(item.qty)

		reference = references[key]
		remaining_qty = flt(reference.qty) - flt(reference.packed_qty)
		if qty_by_reference[key] > remaining_qty:
			frappe.throw(
				_("Row {0}: Total packed qty cannot be greater than {1} for the Item {2}.").format(
					item.idx, frappe.bold(remaining_qty), frappe.bold(item.item_code)
				)
			)

def get_reference_row(self, item):
	return frappe.db.get_value(
		"Delivery Note Item" if item.dn_detail else "Packed Item",
		{"name": item.dn_detail or item.pi_detail, "docstatus": 0},
		["parent", "item_code", "qty", "packed_qty"],
		as_dict=True,
	)

def validate_reference_row(self, item, reference):
	if not reference or reference.parent != self.delivery_note or reference.item_code != item.item_code:
		frappe.throw(
			_("Row {0}: Please provide a valid Delivery Note Item or Packed Item reference.").format(
				item.idx
			)
		)

def validate_remaining_qty(self, item, remaining_qty):
	if remaining_qty <= 0:
		frappe.throw(
			_("Row {0}: Packing Slip is already created for Item {1}.").format(
				item.idx, frappe.bold(item.item_code)
			)
		)
	elif item.qty > remaining_qty:
		frappe.throw(
			_("Row {0}: Qty cannot be greater than {1} for the Item {2}.").format(
				item.idx, frappe.bold(remaining_qty), frappe.bold(item.item_code)
			)
		)

def set_missing_values(self):
	if not self.from_case_no:
		self.from_case_no = self.get_recommended_case_no()

	for item in self.items:
		weight_per_unit, weight_uom = frappe.db.get_value(
			"Item", item.item_code, ["weight_per_unit", "weight_uom"]
		)

		if weight_per_unit and not item.net_weight:
			item.net_weight = flt(weight_per_unit) * self.get_conversion_factor(item)
		if weight_uom and not item.weight_uom:
			item.weight_uom = weight_uom

def get_conversion_factor(self, item):
	if not item.dn_detail:
		return 1.0

	return flt(frappe.db.get_value("Delivery Note Item", item.dn_detail, "conversion_factor")) or 1.0

def get_recommended_case_no(self):
	"""Returns the next case no. for a new packing slip for a delivery note"""

	return (
		cint(
			frappe.db.get_value(
				"Packing Slip",
				{"delivery_note": self.delivery_note, "docstatus": 1},
				[{"MAX": "to_case_no"}],
			)
		)
		+ 1
	)

def calculate_net_total_pkg(self):
	self.net_weight_uom = self.items[0].weight_uom if self.items else None
	self.gross_weight_uom = self.net_weight_uom

	net_weight_pkg = 0
	for item in self.items:
		if item.weight_uom != self.net_weight_uom:
			frappe.throw(
				_(
					"Different UOM for items will lead to incorrect (Total) Net Weight value. Make sure that Net Weight of each item is in the same UOM."
				)
			)

		net_weight_pkg += flt(item.net_weight) * flt(item.qty)

	self.net_weight_pkg = round(net_weight_pkg, 2)

	if not flt(self.gross_weight_pkg):
		self.gross_weight_pkg = self.net_weight_pkg

def on_discard(self):
	self.update_qc_reference()
	self.db_set("status", "Cancelled")

def validate(self):
	if not self.readings and self.item_code:
		self.get_item_specification_details()

	if self.inspection_type == "In Process" and self.reference_type == "Job Card":
		self.set_acceptance_criteria_from_template()

	if self.readings:
		self.validate_reading_number_format()
		self.inspect_and_set_status()

	self.validate_inspection_required()
	self.validate_status()
	self.set_child_row_reference()
	self.set_company()

def set_acceptance_criteria_from_template(self):
	template = self.quality_inspection_template or frappe.db.get_value(
		"Item", self.item_code, "quality_inspection_template"
	)
	parameters = {d.specification: d for d in get_template_details(template)}
	for reading in self.readings:
		if criteria := parameters.get(reading.specification):
			reading.update(criteria)

def validate_status(self):
	if self.status == "Cancelled" and self.docstatus < 2:
		frappe.throw(_("Status Cancelled can only be set by cancelling the Quality Inspection"))

def set_company(self):
	if self.reference_type and self.reference_name:
		company = frappe.get_cached_value(self.reference_type, self.reference_name, "company")
		if company != self.company:
			self.company = company

def set_child_row_reference(self):
	if self.child_row_reference:
		return

	if not (self.reference_type and self.reference_name):
		return

	doctype = self.reference_type + " Item"
	if self.reference_type == "Stock Entry":
		doctype = "Stock Entry Detail"

	child_doc = frappe.qb.DocType(doctype)
	qi_doc = frappe.qb.DocType("Quality Inspection")

	query = (
		frappe.qb.from_(child_doc)
		.left_join(qi_doc)
		.on(
			(child_doc.name == qi_doc.child_row_reference)
			& (qi_doc.docstatus < 2)
			& (qi_doc.name != self.name)
		)
		.select(child_doc.name)
		.where(
			(child_doc.item_code == self.item_code)
			& (child_doc.parent == self.reference_name)
			& (child_doc.docstatus < 2)
			& (qi_doc.name.isnull())
		)
		.orderby(child_doc.idx)
	)
	if self.batch_no and frappe.get_meta(doctype).has_field("batch_no"):
		query = query.where(child_doc.batch_no == self.batch_no)

	if child_row_references := query.run(pluck=True):
		self.child_row_reference = child_row_references[0]
	elif frappe.get_meta(doctype).has_field("quality_inspection") and self.has_inspected_rows(doctype):
		frappe.throw(
			_("Every row of Item {0} in {1} {2} already has a Quality Inspection").format(
				frappe.bold(self.item_code), _(self.reference_type), frappe.bold(self.reference_name)
			)
		)

def has_inspected_rows(self, doctype):
	return frappe.db.exists(
		doctype,
		{
			"parent": self.reference_name,
			"item_code": self.item_code,
			"quality_inspection": ("not in", ["", self.name]),
		},
	)

def validate_inspection_required(self):
	if frappe.db.get_single_value(
		"Stock Settings", "allow_to_make_quality_inspection_after_purchase_or_delivery"
	):
		return

	if self.reference_type in ["Purchase Receipt", "Purchase Invoice"] and not frappe.get_cached_value(
		"Item", self.item_code, "inspection_required_before_purchase"
	):
		frappe.throw(
			_(
				"'Inspection Required before Purchase' has disabled for the item {0}, no need to create the QI"
			).format(get_link_to_form("Item", self.item_code))
		)

	if self.reference_type in ["Delivery Note", "Sales Invoice"] and not frappe.get_cached_value(
		"Item", self.item_code, "inspection_required_before_delivery"
	):
		frappe.throw(
			_(
				"'Inspection Required before Delivery' has disabled for the item {0}, no need to create the QI"
			).format(get_link_to_form("Item", self.item_code))
		)

def before_submit(self):
	self.validate_sample_size()
	self.validate_readings_status_mandatory()

def validate_sample_size(self):
	if flt(self.sample_size) <= 0:
		frappe.throw(_("Sample Size must be greater than zero"), title=_("Invalid Sample Size"))

def get_item_specification_details(self):
	if not self.quality_inspection_template:
		self.quality_inspection_template = frappe.db.get_value(
			"Item", self.item_code, "quality_inspection_template"
		)

	if not self.quality_inspection_template:
		return

	self.set("readings", [])
	parameters = get_template_details(self.quality_inspection_template)
	for d in parameters:
		child = self.append("readings", {})
		child.update(d)
		child.status = "Accepted"
		child.parameter_group = frappe.get_value(
			"Quality Inspection Parameter", d.specification, "parameter_group"
		)

def get_quality_inspection_template(self):
	template = ""
	if self.bom_no:
		template = frappe.db.get_value("BOM", self.bom_no, "quality_inspection_template")

	if not template:
		template = frappe.db.get_value("BOM", self.item_code, "quality_inspection_template")

	self.quality_inspection_template = template
	self.get_item_specification_details()

def on_update(self):
	action_if_qi_in_draft = frappe.db.get_single_value(
		"Stock Settings", "action_if_quality_inspection_is_not_submitted"
	)

	if not action_if_qi_in_draft or action_if_qi_in_draft == "Warn":
		self.update_qc_reference()

def on_submit(self):
	if (
		frappe.db.get_single_value("Stock Settings", "action_if_quality_inspection_is_not_submitted")
		== "Stop"
	):
		self.update_qc_reference()

def validate_not_used_by_submitted_document(self):
	if not (self.reference_type and self.reference_name) or frappe.db.get_single_value(
		"Stock Settings", "allow_to_make_quality_inspection_after_purchase_or_delivery"
	):
		return

	if frappe.db.get_value(self.reference_type, self.reference_name, "docstatus") != 1:
		return

	if self.is_linked_on_reference():
		frappe.throw(
			_("Quality Inspection {0} is used by {1} {2}. Cancel {2} first.").format(
				frappe.bold(self.name),
				_(self.reference_type),
				get_link_to_form(self.reference_type, self.reference_name),
			)
		)

def is_linked_on_reference(self):
	if self.reference_type == "Job Card":
		return frappe.db.get_value("Job Card", self.reference_name, "quality_inspection") == self.name

	doctype = (
		"Stock Entry Detail" if self.reference_type == "Stock Entry" else self.reference_type + " Item"
	)
	return frappe.db.exists(doctype, {"parent": self.reference_name, "quality_inspection": self.name})

def validate_readings_status_mandatory(self):
	for reading in self.readings:
		if not reading.status:
			frappe.throw(_("Row #{0}: Status is mandatory").format(reading.idx))

def update_qc_reference(self, remove_reference=False):
	quality_inspection = self.name if self.docstatus < 2 and not remove_reference else ""

	if self.reference_type == "Job Card":
		if self.reference_name:
			frappe.db.sql(
				f"""
				UPDATE `tab{self.reference_type}`
				SET quality_inspection = %s, modified = %s
				WHERE name = %s and production_item = %s
			""",
				(quality_inspection, self.modified, self.reference_name, self.item_code),
			)

	else:
		doctype = self.reference_type + " Item"

		if self.reference_type == "Stock Entry":
			doctype = "Stock Entry Detail"

		if doctype and self.reference_name:
			child_doc = frappe.qb.DocType(doctype)

			query = (
				frappe.qb.update(child_doc)
				.set(child_doc.quality_inspection, quality_inspection)
				.where(
					(child_doc.parent == self.reference_name) & (child_doc.item_code == self.item_code)
				)
			)

			if self.batch_no and self.docstatus < 2:
				query = query.where(child_doc.batch_no == self.batch_no)

			if self.docstatus == 2 or remove_reference:
				query = query.where(child_doc.quality_inspection == self.name)
			else:
				query = query.where(IfNull(child_doc.quality_inspection, "").isin(["", self.name]))

			if self.child_row_reference:
				query = query.where(child_doc.name == self.child_row_reference)

			query.run()

			frappe.db.set_value(
				self.reference_type,
				self.reference_name,
				"modified",
				self.modified,
			)

	if self.reference_type and self.reference_name:
		frappe.get_lazy_doc(self.reference_type, self.reference_name).notify_update()

def inspect_and_set_status(self):
	for reading in self.readings:
		if not reading.manual_inspection:  # dont auto set status if manual
			if reading.formula_based_criteria:
				self.set_status_based_on_acceptance_formula(reading)
			else:
				# if not formula based check acceptance values set
				self.set_status_based_on_acceptance_values(reading)

	if not self.manual_inspection:
		self.status = "Accepted"
		for reading in self.readings:
			if reading.status == "Rejected":
				self.status = "Rejected"
				frappe.msgprint(
					_("Status set to rejected as there are one or more rejected readings."), alert=True
				)
				break

def set_status_based_on_acceptance_values(self, reading):
	if not cint(reading.numeric):
		reading_value = reading.get("reading_value") or ""
		value = reading.get("value") or ""
		result = reading_value == value
	else:
		# numeric readings
		result = self.min_max_criteria_passed(reading)

	reading.status = "Accepted" if result else "Rejected"

def min_max_criteria_passed(self, reading):
	"""Determine whether all readings fall in the acceptable range."""
	has_reading = False
	for i in range(1, 11):
		reading_value = reading.get("reading_" + str(i))
		if reading_value is not None and reading_value.strip():
			has_reading = True
			result = (
				flt(reading.get("min_value"))
				<= parse_float(reading_value)
				<= flt(reading.get("max_value"))
			)
			if not result:
				return False
	return has_reading

def set_status_based_on_acceptance_formula(self, reading):
	if not reading.acceptance_formula:
		frappe.throw(
			_("Row #{0}: Acceptance Criteria Formula is required.").format(reading.idx),
			title=_("Missing Formula"),
		)

	condition = reading.acceptance_formula
	data = self.get_formula_evaluation_data(reading)

	try:
		result = frappe.safe_eval(condition, None, data)
		reading.status = "Accepted" if result else "Rejected"
	except NameError as e:
		field = frappe.bold(e.args[0].split()[1])
		frappe.throw(
			_(
				"Row #{0}: {1} is not a valid reading field. Please refer to the field description."
			).format(reading.idx, field),
			title=_("Invalid Formula"),
		)
	except Exception:
		frappe.throw(
			_("Row #{0}: Acceptance Criteria Formula is incorrect.").format(reading.idx),
			title=_("Invalid Formula"),
		)

def calculate_mean(self, reading):
	"""Calculate mean of all non-empty readings."""
	from statistics import mean

	readings_list = []

	for i in range(1, 11):
		reading_value = reading.get("reading_" + str(i))
		if reading_value is not None and reading_value.strip():
			readings_list.append(parse_float(reading_value))

	actual_mean = mean(readings_list) if readings_list else 0
	return actual_mean

def quality_inspection_query(doctype, txt, searchfield, start, page_len, filters):
