@Override
public Optional<StockMove> copyAndSplitStockMove(StockMove stockMove) throws AxelorException {

  if (stockMove == null || !isNewBackorderLinePossible(stockMove)) {
    return Optional.empty();
  }

  StockMove newStockMove = stockMoveRepo.copy(stockMove, false);

  setOrigin(stockMove, newStockMove);
  newStockMove.setOrigin(stockMove.getOrigin());
  newStockMove.setRealDate(null);
  newStockMove.setStockMoveSeq(
      stockMoveToolService.getSequenceStockMove(
          newStockMove.getTypeSelect(), newStockMove.getCompany(), stockMove));
  newStockMove.setName(
      stockMoveToolService.computeName(
          newStockMove,
          newStockMove.getStockMoveSeq()
              + " "
              + I18n.get(StockExceptionMessage.STOCK_MOVE_7)
              + " "
              + stockMove.getStockMoveSeq()
              + " )"));
  newStockMove.setExTaxTotal(stockMoveToolService.compute(newStockMove));
  newStockMove.setShipmentMode(null);
  newStockMove.setFreightCarrierMode(null);
  newStockMove.setCarrierPartner(null);
  newStockMove.setForwarderPartner(null);
  newStockMove.setIncoterm(null);
  newStockMove.setTrackingNumber(null);
  newStockMove.setModeOfTransport(null);
  newStockMove.setNumOfPackages(0);
  newStockMove.setNumOfPalettes(0);
  newStockMove.setGrossMass(BigDecimal.ZERO);
  newStockMove.setIsIspmRequired(false);
  newStockMove.setIsNeedingConformityCertificate(false);
  newStockMove.setSignatoryUser(null);
  newStockMove.setIsConformityCertifSigned(false);
  newStockMove.setElectronicSignature(null);
  newStockMove.setStockMoveOrigin(stockMove);
  newStockMove = stockMoveRepo.save(newStockMove);
  stockMove.setBackorderId(newStockMove.getId());
  stockMoveRepo.save(stockMove);
  final StockMove[] newStockMoveHolder = new StockMove[] {newStockMove};
  BatchProcessorHelper.of()
      .<StockMoveLine, AxelorException>forEachByQuery(
          getStockMoveLineQuery(stockMove.getId()),
          line -> processBackorderLine(line, newStockMoveHolder[0]),
          () -> newStockMoveHolder[0] = stockMoveRepo.find(newStockMoveHolder[0].getId()));
  newStockMove = stockMoveRepo.find(newStockMove.getId());
  plan(newStockMove);
  return Optional.of(stockMoveRepo.find(newStockMove.getId()));
}

@Override
public boolean mustBeSplit(StockMove stockMove) {
  return stockMoveLineRepo
          .all()
          .filter("self.stockMove.id = :stockMoveId AND self.realQty != self.qty")
          .bind("stockMoveId", stockMove.getId())
          .count()
      > 0;
}

protected void computeMasses(StockMove stockMove) throws AxelorException {
  Company company = Beans.get(CompanyRepository.class).find(stockMove.getCompany().getId());
  StockConfig stockConfig = company.getStockConfig();
  Unit endUnit = stockConfig != null ? stockConfig.getCustomsMassUnit() : null;
  UnitConversionService unitConversionService = Beans.get(UnitConversionService.class);

  final long stockMoveId = stockMove.getId();
  final StockMove[] stockMoveHolder = {stockMoveRepo.find(stockMoveId)};

  Query<StockMoveLine> query =
      stockMoveLineRepo
          .all()
          .filter(
              "self.stockMove.id = :stockMoveId "
                  + "AND self.product IS NOT NULL "
                  + "AND self.product.productTypeSelect = :storable "
                  + "AND self.id > :lastSeenId")
          .bind("stockMoveId", stockMove.getId())
          .bind("storable", ProductRepository.PRODUCT_TYPE_STORABLE)
          .order("id");

  BatchProcessorHelper.of()
      .<StockMoveLine, AxelorException>forEachByQuery(
          query,
          stockMoveLine -> {
            Product product = stockMoveLine.getProduct();
            if (product == null
                || !ProductRepository.PRODUCT_TYPE_STORABLE.equals(
                    product.getProductTypeSelect())) {
              return;
            }

            boolean massesRequiredForStockMoveLine =
                stockMoveLineService.checkMassesRequired(stockMoveHolder[0], stockMoveLine);

            if (massesRequiredForStockMoveLine && endUnit == null) {
              throw new AxelorException(
                  stockMoveHolder[0],
                  TraceBackRepository.CATEGORY_NO_VALUE,
                  I18n.get(StockExceptionMessage.STOCK_MOVE_17));
            }

            computeNetMass(stockMoveLine, endUnit, unitConversionService);
            computeTotalNetMass(stockMoveLine, massesRequiredForStockMoveLine);
          },
          () -> stockMoveHolder[0] = stockMoveRepo.find(stockMoveId));
}

protected void resetMasses(StockMove stockMove) {

  Long stockMoveId = stockMove.getId();
  Query<StockMoveLine> query = getStockMoveLineQuery(stockMoveId);

  BatchProcessorHelper.of()
      .<StockMoveLine>forEachByQuery(query, (StockMoveLine sml) -> sml.setTotalNetMass(null));
}

protected void checkOngoingInventory(StockMove stockMove) throws AxelorException {

  BatchProcessorHelper batchHelper =
      BatchProcessorHelper.builder().flushAfterBatch(false).build();

  Set<Long> stockLocationIds = new HashSet<>();
  Set<Long> productIds = new HashSet<>();
  Long stockMoveId = stockMove.getId();
  Query<StockMoveLine> smlQuery = getStockMoveLineQuery(stockMoveId);

  batchHelper.<StockMoveLine>forEachByQuery(
      smlQuery,
      sml -> {
        StockLocation from = sml.getFromStockLocation();
        StockLocation to = sml.getToStockLocation();
        if (from != null && from.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
          stockLocationIds.add(from.getId());
          Set<Long> locationIds =
              stockLocationService
                  .getLocationAndAllParentLocationsIdsOrderedFromTheClosestToTheFurthest(from);
          if (locationIds != null) {
            stockLocationIds.addAll(locationIds);
          }
        }
        if (to != null && to.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
          stockLocationIds.add(to.getId());
          Set<Long> locationIds =
              stockLocationService
                  .getLocationAndAllParentLocationsIdsOrderedFromTheClosestToTheFurthest(to);
          if (locationIds != null) {
            stockLocationIds.addAll(locationIds);
          }
        }

        if (sml.getProduct() != null) {
          productIds.add(sml.getProduct().getId());
        }
      });

  if (stockLocationIds.isEmpty() || productIds.isEmpty()) {
    return;
  }

  InventoryLineRepository inventoryLineRepo = Beans.get(InventoryLineRepository.class);

  InventoryLine inventoryLine =
      inventoryLineRepo
          .all()
          .filter(
              "self.inventory.isStockMoveBlocked = true\n"
                  + "AND self.inventory.stockLocation.id IN (:stockLocationIds)\n"
                  + "AND self.product.id IN (:productList)")
          .bind("stockLocationIds", stockLocationIds)
          .bind("productList", productIds)
          .fetchOne();

  if (inventoryLine != null) {
    throw new AxelorException(
        inventoryLine,
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_19),
        inventoryLine.getInventory().getInventorySeq());
  }
}

protected void processBackorderLine(StockMoveLine stockMoveLine, StockMove newStockMove)
    throws AxelorException {
  if (stockMoveLine.getQty().compareTo(stockMoveLine.getRealQty()) <= 0) {
    return;
  }
  StockMoveLine newStockMoveLine = copySplittedStockMoveLine(stockMoveLine);
  newStockMove.addStockMoveLineListItem(newStockMoveLine);

  Product product = newStockMoveLine.getProduct();
  if (product != null) {
    TrackingNumberConfiguration trackingNumberConfiguration =
        (TrackingNumberConfiguration)
            productCompanyService.get(
                product, "trackingNumberConfiguration", newStockMove.getCompany());

    newStockMoveLine.setTrackingNumber(null);
    stockMoveLineService.assignOrGenerateTrackingNumber(
        newStockMoveLine,
        newStockMove,
        product,
        trackingNumberConfiguration,
        newStockMove.getTypeSelect() == StockMoveRepository.TYPE_OUTGOING
            ? StockMoveLineService.TYPE_SALES
            : StockMoveLineService.TYPE_PURCHASES);
  }
}

protected boolean isNewBackorderLinePossible(StockMove stockMove) throws AxelorException {
  return stockMoveLineRepo
          .all()
          .filter("self.stockMove.id = :stockMoveId AND self.qty > self.realQty")
          .bind("stockMoveId", stockMove.getId())
          .count()
      > 0;
}

protected void computeTotalNetMass(
    StockMoveLine stockMoveLine, boolean massesRequiredForStockMoveLine) throws AxelorException {
  BigDecimal netMass = stockMoveLine.getNetMass();
  if (netMass.signum() != 0) {
    BigDecimal totalNetMass = netMass.multiply(stockMoveLine.getRealQty());
    stockMoveLine.setTotalNetMass(totalNetMass);
  } else if (massesRequiredForStockMoveLine) {
    throw new AxelorException(
        stockMoveLine.getStockMove(),
        TraceBackRepository.CATEGORY_NO_VALUE,
        I18n.get(StockExceptionMessage.STOCK_MOVE_18));
  }
}

protected void computeNetMass(
    StockMoveLine stockMoveLine, Unit endUnit, UnitConversionService unitConversionService)
    throws AxelorException {
  BigDecimal netMass = stockMoveLine.getNetMass();
  Product product = stockMoveLine.getProduct();
  if (netMass.signum() == 0) {
    Unit startUnit = product.getMassUnit();
    if (startUnit != null && endUnit != null) {
      netMass =
          unitConversionService.convert(
              startUnit, endUnit, product.getNetMass(), product.getNetMass().scale(), null);
      stockMoveLine.setNetMass(netMass);
    }
  }
}

protected StockMoveLine copySplittedStockMoveLine(StockMoveLine stockMoveLine)
    throws AxelorException {
  StockMoveLine newStockMoveLine = stockMoveLineRepo.copy(stockMoveLine, false);

  newStockMoveLine.setQty(stockMoveLine.getQty().subtract(stockMoveLine.getRealQty()));

  stockMoveLineService.fillRealQuantities(
      newStockMoveLine, stockMoveLine.getStockMove(), newStockMoveLine.getQty());
  return newStockMoveLine;
}

def on_submit(self):
	if not self.shipment_parcel:
		frappe.throw(_("Please enter Shipment Parcel information"))
	if flt(self.value_of_goods) <= 0:
		frappe.throw(_("Value of goods must be greater than 0"))
	self.db_set("status", "Submitted")

def validate_weight(self):
	for parcel in self.shipment_parcel:
		if flt(parcel.weight) <= 0:
			frappe.throw(_("Parcel weight cannot be 0"))

		if cint(parcel.count) < 1:
			frappe.throw(_("Row #{0}: Parcel count must be at least 1").format(parcel.idx))

		for fieldname in ("length", "width", "height"):
			if flt(parcel.get(fieldname)) < 0:
				frappe.throw(
					_("Row #{0}: Parcel {1} cannot be negative").format(
						parcel.idx, _(parcel.meta.get_label(fieldname))
					)
				)

def validate_pickup_time(self):
	if self.pickup_from and self.pickup_to and get_time(self.pickup_to) <= get_time(self.pickup_from):
		frappe.throw(_("Pickup To time should be greater than Pickup From time"))

	if (self.is_new() or self.has_value_changed("pickup_date")) and getdate(self.pickup_date) < getdate():
		frappe.throw(_("Pickup Date cannot be before today"))

def validate_parties(self):
	for side, party_type in (("pickup", self.pickup_from_type), ("delivery", self.delivery_to_type)):
		party = self.get(f"{side}_{frappe.scrub(party_type)}")
		if not party:
			frappe.throw(_("{0} is required for the {1} party").format(_(party_type), _(side.title())))

		for other_type in ("Company", "Customer", "Supplier"):
			if other_type != party_type:
				self.set(f"{side}_{frappe.scrub(other_type)}", None)

		self.set("pickup" if side == "pickup" else "delivery_to", party)
		if self.is_new() or self.has_party_details_changed(side):
			self.validate_party_links(side, party_type, party)

def has_party_details_changed(self, side):
	return any(
		self.has_value_changed(f"{side}_{fieldname}")
		for fieldname in ("company", "customer", "supplier", "address_name", "contact_name")
	)

def validate_party_links(self, side, party_type, party):
	for doctype, fieldname in (("Address", f"{side}_address_name"), ("Contact", f"{side}_contact_name")):
		name = self.get(fieldname)
		if name and not is_linked_to_party(doctype, name, party_type, party):
			frappe.throw(
				_("{0} {1} is not linked to {2} {3}").format(
					_(doctype), bold(name), _(party_type), bold(party)
				)
			)

def validate_delivery_notes(self):
	delivery_notes = set()
	for row in self.get("shipment_delivery_note"):
		if row.delivery_note in delivery_notes:
			frappe.throw(
				_("Row #{0}: Delivery Note {1} is added more than once").format(
					row.idx, bold(row.delivery_note)
				)
			)

		delivery_notes.add(row.delivery_note)
		self.validate_delivery_note_row(row)

def validate_delivery_note_row(self, row):
	lock = self.docstatus == 1
	delivery_note = frappe.db.get_value(
		"Delivery Note",
		row.delivery_note,
		["docstatus", "customer", "base_grand_total"],
		as_dict=True,
		for_update=lock,
	)
	if delivery_note.docstatus != 1:
		frappe.throw(
			_("Row #{0}: Delivery Note {1} must be submitted").format(row.idx, bold(row.delivery_note))
		)

	if self.delivery_to_type == "Customer" and delivery_note.customer != self.delivery_customer:
		frappe.throw(
			_("Row #{0}: Delivery Note {1} belongs to Customer {2}").format(
				row.idx, bold(row.delivery_note), bold(delivery_note.customer)
			)
		)

	if shipment := get_other_shipment(row.delivery_note, self.name, for_update=lock):
		frappe.throw(
			_("Row #{0}: Delivery Note {1} is already in Shipment {2}").format(
				row.idx, bold(row.delivery_note), get_link_to_form("Shipment", shipment)
			)
		)

	row.grand_total = delivery_note.base_grand_total

def set_value_of_goods(self):
	value_of_goods = 0
	for entry in self.get("shipment_delivery_note"):
		value_of_goods += flt(entry.get("grand_total"))
	self.value_of_goods = value_of_goods if value_of_goods else self.value_of_goods

def is_linked_to_party(doctype, name, party_type, party):
	return bool(
		frappe.db.exists(
			"Dynamic Link",
			{"parenttype": doctype, "parent": name, "link_doctype": party_type, "link_name": party},
		)
	)

def __init__(self, *args, **kwargs):
	super().__init__(*args, **kwargs)

	# Google Maps returns distances in meters by default
	self.default_distance_uom = (
		frappe.db.get_single_value("Global Defaults", "default_distance_unit") or "Meter"
	)
	self.uom_conversion_factor = frappe.db.get_value(
		"UOM Conversion Factor", {"from_uom": "Meter", "to_uom": self.default_distance_uom}, "value"
	)

def on_discard(self):
	self.update_status()
	self.update_delivery_notes(delete=True)

def after_mapping(self, source_doc):
	for stop in self.delivery_stops[:]:
		if not any(stop.get(df.fieldname) for df in stop.meta.fields):
			self.remove(stop)

def validate(self):
	if self._action == "submit" and not self.driver:
		frappe.throw(_("A driver must be set to submit."))

	if self._action == "submit":
		self.validate_delivery_note_not_draft()
	self.validate_delivery_notes_not_on_other_trips()
	self.validate_stop_addresses()
	self.validate_stop_contacts()

def on_update(self):
	self.update_delivery_notes()
	self.release_removed_delivery_notes()

def on_cancel(self):
	self.update_status()
	self.update_delivery_notes(delete=True)

def validate_stop_addresses(self):
	for stop in self.delivery_stops:
		if stop.address and not stop.customer_address:
			stop.customer_address = get_address_display(frappe.get_doc("Address", stop.address).as_dict())

def validate_stop_contacts(self):
	stops = [stop for stop in self.delivery_stops if stop.contact and stop.customer]
	if not stops:
		return

	dynamic_link = frappe.qb.DocType("Dynamic Link")
	contact_customers = set(
		frappe.qb.from_(dynamic_link)
		.select(dynamic_link.parent, dynamic_link.link_name)
		.where(
			(dynamic_link.parenttype == "Contact")
			& (dynamic_link.link_doctype == "Customer")
			& dynamic_link.parent.isin({stop.contact for stop in stops})
		)
		.run()
	)
	for stop in stops:
		if (stop.contact, stop.customer) not in contact_customers:
			frappe.throw(
				_("Row #{0}: Contact {1} does not belong to Customer {2}").format(
					stop.idx, frappe.bold(stop.contact), frappe.bold(stop.customer)
				)
			)

def validate_delivery_note_not_draft(self):
	delivery_notes = list(set(stop.delivery_note for stop in self.delivery_stops if stop.delivery_note))
	draft_delivery_notes = frappe.get_all(
		"Delivery Note",
		{"docstatus": 0, "name": ["in", delivery_notes]},
		pluck="name",
	)
	if draft_delivery_notes:
		frappe.throw(
			_(
				"Delivery Notes should not be in draft state when submitting a Delivery Trip. The following Delivery Notes are still in draft state: {0}. Please submit them first."
			).format(", ".join(draft_delivery_notes))
		)

def validate_delivery_notes_not_on_other_trips(self):
	delivery_notes = {stop.delivery_note for stop in self.delivery_stops if stop.delivery_note}
	if not delivery_notes:
		return

	delivery_note = frappe.qb.DocType("Delivery Note")
	notes = (
		frappe.qb.from_(delivery_note)
		.select(delivery_note.name, delivery_note.delivery_trip, delivery_note.company)
		.where(delivery_note.name.isin(delivery_notes))
		.for_update()
		.run(as_dict=True)
	)
	if other_company := [d.name for d in notes if self.company and d.company != self.company]:
		frappe.throw(
			_("Delivery Notes {0} do not belong to Company {1}").format(
				", ".join(other_company), frappe.bold(self.company)
			)
		)

	other_trips = {d.delivery_trip for d in notes if d.delivery_trip and d.delivery_trip != self.name}
	open_trips = other_trips and set(
		frappe.get_all(
			"Delivery Trip",
			filters={"name": ("in", list(other_trips)), "docstatus": ("<", 2)},
			pluck="name",
		)
	)
	if linked := [d for d in notes if open_trips and d.delivery_trip in open_trips]:
		frappe.throw(
			_("Delivery Notes are already on another Delivery Trip: {0}").format(
				", ".join(f"{d.name} ({d.delivery_trip})" for d in linked)
			)
		)

def update_status(self):
	status = {0: "Draft", 1: "Scheduled", 2: "Cancelled"}[self.docstatus]

	if self.docstatus == 1:
		visited_stops = [stop.visited for stop in self.delivery_stops]
		if all(visited_stops):
			status = "Completed"
		elif any(visited_stops):
			status = "In Transit"

	self.db_set("status", status)

def release_removed_delivery_notes(self):
	doc_before_save = self.get_doc_before_save()
	if not doc_before_save:
		return

	current = {stop.delivery_note for stop in self.delivery_stops}
	removed = {stop.delivery_note for stop in doc_before_save.delivery_stops if stop.delivery_note}
	if removed - current:
		self.update_delivery_notes(delete=True, delivery_notes=removed - current)

def update_delivery_notes(self, delete=False, delivery_notes=None):
	if delivery_notes is None:
		delivery_notes = {stop.delivery_note for stop in self.delivery_stops if stop.delivery_note}
	if not delivery_notes:
		return

	trip_values = [self.get_delivery_note_values()]
	if doc_before_save := self.get_doc_before_save():
		trip_values.append(doc_before_save.get_delivery_note_values())

	updated = []
	for note in frappe.get_all(
		"Delivery Note",
		filters={"name": ("in", list(delivery_notes))},
		fields=["name", "delivery_trip", *trip_values[0]],
	):
		update = release_delivery_note if delete else link_delivery_note
		if values := update(note, self.name, trip_values):
			frappe.db.set_value("Delivery Note", note.name, values)
			updated.append(get_link_to_form("Delivery Note", note.name))

	if updated:
		frappe.msgprint(_("Delivery Notes {0} updated").format(", ".join(updated)))

def get_delivery_note_values(self):
	return {
		"driver": self.driver,
		"driver_name": self.driver_name,
		"vehicle_no": self.vehicle,
		"lr_no": self.name,
		"lr_date": getdate(self.departure_time) if self.departure_time else None,
	}

def link_delivery_note(note, trip_name, trip_values):
	values = {} if note.delivery_trip == trip_name else {"delivery_trip": trip_name}
	for field, value in trip_values[0].items():
		if note.get(field) != value and (not note.get(field) or is_trip_value(note, field, trip_values)):
			values[field] = value

	return values

def release_delivery_note(note, trip_name, trip_values):
	if note.delivery_trip != trip_name:
		return {}

	values = {"delivery_trip": None}
	for field in trip_values[0]:
		if note.get(field) and is_trip_value(note, field, trip_values):
			values[field] = None

	return values

def is_remote_file(self):
	if self.file_url:
		return self.file_url.startswith(URL_PREFIXES)
	return not self.content

def autoname(self):
	"""Set name for folder"""
	if self.is_folder:
		if self.folder:
			self.name = self.get_name_based_on_parent_folder()
		else:
			# home
			self.name = self.file_name
	else:
		self.name = frappe.generate_hash(length=10)

def after_insert(self):
	if not self.is_folder:
		self.create_attachment_record()

def create_attachment_copy(
	self,
	attached_to_doctype: str,
	attached_to_name: str,
	attached_to_field: str | None = None,
	ignore_permissions: bool = False,
):
	"""Efficiently copy an attachment from one document to another by reusing `file_url`."""
	if self.is_folder:
		frappe.throw(_("Cannot attach a folder to a document"))

	attachment = frappe.copy_doc(self)
	attachment.update(
		{
			"attached_to_doctype": attached_to_doctype,
			"attached_to_name": attached_to_name,
			"attached_to_field": attached_to_field,
		}
	)
	attachment.folder = None
	attachment.flags.copy_from_existing_file = True
	return attachment.insert(ignore_permissions=ignore_permissions)

def validate(self):
	if self.is_folder:
		if self.file_url:
			frappe.throw(_("A folder cannot have a File URL"))
		return

	if self.is_remote_file:
		self.content_hash = None

	self.validate_attachment_references()
	self.enforce_public_file_restrictions()

	# must run before handle_is_private_changed, which legitimately rewrites file_url
	if not self.is_new() and self.has_value_changed("file_url"):
		self.validate_private_file_access()

	# when dict is passed to get_doc for creation of new_doc, is_new returns None
	# this case is handled inside handle_is_private_changed
	if not self.is_new() and self.has_value_changed("is_private"):
		self.handle_is_private_changed()

	self.validate_file_path()
	self.validate_file_url()
	self.validate_file_on_disk()
	self.file_size = frappe.form_dict.file_size or self.file_size

def validate_attachment_references(self):
	if not self.attached_to_doctype:
		return

	if not self.attached_to_name or not isinstance(self.attached_to_name, str | int):
		frappe.throw(
			_("Attached To Name must be a string or an integer"),
			frappe.ValidationError,
		)

	if self.attached_to_field and SPECIAL_CHAR_PATTERN.search(self.attached_to_field):
		frappe.throw(_("The fieldname you've specified in Attached To Field is invalid"))

	if self.flags.ignore_permissions or frappe.flags.in_install:
		return

	from frappe.handler import check_write_permission

	check_write_permission(self.attached_to_doctype, self.attached_to_name)

def enforce_public_file_restrictions(self):
	if not self.is_private and frappe.get_system_settings(
		"only_allow_system_managers_to_upload_public_files"
	):
		try:
			frappe.only_for("System Manager")
		except PermissionError:
			frappe.throw(_("Only System Managers can make this file public."))

def validate_private_file_access(self):
	"""Validate that the user has permission to access an existing private file."""
	if not self.file_url:
		return

	filters = {"file_url": self.file_url, "is_private": 1}
	if not self.is_new():
		filters["name"] = ["!=", self.name]

	private_files = frappe.get_all("File", filters=filters, fields=["name", "owner"])
	if not private_files:
		return

	user = frappe.session.user
	if user == "Administrator":
		return

	# a file can be attached to multiple documents; access to any one of them is enough
	for private_file in private_files:
		if user == private_file.owner:
			return

		if has_permission(frappe.get_doc("File", private_file.name), "read", user=user):
			return

	frappe.throw(
		_("You do not have permission to access this file"),
		frappe.PermissionError,
	)

def after_rename(self, *args, **kwargs):
	for successor in self.get_successors():
		setup_folder_path(successor, self.name)

def on_trash(self):
	if self.is_home_folder or self.is_attachments_folder:
		frappe.throw(_("Cannot delete Home and Attachments folders"))
	self.validate_empty_folder()
	self.validate_protected_file()
	self._delete_file_on_disk()
	if not self.is_folder:
		self.add_comment_in_reference_doc("Attachment Removed", self.file_name)

def get_name_based_on_parent_folder(self) -> str | None:
	if self.folder:
		return os.path.join(self.folder, self.file_name)

def validate_file_path(self):
	if self.is_remote_file:
		return

	if self.file_url and ".." in self.file_url.split("/"):
		frappe.throw(_("The File URL you've entered is incorrect"), title=_("Invalid File URL"))

	base_path = os.path.realpath(get_files_path(is_private=self.is_private))
	file_path = os.path.realpath(self.get_full_path())
	if os.path.commonpath((base_path, file_path)) != base_path:
		frappe.throw(
			_("The File URL you've entered is incorrect"),
			title=_("Invalid File URL"),
		)

def validate_file_url(self):
	if self.is_remote_file or not self.file_url:
		return

	if not self.file_url.startswith(("/files/", "/private/files/")):
		# Probably an invalid URL since it doesn't start with http either
		frappe.throw(
			_("URL must start with http:// or https://"),
			title=_("Invalid URL"),
		)

def fetch_attached_to_field(self, old_file_url):
	if self.attached_to_field:
		return True

	reference_dict = frappe.get_doc(self.attached_to_doctype, self.attached_to_name).as_dict()

	for key, value in reference_dict.items():
		if value == old_file_url:
			self.attached_to_field = key
			return True

def validate_attachment_limit(self):
	attachment_limit = 0
	if self.attached_to_doctype and self.attached_to_name:
		attachment_limit = cint(frappe.get_meta(self.attached_to_doctype).max_attachments)

	if attachment_limit:
		current_attachment_count = len(
			frappe.get_all(
				"File",
				filters={
					"attached_to_doctype": self.attached_to_doctype,
					"attached_to_name": self.attached_to_name,
				},
				limit=attachment_limit + 1,
			)
		)

		if current_attachment_count >= attachment_limit:
			frappe.throw(
				_("Maximum Attachment Limit of {0} has been reached for {1} {2}.").format(
					frappe.bold(attachment_limit),
					self.attached_to_doctype,
					self.attached_to_name,
				),
				exc=AttachmentLimitReached,
				title=_("Attachment Limit Reached"),
			)

def validate_remote_file(self):
	"""Validates if file uploaded using URL already exist"""
	site_url = get_url()
	if self.file_url and "/files/" in self.file_url and self.file_url.startswith(site_url):
		self.file_url = self.file_url.split(site_url, 1)[1]

def set_folder_name(self):
	"""Make parent folders if not exists based on reference doctype and name"""
	if self.folder:
		return

	if self.attached_to_doctype:
		self.folder = frappe.db.get_value("File", {"is_attachments_folder": 1})

	elif not self.is_home_folder:
		self.folder = "Home"

def set_file_type(self):
	if self.is_folder:
		return

	file_type = mimetypes.guess_type(self.file_name)[0]
	if not file_type:
		return

	file_extension = mimetypes.guess_extension(file_type)
	self.file_type = file_extension.lstrip(".").upper() if file_extension else None

def validate_file_on_disk(self):
	"""Validates existence file"""
	full_path = self.get_full_path()

	if full_path.startswith(URL_PREFIXES):
		return True

	if not os.path.exists(full_path):
		frappe.throw(_("File {0} does not exist").format(self.file_url), IOError)

def validate_file_extension(self):
	# Only validate uploaded files, not generated by code/integrations.
	if self.is_folder or not frappe.request:
		return

	allowed_extensions = frappe.get_system_settings("allowed_file_extensions")
	if not allowed_extensions:
		return

	file_extension = os.path.splitext(self.file_name)[1].lstrip(".").upper()
	if file_extension not in allowed_extensions.splitlines():
		frappe.throw(
			_("File type of {0} is not allowed").format(file_extension),
			exc=FileTypeNotAllowed,
		)

def check_content(self):
	from frappe.utils.pdf import pdf_contains_js

	if self.file_type == "PDF" and self._content and pdf_contains_js(self._content):
		frappe.throw(_("This PDF cannot be uploaded as it contains unsafe content."))

def validate_duplicate_entry(self):
	if not self.flags.ignore_duplicate_entry_error and not self.is_folder:
		if not self.content_hash:
			self.generate_content_hash()

		# check duplicate name
		# check duplicate assignment
		filters = {
			"content_hash": self.content_hash,
			"is_private": self.is_private,
		}

		if self.name:
			filters.update({"name": ("!=", self.name)})

		if self.attached_to_doctype and self.attached_to_name:
			filters.update(
				{
					"attached_to_doctype": self.attached_to_doctype,
					"attached_to_name": self.attached_to_name,
				}
			)
		duplicate_file = frappe.db.get_value("File", filters, ["name", "file_url"], as_dict=1)

		if duplicate_file:
			duplicate_file_doc = frappe.get_cached_doc("File", duplicate_file.name)
			if duplicate_file_doc.exists_on_disk():
				# just use the url, to avoid uploading a duplicate
				self.file_url = duplicate_file.file_url

def set_file_name(self):
	if not self.file_name and not self.file_url:
		frappe.throw(
			_("Fields `file_name` or `file_url` must be set for File"),
			exc=frappe.MandatoryError,
		)
	elif not self.file_name and self.file_url:
		self.file_name = self.file_url.split("/")[-1].split("?")[0]
	else:
		self.file_name = re.sub(r"/", "", self.file_name)

def generate_content_hash(self):
	if self.content_hash or not self.file_url or self.is_remote_file:
		return
	file_name = self.file_url.split("/")[-1]
	try:
		file_path = get_files_path(file_name, is_private=self.is_private)
		with open(file_path, "rb") as f:
			self.content_hash = get_content_hash(f.read())
	except OSError:
		frappe.throw(_("File {0} does not exist").format(file_path))

def validate_empty_folder(self):
	"""Throw exception if folder is not empty"""
	if self.is_folder and frappe.get_all("File", filters={"folder": self.name}, limit=1):
		frappe.throw(_("Folder {0} is not empty").format(self.name), FolderNotEmpty)

def validate_protected_file(self):
	"""Throw an exception if this file is attached to a doctype that protects files.

	Allows deleting the attached file if the linked document is in draft. If submitted,
	deletion is not allowed. If canceled, requires delete permissions on the linked document.
	"""
	if not (self.attached_to_doctype and self.attached_to_name):
		return

	try:
		ref_doc = frappe.get_doc(self.attached_to_doctype, self.attached_to_name)
	except DoesNotExistError:
		return

	if ref_doc.docstatus == 0:
		# If the document is not submitted yet, users can correct wrong attachments
		return

	if not ref_doc.meta.protect_attached_files:
		return

	if ref_doc.docstatus == 2 and ref_doc.has_permission("delete"):
		# Deletion must still be possible if users have the permission to delete the linked document
		return

	frappe.throw(
		msg=_("This file is attached to a protected document and cannot be deleted."),
		title=_("Protected File"),
	)

def _delete_file_on_disk(self):
	"""If file not attached to any other record, delete it"""
	on_disk_file_not_shared = self.content_hash and not frappe.get_all(
		"File",
		filters={
			"content_hash": self.content_hash,
			"name": ["!=", self.name],
			# NOTE: Some old Files might share file_urls while not sharing the is_private value
			# "is_private": self.is_private,
		},
		limit=1,
	)
	if on_disk_file_not_shared:
		self.delete_file_data_content()
	else:
		self.delete_file_data_content(only_thumbnail=True)

def get_content(self, encodings=None) -> bytes | str:
	if self.is_folder:
		frappe.throw(_("Cannot get file contents of a Folder"))

	self.validate_file_path()
	# if doc was just created, content field is already populated, return it as-is
	if self.get("content"):
		self._content = self.content
		if self.decode:
			self._content = decode_file_content(self._content)
			self.decode = False
		# self.content = None # TODO: This needs to happen; make it happen somehow
		return self._content

	if self.file_url:
		self.validate_file_url()
	file_path = self.get_full_path()

	if encodings is None:
		encodings = FILE_ENCODING_OPTIONS
	with open(file_path, mode="rb") as f:
		self._content = f.read()
		if not self._content.startswith(OLE_FILE_SIGNATURE):
			# looping will not result in slowdown, as the content is usually utf-8 or utf-8-sig
			# encoded so the first iteration will be enough most of the time
			for encoding in encodings:
				try:
					# read file with proper encoding
					self._content = self._content.decode(encoding)
					break
				except UnicodeDecodeError:
					# for .png, .jpg, etc
					continue

	return self._content

def get_full_path(self):
	"""Return file path using the set file name."""

	file_path = self.file_url or self.file_name

	site_url = get_url()
	if "/files/" in file_path and file_path.startswith(site_url):
		file_path = file_path.split(site_url, 1)[1]

	if "/" not in file_path:
		if self.is_private:
			file_path = f"/private/files/{file_path}"
		else:
			file_path = f"/files/{file_path}"

	if file_path.startswith("/private/files/"):
		file_path = get_files_path(*file_path.split("/private/files/", 1)[1].split("/"), is_private=1)

	elif file_path.startswith("/files/"):
		file_path = get_files_path(*file_path.split("/files/", 1)[1].split("/"))

	elif file_path.startswith(URL_PREFIXES):
		pass

	elif not self.file_url:
		frappe.throw(_("There is some problem with the file url: {0}").format(file_path))

	if not is_safe_path(file_path):
		frappe.throw(_("Cannot access file path {0}").format(file_path))

	if os.path.sep in self.file_name:
		frappe.throw(_("File name cannot have {0}").format(os.path.sep))

	return file_path

def save_file(
	self,
	content: bytes | str | None = None,
	decode=False,
	ignore_existing_file_check=False,
	overwrite=False,
):
	if self.is_remote_file:
		return

	if not self.flags.new_file:
		self.flags.original_content = self.get_content()

	if content:
		self.content = content
		self.decode = decode
		self.get_content()

	if not self._content:
		return

	file_exists = False
	duplicate_file = None

	self.is_private = cint(self.is_private)
	self.content_type = mimetypes.guess_type(self.file_name)[0]

	# transform file content based on site settings
	if (
		self.content_type
		and self.content_type == "image/jpeg"
		and frappe.get_system_settings("strip_exif_metadata_from_uploaded_images")
	):
		from frappe.utils.image import strip_exif_data

		self._content = strip_exif_data(self._content, self.content_type)

	self.file_size = self.check_max_file_size()
	self.content_hash = get_content_hash(self._content)

	# check if a file exists with the same content hash and is also in the same folder (public or private)
	if not ignore_existing_file_check:
		duplicate_file = frappe.get_value(
			"File",
			{"content_hash": self.content_hash, "is_private": self.is_private},
			["file_url", "name"],
			as_dict=True,
		)

	if duplicate_file:
		file_doc: File = frappe.get_cached_doc("File", duplicate_file.name)
		if file_doc.exists_on_disk():
			if self.exists_on_disk():
				if not self.file_url:
					self.file_url = duplicate_file.file_url
			else:
				self.file_url = duplicate_file.file_url
			file_exists = True

	if not file_exists:
		if not overwrite:
			self.file_name = generate_file_name(
				name=self.file_name,
				suffix=self.content_hash[-6:],
				is_private=self.is_private,
			)
		call_hook_method("before_write_file", file_size=self.file_size)
		write_file_method = get_hook_method("write_file")
		if write_file_method:
			return write_file_method(self)
		return self.save_file_on_filesystem()

def save_file_on_filesystem(self):
	safe_file_name = get_safe_file_name(self.file_name)
	if self.is_private:
		self.file_url = f"/private/files/{safe_file_name}"
	else:
		self.file_url = f"/files/{safe_file_name}"

	fpath = self.write_file()

	return {"file_name": os.path.basename(fpath), "file_url": self.file_url}

def check_max_file_size(self):
	from frappe.core.api.file import get_max_file_size

	max_file_size = get_max_file_size()
	file_size = len(self._content or b"")

	if file_size > max_file_size:
		msg = _("File size exceeded the maximum allowed size of {0} MB").format(max_file_size / 1048576)
		if frappe.has_permission("System Settings", "write"):
			msg += ".<br>" + _("You can increase the limit from System Settings.")
		frappe.throw(msg, exc=MaxFileSizeReachedError)

	return file_size

def delete_file_data_content(self, only_thumbnail=False):
	method = get_hook_method("delete_file_data_content")
	if method:
		method(self, only_thumbnail=only_thumbnail)
	else:
		self.delete_file_from_filesystem(only_thumbnail=only_thumbnail)

def delete_file_from_filesystem(self, only_thumbnail=False):
	"""Delete file, thumbnail from File document"""
	if only_thumbnail:
		delete_file(self.thumbnail_url)
	else:
		delete_file(self.file_url)
		delete_file(self.thumbnail_url)

def get_extension(self):
	"""Split and return filename and extension for the set `file_name`."""
	return os.path.splitext(self.file_name)

def add_comment_in_reference_doc(self, comment_type, text):
	if self.attached_to_doctype and self.attached_to_name:
		try:
			doc = frappe.get_doc(self.attached_to_doctype, self.attached_to_name)
			doc.add_comment(comment_type, text)
		except frappe.DoesNotExistError:
			frappe.clear_messages()

def set_is_private(self):
	if self.is_private:
		return

	if self.file_url:
		self.is_private = cint(self.file_url.startswith("/private"))

def validate_file_url_matches_record(self):
	"""Ensure file_url actually resolves back to an existing File record with this name."""
	if not self.file_url:
		return

	actual_file_url = frappe.db.get_value("File", self.name, "file_url") if self.name else None
	if actual_file_url != self.file_url:
		frappe.throw(_("The File URL does not belong to this File record"), frappe.PermissionError)

def unique_url(self) -> str:
	"""Unique URL contains file ID in URL to speed up permisison checks."""
	from urllib.parse import urlencode

	if self.is_private:
		return self.file_url + "?" + urlencode({"fid": self.name})
	else:
		return self.file_url

def zip_files(files):
	zip_file = io.BytesIO()
	zf = zipfile.ZipFile(zip_file, "w", zipfile.ZIP_DEFLATED)
	for _file in files:
		if isinstance(_file, str):
			_file = frappe.get_doc("File", _file)
		if not isinstance(_file, File):
			continue
		if _file.is_folder:
			continue
		if not has_permission(_file, "read"):
			continue
		zf.writestr(_file.file_name, _file.get_content())
	zf.close()
	return zip_file.getvalue()

def _scoped_attachment_condition(doctype: str, user: str, exists_condition: str) -> str:
	"""Build `(attached_to_doctype = X AND (EXISTS(...) OR individually shared))`."""
	table = get_table_name(doctype, wrap_in_backticks=True)
	shared_names = frappe.share.get_shared(doctype, user)
	shared_condition = ""
	if shared_names:
		shared_list = ", ".join(frappe.db.escape(name, percent=False) for name in shared_names)
		shared_condition = f" OR `tabFile`.`attached_to_name` IN ({shared_list})"

	return f"""(`tabFile`.`attached_to_doctype` = {frappe.db.escape(doctype)}
		AND (
			EXISTS (
				SELECT 1 FROM {table}
				WHERE {table}.`name` = `tabFile`.`attached_to_name`
				AND {exists_condition}
			){shared_condition}
		))"""

def has_permission(doc, ptype=None, user=None, debug=False):
	user = user or frappe.session.user

	if user == "Administrator":
		return True

	if not doc.is_private and ptype in ("read", "select"):
		return True

	if user != "Guest" and doc.owner == user:
		return True
	if (
		user != "Guest"
		and ptype in ["read", "write", "share", "submit"]
		and frappe.share.get_shared(
			"File", filters=[["share_name", "=", doc.name]], rights=[ptype], user=user
		)
	):
		return True

	if doc.attached_to_doctype and doc.attached_to_name:
		attached_to_doctype = doc.attached_to_doctype
		attached_to_name = doc.attached_to_name

		try:
			ref_doc = frappe.get_lazy_doc(attached_to_doctype, attached_to_name)
		except (ModuleNotFoundError, ImportError):
			return False
		except frappe.DoesNotExistError:
			frappe.clear_last_message()
			return False

		if ptype in ["write", "create", "delete"]:
			return ref_doc.has_permission("write", debug=debug, user=user)
		else:
			return ref_doc.has_permission("read", debug=debug, user=user)

	return False

def _compute_res_name(self):
    for attachment in self:
        if attachment.res_model and attachment.res_id:
            record = self.env[attachment.res_model].browse(attachment.res_id)
            attachment.res_name = record.display_name
        else:
            attachment.res_name = False

def _get_storage_domain(self):
    # domain to retrieve the attachments to migrate
    return {
        'db': [('store_fname', '!=', False)],
        'file': [('db_datas', '!=', False)],
    }[self._storage()]

def force_storage(self):
    """Force all attachments to be stored in the currently configured storage"""
    if not self.env.is_admin():
        raise AccessError(_('Only administrators can execute this action.'))

    # Migrate only binary attachments and bypass the res_field automatic
    # filter added in _search override
    self.search(Domain.AND([
        self._get_storage_domain(),
        ['&', ('type', '=', 'binary'), '|', ('res_field', '=', False), ('res_field', '!=', False)]
    ]))._migrate()

def _full_path(self, path):
    assert not path.endswith(GC_FILE_SUFFIX)
    # sanitize path
    path = re.sub(r'[.:]', '', path).strip('/\\')
    return os.path.join(self._filestore(), path)

def _file_read(self) -> BinaryValue:
    assert isinstance(self, IrAttachment) and self.store_fname
    try:
        return LocalBinaryFile(self)
    except OSError:
        full_path = self._full_path(self.store_fname)
        _logger.info("_file_read reading %s", full_path, exc_info=True)
        return EMPTY_BINARY

def _gc_file_store_unsafe(self, grace_period):
    # Generate the file names to check
    limit_time = datetime.now().timestamp() - grace_period

    # Clean up old uploaded files
    upload_dir = self._full_path('upload')
    if os.path.isdir(upload_dir):
        for dirpath, _subdirs, filenames in os.walk(upload_dir):
            for filename in filenames:
                path = os.path.join(dirpath, filename)
                if os.path.getmtime(path) < limit_time:
                    _logger.debug("filestore gc removing old uploaded file %s", path)
                    os.unlink(path)

    def files_to_gc():
        for dirpath, _subdirs, filenames in os.walk(self._full_path('checklist')):
            dirname = os.path.basename(dirpath)
            filenames.sort(reverse=True)  # start with files with suffix
            for filename in filenames:
                check_file = os.path.join(dirpath, filename)
                fname = f"{dirname}/{filename}"
                if check_file.endswith(GC_FILE_SUFFIX):
                    # leftover from a previous GC
                    # move the file back if it exists
                    fname = fname.removesuffix(GC_FILE_SUFFIX)
                    try:
                        full_path = self._full_path(fname)
                        os.replace(full_path + GC_FILE_SUFFIX, full_path)
                    except OSError:
                        _logger.info("filestore gc was interrupted, moving back %s", filename, exc_info=True)
                    else:
                        _logger.info("filestore gc was interrupted, moved back %s", filename)
                    # move the check file back, ignore if file already exists
                    original_check_file = check_file.removesuffix(GC_FILE_SUFFIX)
                    if os.path.exists(original_check_file):
                        os.unlink(check_file)
                    else:
                        try:
                            os.rename(check_file, original_check_file)
                        except OSError:
                            _logger.info("filestore gc failed to add back %s", original_check_file)
                            os.unlink(check_file)
                elif os.path.getmtime(check_file) < limit_time:
                    # we can collect the file
                    yield (fname, check_file)

    # Clean up the checklist. The checklist is split in chunks and files are garbage-collected
    # for each chunk.
    checked = 0
    removed = 0
    for name_pairs in split_every(IN_MAX, files_to_gc()):
        # start a new transaction (see latest data) and release locks of
        # previous loop which we don't want modified during processing
        self.env.cr.commit()
        # determine which files to keep among the checklist
        referenced_fnames = {fname for fname, in self.env.execute_query(SQL("""
            SELECT store_fname
            FROM ir_attachment
            WHERE store_fname IN %s
            FOR UPDATE""", tuple(p[0] for p in name_pairs)
        ))}
        checked += len(name_pairs)

        # remove files, and clean up checklist
        for fname, check_file in name_pairs:
            # If a file is written during the clean up process, we must
            # ensure that it remains on disk. To achieve this on the file
            # system, we are first moving the files and then deleting them
            # after checking if a checkfile did not appear in the meantime.
            full_path = self._full_path(fname)
            del_check_file = check_file + GC_FILE_SUFFIX
            del_full_path = full_path + GC_FILE_SUFFIX
            # 1. Move the check file
            try:
                if fname in referenced_fnames:
                    os.unlink(check_file)
                    continue
                else:
                    os.replace(check_file, del_check_file)
            except OSError:
                _logger.debug("_file_gc could not move %s", check_file, exc_info=True)
                continue
            # 2. Check the mtime of the moved check file
            if not (os.path.getmtime(del_check_file) < limit_time):
                _logger.debug("_file_gc concurrent write for %s", full_path)
                os.replace(del_check_file, check_file)  # restore the check file
                continue
            # 3. Move the file
            try:
                os.replace(full_path, del_full_path)
            except FileNotFoundError:
                pass  # check file created but the whole file does not exist
            except OSError:
                _logger.info("_file_gc could not move %s", full_path, exc_info=True)
                continue
            # 4. Check if a check file was created in the meantime
            if os.path.exists(check_file):
                _logger.debug("_file_gc concurrent write during move for %s", full_path)
                try:  # noqa: SIM105
                    os.replace(del_full_path, full_path)
                except OSError:
                    _logger.warning("_file_gc failed to move files back, ignore for %s", full_path)
                os.unlink(del_check_file)
                continue
            # 5. Remove moved files
            try:
                os.unlink(del_full_path)
            except FileNotFoundError:
                pass
            except OSError:
                _logger.info("_file_gc could not unlink %s", full_path, exc_info=True)
            else:
                removed += 1
                _logger.debug("_file_gc unlinked %s", full_path)
            os.unlink(del_check_file)
    if checked:
        # release locks
        self.env.cr.commit()

    _logger.info("filestore gc %d checked, %d removed", checked, removed)

def _compute_raw(self):
    for attach in self:
        if attach.store_fname:
            raw = attach._file_read()
        else:
            raw = BinaryBytes(attach.db_datas, filename=attach.name)
        attach.raw = raw

def _get_pdf_raw(self):
    self.ensure_one()
    if self.type != 'binary':
        return False
    if not self.mimetype.startswith('application/pdf'):
        return False
    return self.raw

def _inverse_raw(self):
    old_fnames = OrderedSet()
    raw_map = {}

    for attach in self:
        # compute the fields that depend on raw
        bin_data = attach.raw or EMPTY_BINARY
        vals = self._get_datas_related_values(bin_data, attach.mimetype)

        # take current location in filestore to possibly garbage-collect it
        if fname := attach.store_fname:
            old_fnames.add(fname)

        # write as superuser, as user probably does not have write access
        super(IrAttachment, attach.sudo()).write(vals)
        if bin_data and (fname := attach.store_fname):
            raw_map[fname] = bin_data

    if raw_map or old_fnames:
        # before touching the filestore, prevent the GC from
        # running until the end of the transaction
        self.lock_for_update(allow_referencing=True)
    for fname in old_fnames:
        if fname not in raw_map:
            self._file_delete(fname)
    for fname, raw in raw_map.items():
        with raw.open() as f:
            self._file_write(fname, f)

def _get_datas_related_values(self, data: BinaryValue, mimetype):
    checksum = self._compute_checksum(data)
    try:
        if data:
            index_content = self._index(data, mimetype, checksum=checksum)
        else:
            index_content = False
    except TypeError:
        index_content = self._index(data, mimetype)
    values = {
        'file_size': data.size,
        'checksum': checksum,
        'index_content': index_content,
        'store_fname': False,
        'db_datas': data or False,
    }
    if data and self._storage() != 'db':
        values['store_fname'] = self._file_fname(checksum)
        values['db_datas'] = False
    return values

def _compute_checksum(self, bin_data):
    """ compute the checksum for the given bytes
        :param bin_data : data in its binary form
    """
    # an empty file has a checksum too (for caching)
    return hashlib.sha1(bin_data or b'').hexdigest()

def _compute_mimetype(self, values):
    """ compute the mimetype of the given values
        :param values : dict of values to create or write an ir_attachment
        :return mime : string indicating the mimetype, or application/octet-stream by default
    """
    mimetype = None
    if values.get('mimetype'):
        mimetype = values['mimetype']
    if not mimetype and values.get('name'):
        mimetype = mimetypes.guess_type(values['name'])[0]
    if not mimetype and values.get('url'):
        mimetype = mimetypes.guess_type(values['url'].split('?')[0])[0]
    if not mimetype or mimetype == 'application/octet-stream':
        if raw := values.get('raw'):
            if isinstance(raw, BinaryValue):
                if mimetype := raw.mimetype:
                    return mimetype
                raw = raw.content
            assert isinstance(raw, bytes), f"Expecting raw bytes, got {type(raw)}"
            mimetype = guess_mimetype(raw)
    return mimetype.lower() if mimetype else 'application/octet-stream'

def _index(self, bin_data: BinaryValue, file_type: str, checksum=None) -> str | None:
    """ compute the index content of the given binary data.
    This is a python implementation of the unix command 'strings'.
    """
    # compute index_content only for text type
    if file_type and file_type.startswith('text/'):
        word_re = re.compile(rb'[\x20-\x7E]{4,}')
        with bin_data.open() as file:
            # Use readline() with a size limit to avoid unbounded
            # reads on files which may not contain newlines.
            # Note that this could split the indexed content
            # of such files due to the buffer max size.
            return '\n'.join(
                match.group().decode('ascii')
                for line in iter(lambda: file.readline(io.DEFAULT_BUFFER_SIZE), b'')
                for match in word_re.finditer(line)
            )
    return None

def _check_serving_attachments(self):
    if self.env.is_admin():
        return
    for attachment in self:
        # restrict writing on attachments that could be served by the
        # ir.http's dispatch exception handling
        # XDO note: if read on sudo, read twice, one for constraints, one for _inverse_raw as user
        if attachment.type == 'binary' and attachment.url:
            has_group = self.env.user.has_group
            if not any(has_group(g) for g in attachment.get_serving_groups()):
                raise ValidationError(_("Sorry, you are not allowed to write on this document"))

def _check_circular_attachment(self):
    for record in self.sudo():
        if record.res_model == 'ir.attachment' and record.id == record.res_id:
            raise ValidationError(_(
                "You cannot attach an attachment to itself.\n"
                "Attachment %(record)s cannot have res_id: %(res_id)s",
                record=record, res_id=record))

def check(self, mode, values=None):
    """ Restricts the access to an ir.attachment, according to referred mode """
    warnings.warn("Since 19.0, use check_access", DeprecationWarning, stacklevel=2)
    # Always require an internal user (aka, employee) to access to a attachment
    if not (self.env.is_admin() or self.env.user._is_internal()):
        raise AccessError(_("Sorry, you are not allowed to access this document."))
    self.check_access(mode)
    if values and any(self._inaccessible_comodel_records({values.get('res_model'): [values.get('res_id')]}, mode)):
        raise AccessError(_("Sorry, you are not allowed to access this document."))

def _make_access_error_message(self, operation, domain):
    if not domain.is_false():
        return AccessError(self.env._(
            "Sorry, you are not allowed to access this document. "
            "Please contact your system administrator.\n\n"
            "(Operation: %(operation)s)\n\n"
            "Records: %(records)s, User: %(user)s",
            operation=operation,
            records=self[:6],
            user=self.env.uid,
        ))
    return super()._make_access_error_message(operation, domain)

def _search_res_access(self, operation, domain_operator):
    assert operation in ('read', 'write') and self.env.su
    if domain_operator != 'in':
        return NotImplemented
    domain = self.env.context.get('search_domain')
    if not isinstance(domain, Domain):
        domain = Domain.TRUE
    sec_domain = Domain.FALSE
    self = self.sudo(False)  # noqa: PLW0642

    # - res_id == False needs to be system user or creator
    res_ids = condition_values(self, 'res_id', domain)
    if not res_ids or False in res_ids:
        if self.env.is_system():
            sec_domain |= Domain('res_id', '=', False)
        else:
            sec_domain |= Domain('res_id', '=', False) & Domain('create_uid', '=', self.env.uid)

    # Search by res_model and res_id, filter using permissions from res_model
    # - res_id != False needs then check access on the linked res_model record
    # - res_field != False needs to check field access on the res_model
    res_model_names = condition_values(self, 'res_model', domain)
    if 0 < len(res_model_names or ()) <= MAX_COMODELS_FOR_DOMAIN:
        env = self.with_context(active_test=False).env
        check_res_fields = not self.env.is_system() and tuple(condition_values(self, 'res_field', domain) or ()) != (False,)
        for res_model_name in res_model_names:
            comodel = env.get(res_model_name)
            if comodel is None:
                continue
            codomain = Domain('res_model', '=', comodel._name)
            comodel_res_ids = condition_values(self, 'res_id', domain.map_conditions(
                lambda cond: codomain & cond if cond.field_expr == 'res_model' else cond
            ))
            comodel_domain = Domain('id', 'in', comodel_res_ids) if comodel_res_ids else Domain.TRUE
            if operation != 'read':
                comodel_domain &= comodel._access_domain(operation).optimize_full(comodel.sudo())
            query = comodel._search(comodel_domain)
            if query.is_empty():
                continue
            if query.where_clause:
                codomain &= Domain('res_id', 'in', query)
            if check_res_fields:
                accessible_fields = [
                    field.name
                    for field in comodel._fields.values()
                    if field.type == 'binary' or (field.relational and field.comodel_name == self._name)
                    if comodel.has_field_access(field, operation)
                ]
                accessible_fields.append(False)
                codomain &= Domain('res_field', 'in', accessible_fields)
            sec_domain |= codomain

        return sec_domain

    # We do not have a small restriction on res_model. We still need to
    # support other queries such as: `('id', 'in' ...)`.
    records = self.sudo().with_context(active_test=False).search_fetch(
        domain & Domain('res_model', '!=', False) & ~sec_domain, SECURITY_FIELDS, order='id', limit=MAX_SEARCH_LIMIT).sudo(False)
    if len(records) == MAX_SEARCH_LIMIT:  # avoid out of memory
        raise UserError(self.env._("Cannot search, too many attachments"))
    records = records._filtered_access(operation)
    # [('id', 'any!', query_with_ids)] is optimized in sec_domain
    return sec_domain | Domain('id', 'any!', records._as_query(ordered=False))

def _inaccessible_comodel_records(self, model_and_ids: dict[str, Collection[int]], operation: str):
    # check access rights on the records
    if self.env.su:
        return
    for res_model, res_ids in model_and_ids.items():
        res_ids = OrderedSet(filter(None, res_ids))
        if not res_model or not res_ids:
            # nothing to check
            continue
        # forbid access to attachments linked to removed models as we do not
        # know what persmissions should be checked
        if res_model not in self.env:
            for res_id in res_ids:
                yield res_model, res_id
            continue
        records = self.env[res_model].browse(res_ids)
        if res_model == 'res.users' and len(records) == 1 and self.env.uid == records.id:
            # by default a user cannot write on itself, despite the list of writeable fields
            # e.g. in the case of a user inserting an image into his image signature
            # we need to bypass this check which would needlessly throw us away
            continue
        try:
            records = records._filtered_access(operation)
        except MissingError:
            records = records.exists()._filtered_access(operation)
        res_ids.difference_update(records._ids)
        for res_id in res_ids:
            yield res_model, res_id

def _search(self, domain, offset=0, limit=None, order=None, *, active_test=True, bypass_access=False):
    assert not self._active_name, "active name not supported on ir.attachment"
    domain = Domain(domain)
    if (
        not self.env.context.get('skip_res_field_check')
        and not any(d.field_expr in ('id', 'res_field') for d in domain.iter_conditions())
        and not bypass_access
    ):
        domain &= Domain('res_field', '=', False)

    domain = domain.optimize_full(self)
    if self.env.su or bypass_access or domain.is_false():
        return super()._search(domain, offset, limit, order, active_test=active_test, bypass_access=bypass_access)
    if self.env.context.get('_generating_sql_for_fields'):
        raise ValueError("Cannot generate SQL for whole ir.attachment")
    if 0 < len(condition_values(self, 'res_model', domain) or ()) <= MAX_COMODELS_FOR_DOMAIN:
        return super()._search(domain, offset, limit, order, active_test=active_test, bypass_access=bypass_access)

    # Filter in SQL with the read access domain, where res_access_* keep
    # the attachments they may accept and conditions SQL cannot express
    # keep every attachment. The check in Python drops the rest.
    def to_sql(cond):
        if cond.field_expr in ('res_access_read', 'res_access_write'):
            if cond.operator == 'in' and set(cond.value) == {True} and not self.env.is_system():
                # a linked record, or no record and created by the user
                return Domain('res_id', '!=', False) | Domain('create_uid', '=', self.env.uid)
            return Domain.TRUE
        if not cond._field(self)._description_searchable:
            return Domain.TRUE
        return cond

    domain &= self._access_domain('read').optimize(self).map_conditions(to_sql)

    self_sudo = self.sudo().with_context(active_test=False)
    ordered = bool(order)
    if limit is None:
        records = self_sudo.search_fetch(
            domain, SECURITY_FIELDS, order=order).sudo(False)
        return records._filtered_access('read')[offset:]._as_query(ordered)
    # Fetch by small batches
    sub_offset = 0
    limit += offset
    result = []
    if not ordered:
        # By default, order by model to batch access checks.
        order = 'res_model nulls first, id'
    while len(result) < limit:
        records = self_sudo.search_fetch(
            domain,
            SECURITY_FIELDS,
            offset=sub_offset,
            limit=IN_MAX,
            order=order,
        ).sudo(False)
        result.extend(records._filtered_access('read')._ids)
        if len(records) < IN_MAX:
            # There are no more records
            break
        sub_offset += IN_MAX
    return self.browse(result[offset:limit])._as_query(ordered)

def write(self, vals):
    self.check_access('write')
    if vals.get('res_model') or vals.get('res_id'):
        model_and_ids = defaultdict(OrderedSet)
        if 'res_model' in vals and 'res_id' in vals:
            model_and_ids[vals['res_model']].add(vals['res_id'])
        else:
            for record in self:
                model_and_ids[vals.get('res_model', record.res_model)].add(vals.get('res_id', record.res_id))
        if any(self._inaccessible_comodel_records(model_and_ids, 'write')):
            raise AccessError(_("Sorry, you are not allowed to access this document."))
    # remove computed field depending of raw
    for field in ('file_size', 'checksum', 'store_fname'):
        vals.pop(field, False)
    if 'mimetype' in vals or 'raw' in vals:
        vals = self._check_contents(vals)
    res = super().write(vals)
    if 'url' in vals or 'type' in vals:
        self._check_serving_attachments()
    return res

def copy_data(self, default=None):
    default = dict(default or {})
    vals_list = super().copy_data(default=default)
    for attachment, vals in zip(self, vals_list):
        if not default.keys() & {'db_datas', 'raw'}:
            # ensure the content is kept and recomputes checksum/store_fname
            vals['raw'] = attachment.raw
    return vals_list

def create(self, vals_list):
    record_tuple_set = set()

    if self.env.context.get('ir_attachment_from_stream') is not CREATE_FROM_STREAM_FLAG:
        # remove computed field depending of raw
        vals_list = [{
            key: value
            for key, value
            in vals.items()
            if key not in ('file_size', 'checksum', 'store_fname')
        } for vals in vals_list]
    raw_map = {}

    for values in vals_list:
        values = self._check_contents(values)
        if raw := values.pop('raw', None):
            values.update(self._get_datas_related_values(raw, values['mimetype']))
            if fname := values.get('store_fname'):
                raw_map[fname] = raw

        # 'check()' only uses res_model and res_id from values, and make an exists.
        # We can group the values by model, res_id to make only one query when
        # creating multiple attachments on a single record.
        record_tuple = (values.get('res_model'), values.get('res_id'))
        record_tuple_set.add(record_tuple)

    # don't use possible contextual recordset for check, see commit for details
    model_and_ids = defaultdict(set)
    for res_model, res_id in record_tuple_set:
        model_and_ids[res_model].add(res_id)
    if any(self._inaccessible_comodel_records(model_and_ids, 'write')):
        raise AccessError(_("Sorry, you are not allowed to access this document."))
    records = super().create(vals_list)
    for fname, raw in raw_map.items():
        with raw.open() as f:
            self._file_write(fname, f)
    records._check_serving_attachments()
    return records

def _post_add_create(self, **kwargs):
