def on_change_account(self):
    if self.product:
        return
    taxes = set()
    party = None
    if self.invoice and self.invoice.party:
        party = self.invoice.party
    elif self.party:
        party = self.party

    if self.invoice and self.invoice.type:
        type_ = self.invoice.type
    else:
        type_ = self.invoice_type
    if party and type_:
        if type_ == 'in':
            tax_rule = party.supplier_tax_rule
        else:
            tax_rule = party.customer_tax_rule
    else:
        tax_rule = None

    if self.account:
        pattern = self._get_tax_rule_pattern()
        for tax in self.account.taxes:
            if tax_rule:
                tax_ids = tax_rule.apply(tax, pattern)
                if tax_ids:
                    taxes.update(tax_ids)
                continue
            taxes.add(tax.id)
        if tax_rule:
            tax_ids = tax_rule.apply(None, pattern)
            if tax_ids:
                taxes.update(tax_ids)
    self.taxes = taxes

