def get_rec_name(self, name):
    pool = Pool()
    Lang = pool.get('ir.lang')
    name = self.product.rec_name if self.product else self.summary
    if not name and self.account:
        name = self.account.rec_name

    if self.type == 'line':
        lang = Lang.get()
        if self.unit:
            quantity = lang.format_number_symbol(
                self.quantity or 0, self.unit, digits=self.unit.digits)
        else:
            quantity = lang.format_number(self.quantity or 0)
        if name:
            name = f'{quantity} {name}'
        else:
            name = quantity
    elif not name:
        name = f'({self.id})'

    if self.invoice:
        name = f'{name} @ {self.invoice.rec_name}'
    return name

def search_rec_name(cls, name, clause):
    _, operator, value = clause
    if operator.startswith('!') or operator.startswith('not '):
        bool_op = 'AND'
    else:
        bool_op = 'OR'
    return [bool_op,
        ('invoice.rec_name', *clause[1:]),
        ('product.rec_name', *clause[1:]),
        ('account.rec_name', *clause[1:]),
        ('summary', *clause[1:]),
        ]

def check_modification(cls, mode, lines, values=None, external=False):
    super().check_modification(
        mode, lines, values=values, external=external)
    if mode == 'create':
        for line in lines:
            if line.invoice and line.invoice.state != 'draft':
                raise AccessError(gettext(
                        'account_invoice.msg_invoice_line_create_draft',
                        invoice=line.invoice.rec_name))
    elif (mode == 'delete'
            or (mode == 'write'
                and values.keys() - cls._check_modify_exclude)):
        for line in lines:
            if line.invoice and not line.invoice.is_modifiable:
                raise AccessError(gettext(
                        'account_invoice.msg_invoice_line_modify',
                        line=line.rec_name,
                        invoice=line.invoice.rec_name))

